window.MT_DATA['ta'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Inde du Sud, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une nouvelle vie à Chennai","phrases":[{"fr":"Je vis à Chennai.","tgt":"நான் சென்னையில் வசிக்கிறேன்.","ro":"Nāṉ Chennaiyil vachikkiṛēṉ.","lit":"je · Chennai [dans] (-il) · habite"},{"fr":"Chaque matin, je bois du café.","tgt":"தினமும் காலையில் நான் காப்பி குடிக்கிறேன்.","ro":"Tiṉamum kālaiyil nāṉ kāppi kuḍikkiṛēṉ.","lit":"chaque jour · matin [dans] (-il) · je · café · bois"},{"fr":"Ma femme mange des idlis.","tgt":"என் மனைவி இட்லி சாப்பிடுகிறாள்.","ro":"Eṉ maṉaivi iṭli chāppiḍugiṛāḷ.","lit":"ma · épouse · idli · mange (elle)"},{"fr":"Je vais au bureau.","tgt":"நான் அலுவலகத்துக்குப் போகிறேன்.","ro":"Nāṉ aluvalagattukkup pōgiṛēṉ.","lit":"je · bureau [à] (-ukku) · vais"},{"fr":"Mon petit frère lit le journal.","tgt":"என் தம்பி செய்தித்தாள் படிக்கிறான்.","ro":"Eṉ tambi cheydittāḷ paḍikkiṛāṉ.","lit":"mon · petit frère · journal · lit (il)"},{"fr":"Le chauffeur conduit le bus.","tgt":"ஓட்டுநர் பேருந்தை ஓட்டுகிறார்.","ro":"Ōṭṭunar pērundai ōṭṭugiṛār.","lit":"chauffeur · bus [objet] (-ai) · conduit [respect]"},{"fr":"Maman prépare le café.","tgt":"அம்மா காப்பி போடுகிறார்.","ro":"Ammā kāppi pōḍugiṛār.","lit":"maman · café · prépare [respect]"},{"fr":"Le matin, j'achète des légumes.","tgt":"காலையில் நான் காய்கறி வாங்குகிறேன்.","ro":"Kālaiyil nāṉ kāykaṛi vāngugiṛēṉ.","lit":"matin [dans] (-il) · je · légumes · achète"},{"fr":"Le soir, nous marchons sur la plage.","tgt":"மாலையில் நாங்கள் கடற்கரையில் நடக்கிறோம்.","ro":"Mālaiyil nāngaḷ kaḍaṛkaraiyil naḍakkiṛōm.","lit":"soir [dans] (-il) · nous · plage [dans] (-il) · marchons"},{"fr":"En tamoul, le verbe vient à la fin.","tgt":"தமிழில் வினைச்சொல் கடைசியில் வரும்.","ro":"Tamiḻil viṉaichchol kaḍaichiyil varum.","lit":"tamoul [dans] (-il) · verbe · fin [dans] (-il) · vient"}],"tip":{"title":"Le verbe à la fin : sujet, objet, verbe","example":"Chaque matin, je bois du café. — தினமும் காலையில் நான் காப்பி <b>குடிக்கிறேன்</b>.","body":"Voici la règle d'or du tamoul : le verbe se place toujours à la fin de la phrase. En français, on dit « je bois du café » ; en tamoul, on dit « je café bois ». Prenons « Tiṉamum kālaiyil nāṉ kāppi kuḍikkiṛēṉ » : mot à mot, « tiṉamum », chaque jour, « kālaiyil », le matin, « nāṉ », je, « kāppi », café, et enfin « kuḍikkiṛēṉ », je bois. Tout ce qui précise l'action, le moment, le lieu, l'objet, vient avant, et le verbe ferme la phrase comme une porte. Autres exemples : « Nāṉ kāppi kuḍikkiṛēṉ », je bois du café, ou « Ammā kāppi pōḍugiṛār », maman prépare le café. Astuce pour retenir : quand vous parlez, gardez le verbe en réserve, comme une chute, et dites-le en dernier. Au début, cela semble étrange, puis cela devient un vrai rythme.","exampleRo":"Tiṉamum kālaiyil nāṉ kāppi kuḍikkiṛēṉ.","lit":"chaque jour · matin [dans] (-il) · je · café · bois","say":{"Tiṉamum kālaiyil nāṉ kāppi kuḍikkiṛēṉ":"தினமும் காலையில் நான் காப்பி குடிக்கிறேன்","tiṉamum":"தினமும்","kālaiyil":"காலையில்","nāṉ":"நான்","kāppi":"காப்பி","kuḍikkiṛēṉ":"குடிக்கிறேன்","Nāṉ kāppi kuḍikkiṛēṉ":"நான் காப்பி குடிக்கிறேன்","Ammā kāppi pōḍugiṛār":"அம்மா காப்பி போடுகிறார்"}}},{"title":"Les voisins de Mylapore","phrases":[{"fr":"Je suis ingénieur à Chennai.","tgt":"நான் சென்னையில் பொறியாளர்.","ro":"Nāṉ Chennaiyil poṛiyāḷar.","lit":"je · Chennai [dans] (-il) · ingénieur"},{"fr":"Mon voisin est professeur.","tgt":"என் பக்கத்து வீட்டுக்காரர் ஆசிரியர்.","ro":"Eṉ pakkattu vīṭṭukkārar āchiriyar.","lit":"mon · d'à côté · voisin [respect] · professeur"},{"fr":"Sa fille est étudiante.","tgt":"அவருடைய மகள் மாணவி.","ro":"Avaruḍaiya magaḷ māṇavi.","lit":"lui [respect] [de] (-uḍaiya) · fille · étudiante"},{"fr":"Notre immeuble est neuf.","tgt":"எங்கள் கட்டடம் புதியது.","ro":"Engaḷ kaṭṭaḍam pudiyadu.","lit":"notre · immeuble · neuf (chose)"},{"fr":"Mylapore est un vieux quartier.","tgt":"மயிலாப்பூர் ஒரு பழைய பகுதி.","ro":"Mayilāppūr oru paḻaiya pagudi.","lit":"Mylapore · un · vieux · quartier"},{"fr":"Cet appartement est grand.","tgt":"இந்த வீடு பெரியது.","ro":"Inda vīḍu periyadu.","lit":"ce · logement · grand (chose)"},{"fr":"La cuisine est un peu petite.","tgt":"சமையலறை கொஞ்சம் சிறியது.","ro":"Chamaiyalaṛai koncham chiṛiyadu.","lit":"cuisine · un peu · petite (chose)"},{"fr":"Le café est brûlant.","tgt":"காப்பி மிகவும் சூடு.","ro":"Kāppi migavum chūḍu.","lit":"café · très · chaud"},{"fr":"Ma grande sœur est médecin.","tgt":"என் அக்கா மருத்துவர்.","ro":"Eṉ akkā maruttuvar.","lit":"ma · grande sœur · médecin"},{"fr":"Nous sommes une famille française.","tgt":"நாங்கள் ஒரு பிரெஞ்சுக் குடும்பம்.","ro":"Nāngaḷ oru pirenchuk kuḍumbam.","lit":"nous · une · française · famille"}],"tip":{"title":"Pas de verbe être : « Nāṉ māṇavaṉ », je étudiant","example":"Je suis ingénieur à Chennai. — நான் சென்னையில் <b>பொறியாளர்</b>.","body":"Bonne nouvelle : pour dire « je suis étudiant », le tamoul n'a pas besoin du verbe être. On pose simplement deux mots côte à côte : « Nāṉ māṇavaṉ », mot à mot « je étudiant ». De la même façon, « Nāṉ poṛiyāḷar » veut dire je suis ingénieur, et « Eṉ akkā maruttuvar », ma grande sœur est médecin. Pour décrire une chose, on ajoute souvent la petite terminaison « -adu » à l'adjectif : « Inda vīḍu periyadu », ce logement est grand, ou « Chamaiyalaṛai chiṛiyadu », la cuisine est petite. Comparez avec le français familier, quand on dit « moi, ingénieur » : c'est exactement l'idée. Astuce pour retenir : qui, puis quoi, et c'est tout. Pas de « suis », pas de « est », la phrase est déjà complète.","exampleRo":"Nāṉ Chennaiyil poṛiyāḷar.","lit":"je · Chennai [dans] (-il) · ingénieur","say":{"Nāṉ māṇavaṉ":"நான் மாணவன்","Nāṉ poṛiyāḷar":"நான் பொறியாளர்","Eṉ akkā maruttuvar":"என் அக்கா மருத்துவர்","Inda vīḍu periyadu":"இந்த வீடு பெரியது","Chamaiyalaṛai chiṛiyadu":"சமையலறை சிறியது"}}},{"title":"Les gens de l'immeuble","phrases":[{"fr":"Il s'appelle Ravi.","tgt":"அவன் பெயர் ரவி.","ro":"Avaṉ peyar Ravi.","lit":"lui · nom · Ravi"},{"fr":"Elle s'appelle Meena.","tgt":"அவள் பெயர் மீனா.","ro":"Avaḷ peyar Mīṉā.","lit":"elle · nom · Meena"},{"fr":"Vous êtes quelqu'un de bien.","tgt":"நீங்கள் ரொம்ப நல்லவர்.","ro":"Nīngaḷ romba nallavar.","lit":"vous · très · bonne personne [respect]"},{"fr":"Il travaille avec moi.","tgt":"அவன் என்னோடு வேலை செய்கிறான்.","ro":"Avaṉ eṉṉōḍu vēlai cheygiṛāṉ.","lit":"lui · moi [avec] (-ōḍu) · travail · fait (il)"},{"fr":"Elle est vraiment adorable.","tgt":"அவள் மிகவும் அன்பானவள்.","ro":"Avaḷ migavum aṉbāṉavaḷ.","lit":"elle · très · affectueuse"},{"fr":"Je suis nouveau ici.","tgt":"நான் இங்கே புதியவன்.","ro":"Nāṉ ingē pudiyavaṉ.","lit":"je · ici · nouveau (homme)"},{"fr":"Vous parlez bien français.","tgt":"நீங்கள் நன்றாகப் பிரெஞ்சு பேசுகிறீர்கள்.","ro":"Nīngaḷ naṉṛāgap pirenchu pēchugiṛīrgaḷ.","lit":"vous · bien · français · parlez"},{"fr":"Il habite au premier étage.","tgt":"அவன் முதல் மாடியில் இருக்கிறான்.","ro":"Avaṉ mudal māḍiyil irukkiṛāṉ.","lit":"lui · premier · étage [dans] (-il) · se trouve (il)"},{"fr":"Elle va au marché.","tgt":"அவள் சந்தைக்குப் போகிறாள்.","ro":"Avaḷ chandaikkup pōgiṛāḷ.","lit":"elle · marché [à] (-ukku) · va (elle)"},{"fr":"Nous sommes voisins, vous et moi.","tgt":"நாம் பக்கத்து வீட்டுக்காரர்கள்.","ro":"Nām pakkattu vīṭṭukkārargaḷ.","lit":"nous (vous et moi) · d'à côté · voisins"}],"tip":{"title":"Les pronoms : « nāṉ », « nīngaḷ », « avaṉ », « avaḷ »","example":"Elle s'appelle Meena. — <b>அவள்</b> பெயர் மீனா.","body":"Les pronoms tamouls sont courts et faciles à dire. « Nāṉ » veut dire je, « nīngaḷ » veut dire vous, la forme polie qu'on utilise avec presque tout le monde. Pour il, on dit « avaṉ », et pour elle, « avaḷ » : seule la dernière consonne change, un « n » pour un homme, un « l » pour une femme. Écoutez bien « Avaḷ peyar Mīṉā », mot à mot « elle nom Meena », c'est-à-dire elle s'appelle Meena. Attention, « avaṉ » et « avaḷ » sont familiers : pour un adulte qu'on respecte, on dit « avar », il ou elle avec respect. Pour nous, il y a « nāngaḷ », nous sans vous, et « nām », nous tous ensemble. Astuce pour retenir : « avaṉ » finit comme « garçon », en « n », et « avaḷ » finit en « l » comme « elle ».","exampleRo":"Avaḷ peyar Mīṉā.","lit":"elle · nom · Meena","say":{"nāṉ":"நான்","nīngaḷ":"நீங்கள்","avaṉ":"அவன்","avaḷ":"அவள்","Nāṉ":"நான்","Avaḷ peyar Mīṉā":"அவள் பெயர் மீனா","avar":"அவர்","nāngaḷ":"நாங்கள்","nām":"நாம்"}}},{"title":"Idli et café filtre au petit-déjeuner","phrases":[{"fr":"C'est du café ?","tgt":"இது காப்பியா?","ro":"Idu kāppiyā?","lit":"ceci · café [question] (-ā)"},{"fr":"Oui, c'est du café.","tgt":"ஆமாம், இது காப்பி.","ro":"Āmām, idu kāppi.","lit":"oui · ceci · café"},{"fr":"Les idlis sont chauds ?","tgt":"இட்லி சூடாக இருக்கிறதா?","ro":"Iṭli chūḍāga irukkiṛadā?","lit":"idli · chaud · est [question] (-ā)"},{"fr":"C'est du sambar ?","tgt":"இது சாம்பாரா?","ro":"Idu chāmbārā?","lit":"ceci · sambar [question] (-ā)"},{"fr":"Vous mangez des dosas ?","tgt":"நீங்கள் தோசை சாப்பிடுகிறீர்களா?","ro":"Nīngaḷ tōchai chāppiḍugiṛīrgaḷā?","lit":"vous · dosa · mangez [question] (-ā)"},{"fr":"Il y a du sucre dans le café ?","tgt":"காப்பியில் சர்க்கரை இருக்கிறதா?","ro":"Kāppiyil charkkarai irukkiṛadā?","lit":"café [dans] (-il) · sucre · il y a [question] (-ā)"},{"fr":"Vous êtes prêt pour le petit-déjeuner ?","tgt":"காலை உணவுக்கு நீங்கள் தயாரா?","ro":"Kālai uṇavukku nīngaḷ tayārā?","lit":"matin · repas [pour] (-ukku) · vous · prêt [question] (-ā)"},{"fr":"C'est bon ?","tgt":"நன்றாக இருக்கிறதா?","ro":"Naṉṛāga irukkiṛadā?","lit":"bien · est [question] (-ā)"},{"fr":"Oui, c'est très savoureux.","tgt":"ஆமாம், ரொம்ப ருசியாக இருக்கிறது.","ro":"Āmām, romba ruchiyāga irukkiṛadu.","lit":"oui · très · savoureux · est"},{"fr":"Vous voulez un autre idli ?","tgt":"இன்னொரு இட்லி வேண்டுமா?","ro":"Iṉṉoru iṭli vēṇḍumā?","lit":"un autre · idli · il faut [question] (-ā)"}],"tip":{"title":"« -ā » : transformer une phrase en question","example":"C'est du café ? — இது <b>காப்பியா</b>?","body":"Poser une question en tamoul est un jeu d'enfant : on prend une phrase normale et on ajoute un « ā » long à la fin du dernier mot. « Idu kāppi » veut dire c'est du café ; « Idu kāppiyā ? » veut dire c'est du café ? Décomposons : « idu », ceci, puis « kāppi », café, et le petit « ā » final qui transforme tout en question. Remarquez qu'un petit « y » se glisse entre deux voyelles pour faciliter la prononciation : « kāppi » devient « kāppiyā ». Avec un verbe, c'est pareil : « Nīngaḷ tayār », vous êtes prêt, devient « Nīngaḷ tayārā ? », vous êtes prêt ? Et « vēṇḍum », il faut, devient « vēṇḍumā ? ». Pas besoin de changer l'ordre des mots ni d'ajouter « est-ce que ». Astuce pour retenir : le « ā » final, c'est comme le « hein ? » qu'on ajoute en français, en levant un peu la voix.","exampleRo":"Idu kāppiyā?","lit":"ceci · café [question] (-ā)","say":{"Idu kāppi":"இது காப்பி","Idu kāppiyā ?":"இது காப்பியா?","idu":"இது","kāppi":"காப்பி","kāppiyā":"காப்பியா","Nīngaḷ tayār":"நீங்கள் தயார்","Nīngaḷ tayārā ?":"நீங்கள் தயாரா?","vēṇḍum":"வேண்டும்","vēṇḍumā ?":"வேண்டுமா?"}}},{"title":"Premier jour au bureau","phrases":[{"fr":"Cette table n'est pas la mienne.","tgt":"இந்த மேசை என்னுடையது இல்லை.","ro":"Inda mēchai eṉṉuḍaiyadu illai.","lit":"cette · table · la mienne · pas"},{"fr":"Je ne suis pas le chef.","tgt":"நான் மேலாளர் இல்லை.","ro":"Nāṉ mēlāḷar illai.","lit":"je · responsable · pas"},{"fr":"Il n'y a pas de café ici.","tgt":"இங்கே காப்பி இல்லை.","ro":"Ingē kāppi illai.","lit":"ici · café · pas"},{"fr":"Monsieur Kumar n'est pas là aujourd'hui.","tgt":"இன்று குமார் இங்கே இல்லை.","ro":"Iṉṛu Kumār ingē illai.","lit":"aujourd'hui · Kumar · ici · pas"},{"fr":"Ce n'est pas difficile.","tgt":"இது கஷ்டம் இல்லை.","ro":"Idu kashṭam illai.","lit":"ceci · difficile · pas"},{"fr":"Aujourd'hui, ce n'est pas un jour de congé.","tgt":"இன்று விடுமுறை இல்லை.","ro":"Iṉṛu viḍumuṛai illai.","lit":"aujourd'hui · congé · pas"},{"fr":"L'ordinateur ne marche pas.","tgt":"கணினி வேலை செய்யவில்லை.","ro":"Kaṇiṉi vēlai cheyyavillai.","lit":"ordinateur · travail · ne fait pas (-illai)"},{"fr":"Non, je ne suis pas fatigué.","tgt":"இல்லை, எனக்குக் களைப்பு இல்லை.","ro":"Illai, eṉakkuk kaḷaippu illai.","lit":"non · moi [à] (-ukku) · fatigue · pas"},{"fr":"Le bureau n'est pas loin.","tgt":"அலுவலகம் தூரம் இல்லை.","ro":"Aluvalagam tūram illai.","lit":"bureau · loin · pas"},{"fr":"Il n'y a aucun problème.","tgt":"பிரச்சினை இல்லை.","ro":"Pirachchiṉai illai.","lit":"problème · pas"}],"tip":{"title":"« Illai » : la négation, ce n'est pas","example":"Le bureau n'est pas loin. — அலுவலகம் தூரம் <b>இல்லை</b>.","body":"Pour dire non en tamoul, retenez un seul mot : « illai ». Il veut dire non, pas, ce n'est pas, et aussi il n'y a pas. Et comme un verbe, il se place à la fin de la phrase. « Aluvalagam tūram illai » se décompose ainsi : « aluvalagam », le bureau, « tūram », loin, « illai », pas. Donc : le bureau n'est pas loin. Même logique pour « Ingē kāppi illai », ici, café, pas : il n'y a pas de café ici. Et tout seul, au début d'une réponse, « Illai » veut simplement dire non. Avec un verbe d'action, « illai » se colle à la fin : « cheyyavillai », il ne fait pas, comme dans l'ordinateur ne marche pas. Astuce pour retenir : en français, on finit souvent par « pas » ; en tamoul, on finit par « illai », et tout le monde comprend tout de suite.","exampleRo":"Aluvalagam tūram illai.","lit":"bureau · loin · pas","say":{"Illai":"இல்லை","illai":"இல்லை","Aluvalagam tūram illai":"அலுவலகம் தூரம் இல்லை","aluvalagam":"அலுவலகம்","tūram":"தூரம்","Ingē kāppi illai":"இங்கே காப்பி இல்லை","cheyyavillai":"செய்யவில்லை"}}},{"title":"Saluer dans le quartier","phrases":[{"fr":"Bonjour, monsieur !","tgt":"வணக்கம், ஐயா!","ro":"Vaṇakkam, aiyā!","lit":"salutation · monsieur"},{"fr":"Bonjour à vous, madame !","tgt":"வணக்கம், அம்மா!","ro":"Vaṇakkam, ammā!","lit":"salutation · madame (mère)"},{"fr":"Bonjour à tout le monde !","tgt":"எல்லோருக்கும் வணக்கம்!","ro":"Ellōrukkum vaṇakkam!","lit":"tous [à] (-ukku) [aussi] (-um) · salutation"},{"fr":"Comment allez-vous ?","tgt":"எப்படி இருக்கிறீர்கள்?","ro":"Eppaḍi irukkiṛīrgaḷ?","lit":"comment · êtes (vous)"},{"fr":"Moi, je vais bien, merci.","tgt":"நான் நன்றாக இருக்கிறேன், நன்றி.","ro":"Nāṉ naṉṛāga irukkiṛēṉ, naṉṛi.","lit":"je · bien · suis · merci"},{"fr":"Et vous, ça va ?","tgt":"நீங்கள் நலமா?","ro":"Nīngaḷ nalamā?","lit":"vous · bien-être [question] (-ā)"},{"fr":"Bonsoir, Meena !","tgt":"வணக்கம், மீனா!","ro":"Vaṇakkam, Mīṉā!","lit":"salutation · Meena"},{"fr":"Au revoir, à demain.","tgt":"போய் வருகிறேன், நாளை பார்க்கலாம்.","ro":"Pōy varugiṛēṉ, nāḷai pārkkalām.","lit":"étant parti · je reviens · demain · on peut se voir"},{"fr":"On peut dire bonjour matin et soir.","tgt":"காலையிலும் மாலையிலும் வணக்கம் சொல்லலாம்.","ro":"Kālaiyilum mālaiyilum vaṇakkam chollalām.","lit":"matin [dans] [et] (-um) · soir [dans] [et] (-um) · salutation · on peut dire"},{"fr":"Les enfants saluent le professeur.","tgt":"குழந்தைகள் ஆசிரியருக்கு வணக்கம் சொல்கிறார்கள்.","ro":"Kuḻandaigaḷ āchiriyarukku vaṇakkam cholgiṛārgaḷ.","lit":"enfants · professeur [à] (-ukku) · salutation · disent"}],"tip":{"title":"« Vaṇakkam » : saluer en toute occasion","example":"Bonjour, monsieur ! — <b>வணக்கம்</b>, ஐயா!","body":"« Vaṇakkam » est le premier mot à apprendre : il sert à la fois de bonjour, de bonsoir et parfois de au revoir. Il marche à toute heure, avec tout le monde, du voisin au directeur. On l'accompagne souvent d'un sourire, et parfois des deux mains jointes devant la poitrine. Pour être poli, on ajoute un titre : « Vaṇakkam, aiyā », bonjour monsieur, ou « Vaṇakkam, ammā », bonjour madame, mot à mot « salutation, mère », une marque de respect envers une femme. Pour saluer un groupe, on dit « Ellōrukkum vaṇakkam », bonjour à tous. Ensuite vient la question « Eppaḍi irukkiṛīrgaḷ ? », comment allez-vous ? Pour partir, on dit joliment « Pōy varugiṛēṉ », je pars et je reviens. Astuce pour retenir : « vaṇakkam » commence comme « va », allez-y, dites-le à tout le monde.","exampleRo":"Vaṇakkam, aiyā!","lit":"salutation · monsieur","say":{"Vaṇakkam":"வணக்கம்","Vaṇakkam, aiyā":"வணக்கம், ஐயா","Vaṇakkam, ammā":"வணக்கம், அம்மா","Ellōrukkum vaṇakkam":"எல்லோருக்கும் வணக்கம்","Eppaḍi irukkiṛīrgaḷ ?":"எப்படி இருக்கிறீர்கள்?","Pōy varugiṛēṉ":"போய் வருகிறேன்","vaṇakkam":"வணக்கம்"}}},{"title":"Se présenter aux collègues","phrases":[{"fr":"Je m'appelle Thomas.","tgt":"என் பெயர் தாமஸ்.","ro":"Eṉ peyar Tāmas.","lit":"mon · nom · Thomas"},{"fr":"Quel est votre nom ?","tgt":"உங்கள் பெயர் என்ன?","ro":"Ungaḷ peyar eṉṉa?","lit":"votre · nom · quoi"},{"fr":"Moi, je m'appelle Karthik.","tgt":"என் பெயர் கார்த்திக்.","ro":"Eṉ peyar Kārttik.","lit":"mon · nom · Karthik"},{"fr":"Mon nom de famille est Martin.","tgt":"என் குடும்பப் பெயர் மார்ட்டின்.","ro":"Eṉ kuḍumbap peyar Mārṭṭiṉ.","lit":"mon · famille · nom · Martin"},{"fr":"Je viens du sud de la France.","tgt":"நான் தென் பிரான்சிலிருந்து வருகிறேன்.","ro":"Nāṉ teṉ Pirāṉchilirundu varugiṛēṉ.","lit":"je · sud · France [depuis] (-ilirundu) · viens"},{"fr":"Je suis le nouvel ingénieur.","tgt":"நான் புதிய பொறியாளர்.","ro":"Nāṉ pudiya poṛiyāḷar.","lit":"je · nouveau · ingénieur"},{"fr":"Ravi est mon collègue.","tgt":"ரவி என் சக ஊழியர்.","ro":"Ravi eṉ chaga ūḻiyar.","lit":"Ravi · mon · co- · employé [respect]"},{"fr":"Ma femme s'appelle Marie.","tgt":"என் மனைவியின் பெயர் மேரி.","ro":"Eṉ maṉaiviyiṉ peyar Mēri.","lit":"mon · épouse [de] (-iṉ) · nom · Marie"},{"fr":"Je suis content de vous rencontrer.","tgt":"உங்களைச் சந்தித்ததில் மகிழ்ச்சி.","ro":"Ungaḷaich chandittadil magiḻchchi.","lit":"vous [objet] (-ai) · avoir rencontré [dans] (-il) · joie"},{"fr":"Votre nom est très joli.","tgt":"உங்கள் பெயர் மிகவும் அழகு.","ro":"Ungaḷ peyar migavum aḻagu.","lit":"votre · nom · très · beauté"}],"tip":{"title":"« Eṉ peyar » : se présenter, mon nom est","example":"Je m'appelle Thomas. — <b>என் பெயர்</b> தாமஸ்.","body":"Pour vous présenter, deux petits mots suffisent : « Eṉ peyar », mon nom, suivi de votre prénom. « Eṉ peyar Tāmas » se décompose ainsi : « eṉ », mon, « peyar », nom, et « Tāmas », Thomas. Il n'y a aucun verbe : c'est la règle des phrases sans verbe être, mon nom, Thomas. Pour demander le nom de quelqu'un, on remplace le prénom par « eṉṉa », quoi : « Ungaḷ peyar eṉṉa ? », votre nom quoi, c'est-à-dire quel est votre nom ? Retenez la paire « eṉ », mon, et « ungaḷ », votre. Pour parler d'une autre personne, on dit par exemple « Avar peyar Ravi », son nom est Ravi. Et pour finir poliment, « Ungaḷaich chandittadil magiḻchchi », ravi de vous rencontrer. Astuce pour retenir : commencez par « Vaṇakkam », enchaînez avec « Eṉ peyar » et votre prénom, et vous avez une présentation complète.","exampleRo":"Eṉ peyar Tāmas.","lit":"mon · nom · Thomas","say":{"Eṉ peyar":"என் பெயர்","Eṉ peyar Tāmas":"என் பெயர் தாமஸ்","eṉ":"என்","peyar":"பெயர்","Tāmas":"தாமஸ்","eṉṉa":"என்ன","Ungaḷ peyar eṉṉa ?":"உங்கள் பெயர் என்ன?","ungaḷ":"உங்கள்","Avar peyar Ravi":"அவர் பெயர் ரவி","Ungaḷaich chandittadil magiḻchchi":"உங்களைச் சந்தித்ததில் மகிழ்ச்சி","Vaṇakkam":"வணக்கம்"}}},{"title":"La visite de l'appartement","phrases":[{"fr":"Ceci, c'est le salon.","tgt":"இது வரவேற்பறை.","ro":"Idu varavēṛpaṛai.","lit":"ceci · salon"},{"fr":"Cela, c'est la chambre.","tgt":"அது படுக்கையறை.","ro":"Adu paḍukkaiyaṛai.","lit":"cela · chambre"},{"fr":"La cuisine est ici.","tgt":"சமையலறை இங்கே.","ro":"Chamaiyalaṛai ingē.","lit":"cuisine · ici"},{"fr":"La salle de bain est là-bas.","tgt":"குளியலறை அங்கே.","ro":"Kuḷiyalaṛai angē.","lit":"salle de bain · là-bas"},{"fr":"Et ça, là-bas, c'est quoi ?","tgt":"அங்கே அது என்ன?","ro":"Angē adu eṉṉa?","lit":"là-bas · cela · quoi"},{"fr":"Ça, c'est un ventilateur.","tgt":"அது மின்விசிறி.","ro":"Adu miṉvichiṛi.","lit":"cela · ventilateur"},{"fr":"Cette fenêtre est grande.","tgt":"இந்த ஜன்னல் பெரியது.","ro":"Inda jaṉṉal periyadu.","lit":"ce · fenêtre · grande (chose)"},{"fr":"Asseyez-vous ici.","tgt":"இங்கே உட்காருங்கள்.","ro":"Ingē uṭkārungaḷ.","lit":"ici · asseyez-vous [respect]"},{"fr":"Posez les sacs là-bas.","tgt":"பைகளை அங்கே வையுங்கள்.","ro":"Paigaḷai angē vaiyungaḷ.","lit":"sacs [objet] (-ai) · là-bas · posez [respect]"},{"fr":"Cet appartement me plaît.","tgt":"எனக்கு இந்த வீடு பிடித்திருக்கிறது.","ro":"Eṉakku inda vīḍu piḍittirukkiṛadu.","lit":"moi [à] (-ukku) · ce · logement · plaît"}],"tip":{"title":"« Idu » et « adu », « ingē » et « angē » : ceci, cela, ici, là","example":"Ceci, c'est le salon. — <b>இது</b> வரவேற்பறை.","body":"Le tamoul a un système très régulier pour montrer les choses : un « i » au début pour ce qui est proche, un « a » au début pour ce qui est loin. « Idu », ceci, et « adu », cela. « Ingē », ici, et « angē », là-bas. Et devant un nom : « inda », ce, et « anda », ce là-bas. Décomposons « Idu varavēṛpaṛai » : « idu », ceci, « varavēṛpaṛai », salon, donc ceci, c'est le salon, toujours sans verbe être. De même, « Chamaiyalaṛai ingē », la cuisine ici, et « Kuḷiyalaṛai angē », la salle de bain là-bas. Pour demander, on ajoute « eṉṉa », quoi : « Adu eṉṉa ? », c'est quoi, ça ? Astuce pour retenir : « i » comme ici, tout près de vous, et « a » comme au loin, là-bas. Pointez du doigt en le disant, cela aide beaucoup.","exampleRo":"Idu varavēṛpaṛai.","lit":"ceci · salon","say":{"Idu":"இது","adu":"அது","ingē":"இங்கே","angē":"அங்கே","Ingē":"இங்கே","inda":"இந்த","anda":"அந்த","Idu varavēṛpaṛai":"இது வரவேற்பறை","idu":"இது","varavēṛpaṛai":"வரவேற்பறை","Chamaiyalaṛai ingē":"சமையலறை இங்கே","Kuḷiyalaṛai angē":"குளியலறை அங்கே","eṉṉa":"என்ன","Adu eṉṉa ?":"அது என்ன?"}}},{"title":"Au marché aux légumes","phrases":[{"fr":"Il me faut des tomates.","tgt":"எனக்குத் தக்காளி வேண்டும்.","ro":"Eṉakkut takkāḷi vēṇḍum.","lit":"moi [à] (-ukku) · tomate · il faut"},{"fr":"Les bananes sont très fraîches.","tgt":"வாழைப்பழங்கள் மிகவும் புதியவை.","ro":"Vāḻaippaḻangaḷ migavum pudiyavai.","lit":"bananes · très · fraîches (choses)"},{"fr":"Un kilo de gombos, s'il vous plaît.","tgt":"ஒரு கிலோ வெண்டைக்காய் கொடுங்கள்.","ro":"Oru kilō veṇḍaikkāy koḍungaḷ.","lit":"un · kilo · gombo · donnez [respect]"},{"fr":"Les mangues sont mûres ?","tgt":"மாம்பழம் பழுத்திருக்கிறதா?","ro":"Māmbaḻam paḻuttirukkiṛadā?","lit":"mangue · est mûre [question] (-ā)"},{"fr":"Ces piments sont forts.","tgt":"இந்த மிளகாய் காரமாக இருக்கிறது.","ro":"Inda miḷagāy kāramāga irukkiṛadu.","lit":"ce · piment · piquant · est"},{"fr":"Je prends aussi des pommes de terre.","tgt":"உருளைக்கிழங்கும் வாங்குகிறேன்.","ro":"Uruḷaikkiḻangum vāngugiṛēṉ.","lit":"pomme de terre [aussi] (-um) · j'achète"},{"fr":"Une noix de coco, c'est combien ?","tgt":"ஒரு தேங்காய் எவ்வளவு?","ro":"Oru tēngāy evvaḷavu?","lit":"une · noix de coco · combien"},{"fr":"Le marchand est très aimable.","tgt":"கடைக்காரர் மிகவும் நல்லவர்.","ro":"Kaḍaikkārar migavum nallavar.","lit":"marchand [respect] · très · bonne personne"},{"fr":"Le marché est plein de monde.","tgt":"சந்தையில் நிறைய கூட்டம்.","ro":"Chandaiyil niṛaiya kūṭṭam.","lit":"marché [dans] (-il) · beaucoup · foule"},{"fr":"Le tamoul est une belle langue.","tgt":"தமிழ் ஓர் அழகான மொழி.","ro":"Tamiḻ ōr aḻagāṉa moḻi.","lit":"tamoul · une · belle · langue"}],"tip":{"title":"Les sons rétroflexes : la langue retournée pour « ṭ », « ṇ », « ḷ » et « ḻ »","example":"Les bananes sont très fraîches. — <b>வாழைப்பழங்கள்</b> மிகவும் புதியவை.","body":"Le tamoul possède des sons que le français ne connaît pas : les rétroflexes. Pour les faire, on retourne le bout de la langue vers l'arrière et on touche le haut du palais. Dans la transcription, on les reconnaît au petit point sous la lettre. Le « ṭ » de « kūṭṭam », la foule, sonne plus sourd qu'un t français. Le « ṇ » de « vēṇḍum », il faut, et le « ḷ » de « takkāḷi », la tomate, se font de la même façon, langue retournée. Le plus célèbre est « ḻ », dans « Tamiḻ » lui-même : c'est un son entre le r et le l, langue très en arrière, sans toucher le palais. Essayez « vāḻaippaḻam », la banane, lentement, puis plus vite. Astuce pour retenir : imaginez que vous avez une bille sur la langue et que vous la poussez vers le fond du palais. Exagérez au début, les Tamouls apprécieront l'effort.","exampleRo":"Vāḻaippaḻangaḷ migavum pudiyavai.","lit":"bananes · très · fraîches (choses)","say":{"kūṭṭam":"கூட்டம்","vēṇḍum":"வேண்டும்","takkāḷi":"தக்காளி","Tamiḻ":"தமிழ்","vāḻaippaḻam":"வாழைப்பழம்"}}},{"title":"Prendre l'autobus","phrases":[{"fr":"Où est l'arrêt de bus ?","tgt":"பேருந்து நிறுத்தம் எங்கே?","ro":"Pērundu niṛuttam engē?","lit":"bus · arrêt · où"},{"fr":"Quel bus va à la plage de Marina ?","tgt":"எந்தப் பேருந்து மெரினாவுக்குப் போகும்?","ro":"Endap pērundu Meriṉāvukkup pōgum?","lit":"quel · bus · Marina [à] (-ukku) · ira"},{"fr":"Qui est le receveur ?","tgt":"நடத்துநர் யார்?","ro":"Naḍattunar yār?","lit":"receveur · qui"},{"fr":"Qu'est-ce que vous dites ?","tgt":"நீங்கள் என்ன சொல்கிறீர்கள்?","ro":"Nīngaḷ eṉṉa cholgiṛīrgaḷ?","lit":"vous · quoi · dites"},{"fr":"Où allez-vous ce matin ?","tgt":"இன்று காலை நீங்கள் எங்கே போகிறீர்கள்?","ro":"Iṉṛu kālai nīngaḷ engē pōgiṛīrgaḷ?","lit":"aujourd'hui · matin · vous · où · allez"},{"fr":"Je vais à Mylapore.","tgt":"நான் மயிலாப்பூருக்குப் போகிறேன்.","ro":"Nāṉ Mayilāppūrukkup pōgiṛēṉ.","lit":"je · Mylapore [à] (-ukku) · vais"},{"fr":"C'est combien, le billet ?","tgt":"டிக்கெட் எவ்வளவு?","ro":"Ṭikkeṭ evvaḷavu?","lit":"billet · combien"},{"fr":"Qui est ce monsieur, là-bas ?","tgt":"அந்த நபர் யார்?","ro":"Anda nabar yār?","lit":"ce (là-bas) · personne · qui"},{"fr":"Quel est le prochain arrêt ?","tgt":"அடுத்த நிறுத்தம் எது?","ro":"Aḍutta niṛuttam edu?","lit":"prochain · arrêt · lequel"},{"fr":"Pourquoi le bus est-il en retard ?","tgt":"பேருந்து ஏன் தாமதம்?","ro":"Pērundu ēṉ tāmadam?","lit":"bus · pourquoi · retard"}],"tip":{"title":"« Eṉṉa », « engē », « yār » : les mots interrogatifs","example":"Où est l'arrêt de bus ? — பேருந்து நிறுத்தம் <b>எங்கே</b>?","body":"Voici trois mots précieux pour se débrouiller : « eṉṉa », quoi, « engē », où, et « yār », qui. Bonne nouvelle, on ne déplace rien : le mot interrogatif prend simplement la place de la réponse, souvent juste avant le verbe ou en fin de phrase. « Pērundu niṛuttam engē ? » se décompose en « pērundu », bus, « niṛuttam », arrêt, « engē », où : où est l'arrêt de bus ? De même, « Naḍattunar yār ? », le receveur, qui ? Et « Ungaḷ peyar eṉṉa ? », votre nom, quoi ? Ajoutez deux amis utiles : « ēṉ », pourquoi, et « evvaḷavu », combien. Remarquez qu'avec ces mots, on n'ajoute pas le « ā » de question : le mot interrogatif suffit. Astuce pour retenir : presque tous commencent par un « e », comme dans « eh ? », le son de la curiosité.","exampleRo":"Pērundu niṛuttam engē?","lit":"bus · arrêt · où","say":{"Eṉṉa":"என்ன","engē":"எங்கே","yār":"யார்","eṉṉa":"என்ன","Pērundu niṛuttam engē ?":"பேருந்து நிறுத்தம் எங்கே?","pērundu":"பேருந்து","niṛuttam":"நிறுத்தம்","Naḍattunar yār ?":"நடத்துநர் யார்?","Ungaḷ peyar eṉṉa ?":"உங்கள் பெயர் என்ன?","ēṉ":"ஏன்","evvaḷavu":"எவ்வளவு"}}},{"title":"Compter au marché","phrases":[{"fr":"Pour moi, un café, s'il vous plaît.","tgt":"எனக்கு ஒரு காப்பி, தயவுசெய்து.","ro":"Eṉakku oru kāppi, tayavucheydu.","lit":"moi [à] (-ukku) · un · café · s'il vous plaît"},{"fr":"Deux idlis et un dosa.","tgt":"இரண்டு இட்லி, ஒரு தோசை.","ro":"Iraṇḍu iṭli, oru tōchai.","lit":"deux · idli · un · dosa"},{"fr":"Trois bananes, c'est combien ?","tgt":"மூன்று வாழைப்பழம் எவ்வளவு?","ro":"Mūṉṛu vāḻaippaḻam evvaḷavu?","lit":"trois · banane · combien"},{"fr":"Le citron coûte quatre roupies.","tgt":"ஒரு எலுமிச்சை நான்கு ரூபாய்.","ro":"Oru elumichchai nāṉgu rūbāy.","lit":"un · citron · quatre · roupies"},{"fr":"Cinq tomates, s'il vous plaît.","tgt":"ஐந்து தக்காளி கொடுங்கள்.","ro":"Aindu takkāḷi koḍungaḷ.","lit":"cinq · tomate · donnez [respect]"},{"fr":"Donnez-moi six œufs.","tgt":"ஆறு முட்டை கொடுங்கள்.","ro":"Āṛu muṭṭai koḍungaḷ.","lit":"six · œuf · donnez [respect]"},{"fr":"Il y a sept mangues dans le sac.","tgt":"பையில் ஏழு மாம்பழம் இருக்கிறது.","ro":"Paiyil ēḻu māmbaḻam irukkiṛadu.","lit":"sac [dans] (-il) · sept · mangue · il y a"},{"fr":"Combien de dosas ? Un seul.","tgt":"எத்தனை தோசை? ஒன்று மட்டும்.","ro":"Ettaṉai tōchai? Oṉṛu maṭṭum.","lit":"combien · dosa · un · seulement"},{"fr":"Je prends neuf citrons.","tgt":"நான் ஒன்பது எலுமிச்சை வாங்குகிறேன்.","ro":"Nāṉ oṉbadu elumichchai vāngugiṛēṉ.","lit":"je · neuf · citron · achète"},{"fr":"Voici dix roupies.","tgt":"இதோ பத்து ரூபாய்.","ro":"Idō pattu rūbāy.","lit":"voici · dix · roupies"}],"tip":{"title":"Compter de un à dix : « oṉṛu », « iraṇḍu », « mūṉṛu »","example":"Deux idlis et un dosa. — <b>இரண்டு</b> இட்லி, <b>ஒரு</b> தோசை.","body":"Voici les nombres de un à dix : « oṉṛu », « iraṇḍu », « mūṉṛu », « nāṉgu », « aindu », « āṛu », « ēḻu », « eṭṭu », « oṉbadu », « pattu ». Petite subtilité pour un : quand on compte ou qu'on répond seul, on dit « oṉṛu », mais devant un nom, on dit « oru » : « oru kāppi », un café. Les autres nombres se placent tels quels devant le nom, et le nom reste souvent au singulier : « iraṇḍu iṭli », deux idlis, mot à mot deux idli. Décomposons « Mūṉṛu vāḻaippaḻam evvaḷavu ? » : trois, banane, combien ? Au marché, c'est tout ce qu'il faut. Pour l'argent, on ajoute « rūbāy », roupies : « pattu rūbāy », dix roupies. Astuce pour retenir : comptez sur vos doigts à voix haute chaque matin, de « oṉṛu » à « pattu », et dites « oru » dès qu'un nom suit.","exampleRo":"Iraṇḍu iṭli, oru tōchai.","lit":"deux · idli · un · dosa","say":{"oṉṛu":"ஒன்று","iraṇḍu":"இரண்டு","mūṉṛu":"மூன்று","nāṉgu":"நான்கு","aindu":"ஐந்து","āṛu":"ஆறு","ēḻu":"ஏழு","eṭṭu":"எட்டு","oṉbadu":"ஒன்பது","pattu":"பத்து","oru":"ஒரு","oru kāppi":"ஒரு காப்பி","iraṇḍu iṭli":"இரண்டு இட்லி","Mūṉṛu vāḻaippaḻam evvaḷavu ?":"மூன்று வாழைப்பழம் எவ்வளவு?","rūbāy":"ரூபாய்","pattu rūbāy":"பத்து ரூபாய்"}}},{"title":"Le trajet vers le bureau","phrases":[{"fr":"Ce bus va à la gare.","tgt":"இந்தப் பேருந்து ரயில் நிலையத்துக்குப் போகும்.","ro":"Indap pērundu rayil nilaiyattukkup pōgum.","lit":"ce · bus · train · station [à] (-ukku) · ira"},{"fr":"J'envoie un message à mon chef.","tgt":"நான் மேலாளருக்குச் செய்தி அனுப்புகிறேன்.","ro":"Nāṉ mēlāḷarukkuch cheydi aṉuppugiṛēṉ.","lit":"je · responsable [à] (-ukku) · message · envoie"},{"fr":"Ce café est pour vous.","tgt":"இந்தக் காப்பி உங்களுக்கு.","ro":"Indak kāppi ungaḷukku.","lit":"ce · café · vous [pour] (-ukku)"},{"fr":"J'ai faim.","tgt":"எனக்குப் பசிக்கிறது.","ro":"Eṉakkup pachikkiṛadu.","lit":"moi [à] (-ukku) · ça a faim"},{"fr":"Je donne le document à Ravi.","tgt":"நான் ரவிக்கு ஆவணத்தைக் கொடுக்கிறேன்.","ro":"Nāṉ Ravikku āvaṇattaik koḍukkiṛēṉ.","lit":"je · Ravi [à] (-ukku) · document [objet] (-ai) · donne"},{"fr":"Le cadeau est pour ma fille.","tgt":"பரிசு என் மகளுக்கு.","ro":"Parichu eṉ magaḷukku.","lit":"cadeau · ma · fille [pour] (-ukku)"},{"fr":"J'arrive au bureau vers neuf heures.","tgt":"நான் சுமார் ஒன்பது மணிக்கு அலுவலகத்துக்கு வருகிறேன்.","ro":"Nāṉ chumār oṉbadu maṇikku aluvalagattukku varugiṛēṉ.","lit":"je · environ · neuf · heure [à] (-ukku) · bureau [à] (-ukku) · viens"},{"fr":"Ravi a mal à la tête.","tgt":"ரவிக்குத் தலைவலி.","ro":"Ravikkut talaivali.","lit":"Ravi [à] (-ukku) · mal de tête"},{"fr":"On va à la plage ce soir ?","tgt":"இன்று மாலை கடற்கரைக்குப் போகலாமா?","ro":"Iṉṛu mālai kaḍaṛkaraikkup pōgalāmā?","lit":"aujourd'hui · soir · plage [à] (-ukku) · on peut aller [question] (-ā)"},{"fr":"Le tamoul me plaît.","tgt":"எனக்குத் தமிழ் பிடிக்கும்.","ro":"Eṉakkut tamiḻ piḍikkum.","lit":"moi [à] (-ukku) · tamoul · plaît"}],"tip":{"title":"« -ukku » : à, pour, vers","example":"J'ai faim. — <b>எனக்குப்</b> பசிக்கிறது.","body":"En tamoul, les petits mots « à », « pour » et « vers » ne se placent pas devant le nom : ils se collent derrière, sous la forme « -ukku ». « Aluvalagam », le bureau, devient « aluvalagattukku », au bureau. « Ravi » devient « Ravikku », à Ravi. « Ungaḷ », vous, devient « ungaḷukku », pour vous. Et « nāṉ », je, devient « eṉakku », à moi. Cette forme sert aussi pour les sensations : « Eṉakkup pachikkiṛadu » se décompose en « eṉakku », à moi, et « pachikkiṛadu », ça a faim. Littéralement, la faim m'arrive. De même, « Ravikkut talaivali », à Ravi, mal de tête. Parfois, une petite consonne se double à la suite, comme « eṉakkup », c'est juste pour la fluidité. Astuce pour retenir : « -ukku », c'est la flèche qui pointe vers quelqu'un ou quelque part.","exampleRo":"Eṉakkup pachikkiṛadu.","lit":"moi [à] (-ukku) · ça a faim","say":{"Aluvalagam":"அலுவலகம்","aluvalagattukku":"அலுவலகத்துக்கு","Ravi":"ரவி","Ravikku":"ரவிக்கு","Ungaḷ":"உங்கள்","ungaḷukku":"உங்களுக்கு","nāṉ":"நான்","eṉakku":"எனக்கு","Eṉakkup pachikkiṛadu":"எனக்குப் பசிக்கிறது","pachikkiṛadu":"பசிக்கிறது","Ravikkut talaivali":"ரவிக்குத் தலைவலி","eṉakkup":"எனக்குப்"}}},{"title":"Dans le quartier de Mylapore","phrases":[{"fr":"J'habite à Mylapore.","tgt":"நான் மயிலாப்பூரில் வசிக்கிறேன்.","ro":"Nāṉ Mayilāppūril vachikkiṛēṉ.","lit":"je · Mylapore [dans] (-il) · habite"},{"fr":"Le lait est dans le frigo.","tgt":"பால் குளிர்சாதனப் பெட்டியில் இருக்கிறது.","ro":"Pāl kuḷirchādaṉap peṭṭiyil irukkiṛadu.","lit":"lait · réfrigérateur [dans] (-il) · se trouve"},{"fr":"Les clés sont dans mon sac.","tgt":"சாவி என் பையில் இருக்கிறது.","ro":"Chāvi eṉ paiyil irukkiṛadu.","lit":"clé · mon · sac [dans] (-il) · se trouve"},{"fr":"Mon bureau est au deuxième étage.","tgt":"என் அலுவலகம் இரண்டாவது மாடியில் இருக்கிறது.","ro":"Eṉ aluvalagam iraṇḍāvadu māḍiyil irukkiṛadu.","lit":"mon · bureau · deuxième · étage [dans] (-il) · se trouve"},{"fr":"Les enfants jouent dans notre rue.","tgt":"குழந்தைகள் எங்கள் தெருவில் விளையாடுகிறார்கள்.","ro":"Kuḻandaigaḷ engaḷ teruvil viḷaiyāḍugiṛārgaḷ.","lit":"enfants · notre · rue [dans] (-il) · jouent"},{"fr":"Il y a beaucoup de boutiques dans ce quartier.","tgt":"இந்தப் பகுதியில் நிறைய கடைகள் இருக்கின்றன.","ro":"Indap pagudiyil niṛaiya kaḍaigaḷ irukkiṉṛaṉa.","lit":"ce · quartier [dans] (-il) · beaucoup · boutiques · il y a"},{"fr":"Le matin, je bois mon café dans la cuisine.","tgt":"காலையில் நான் சமையலறையில் காப்பி குடிக்கிறேன்.","ro":"Kālaiyil nāṉ chamaiyalaṛaiyil kāppi kuḍikkiṛēṉ.","lit":"matin [dans] (-il) · je · cuisine [dans] (-il) · café · bois"},{"fr":"En novembre, il pleut beaucoup.","tgt":"நவம்பரில் நிறைய மழை பெய்கிறது.","ro":"Navambaril niṛaiya maḻai peygiṛadu.","lit":"novembre [dans] (-il) · beaucoup · pluie · tombe"},{"fr":"Je travaille dans une grande entreprise.","tgt":"நான் ஒரு பெரிய நிறுவனத்தில் வேலை செய்கிறேன்.","ro":"Nāṉ oru periya niṛuvaṉattil vēlai cheygiṛēṉ.","lit":"je · une · grande · entreprise [dans] (-il) · travail · fais"},{"fr":"À Chennai, on parle tamoul.","tgt":"சென்னையில் தமிழ் பேசுகிறார்கள்.","ro":"Chennaiyil tamiḻ pēchugiṛārgaḷ.","lit":"Chennai [dans] (-il) · tamoul · parlent (ils)"}],"tip":{"title":"« -il » : dans, à un endroit","example":"Les clés sont dans mon sac. — சாவி என் <b>பையில்</b> இருக்கிறது.","body":"Pour dire « dans » ou « à » un endroit, le tamoul colle la terminaison « -il » à la fin du mot. « Pai », le sac, devient « paiyil », dans le sac. « Chennai » devient « Chennaiyil », à Chennai. « Teru », la rue, devient « teruvil », dans la rue. Un petit « y » ou « v » se glisse parfois entre les voyelles pour que cela coule mieux. Décomposons « Chāvi eṉ paiyil irukkiṛadu » : « chāvi », la clé, « eṉ », mon, « paiyil », dans le sac, « irukkiṛadu », se trouve. La même terminaison sert pour le temps : « kālaiyil », le matin, ou « Navambaril », en novembre. Comparez avec le français « dans le sac » : en tamoul, c'est « sac-dans ». Astuce pour retenir : « -il » sonne comme « il est là », pile à cet endroit.","exampleRo":"Chāvi eṉ paiyil irukkiṛadu.","lit":"clé · mon · sac [dans] (-il) · se trouve","say":{"Pai":"பை","paiyil":"பையில்","Chennai":"சென்னை","Chennaiyil":"சென்னையில்","Teru":"தெரு","teruvil":"தெருவில்","Chāvi eṉ paiyil irukkiṛadu":"சாவி என் பையில் இருக்கிறது","chāvi":"சாவி","eṉ":"என்","irukkiṛadu":"இருக்கிறது","kālaiyil":"காலையில்","Navambaril":"நவம்பரில்"}}},{"title":"Ce qu'on trouve près de chez soi","phrases":[{"fr":"Il y a une pharmacie tout près d'ici.","tgt":"இங்கே பக்கத்தில் ஒரு மருந்துக்கடை இருக்கிறது.","ro":"Ingē pakkattil oru marundukkaḍai irukkiṛadu.","lit":"ici · à côté [dans] (-il) · une · pharmacie · il y a"},{"fr":"Il y a une banque dans cette rue.","tgt":"இந்தத் தெருவில் ஒரு வங்கி இருக்கிறது.","ro":"Indat teruvil oru vangi irukkiṛadu.","lit":"cette · rue [dans] (-il) · une · banque · il y a"},{"fr":"Où se trouve le marché ?","tgt":"சந்தை எங்கே இருக்கிறது?","ro":"Chandai engē irukkiṛadu?","lit":"marché · où · se trouve"},{"fr":"Le marché se trouve derrière la gare.","tgt":"சந்தை ரயில் நிலையத்துக்குப் பின்னால் இருக்கிறது.","ro":"Chandai rayil nilaiyattukkup piṉṉāl irukkiṛadu.","lit":"marché · train · station [à] (-ukku) · derrière · se trouve"},{"fr":"Y a-t-il un restaurant près d'ici ?","tgt":"பக்கத்தில் உணவகம் இருக்கிறதா?","ro":"Pakkattil uṇavagam irukkiṛadā?","lit":"à côté [dans] (-il) · restaurant · il y a [question] (-ā)"},{"fr":"Oui, il y a un petit restaurant.","tgt":"ஆமாம், ஒரு சின்ன உணவகம் இருக்கிறது.","ro":"Āmām, oru chiṉṉa uṇavagam irukkiṛadu.","lit":"oui · un · petit · restaurant · il y a"},{"fr":"Il n'y a pas de jardin public ici.","tgt":"இங்கே பூங்கா இல்லை.","ro":"Ingē pūngā illai.","lit":"ici · jardin public · pas"},{"fr":"La plage est toute proche.","tgt":"கடற்கரை மிக அருகில் இருக்கிறது.","ro":"Kaḍaṛkarai miga arugil irukkiṛadu.","lit":"plage · très · proximité [dans] (-il) · se trouve"},{"fr":"Il y a un arbre devant la maison.","tgt":"வீட்டின் முன்னால் ஒரு மரம் இருக்கிறது.","ro":"Vīṭṭiṉ muṉṉāl oru maram irukkiṛadu.","lit":"maison [de] (-iṉ) · devant · un · arbre · il y a"},{"fr":"Papa est à la maison.","tgt":"அப்பா வீட்டில் இருக்கிறார்.","ro":"Appā vīṭṭil irukkiṛār.","lit":"papa · maison [dans] (-il) · est [respect]"}],"tip":{"title":"« Irukkiṛadu » : il y a, se trouver","example":"Il y a une pharmacie tout près d'ici. — இங்கே பக்கத்தில் ஒரு மருந்துக்கடை <b>இருக்கிறது</b>.","body":"Le verbe « irukkiṛadu » est un vrai couteau suisse : il veut dire il y a, et aussi se trouver, être quelque part. Comme tout verbe tamoul, il se place à la fin. Décomposons « Ingē pakkattil oru marundukkaḍai irukkiṛadu » : « ingē », ici, « pakkattil », à côté, « oru », une, « marundukkaḍai », pharmacie, « irukkiṛadu », il y a. Pour demander, on ajoute le « ā » de question : « Pakkattil uṇavagam irukkiṛadā ? », il y a un restaurant près d'ici ? Et pour dire qu'il n'y en a pas, on remplace tout simplement par « illai » : « Ingē pūngā illai ». Pour une personne qu'on respecte, la fin change : « Appā vīṭṭil irukkiṛār », papa est à la maison. Astuce pour retenir : « irukkiṛadu » pour une chose, « irukkiṛār » pour une personne respectée, et « illai » quand il n'y a rien.","exampleRo":"Ingē pakkattil oru marundukkaḍai irukkiṛadu.","lit":"ici · à côté [dans] (-il) · une · pharmacie · il y a","say":{"Irukkiṛadu":"இருக்கிறது","irukkiṛadu":"இருக்கிறது","Ingē pakkattil oru marundukkaḍai irukkiṛadu":"இங்கே பக்கத்தில் ஒரு மருந்துக்கடை இருக்கிறது","ingē":"இங்கே","pakkattil":"பக்கத்தில்","oru":"ஒரு","marundukkaḍai":"மருந்துக்கடை","Pakkattil uṇavagam irukkiṛadā ?":"பக்கத்தில் உணவகம் இருக்கிறதா?","illai":"இல்லை","Ingē pūngā illai":"இங்கே பூங்கா இல்லை","Appā vīṭṭil irukkiṛār":"அப்பா வீட்டில் இருக்கிறார்","irukkiṛār":"இருக்கிறார்"}}},{"title":"Ce que j'ai sur moi","phrases":[{"fr":"J'ai une voiture.","tgt":"என்னிடம் ஒரு கார் இருக்கிறது.","ro":"Eṉṉiḍam oru kār irukkiṛadu.","lit":"moi [chez] (-iḍam) · une · voiture · il y a"},{"fr":"J'ai toujours un parapluie.","tgt":"என்னிடம் எப்போதும் குடை இருக்கிறது.","ro":"Eṉṉiḍam eppōdum kuḍai irukkiṛadu.","lit":"moi [chez] (-iḍam) · toujours · parapluie · il y a"},{"fr":"Vous avez de la petite monnaie ?","tgt":"உங்களிடம் சில்லறை இருக்கிறதா?","ro":"Ungaḷiḍam chillaṛai irukkiṛadā?","lit":"vous [chez] (-iḍam) · monnaie · il y a [question] (-ā)"},{"fr":"Non, je n'ai pas de monnaie.","tgt":"இல்லை, என்னிடம் சில்லறை இல்லை.","ro":"Illai, eṉṉiḍam chillaṛai illai.","lit":"non · moi [chez] (-iḍam) · monnaie · pas"},{"fr":"Elle a un nouveau téléphone.","tgt":"அவளிடம் ஒரு புதிய கைபேசி இருக்கிறது.","ro":"Avaḷiḍam oru pudiya kaibēchi irukkiṛadu.","lit":"elle [chez] (-iḍam) · un · nouveau · téléphone · il y a"},{"fr":"Il a beaucoup de livres.","tgt":"அவனிடம் நிறைய புத்தகங்கள் இருக்கின்றன.","ro":"Avaṉiḍam niṛaiya puttagangaḷ irukkiṉṛaṉa.","lit":"lui [chez] (-iḍam) · beaucoup · livres · il y a"},{"fr":"Nous avons deux enfants.","tgt":"எங்களுக்கு இரண்டு குழந்தைகள் இருக்கிறார்கள்.","ro":"Engaḷukku iraṇḍu kuḻandaigaḷ irukkiṛārgaḷ.","lit":"nous [à] (-ukku) · deux · enfants · il y a (personnes)"},{"fr":"Aujourd'hui, je n'ai pas le temps.","tgt":"இன்று எனக்கு நேரம் இல்லை.","ro":"Iṉṛu eṉakku nēram illai.","lit":"aujourd'hui · moi [à] (-ukku) · temps · pas"},{"fr":"Vous avez un stylo, par hasard ?","tgt":"உங்களிடம் பேனா இருக்கிறதா?","ro":"Ungaḷiḍam pēṉā irukkiṛadā?","lit":"vous [chez] (-iḍam) · stylo · il y a [question] (-ā)"},{"fr":"Oui, j'ai un stylo bleu.","tgt":"ஆமாம், என்னிடம் ஒரு நீலப் பேனா இருக்கிறது.","ro":"Āmām, eṉṉiḍam oru nīlap pēṉā irukkiṛadu.","lit":"oui · moi [chez] (-iḍam) · un · bleu · stylo · il y a"}],"tip":{"title":"Avoir : « eṉṉiḍam ... irukkiṛadu », chez moi il y a","example":"J'ai une voiture. — <b>என்னிடம்</b> ஒரு கார் <b>இருக்கிறது</b>.","body":"Surprise : le tamoul n'a pas de verbe avoir. Pour dire « j'ai une voiture », on dit « chez moi, il y a une voiture ». La formule est « Eṉṉiḍam ... irukkiṛadu » : « eṉṉiḍam » veut dire chez moi, auprès de moi, et « irukkiṛadu » veut dire il y a. Décomposons « Eṉṉiḍam oru kār irukkiṛadu » : chez moi, une, voiture, il y a. Pour les autres personnes, on change le début : « ungaḷiḍam », chez vous, « avaṉiḍam », chez lui, « avaḷiḍam », chez elle. Pour poser la question, on ajoute le « ā » : « Ungaḷiḍam pēṉā irukkiṛadā ? », vous avez un stylo ? Pour la famille, le temps ou les sensations, on préfère « eṉakku », à moi : « Eṉakku nēram illai », je n'ai pas le temps. Astuce pour retenir : pensez à « j'ai sur moi », c'est exactement l'image.","exampleRo":"Eṉṉiḍam oru kār irukkiṛadu.","lit":"moi [chez] (-iḍam) · une · voiture · il y a","say":{"eṉṉiḍam ... irukkiṛadu":"என்னிடம் ... இருக்கிறது","Eṉṉiḍam ... irukkiṛadu":"என்னிடம் ... இருக்கிறது","eṉṉiḍam":"என்னிடம்","irukkiṛadu":"இருக்கிறது","Eṉṉiḍam oru kār irukkiṛadu":"என்னிடம் ஒரு கார் இருக்கிறது","ungaḷiḍam":"உங்களிடம்","avaṉiḍam":"அவனிடம்","avaḷiḍam":"அவளிடம்","Ungaḷiḍam pēṉā irukkiṛadā ?":"உங்களிடம் பேனா இருக்கிறதா?","eṉakku":"எனக்கு","Eṉakku nēram illai":"எனக்கு நேரம் இல்லை"}}},{"title":"Les horaires de la journée","phrases":[{"fr":"Excusez-moi, quelle heure est-il ?","tgt":"மன்னிக்கவும், மணி என்ன?","ro":"Maṉṉikkavum, maṇi eṉṉa?","lit":"pardonnez · heure · quoi"},{"fr":"Il est sept heures.","tgt":"மணி ஏழு.","ro":"Maṇi ēḻu.","lit":"heure · sept"},{"fr":"Je me lève tous les jours à six heures.","tgt":"நான் தினமும் ஆறு மணிக்கு எழுந்திருக்கிறேன்.","ro":"Nāṉ tiṉamum āṛu maṇikku eḻundirukkiṛēṉ.","lit":"je · chaque jour · six · heure [à] (-ukku) · me lève"},{"fr":"Le bus passe à huit heures.","tgt":"பேருந்து எட்டு மணிக்கு வரும்.","ro":"Pērundu eṭṭu maṇikku varum.","lit":"bus · huit · heure [à] (-ukku) · viendra"},{"fr":"Notre bureau ouvre à neuf heures.","tgt":"எங்கள் அலுவலகம் ஒன்பது மணிக்குத் திறக்கும்.","ro":"Engaḷ aluvalagam oṉbadu maṇikkut tiṛakkum.","lit":"notre · bureau · neuf · heure [à] (-ukku) · ouvrira"},{"fr":"Je prends mon déjeuner à une heure.","tgt":"நான் ஒரு மணிக்கு மதிய உணவு சாப்பிடுகிறேன்.","ro":"Nāṉ oru maṇikku madiya uṇavu chāppiḍugiṛēṉ.","lit":"je · une · heure [à] (-ukku) · midi · repas · mange"},{"fr":"Il est cinq heures et demie.","tgt":"மணி ஐந்தரை.","ro":"Maṇi aindarai.","lit":"heure · cinq et demie"},{"fr":"On se voit à six heures ?","tgt":"ஆறு மணிக்குப் பார்க்கலாமா?","ro":"Āṛu maṇikkup pārkkalāmā?","lit":"six · heure [à] (-ukku) · on peut se voir [question] (-ā)"},{"fr":"Le soir, je rentre à sept heures.","tgt":"மாலையில் நான் ஏழு மணிக்கு வீட்டுக்கு வருகிறேன்.","ro":"Mālaiyil nāṉ ēḻu maṇikku vīṭṭukku varugiṛēṉ.","lit":"soir [dans] (-il) · je · sept · heure [à] (-ukku) · maison [à] (-ukku) · viens"},{"fr":"Il est déjà dix heures !","tgt":"மணி ஏற்கனவே பத்து!","ro":"Maṇi ēṛkaṉavē pattu!","lit":"heure · déjà · dix"}],"tip":{"title":"L'heure : « maṇi », et quelle heure est-il","example":"Il est sept heures. — <b>மணி</b> ஏழு.","body":"Le mot clé pour l'heure est « maṇi », qui veut dire à l'origine la cloche, celle qui sonnait les heures. Pour demander l'heure, on dit simplement « Maṇi eṉṉa ? », mot à mot l'heure, quoi ? Et pour répondre, on pose le nombre après : « Maṇi ēḻu », l'heure, sept, c'est-à-dire il est sept heures. Toujours pas de verbe être ! Pour dire « à sept heures », on inverse et on ajoute la flèche « -ukku » : « ēḻu maṇikku », à sept heures. Exemple : « Nāṉ āṛu maṇikku eḻundirukkiṛēṉ », je me lève à six heures. Pour la demie, on ajoute « -arai » : « aindarai », cinq heures et demie. Astuce pour retenir : « Maṇi eṉṉa ? » pour la question, « Maṇi » plus le nombre pour la réponse, et « maṇikku » pour un rendez-vous.","exampleRo":"Maṇi ēḻu.","lit":"heure · sept","say":{"maṇi":"மணி","Maṇi eṉṉa ?":"மணி என்ன?","Maṇi ēḻu":"மணி ஏழு","ēḻu maṇikku":"ஏழு மணிக்கு","Nāṉ āṛu maṇikku eḻundirukkiṛēṉ":"நான் ஆறு மணிக்கு எழுந்திருக்கிறேன்","aindarai":"ஐந்தரை","Maṇi":"மணி","maṇikku":"மணிக்கு"}}},{"title":"Au petit restaurant du coin","phrases":[{"fr":"Je voudrais un dosa.","tgt":"எனக்கு ஒரு தோசை வேண்டும்.","ro":"Eṉakku oru tōchai vēṇḍum.","lit":"moi [à] (-ukku) · un · dosa · il faut"},{"fr":"Que désirez-vous ?","tgt":"உங்களுக்கு என்ன வேண்டும்?","ro":"Ungaḷukku eṉṉa vēṇḍum?","lit":"vous [à] (-ukku) · quoi · il faut"},{"fr":"Nous voulons un repas sur feuille de bananier.","tgt":"எங்களுக்கு வாழை இலைச் சாப்பாடு வேண்டும்.","ro":"Engaḷukku vāḻai ilaich chāppāḍu vēṇḍum.","lit":"nous [à] (-ukku) · bananier · feuille · repas · il faut"},{"fr":"Vous voulez de l'eau ?","tgt":"தண்ணீர் வேண்டுமா?","ro":"Taṇṇīr vēṇḍumā?","lit":"eau · il faut [question] (-ā)"},{"fr":"Non, ça ira, merci.","tgt":"வேண்டாம், நன்றி.","ro":"Vēṇḍām, naṉṛi.","lit":"pas besoin · merci"},{"fr":"Je voudrais un café sans sucre.","tgt":"எனக்குச் சர்க்கரை இல்லாத காப்பி வேண்டும்.","ro":"Eṉakkuch charkkarai illāda kāppi vēṇḍum.","lit":"moi [à] (-ukku) · sucre · sans · café · il faut"},{"fr":"Il me faut une cuillère.","tgt":"எனக்கு ஒரு கரண்டி வேண்டும்.","ro":"Eṉakku oru karaṇḍi vēṇḍum.","lit":"moi [à] (-ukku) · une · cuillère · il faut"},{"fr":"Ma fille veut une glace.","tgt":"என் மகளுக்கு ஐஸ்கிரீம் வேண்டும்.","ro":"Eṉ magaḷukku aiskirīm vēṇḍum.","lit":"ma · fille [à] (-ukku) · glace · il faut"},{"fr":"Il faut payer à la caisse.","tgt":"காசாளரிடம் பணம் கட்ட வேண்டும்.","ro":"Kāchāḷariḍam paṇam kaṭṭa vēṇḍum.","lit":"caissier [chez] (-iḍam) · argent · payer · il faut"},{"fr":"Encore un peu de chutney, s'il vous plaît.","tgt":"இன்னும் கொஞ்சம் சட்னி வேண்டும்.","ro":"Iṉṉum koncham chaṭṉi vēṇḍum.","lit":"encore · un peu · chutney · il faut"}],"tip":{"title":"« Vēṇḍum » : vouloir, avoir besoin de","example":"Je voudrais un dosa. — எனக்கு ஒரு தோசை <b>வேண்டும்</b>.","body":"Au restaurant, « vēṇḍum » est le mot magique : il veut dire il faut, j'ai besoin, je voudrais. La construction est la même que pour la faim : on ne dit pas « je veux », on dit « à moi, il faut ». « Eṉakku oru tōchai vēṇḍum » se décompose en « eṉakku », à moi, « oru », un, « tōchai », dosa, « vēṇḍum », il faut. Pour proposer quelque chose, on ajoute le « ā » de question : « Taṇṇīr vēṇḍumā ? », vous voulez de l'eau ? Et pour refuser poliment, on dit le contraire : « Vēṇḍām », je n'en veux pas, très souvent suivi de « naṉṛi », merci. Après un verbe, « vēṇḍum » veut dire il faut faire : « paṇam kaṭṭa vēṇḍum », il faut payer. Astuce pour retenir : « vēṇḍum », c'est oui, j'en veux ; « vēṇḍām », c'est non merci. Une seule voyelle change tout.","exampleRo":"Eṉakku oru tōchai vēṇḍum.","lit":"moi [à] (-ukku) · un · dosa · il faut","say":{"Vēṇḍum":"வேண்டும்","vēṇḍum":"வேண்டும்","Eṉakku oru tōchai vēṇḍum":"எனக்கு ஒரு தோசை வேண்டும்","eṉakku":"எனக்கு","oru":"ஒரு","tōchai":"தோசை","Taṇṇīr vēṇḍumā ?":"தண்ணீர் வேண்டுமா?","Vēṇḍām":"வேண்டாம்","naṉṛi":"நன்றி","paṇam kaṭṭa vēṇḍum":"பணம் கட்ட வேண்டும்","vēṇḍām":"வேண்டாம்"}}},{"title":"Ma journée ordinaire","phrases":[{"fr":"Je me réveille tôt le matin.","tgt":"நான் காலையில் சீக்கிரம் எழுந்திருக்கிறேன்.","ro":"Nāṉ kālaiyil chīkkiram eḻundirukkiṛēṉ.","lit":"je · matin [dans] (-il) · tôt · me lève"},{"fr":"Je prends une douche.","tgt":"நான் குளிக்கிறேன்.","ro":"Nāṉ kuḷikkiṛēṉ.","lit":"je · me lave"},{"fr":"Je prépare le café.","tgt":"நான் காப்பி போடுகிறேன்.","ro":"Nāṉ kāppi pōḍugiṛēṉ.","lit":"je · café · prépare"},{"fr":"Ensuite, je lis le journal.","tgt":"பிறகு நான் செய்தித்தாள் படிக்கிறேன்.","ro":"Piṛagu nāṉ cheydittāḷ paḍikkiṛēṉ.","lit":"ensuite · je · journal · lis"},{"fr":"Je mange deux idlis.","tgt":"நான் இரண்டு இட்லி சாப்பிடுகிறேன்.","ro":"Nāṉ iraṇḍu iṭli chāppiḍugiṛēṉ.","lit":"je · deux · idli · mange"},{"fr":"Je sors de chez moi à huit heures.","tgt":"நான் எட்டு மணிக்கு வீட்டிலிருந்து கிளம்புகிறேன்.","ro":"Nāṉ eṭṭu maṇikku vīṭṭilirundu kiḷambugiṛēṉ.","lit":"je · huit · heure [à] (-ukku) · maison [depuis] (-ilirundu) · pars"},{"fr":"Que faites-vous ?","tgt":"நீங்கள் என்ன செய்கிறீர்கள்?","ro":"Nīngaḷ eṉṉa cheygiṛīrgaḷ?","lit":"vous · quoi · faites"},{"fr":"Je travaille sur l'ordinateur.","tgt":"நான் கணினியில் வேலை செய்கிறேன்.","ro":"Nāṉ kaṇiṉiyil vēlai cheygiṛēṉ.","lit":"je · ordinateur [dans] (-il) · travail · fais"},{"fr":"Ma femme cuisine très bien.","tgt":"என் மனைவி நன்றாகச் சமைக்கிறாள்.","ro":"Eṉ maṉaivi naṉṛāgach chamaikkiṛāḷ.","lit":"mon · épouse · bien · cuisine (elle)"},{"fr":"J'apprends le tamoul tous les jours.","tgt":"நான் தினமும் தமிழ் கற்றுக்கொள்கிறேன்.","ro":"Nāṉ tiṉamum tamiḻ kaṛṛukkoḷgiṛēṉ.","lit":"je · chaque jour · tamoul · apprends"}],"tip":{"title":"Le présent : « -kiṛēṉ », je fais","example":"Je prends une douche. — நான் <b>குளிக்கிறேன்</b>.","body":"Le présent tamoul se construit comme un jeu de construction : la racine du verbe, puis la marque du présent « -kiṛ- », puis la marque de la personne. Pour je, la fin est « -ēṉ » : on obtient « -kiṛēṉ ». « Kuḷi », se laver, donne « kuḷikkiṛēṉ », je me lave. « Paḍi », lire, donne « paḍikkiṛēṉ », je lis. Après certaines racines, le « k » s'adoucit en « g » à l'oreille : « chāppiḍugiṛēṉ », je mange, « cheygiṛēṉ », je fais. Seule la fin change avec la personne : « -kiṛīrgaḷ » pour vous, « -kiṛāṉ » pour il, « -kiṛāḷ » pour elle, « -kiṛōm » pour nous. Décomposons « Nāṉ kāppi pōḍugiṛēṉ » : je, café, je prépare. Astuce pour retenir : « -ēṉ » finit comme « nāṉ », je ; la fin du verbe répète en écho qui parle.","exampleRo":"Nāṉ kuḷikkiṛēṉ.","lit":"je · me lave","say":{"Kuḷi":"குளி","kuḷikkiṛēṉ":"குளிக்கிறேன்","Paḍi":"படி","paḍikkiṛēṉ":"படிக்கிறேன்","chāppiḍugiṛēṉ":"சாப்பிடுகிறேன்","cheygiṛēṉ":"செய்கிறேன்","Nāṉ kāppi pōḍugiṛēṉ":"நான் காப்பி போடுகிறேன்","nāṉ":"நான்"}}},{"title":"La promenade du soir à Marina","phrases":[{"fr":"Ma femme et moi, nous marchons sur la plage.","tgt":"நானும் என் மனைவியும் கடற்கரையில் நடக்கிறோம்.","ro":"Nāṉum eṉ maṉaiviyum kaḍaṛkaraiyil naḍakkiṛōm.","lit":"je [et] (-um) · mon · épouse [et] (-um) · plage [dans] (-il) · marchons"},{"fr":"Le vent et la mer sont agréables.","tgt":"காற்றும் கடலும் இனிமையாக இருக்கின்றன.","ro":"Kāṛṛum kaḍalum iṉimaiyāga irukkiṉṛaṉa.","lit":"vent [et] (-um) · mer [et] (-um) · agréables · sont"},{"fr":"Moi aussi, j'aime la mer.","tgt":"எனக்கும் கடல் பிடிக்கும்.","ro":"Eṉakkum kaḍal piḍikkum.","lit":"moi [à] [aussi] (-um) · mer · plaît"},{"fr":"Les enfants viennent aussi.","tgt":"குழந்தைகளும் வருகிறார்கள்.","ro":"Kuḻandaigaḷum varugiṛārgaḷ.","lit":"enfants [aussi] (-um) · viennent"},{"fr":"Nous achetons des cacahuètes et du thé.","tgt":"நாங்கள் வேர்க்கடலையும் டீயும் வாங்குகிறோம்.","ro":"Nāngaḷ vērkkaḍalaiyum ṭīyum vāngugiṛōm.","lit":"nous · cacahuète [et] (-um) · thé [et] (-um) · achetons"},{"fr":"Ravi vient aussi ce soir.","tgt":"இன்று மாலை ரவியும் வருகிறான்.","ro":"Iṉṛu mālai Raviyum varugiṛāṉ.","lit":"aujourd'hui · soir · Ravi [aussi] (-um) · vient"},{"fr":"Sur la plage, il y a des marchands et des familles.","tgt":"கடற்கரையில் வியாபாரிகளும் குடும்பங்களும் இருக்கிறார்கள்.","ro":"Kaḍaṛkaraiyil viyābārigaḷum kuḍumbangaḷum irukkiṛārgaḷ.","lit":"plage [dans] (-il) · marchands [et] (-um) · familles [et] (-um) · il y a (personnes)"},{"fr":"Le matin aussi, la plage est belle.","tgt":"காலையிலும் கடற்கரை அழகாக இருக்கிறது.","ro":"Kālaiyilum kaḍaṛkarai aḻagāga irukkiṛadu.","lit":"matin [dans] [aussi] (-um) · plage · belle · est"},{"fr":"Mon ami et sa femme attendent là-bas.","tgt":"என் நண்பரும் அவர் மனைவியும் அங்கே காத்திருக்கிறார்கள்.","ro":"Eṉ naṇbarum avar maṉaiviyum angē kāttirukkiṛārgaḷ.","lit":"mon · ami [et] (-um) · son · épouse [et] (-um) · là-bas · attendent"},{"fr":"Je parle français et un peu tamoul.","tgt":"நான் பிரெஞ்சும் கொஞ்சம் தமிழும் பேசுகிறேன்.","ro":"Nāṉ pirenchum koncham tamiḻum pēchugiṛēṉ.","lit":"je · français [et] (-um) · un peu · tamoul [et] (-um) · parle"}],"tip":{"title":"« -um » : et, aussi","example":"Ma femme et moi, nous marchons sur la plage. — <b>நானும்</b> என் <b>மனைவியும்</b> கடற்கரையில் நடக்கிறோம்.","body":"En tamoul, le mot « et » n'existe pas vraiment comme mot séparé. À la place, on colle la petite terminaison « -um » sur chacun des éléments qu'on relie. « Nāṉum eṉ maṉaiviyum » veut dire moi et ma femme, mot à mot « moi-et, ma femme-et ». Décomposons : « nāṉum », moi et, « eṉ maṉaiviyum », ma femme et, « kaḍaṛkaraiyil », sur la plage, « naḍakkiṛōm », nous marchons. Autre exemple : « kāṛṛum kaḍalum », le vent et la mer. Utilisé sur un seul mot, « -um » veut dire aussi : « Eṉakkum kaḍal piḍikkum », à moi aussi, la mer plaît, et « Raviyum varugiṛāṉ », Ravi vient aussi. Comparez avec le français « et moi, et toi » : on répète le lien sur chaque élément. Astuce pour retenir : « -um », c'est le petit « hum » d'accord qu'on ajoute pour dire moi aussi.","exampleRo":"Nāṉum eṉ maṉaiviyum kaḍaṛkaraiyil naḍakkiṛōm.","lit":"je [et] (-um) · mon · épouse [et] (-um) · plage [dans] (-il) · marchons","say":{"Nāṉum eṉ maṉaiviyum":"நானும் என் மனைவியும்","nāṉum":"நானும்","eṉ maṉaiviyum":"என் மனைவியும்","kaḍaṛkaraiyil":"கடற்கரையில்","naḍakkiṛōm":"நடக்கிறோம்","kāṛṛum kaḍalum":"காற்றும் கடலும்","Eṉakkum kaḍal piḍikkum":"எனக்கும் கடல் பிடிக்கும்","Raviyum varugiṛāṉ":"ரவியும் வருகிறான்"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Un grand merci pour tout !","tgt":"எல்லாவற்றுக்கும் மிக்க நன்றி!","ro":"Ellāvaṛṛukkum mikka naṉṛi!","lit":"tout [pour] (-ukku) [aussi] (-um) · grand · merci"},{"fr":"Excusez-moi, je n'ai pas compris.","tgt":"மன்னிக்கவும், எனக்குப் புரியவில்லை.","ro":"Maṉṉikkavum, eṉakkup puriyavillai.","lit":"pardonnez · moi [à] (-ukku) · pas compris (-illai)"},{"fr":"Ce n'est pas grave, ne vous inquiétez pas.","tgt":"பரவாயில்லை, கவலைப்படாதீர்கள்.","ro":"Paravāyillai, kavalaippaḍādīrgaḷ.","lit":"ça ne fait rien · ne vous inquiétez pas"},{"fr":"Le premier module est terminé.","tgt":"முதல் பகுதி முடிந்தது.","ro":"Mudal pagudi muḍindadu.","lit":"premier · partie · s'est terminée"},{"fr":"Maintenant, nous parlons un peu tamoul.","tgt":"இப்போது நாம் கொஞ்சம் தமிழ் பேசுகிறோம்.","ro":"Ippōdu nām koncham tamiḻ pēchugiṛōm.","lit":"maintenant · nous · un peu · tamoul · parlons"},{"fr":"Chennai, c'est maintenant notre maison.","tgt":"சென்னை இப்போது நம் வீடு.","ro":"Chennai ippōdu nam vīḍu.","lit":"Chennai · maintenant · notre · maison"},{"fr":"Merci à vous, et à la prochaine !","tgt":"உங்களுக்கு நன்றி, மீண்டும் சந்திப்போம்!","ro":"Ungaḷukku naṉṛi, mīṇḍum chandippōm!","lit":"vous [à] (-ukku) · merci · de nouveau · nous nous rencontrerons"},{"fr":"Pardon, répétez, s'il vous plaît.","tgt":"மன்னிக்கவும், மீண்டும் சொல்லுங்கள்.","ro":"Maṉṉikkavum, mīṇḍum chollungaḷ.","lit":"pardonnez · de nouveau · dites [respect]"},{"fr":"Bientôt, nous partons en voyage à Pondichéry.","tgt":"விரைவில் நாம் புதுச்சேரிக்குப் பயணம் போகிறோம்.","ro":"Viraivil nām Puduchchērikkup payaṇam pōgiṛōm.","lit":"bientôt · nous · Pondichéry [à] (-ukku) · voyage · allons"},{"fr":"Bravo, continuez vos efforts !","tgt":"பாராட்டுகள், தொடர்ந்து முயற்சி செய்யுங்கள்!","ro":"Pārāṭṭugaḷ, toḍarndu muyaṛchi cheyyungaḷ!","lit":"félicitations · en continuant · effort · faites [respect]"}],"tip":{"title":"Les formules magiques : « naṉṛi », « maṉṉikkavum », « paravāyillai »","example":"Excusez-moi, je n'ai pas compris. — <b>மன்னிக்கவும்</b>, எனக்குப் புரியவில்லை.","body":"Pour finir ce module, voici trois formules qui ouvrent toutes les portes. « Naṉṛi » veut dire merci ; pour insister, on dit « mikka naṉṛi » ou « romba naṉṛi », merci beaucoup. « Maṉṉikkavum » veut dire pardon, excusez-moi : il sert pour s'excuser, mais aussi pour attirer l'attention de quelqu'un dans la rue. Décomposons « Maṉṉikkavum, eṉakkup puriyavillai » : pardonnez, à moi, ce n'est pas compris, donc excusez-moi, je n'ai pas compris. Une phrase en or pour un débutant ! Enfin, « paravāyillai » veut dire ce n'est pas grave, ça ne fait rien ; vous reconnaissez « illai » à la fin, la négation. Quand quelqu'un vous dit « maṉṉikkavum », répondez « paravāyillai » avec un sourire. Astuce pour retenir : merci, pardon, pas grave ; trois mots, et vous voilà poli en toute situation.","exampleRo":"Maṉṉikkavum, eṉakkup puriyavillai.","lit":"pardonnez · moi [à] (-ukku) · pas compris (-illai)","say":{"naṉṛi":"நன்றி","maṉṉikkavum":"மன்னிக்கவும்","paravāyillai":"பரவாயில்லை","Naṉṛi":"நன்றி","mikka naṉṛi":"மிக்க நன்றி","romba naṉṛi":"ரொம்ப நன்றி","Maṉṉikkavum":"மன்னிக்கவும்","Maṉṉikkavum, eṉakkup puriyavillai":"மன்னிக்கவும், எனக்குப் புரியவில்லை","illai":"இல்லை"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Inde du Sud.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"À la gare d'Egmore, à Chennai","phrases":[{"fr":"Où est la gare d'Egmore ?","tgt":"எழும்பூர் ரயில் நிலையம் எங்கே?","ro":"Eḻumpūr rayil nilaiyam enkē?","lit":"Egmore · train · gare · où"},{"fr":"La voilà, juste en face.","tgt":"அதோ, எதிரே இருக்கிறது.","ro":"Atō, etirē irukkiratu.","lit":"la voilà · en face · [elle] se trouve"},{"fr":"Le guichet des billets, il est où ?","tgt":"டிக்கெட் கவுண்டர் எங்கே?","ro":"Ṭikkeṭ kavuṇḍar enkē?","lit":"billet · guichet · où"},{"fr":"Le guichet est sur la gauche.","tgt":"கவுண்டர் இடது பக்கம் இருக்கிறது.","ro":"Kavuṇḍar iḍatu pakkam irukkiratu.","lit":"guichet · gauche · côté · se trouve"},{"fr":"La file d'attente est très longue.","tgt":"வரிசை ரொம்ப நீளமாக இருக்கிறது.","ro":"Varichai rompa nīḷamāka irukkiratu.","lit":"file · très · long[-ment] · est"},{"fr":"J'ai une grosse valise.","tgt":"என்னிடம் ஒரு பெரிய பெட்டி இருக்கிறது.","ro":"Eṉṉiḍam oru periya peṭṭi irukkiratu.","lit":"moi[chez] · une · grande · valise · se trouve"},{"fr":"Où sont les toilettes, s'il vous plaît ?","tgt":"கழிப்பறை எங்கே?","ro":"Kaḻipparai enkē?","lit":"toilettes · où"},{"fr":"Il y a un stand de café ici ?","tgt":"இங்கே காபி கடை இருக்கிறதா?","ro":"Inkē kāpi kaḍai irukkiratā?","lit":"ici · café · boutique · se trouve[question] (-ā)"},{"fr":"Je voudrais un café bien chaud.","tgt":"எனக்கு ஒரு சூடான காபி வேண்டும்.","ro":"Eṉakku oru chūḍāṉa kāpi vēṇḍum.","lit":"moi[à] (-ukku) · un · chaud · café · [il faut]"},{"fr":"Le train part à sept heures du matin.","tgt":"ரயில் காலை ஏழு மணிக்குப் புறப்படுகிறது.","ro":"Rayil kālai ēḻu maṇikkup purappaḍukiratu.","lit":"train · matin · sept · heure[à] (-ukku) · part"}]},{"title":"Un billet pour Pondichéry","phrases":[{"fr":"Je voudrais un billet pour Pondichéry.","tgt":"எனக்குப் பாண்டிச்சேரிக்கு ஒரு டிக்கெட் வேண்டும்.","ro":"Eṉakkup Pāṇḍichchērikku oru ṭikkeṭ vēṇḍum.","lit":"moi[à] (-ukku) · Pondichéry[pour] (-ukku) · un · billet · [il faut]"},{"fr":"Pour aujourd'hui ou pour demain ?","tgt":"இன்றைக்கா, நாளைக்கா?","ro":"Iṉraikkā, nāḷaikkā?","lit":"aujourd'hui[pour][question] · demain[pour][question]"},{"fr":"Aujourd'hui, il n'y a plus de place.","tgt":"இன்று இடம் இல்லை.","ro":"Iṉru iḍam illai.","lit":"aujourd'hui · place · [il n'y a] pas"},{"fr":"Demain matin, il reste des places.","tgt":"நாளை காலையில் இடம் இருக்கிறது.","ro":"Nāḷai kālaiyil iḍam irukkiratu.","lit":"demain · matin[dans] (-il) · place · se trouve"},{"fr":"Alors un billet pour demain matin.","tgt":"அப்படியென்றால் நாளை காலைக்கு ஒரு டிக்கெட்.","ro":"Appaḍiyeṉrāl nāḷai kālaikku oru ṭikkeṭ.","lit":"alors · demain · matin[pour] (-ukku) · un · billet"},{"fr":"Je suis arrivé à Chennai hier.","tgt":"நான் நேற்று சென்னைக்கு வந்தேன்.","ro":"Nāṉ nērru Cheṉṉaikku vantēṉ.","lit":"je · hier · Chennai[à] (-ukku) · suis venu"},{"fr":"Aujourd'hui, je suis encore à Chennai.","tgt":"இன்று நான் இன்னும் சென்னையில் இருக்கிறேன்.","ro":"Iṉru nāṉ iṉṉum Cheṉṉaiyil irukkirēṉ.","lit":"aujourd'hui · je · encore · Chennai[dans] (-il) · suis"},{"fr":"Demain, je pars pour Pondichéry.","tgt":"நாளை நான் பாண்டிச்சேரிக்குப் போகிறேன்.","ro":"Nāḷai nāṉ Pāṇḍichchērikkup pōkirēṉ.","lit":"demain · je · Pondichéry[à] (-ukku) · vais"},{"fr":"Hier, il faisait une chaleur terrible.","tgt":"நேற்று ரொம்ப வெயில்.","ro":"Nērru rompa veyil.","lit":"hier · très · soleil"},{"fr":"Et aujourd'hui, toujours ce soleil !","tgt":"இன்றும் வெயில்தான்!","ro":"Iṉrum veyiltāṉ!","lit":"aujourd'hui[aussi] (-um) · soleil[justement] (-tāṉ)"}],"tip":{"title":"« Iṉru », « nāḷai », « nērru » : aujourd'hui, demain, hier","example":"Je suis arrivé à Chennai hier. — நான் <b>நேற்று</b> சென்னைக்கு வந்தேன்.","body":"En tamoul, les trois mots du temps qui passe sont « iṉru », aujourd'hui, « nāḷai », demain, et « nērru », hier. Ils se placent en général tout au début de la phrase, ou juste après le sujet, et le verbe reste bien sagement à la fin. Prenons « Nāṉ nērru Cheṉṉaikku vantēṉ » : mot à mot, je, hier, à Chennai, suis venu. Comme en français, pas besoin de préposition devant ces mots. Pour dire pour aujourd'hui ou pour demain, on ajoute « -kku » : « iṉraikku », « nāḷaikku ». On peut aussi préciser le moment : « nāḷai kālaiyil », demain matin. Côté prononciation, le double r de « nērru » se dit presque comme « tr » : on entend « nétrou », et « iṉru » sonne souvent « indrou ». Pour retenir, récitez-les dans l'ordre à voix haute, hier, aujourd'hui, demain : « nērru, iṉru, nāḷai », trois fois de suite.","exampleRo":"Nāṉ nērru Cheṉṉaikku vantēṉ.","lit":"je · hier · Chennai[à] (-ukku) · suis venu","say":{"Iṉru":"இன்று","nāḷai":"நாளை","nērru":"நேற்று","iṉru":"இன்று","Nāṉ nērru Cheṉṉaikku vantēṉ":"நான் நேற்று சென்னைக்கு வந்தேன்","iṉraikku":"இன்றைக்கு","nāḷaikku":"நாளைக்கு","nāḷai kālaiyil":"நாளை காலையில்","nērru, iṉru, nāḷai":"நேற்று, இன்று, நாளை"}}},{"title":"En bus sur la route de la côte","phrases":[{"fr":"Ce bus va bien à Pondichéry ?","tgt":"இந்தப் பஸ் பாண்டிச்சேரிக்குப் போகுமா?","ro":"Intap pas Pāṇḍichchērikkup pōkumā?","lit":"ce · bus · Pondichéry[à] (-ukku) · ira[question] (-ā)"},{"fr":"Oui, montez vite.","tgt":"ஆமாம், சீக்கிரம் ஏறுங்கள்.","ro":"Āmām, chīkkiram ērunkaḷ.","lit":"oui · vite · montez [respect]"},{"fr":"Cette place-là est libre ?","tgt":"இந்த இடம் காலியா?","ro":"Inta iḍam kāliyā?","lit":"cette · place · vide[question] (-ā)"},{"fr":"Merci, je m'assois ici.","tgt":"நன்றி, நான் இங்கே உட்கார்கிறேன்.","ro":"Naṉri, nāṉ inkē uṭkārkirēṉ.","lit":"merci · je · ici · m'assois"},{"fr":"Le trajet dure combien de temps, à peu près ?","tgt":"எவ்வளவு நேரம் ஆகும்?","ro":"Evvaḷavu nēram ākum?","lit":"combien · temps · prendra"},{"fr":"À peu près trois heures.","tgt":"சுமார் மூன்று மணி நேரம்.","ro":"Chumār mūṉru maṇi nēram.","lit":"environ · trois · heure · temps"},{"fr":"La route longe la mer.","tgt":"சாலை கடல் ஓரமாகப் போகிறது.","ro":"Chālai kaḍal ōramākap pōkiratu.","lit":"route · mer · bord[le long] · va"},{"fr":"Regardez, la mer est superbe !","tgt":"பாருங்கள், கடல் ரொம்ப அழகு!","ro":"Pārunkaḷ, kaḍal rompa aḻaku!","lit":"regardez [respect] · mer · très · beauté"},{"fr":"Le bus s'arrête à Mahabalipuram ?","tgt":"பஸ் மாமல்லபுரத்தில் நிற்குமா?","ro":"Pas Māmallapurattil nirkumā?","lit":"bus · Mahabalipuram[dans] (-il) · s'arrêtera[question] (-ā)"},{"fr":"Cinq minutes seulement, pas plus.","tgt":"ஐந்து நிமிடம் மட்டும்தான்.","ro":"Aintu nimiḍam maṭṭumtāṉ.","lit":"cinq · minute · seulement[justement] (-tāṉ)"}]},{"title":"La petite pension près de la mer","phrases":[{"fr":"Bonjour, une chambre est réservée à mon nom.","tgt":"வணக்கம், என் பெயரில் ஒரு அறை இருக்கிறது.","ro":"Vaṇakkam, eṉ peyaril oru arai irukkiratu.","lit":"bonjour · mon · nom[dans] (-il) · une · chambre · se trouve"},{"fr":"Donnez-moi votre passeport, s'il vous plaît.","tgt":"உங்கள் பாஸ்போர்ட்டைக் கொடுங்கள்.","ro":"Unkaḷ pāspōrṭṭaik koḍunkaḷ.","lit":"votre · passeport[objet] (-ai) · donnez [respect]"},{"fr":"Voici, tenez.","tgt":"இதோ, எடுத்துக்கொள்ளுங்கள்.","ro":"Itō, eḍuttukkoḷḷunkaḷ.","lit":"voici · prenez [respect]"},{"fr":"Montrez-moi la chambre d'abord, s'il vous plaît.","tgt":"முதலில் அறையைக் காட்டுங்கள்.","ro":"Mutalil araiyaik kāṭṭunkaḷ.","lit":"d'abord · chambre[objet] (-ai) · montrez [respect]"},{"fr":"De la chambre, on voit la mer.","tgt":"அறையிலிருந்து கடல் தெரியும்.","ro":"Araiyiliruntu kaḍal teriyum.","lit":"chambre[depuis] (-iliruntu) · mer · se voit"},{"fr":"Donnez-moi la clé de la chambre, s'il vous plaît.","tgt":"அறைச் சாவியைக் கொடுங்கள்.","ro":"Araich chāviyaik koḍunkaḷ.","lit":"chambre · clé[objet] (-ai) · donnez [respect]"},{"fr":"Donnez-moi aussi une serviette.","tgt":"ஒரு டவலும் கொடுங்கள்.","ro":"Oru ṭavalum koḍunkaḷ.","lit":"une · serviette[aussi] (-um) · donnez [respect]"},{"fr":"Le petit-déjeuner est servi à quelle heure ?","tgt":"காலை உணவு எத்தனை மணிக்கு?","ro":"Kālai uṇavu ettaṉai maṇikku?","lit":"matin · repas · combien · heure[à] (-ukku)"},{"fr":"De sept heures à dix heures.","tgt":"ஏழு மணியிலிருந்து பத்து மணி வரை.","ro":"Ēḻu maṇiyiliruntu pattu maṇi varai.","lit":"sept · heure[depuis] (-iliruntu) · dix · heure · jusqu'à"},{"fr":"Reposez-vous bien après le voyage.","tgt":"பயணத்துக்குப் பிறகு நன்றாக ஓய்வு எடுங்கள்.","ro":"Payaṇattukkup piraku naṉrāka ōyvu eḍunkaḷ.","lit":"voyage[à] (-ukku) · après · bien · repos · prenez [respect]"}],"tip":{"title":"« -unkaḷ » : demander poliment, « koḍunkaḷ », donnez-moi","example":"Donnez-moi la clé de la chambre, s'il vous plaît. — அறைச் சாவியைக் <b>கொடுங்கள்</b>.","body":"Pour demander quelque chose poliment en tamoul, on prend le verbe et on lui ajoute la terminaison « -unkaḷ ». C'est un peu notre « veuillez », ou l'impératif avec vous. Le verbe donner, « koḍu », devient « koḍunkaḷ », donnez-moi. De même, « pār », regarde, devient « pārunkaḷ », regardez, et « kāṭṭu », montre, devient « kāṭṭunkaḷ », montrez. Le verbe se place toujours à la fin : « Chāviyaik koḍunkaḷ », mot à mot, la clé, donnez. Pas besoin d'ajouter s'il vous plaît, la terminaison suffit à être poli. Le « n » de « -unkaḷ » est nasal, comme dans le mot camping, et le « ḷ » final se dit la langue retournée. Astuce : retenez d'abord « koḍunkaḷ », vous l'utiliserez dix fois par jour, au marché, au restaurant et à la pension.","exampleRo":"Araich chāviyaik koḍunkaḷ.","lit":"chambre · clé[objet] (-ai) · donnez [respect]","say":{"koḍunkaḷ":"கொடுங்கள்","koḍu":"கொடு","pār":"பார்","pārunkaḷ":"பாருங்கள்","kāṭṭu":"காட்டு","kāṭṭunkaḷ":"காட்டுங்கள்","Chāviyaik koḍunkaḷ":"சாவியைக் கொடுங்கள்"}}},{"title":"En auto-rickshaw dans Pondichéry","phrases":[{"fr":"Auto ! Vous êtes libre ?","tgt":"ஆட்டோ! வருகிறீர்களா?","ro":"Āṭṭō! Varukirīrkaḷā?","lit":"auto · venez [respect][question] (-ā)"},{"fr":"Vous allez où ?","tgt":"எங்கே போக வேண்டும்?","ro":"Enkē pōka vēṇḍum?","lit":"où · aller · [il faut]"},{"fr":"Au quartier français, s'il vous plaît.","tgt":"பிரெஞ்சுப் பகுதிக்குப் போங்கள்.","ro":"Pirenchup pakutikkup pōnkaḷ.","lit":"français · quartier[à] (-ukku) · allez [respect]"},{"fr":"C'est combien pour y aller ?","tgt":"அங்கே போக எவ்வளவு?","ro":"Ankē pōka evvaḷavu?","lit":"là-bas · aller · combien"},{"fr":"Ça fera cent roupies.","tgt":"நூறு ரூபாய்.","ro":"Nūru rūpāy.","lit":"cent · roupie"},{"fr":"C'est beaucoup trop !","tgt":"ரொம்ப அதிகம்!","ro":"Rompa atikam!","lit":"très · excessif"},{"fr":"Soixante-dix roupies, ça vous va ?","tgt":"எழுபது ரூபாய், சரியா?","ro":"Eḻupatu rūpāy, chariyā?","lit":"soixante-dix · roupie · correct[question] (-ā)"},{"fr":"Bon, d'accord, montez.","tgt":"சரி, ஏறுங்கள்.","ro":"Chari, ērunkaḷ.","lit":"d'accord · montez [respect]"},{"fr":"Roulez doucement, s'il vous plaît.","tgt":"மெதுவாகப் போங்கள்.","ro":"Metuvākap pōnkaḷ.","lit":"lentement · allez [respect]"},{"fr":"Arrêtez-vous ici, s'il vous plaît.","tgt":"இங்கே நிறுத்துங்கள்.","ro":"Inkē niruttunkaḷ.","lit":"ici · arrêtez [respect]"}]},{"title":"Au bazar de Pondichéry","phrases":[{"fr":"Combien coûte ce châle ?","tgt":"இந்தச் சால்வை எவ்வளவு?","ro":"Intach chālvai evvaḷavu?","lit":"ce · châle · combien"},{"fr":"Trois cents roupies.","tgt":"முந்நூறு ரூபாய்.","ro":"Munnūru rūpāy.","lit":"trois cents · roupie"},{"fr":"Et celui-ci, c'est combien ?","tgt":"இது எவ்வளவு?","ro":"Itu evvaḷavu?","lit":"ceci · combien"},{"fr":"Celui-ci fait deux cents roupies.","tgt":"இது இருநூறு ரூபாய்.","ro":"Itu irunūru rūpāy.","lit":"ceci · deux cents · roupie"},{"fr":"Baissez un peu le prix, s'il vous plaît.","tgt":"கொஞ்சம் குறைத்துக் கொடுங்கள்.","ro":"Koncham kuraittuk koḍunkaḷ.","lit":"un peu · en baissant · donnez [respect]"},{"fr":"Deux cent cinquante, c'est mon dernier prix.","tgt":"இருநூற்று ஐம்பது, இதுதான் கடைசி விலை.","ro":"Irunūrru aimpatu, itutāṉ kaḍaichi vilai.","lit":"deux cent · cinquante · ceci[justement] (-tāṉ) · dernier · prix"},{"fr":"Et les deux châles ensemble, c'est combien ?","tgt":"இரண்டு சால்வைக்கும் சேர்த்து எவ்வளவு?","ro":"Iraṇḍu chālvaikkum chērttu evvaḷavu?","lit":"deux · châle[pour][tous] (-ukkum) · en comptant ensemble · combien"},{"fr":"Quatre cents roupies pour les deux.","tgt":"இரண்டும் நானூறு ரூபாய்.","ro":"Iraṇḍum nāṉūru rūpāy.","lit":"deux[tous] (-um) · quatre cents · roupie"},{"fr":"D'accord, je les achète.","tgt":"சரி, நான் வாங்குகிறேன்.","ro":"Chari, nāṉ vānkukirēṉ.","lit":"d'accord · je · achète"},{"fr":"Je vous paie en liquide.","tgt":"நான் பணமாகக் கொடுக்கிறேன்.","ro":"Nāṉ paṇamākak koḍukkirēṉ.","lit":"je · argent[en] (-āka) · donne"}],"tip":{"title":"« Evvaḷavu » : demander un prix, les roupies","example":"Combien coûte ce châle ? — இந்தச் சால்வை <b>எவ்வளவு</b>?","body":"Pour demander un prix, un seul mot suffit : « evvaḷavu », combien. On le met à la fin, juste après la chose dont on parle : « Intach chālvai evvaḷavu ? », mot à mot, ce châle, combien. Pas de verbe coûter, pas de verbe être : le tamoul va droit au but. La réponse arrive avec le mot « rūpāy », roupie, qui ne change pas au pluriel : « nūru rūpāy », cent roupies, « irunūru rūpāy », deux cents roupies. Pour une quantité qu'on compte une à une, on dit plutôt « ettaṉai », combien de : « ettaṉai maṇi ? », combien d'heures. Dans « evvaḷavu », le « ḷ » se dit la langue retournée vers le palais, et l'accent tombe sur la première syllabe. Astuce : au bazar, montrez l'objet du doigt et dites simplement « Itu evvaḷavu ? », ceci combien, ça marche partout.","exampleRo":"Intach chālvai evvaḷavu?","lit":"ce · châle · combien","say":{"Evvaḷavu":"எவ்வளவு","evvaḷavu":"எவ்வளவு","Intach chālvai evvaḷavu ?":"இந்தச் சால்வை எவ்வளவு?","rūpāy":"ரூபாய்","nūru rūpāy":"நூறு ரூபாய்","irunūru rūpāy":"இருநூறு ரூபாய்","ettaṉai":"எத்தனை","ettaṉai maṇi ?":"எத்தனை மணி?","Itu evvaḷavu ?":"இது எவ்வளவு?"}}},{"title":"À la banque","phrases":[{"fr":"Il y a une banque près d'ici ?","tgt":"இங்கே பக்கத்தில் வங்கி இருக்கிறதா?","ro":"Inkē pakkattil vanki irukkiratā?","lit":"ici · côté[dans] (-il) · banque · se trouve[question] (-ā)"},{"fr":"La banque est dans cette rue.","tgt":"வங்கி இந்தத் தெருவில் இருக்கிறது.","ro":"Vanki intat teruvil irukkiratu.","lit":"banque · cette · rue[dans] (-il) · se trouve"},{"fr":"Je voudrais changer des euros.","tgt":"எனக்கு யூரோ மாற்ற வேண்டும்.","ro":"Eṉakku yūrō mārra vēṇḍum.","lit":"moi[à] (-ukku) · euro · changer · [il faut]"},{"fr":"Combien de roupies pour un euro ?","tgt":"ஒரு யூரோவுக்கு எத்தனை ரூபாய்?","ro":"Oru yūrōvukku ettaṉai rūpāy?","lit":"un · euro[pour] (-ukku) · combien · roupie"},{"fr":"Environ quatre-vingt-dix roupies.","tgt":"சுமார் தொண்ணூறு ரூபாய்.","ro":"Chumār toṇṇūru rūpāy.","lit":"environ · quatre-vingt-dix · roupie"},{"fr":"Montrez-moi votre passeport, s'il vous plaît.","tgt":"உங்கள் பாஸ்போர்ட்டைக் காட்டுங்கள்.","ro":"Unkaḷ pāspōrṭṭaik kāṭṭunkaḷ.","lit":"votre · passeport[objet] (-ai) · montrez [respect]"},{"fr":"Mettez votre signature ici, s'il vous plaît.","tgt":"இங்கே கையெழுத்துப் போடுங்கள்.","ro":"Inkē kaiyeḻuttup pōḍunkaḷ.","lit":"ici · signature · mettez [respect]"},{"fr":"Voici vos roupies.","tgt":"இதோ உங்கள் ரூபாய்.","ro":"Itō unkaḷ rūpāy.","lit":"voici · votre · roupie"},{"fr":"Il me faut aussi de la petite monnaie.","tgt":"எனக்குச் சில்லறையும் வேண்டும்.","ro":"Eṉakkuch chillaraiyum vēṇḍum.","lit":"moi[à] (-ukku) · monnaie[aussi] (-um) · [il faut]"},{"fr":"Les chauffeurs de rickshaw n'ont jamais de monnaie.","tgt":"ஆட்டோக்காரர்களிடம் சில்லறை இருக்காது.","ro":"Āṭṭōkkārarkaḷiḍam chillarai irukkātu.","lit":"chauffeurs d'auto[chez] (-iḍam) · monnaie · ne sera pas"}]},{"title":"En route pour Mahabalipuram","phrases":[{"fr":"Je viens tout droit de France.","tgt":"நான் பிரான்சிலிருந்து வருகிறேன்.","ro":"Nāṉ Pirāṉchiliruntu varukirēṉ.","lit":"je · France[depuis] (-iliruntu) · viens"},{"fr":"Et vous, vous venez de quel endroit ?","tgt":"நீங்கள் எங்கிருந்து வருகிறீர்கள்?","ro":"Nīnkaḷ enkiruntu varukirīrkaḷ?","lit":"vous · où[depuis] (-iruntu) · venez"},{"fr":"Ma ville à moi, c'est Pondichéry.","tgt":"என் ஊர் பாண்டிச்சேரிதான்.","ro":"Eṉ ūr Pāṇḍichchēritāṉ.","lit":"ma · ville natale · Pondichéry[justement] (-tāṉ)"},{"fr":"Le bus part de la gare routière de Pondichéry.","tgt":"பாண்டிச்சேரி பேருந்து நிலையத்திலிருந்து பஸ் கிளம்புகிறது.","ro":"Pāṇḍichchēri pēruntu nilaiyattiliruntu pas kiḷampukiratu.","lit":"Pondichéry · bus · station[depuis] (-iliruntu) · bus · part"},{"fr":"D'ici, c'est à combien de kilomètres ?","tgt":"இங்கிருந்து எத்தனை கிலோமீட்டர்?","ro":"Inkiruntu ettaṉai kilōmīṭṭar?","lit":"ici[depuis] (-iruntu) · combien · kilomètre"},{"fr":"Ça doit faire cent kilomètres.","tgt":"நூறு கிலோமீட்டர் இருக்கும்.","ro":"Nūru kilōmīṭṭar irukkum.","lit":"cent · kilomètre · il y aura (environ)"},{"fr":"De Pondichéry à Mahabalipuram, il faut deux heures.","tgt":"பாண்டிச்சேரியிலிருந்து மாமல்லபுரத்துக்கு இரண்டு மணி நேரம் ஆகும்.","ro":"Pāṇḍichchēriyiliruntu Māmallapurattukku iraṇḍu maṇi nēram ākum.","lit":"Pondichéry[depuis] (-iliruntu) · Mahabalipuram[à] (-ukku) · deux · heure · temps · prendra"},{"fr":"Je quitte la pension à six heures.","tgt":"நான் ஆறு மணிக்கு விடுதியிலிருந்து கிளம்புகிறேன்.","ro":"Nāṉ āru maṇikku viḍutiyiliruntu kiḷampukirēṉ.","lit":"je · six · heure[à] (-ukku) · pension[depuis] (-iliruntu) · pars"},{"fr":"Le soleil sort de la mer.","tgt":"கடலிலிருந்து சூரியன் உதிக்கிறது.","ro":"Kaḍaliliruntu chūriyaṉ utikkiratu.","lit":"mer[depuis] (-iliruntu) · soleil · se lève"},{"fr":"Quelle belle vue depuis le bus !","tgt":"பஸ்ஸிலிருந்து என்ன அழகான காட்சி!","ro":"Passiliruntu eṉṉa aḻakāṉa kāṭchi!","lit":"bus[depuis] (-iliruntu) · quelle · belle · vue"}],"tip":{"title":"« -iliruntu » : depuis, en partant de","example":"Je viens tout droit de France. — நான் <b>பிரான்சிலிருந்து</b> வருகிறேன்.","body":"Pour dire d'où l'on vient, le tamoul ne met pas de petit mot devant le lieu, mais une terminaison derrière : « -iliruntu », depuis. On la colle au nom : « Pirāṉs », la France, devient « Pirāṉchiliruntu », depuis la France. La phrase « Nāṉ Pirāṉchiliruntu varukirēṉ » se lit mot à mot : je, France-depuis, viens. On y reconnaît « -il », dans, suivi de « iruntu », qui veut dire à partir de là. Pour ici, on dit « inkiruntu », d'ici, et pour où, « enkiruntu », d'où. On le combine avec « -kku », vers, pour faire un trajet complet : « Pāṇḍichchēriyiliruntu Māmallapurattukku », de Pondichéry à Mahabalipuram. À l'oral, la fin sonne plutôt « iliroundou », avec un son doux. Astuce : dites « i-li-roun-dou » en tapant quatre fois dans vos mains, c'est le rythme du départ.","exampleRo":"Nāṉ Pirāṉchiliruntu varukirēṉ.","lit":"je · France[depuis] (-iliruntu) · viens","say":{"Pirāṉs":"பிரான்ஸ்","Pirāṉchiliruntu":"பிரான்சிலிருந்து","Nāṉ Pirāṉchiliruntu varukirēṉ":"நான் பிரான்சிலிருந்து வருகிறேன்","iruntu":"இருந்து","inkiruntu":"இங்கிருந்து","enkiruntu":"எங்கிருந்து","Pāṇḍichchēriyiliruntu Māmallapurattukku":"பாண்டிச்சேரியிலிருந்து மாமல்லபுரத்துக்கு"}}},{"title":"Les rues du quartier français","phrases":[{"fr":"Ici, les rues sont très calmes.","tgt":"இங்கே தெருக்கள் ரொம்ப அமைதியாக இருக்கின்றன.","ro":"Inkē terukkaḷ rompa amaitiyāka irukkiṉraṉa.","lit":"ici · rues · très · calme[-ment] (-āka) · sont"},{"fr":"Les maisons sont jaunes et blanches.","tgt":"வீடுகள் மஞ்சளும் வெள்ளையுமாக இருக்கின்றன.","ro":"Vīḍukaḷ manchaḷum veḷḷaiyumāka irukkiṉraṉa.","lit":"maisons · jaune[et] (-um) · blanc[et] (-um)[-ment] · sont"},{"fr":"Cette rue porte un nom français.","tgt":"இந்தத் தெருவுக்குப் பிரெஞ்சுப் பெயர்.","ro":"Intat teruvukkup pirenchup peyar.","lit":"cette · rue[à] (-ukku) · français · nom"},{"fr":"Il y a des fleurs partout.","tgt":"எல்லா இடத்திலும் பூக்கள் இருக்கின்றன.","ro":"Ellā iḍattilum pūkkaḷ irukkiṉraṉa.","lit":"tous · endroit[dans][aussi] (-ilum) · fleurs · se trouvent"},{"fr":"On marche jusqu'à la plage ?","tgt":"கடற்கரை வரை நடக்கலாமா?","ro":"Kaḍarkarai varai naḍakkalāmā?","lit":"plage · jusqu'à · marcher[on peut][question] (-ā)"},{"fr":"Le front de mer est au bout de la rue.","tgt":"கடற்கரை தெருவின் கடைசியில் இருக்கிறது.","ro":"Kaḍarkarai teruviṉ kaḍaichiyil irukkiratu.","lit":"plage · rue[de] (-iṉ) · bout[dans] (-il) · se trouve"},{"fr":"Ce petit café est vraiment joli.","tgt":"இந்தக் காபிக் கடை ரொம்ப அழகாக இருக்கிறது.","ro":"Intak kāpik kaḍai rompa aḻakāka irukkiratu.","lit":"ce · café · boutique · très · joli[-ment] (-āka) · est"},{"fr":"On s'assoit un petit moment ?","tgt":"கொஞ்சம் உட்காரலாமா?","ro":"Koncham uṭkāralāmā?","lit":"un peu · s'asseoir[on peut][question] (-ā)"},{"fr":"Ce quartier me plaît beaucoup.","tgt":"எனக்கு இந்தப் பகுதி ரொம்பப் பிடிக்கும்.","ro":"Eṉakku intap pakuti rompap piḍikkum.","lit":"moi[à] (-ukku) · ce · quartier · très · plaît"},{"fr":"On prend une photo ici ?","tgt":"இங்கே ஒரு போட்டோ எடுக்கலாமா?","ro":"Inkē oru pōṭṭō eḍukkalāmā?","lit":"ici · une · photo · prendre[on peut][question] (-ā)"}]},{"title":"Un repas sur feuille de bananier","phrases":[{"fr":"Une table pour deux personnes, s'il vous plaît.","tgt":"இரண்டு பேருக்கு ஒரு மேசை வேண்டும்.","ro":"Iraṇḍu pērukku oru mēchai vēṇḍum.","lit":"deux · personne[pour] (-ukku) · une · table · [il faut]"},{"fr":"Je voudrais le repas complet.","tgt":"எனக்கு ஒரு சாப்பாடு வேண்டும்.","ro":"Eṉakku oru chāppāḍu vēṇḍum.","lit":"moi[à] (-ukku) · un · repas · [il faut]"},{"fr":"Ici, on sert le repas sur une feuille de bananier.","tgt":"இங்கே வாழை இலையில் சாப்பாடு போடுவார்கள்.","ro":"Inkē vāḻai ilaiyil chāppāḍu pōḍuvārkaḷ.","lit":"ici · bananier · feuille[dans] (-il) · repas · ils servent"},{"fr":"Je mange avec la main droite.","tgt":"நான் வலது கையால் சாப்பிடுகிறேன்.","ro":"Nāṉ valatu kaiyāl chāppiḍukirēṉ.","lit":"je · droite · main[avec] (-āl) · mange"},{"fr":"Encore un peu de riz, s'il vous plaît.","tgt":"இன்னும் கொஞ்சம் சாதம் போடுங்கள்.","ro":"Iṉṉum koncham chātam pōḍunkaḷ.","lit":"encore · un peu · riz · servez [respect]"},{"fr":"Passez-moi le sambar, s'il vous plaît.","tgt":"சாம்பாரைக் கொடுங்கள்.","ro":"Chāmpāraik koḍunkaḷ.","lit":"sambar[objet] (-ai) · donnez [respect]"},{"fr":"Je bois le rasam.","tgt":"நான் ரசத்தைக் குடிக்கிறேன்.","ro":"Nāṉ rachattaik kuḍikkirēṉ.","lit":"je · rasam[objet] (-ai) · bois"},{"fr":"Je ne mange jamais de piment.","tgt":"நான் மிளகாயைச் சாப்பிடுவதில்லை.","ro":"Nāṉ miḷakāyaich chāppiḍuvatillai.","lit":"je · piment[objet] (-ai) · ne mange pas"},{"fr":"Apportez l'addition, s'il vous plaît.","tgt":"பில்லைக் கொண்டு வாருங்கள்.","ro":"Pillaik koṇḍu vārunkaḷ.","lit":"addition[objet] (-ai) · en apportant · venez [respect]"},{"fr":"Le repas était délicieux.","tgt":"சாப்பாடு ரொம்ப ருசியாக இருந்தது.","ro":"Chāppāḍu rompa ruchiyāka iruntatu.","lit":"repas · très · délicieux[-ment] (-āka) · était"}],"tip":{"title":"« -ai » : le complément d'objet direct","example":"Passez-moi le sambar, s'il vous plaît. — <b>சாம்பாரைக்</b> கொடுங்கள்.","body":"En tamoul, l'objet direct d'un verbe porte souvent une petite étiquette : la terminaison « -ai ». On l'ajoute quand on parle d'une chose précise, déjà connue : « chāmpār » devient « chāmpārai », le sambar. Comme le verbe arrive à la fin, cette étiquette aide à comprendre qui fait quoi. Exemple : « Chāmpāraik koḍunkaḷ », mot à mot, le sambar, donnez. Vous entendez le petit « k » ajouté ? Devant un mot qui commence par k, ch, t ou p, on double cette consonne, ce qui fait une liaison bien nette à l'oral. De même, « pil », l'addition, donne « Pillaik koṇḍu vārunkaḷ », apportez l'addition, et « racham » donne « rachattaik kuḍikkirēṉ », je bois le rasam. Pour une chose quelconque, comme un café, on garde le mot tel quel, sans étiquette. Astuce : chaque fois que vous montrez une chose précise du doigt, pensez « -ai ».","exampleRo":"Chāmpāraik koḍunkaḷ.","lit":"sambar[objet] (-ai) · donnez [respect]","say":{"chāmpār":"சாம்பார்","chāmpārai":"சாம்பாரை","Chāmpāraik koḍunkaḷ":"சாம்பாரைக் கொடுங்கள்","pil":"பில்","Pillaik koṇḍu vārunkaḷ":"பில்லைக் கொண்டு வாருங்கள்","racham":"ரசம்","rachattaik kuḍikkirēṉ":"ரசத்தைக் குடிக்கிறேன்"}}},{"title":"Les sculptures de Mahabalipuram","phrases":[{"fr":"Ces sculptures sont très anciennes.","tgt":"இந்தச் சிற்பங்கள் ரொம்பப் பழமையானவை.","ro":"Intach chirpankaḷ rompap paḻamaiyāṉavai.","lit":"ces · sculptures · très · anciennes"},{"fr":"Elles ont plus de mille ans.","tgt":"இவை ஆயிரம் வருடங்களுக்கு மேல் பழமையானவை.","ro":"Ivai āyiram varuḍankaḷukku mēl paḻamaiyāṉavai.","lit":"celles-ci · mille · ans[à] (-ukku) · au-dessus · anciennes"},{"fr":"Regardez cet éléphant en pierre !","tgt":"இந்தக் கல் யானையைப் பாருங்கள்!","ro":"Intak kal yāṉaiyaip pārunkaḷ!","lit":"cet · pierre · éléphant[objet] (-ai) · regardez [respect]"},{"fr":"Il est aussi grand qu'un vrai !","tgt":"உண்மையான யானை மாதிரி பெரியது!","ro":"Uṇmaiyāṉa yāṉai mātiri periyatu!","lit":"vrai · éléphant · comme · grand"},{"fr":"Ce gros rocher ne tombe jamais.","tgt":"இந்தப் பெரிய பாறை விழுவதே இல்லை.","ro":"Intap periya pārai viḻuvatē illai.","lit":"ce · grand · rocher · tomber[même] · pas"},{"fr":"Des sculpteurs travaillent encore ici.","tgt":"சிற்பிகள் இன்னும் இங்கே வேலை செய்கிறார்கள்.","ro":"Chirpikaḷ iṉṉum inkē vēlai cheykirārkaḷ.","lit":"sculpteurs · encore · ici · travail · font"},{"fr":"J'entends le bruit des marteaux.","tgt":"சுத்தியல் சத்தம் கேட்கிறது.","ro":"Chuttiyal chattam kēṭkiratu.","lit":"marteau · bruit · s'entend"},{"fr":"Il y a un guide qui parle le français, ici ?","tgt":"இங்கே பிரெஞ்சு பேசும் வழிகாட்டி இருக்கிறாரா?","ro":"Inkē pirenchu pēchum vaḻikāṭṭi irukkirārā?","lit":"ici · français · parlant · guide · est là [respect][question] (-ā)"},{"fr":"À midi, le soleil tape fort.","tgt":"மதியம் ரொம்ப வெயிலாக இருக்கிறது.","ro":"Matiyam rompa veyilāka irukkiratu.","lit":"midi · très · ensoleillé (-āka) · est"},{"fr":"On peut se reposer à l'ombre.","tgt":"நிழலில் ஓய்வு எடுக்கலாம்.","ro":"Niḻalil ōyvu eḍukkalām.","lit":"ombre[dans] (-il) · repos · prendre[on peut]"}]},{"title":"Demander son chemin","phrases":[{"fr":"Pardon, comment va-t-on à la plage ?","tgt":"மன்னிக்கவும், கடற்கரைக்கு எப்படிப் போவது?","ro":"Maṉṉikkavum, kaḍarkaraikku eppaḍip pōvatu?","lit":"pardon · plage[à] (-ukku) · comment · aller"},{"fr":"Continuez bien tout droit.","tgt":"நேராகவே போங்கள்.","ro":"Nērākavē pōnkaḷ.","lit":"droit[-ment] (-āka)[bien] (-ē) · allez [respect]"},{"fr":"Après, vous tournez sur la gauche.","tgt":"பிறகு இடது பக்கம் திரும்புங்கள்.","ro":"Piraku iḍatu pakkam tirumpunkaḷ.","lit":"ensuite · gauche · côté · tournez [respect]"},{"fr":"Et pour aller à la gare routière ?","tgt":"பஸ் நிலையத்துக்கு எப்படிப் போவது?","ro":"Pas nilaiyattukku eppaḍip pōvatu?","lit":"bus · station[à] (-ukku) · comment · aller"},{"fr":"On peut y aller à pied ?","tgt":"நடந்து போக முடியுமா?","ro":"Naḍantu pōka muḍiyumā?","lit":"en marchant · aller · possible[question] (-ā)"},{"fr":"Allez-y plutôt en rickshaw.","tgt":"ஆட்டோவில் போங்கள்.","ro":"Āṭṭōvil pōnkaḷ.","lit":"auto[dans] (-il) · allez [respect]"},{"fr":"Comment dit-on ça en tamoul ?","tgt":"தமிழில் இதை எப்படிச் சொல்வது?","ro":"Tamiḻil itai eppaḍich cholvatu?","lit":"tamoul[dans] (-il) · ceci[objet] (-ai) · comment · dire"},{"fr":"Et vous, comment allez-vous aujourd'hui ?","tgt":"நீங்கள் இன்று எப்படி இருக்கிறீர்கள்?","ro":"Nīnkaḷ iṉru eppaḍi irukkirīrkaḷ?","lit":"vous · aujourd'hui · comment · êtes [respect]"},{"fr":"Moi, je vais très bien, merci.","tgt":"நான் நன்றாக இருக்கிறேன், நன்றி.","ro":"Nāṉ naṉrāka irukkirēṉ, naṉri.","lit":"je · bien · suis · merci"},{"fr":"Montrez-moi la plage sur le plan, s'il vous plaît.","tgt":"கடற்கரையை வரைபடத்தில் காட்டுங்கள்.","ro":"Kaḍarkaraiyai varaipaḍattil kāṭṭunkaḷ.","lit":"plage[objet] (-ai) · plan[dans] (-il) · montrez [respect]"}],"tip":{"title":"« Eppaḍi » : comment, et comment aller quelque part","example":"Pardon, comment va-t-on à la plage ? — மன்னிக்கவும், கடற்கரைக்கு <b>எப்படிப்</b> போவது?","body":"Le mot « eppaḍi » veut dire comment. Pour demander son chemin, on dit le lieu avec « -kku », vers, puis « eppaḍi », puis « pōvatu », aller : « Kaḍarkaraikku eppaḍip pōvatu ? », mot à mot, plage-vers, comment, aller. C'est une phrase passe-partout : remplacez la plage par la gare ou le marché, et le tour est joué. « Eppaḍi » sert aussi à prendre des nouvelles : « Eppaḍi irukkirīrkaḷ ? », comment allez-vous, à quoi l'on répond « Naṉrāka irukkirēṉ », je vais bien. Et pour apprendre un mot nouveau : « Tamiḻil itai eppaḍich cholvatu ? », comment dit-on ça en tamoul. Le « ḍ » se prononce la langue légèrement retournée, avec un son doux. Astuce : « eppaḍi » ressemble à « et pas d'ici », ce que vous êtes justement quand vous cherchez votre chemin.","exampleRo":"Maṉṉikkavum, kaḍarkaraikku eppaḍip pōvatu?","lit":"pardon · plage[à] (-ukku) · comment · aller","say":{"Eppaḍi":"எப்படி","eppaḍi":"எப்படி","pōvatu":"போவது","Kaḍarkaraikku eppaḍip pōvatu ?":"கடற்கரைக்கு எப்படிப் போவது?","Eppaḍi irukkirīrkaḷ ?":"எப்படி இருக்கிறீர்கள்?","Naṉrāka irukkirēṉ":"நன்றாக இருக்கிறேன்","Tamiḻil itai eppaḍich cholvatu ?":"தமிழில் இதை எப்படிச் சொல்வது?"}}},{"title":"Un petit souci de santé","phrases":[{"fr":"Je ne me sens pas très bien aujourd'hui.","tgt":"இன்று எனக்கு உடம்பு சரியில்லை.","ro":"Iṉru eṉakku uḍampu chariyillai.","lit":"aujourd'hui · moi[à] (-ukku) · corps · pas correct"},{"fr":"Et j'ai mal à la tête depuis ce matin.","tgt":"காலையிலிருந்து தலைவலி.","ro":"Kālaiyiliruntu talaivali.","lit":"matin[depuis] (-iliruntu) · tête-douleur"},{"fr":"J'ai un peu de fièvre aussi.","tgt":"கொஞ்சம் காய்ச்சலும் இருக்கிறது.","ro":"Koncham kāychchalum irukkiratu.","lit":"un peu · fièvre[aussi] (-um) · se trouve"},{"fr":"Où se trouve la pharmacie ?","tgt":"மருந்துக் கடை எங்கே?","ro":"Maruntuk kaḍai enkē?","lit":"médicament · boutique · où"},{"fr":"Il y a une pharmacie là, au coin.","tgt":"முனையில் ஒரு மருந்துக் கடை இருக்கிறது.","ro":"Muṉaiyil oru maruntuk kaḍai irukkiratu.","lit":"coin[dans] (-il) · une · médicament · boutique · se trouve"},{"fr":"Donnez-moi un médicament contre la fièvre.","tgt":"காய்ச்சலுக்கு மருந்து கொடுங்கள்.","ro":"Kāychchalukku maruntu koḍunkaḷ.","lit":"fièvre[pour] (-ukku) · médicament · donnez [respect]"},{"fr":"Prenez ceci après le repas.","tgt":"சாப்பாட்டுக்குப் பிறகு இதைச் சாப்பிடுங்கள்.","ro":"Chāppāṭṭukkup piraku itaich chāppiḍunkaḷ.","lit":"repas[à] (-ukku) · après · ceci[objet] (-ai) · prenez [respect]"},{"fr":"Buvez beaucoup d'eau, surtout avec cette chaleur.","tgt":"இந்த வெயிலில் நிறையத் தண்ணீர் குடியுங்கள்.","ro":"Inta veyilil niraiyat taṇṇīr kuḍiyunkaḷ.","lit":"ce · soleil[dans] (-il) · beaucoup · eau · buvez [respect]"},{"fr":"C'est à cause du soleil.","tgt":"இது வெயிலால்தான்.","ro":"Itu veyilāltāṉ.","lit":"ceci · soleil[à cause de] (-āl)[justement] (-tāṉ)"},{"fr":"Aujourd'hui, restez au calme.","tgt":"இன்று ஓய்வு எடுங்கள்.","ro":"Iṉru ōyvu eḍunkaḷ.","lit":"aujourd'hui · repos · prenez [respect]"}]},{"title":"Une journée à la plage","phrases":[{"fr":"On peut se baigner à cet endroit ?","tgt":"இங்கே குளிக்க முடியுமா?","ro":"Inkē kuḷikka muḍiyumā?","lit":"ici · se baigner · possible[question] (-ā)"},{"fr":"Non, les vagues sont trop grosses.","tgt":"இல்லை, அலைகள் ரொம்பப் பெரியவை.","ro":"Illai, alaikaḷ rompap periyavai.","lit":"non · vagues · très · grandes"},{"fr":"On peut marcher sur le sable.","tgt":"மணலில் நடக்க முடியும்.","ro":"Maṇalil naḍakka muḍiyum.","lit":"sable[dans] (-il) · marcher · possible"},{"fr":"Je ne sais pas nager.","tgt":"என்னால் நீந்த முடியாது.","ro":"Eṉṉāl nīnta muḍiyātu.","lit":"moi[par] (-āl) · nager · impossible"},{"fr":"Pouvez-vous surveiller mon sac ?","tgt":"என் பையைப் பார்த்துக்கொள்ள முடியுமா?","ro":"Eṉ paiyaip pārttukkoḷḷa muḍiyumā?","lit":"mon · sac[objet] (-ai) · surveiller · possible[question] (-ā)"},{"fr":"Bien sûr, aucun souci.","tgt":"நிச்சயமாக, பரவாயில்லை.","ro":"Nichchayamāka, paravāyillai.","lit":"certainement · pas de souci"},{"fr":"On peut louer un vélo par ici ?","tgt":"இங்கே சைக்கிள் வாடகைக்குக் கிடைக்குமா?","ro":"Inkē chaikkiḷ vāḍakaikkuk kiḍaikkumā?","lit":"ici · vélo · location[pour] (-ukku) · se trouvera[question] (-ā)"},{"fr":"Demain, je ne peux pas venir.","tgt":"நாளை என்னால் வர முடியாது.","ro":"Nāḷai eṉṉāl vara muḍiyātu.","lit":"demain · moi[par] (-āl) · venir · impossible"},{"fr":"Ici, on peut manger du poisson frit.","tgt":"இங்கே வறுத்த மீன் சாப்பிட முடியும்.","ro":"Inkē varutta mīṉ chāppiḍa muḍiyum.","lit":"ici · frit · poisson · manger · possible"},{"fr":"Le ciel du soir est magnifique.","tgt":"மாலை வானம் ரொம்ப அழகு.","ro":"Mālai vāṉam rompa aḻaku.","lit":"soir · ciel · très · beauté"}],"tip":{"title":"« Muḍiyum » : pouvoir, c'est possible","example":"On peut se baigner à cet endroit ? — இங்கே குளிக்க <b>முடியுமா</b>?","body":"Pour dire qu'une chose est possible, le tamoul utilise « muḍiyum », c'est possible, juste après le verbe. « Kuḷikka muḍiyum » veut dire on peut se baigner. Pour en faire une question, on ajoute « -ā » : « Inkē kuḷikka muḍiyumā ? », mot à mot, ici, se baigner, possible-question. Le contraire est « muḍiyātu », c'est impossible. Quand on veut dire je ne peux pas, on met la personne avec « -āl », par : « Eṉṉāl nīnta muḍiyātu », mot à mot, par moi, nager, impossible. C'est très différent du français, où l'on dit je peux : ici, c'est l'action elle-même qui est possible ou non. Le « ḍ » du milieu se dit la langue retournée, tout en douceur. Astuce : retenez la paire « muḍiyumā ? » pour demander, et « muḍiyātu » pour refuser poliment.","exampleRo":"Inkē kuḷikka muḍiyumā?","lit":"ici · se baigner · possible[question] (-ā)","say":{"Muḍiyum":"முடியும்","muḍiyum":"முடியும்","Kuḷikka muḍiyum":"குளிக்க முடியும்","Inkē kuḷikka muḍiyumā ?":"இங்கே குளிக்க முடியுமா?","muḍiyātu":"முடியாது","Eṉṉāl nīnta muḍiyātu":"என்னால் நீந்த முடியாது","muḍiyumā ?":"முடியுமா?"}}},{"title":"Des billets pour les sites","phrases":[{"fr":"Où est-ce qu'on achète les billets ?","tgt":"டிக்கெட் எங்கே வாங்குவது?","ro":"Ṭikkeṭ enkē vānkuvatu?","lit":"billet · où · acheter"},{"fr":"Deux billets d'entrée, s'il vous plaît.","tgt":"இரண்டு டிக்கெட் கொடுங்கள்.","ro":"Iraṇḍu ṭikkeṭ koḍunkaḷ.","lit":"deux · billet · donnez [respect]"},{"fr":"Pour les étrangers, le billet est plus cher.","tgt":"வெளிநாட்டவர்களுக்கு டிக்கெட் விலை அதிகம்.","ro":"Veḷināṭṭavarkaḷukku ṭikkeṭ vilai atikam.","lit":"étrangers[pour] (-ukku) · billet · prix · élevé"},{"fr":"Il y a une réduction pour les étudiants ?","tgt":"மாணவர்களுக்குத் தள்ளுபடி உண்டா?","ro":"Māṇavarkaḷukkut taḷḷupaḍi uṇḍā?","lit":"étudiants[pour] (-ukku) · réduction · il y a[question] (-ā)"},{"fr":"Pour les enfants, l'entrée ne coûte rien.","tgt":"குழந்தைகளுக்கு இலவசம்.","ro":"Kuḻantaikaḷukku ilavacham.","lit":"enfants[pour] (-ukku) · gratuit"},{"fr":"Ce billet est valable toute la journée.","tgt":"இந்த டிக்கெட் நாள் முழுவதும் செல்லும்.","ro":"Inta ṭikkeṭ nāḷ muḻuvatum chellum.","lit":"ce · billet · jour · entier · est valable"},{"fr":"On ferme à six heures du soir.","tgt":"மாலை ஆறு மணிக்கு மூடுவார்கள்.","ro":"Mālai āru maṇikku mūḍuvārkaḷ.","lit":"soir · six · heure[à] (-ukku) · ils fermeront"},{"fr":"Les photos sont permises sur le site ?","tgt":"புகைப்படம் எடுக்க அனுமதி உண்டா?","ro":"Pukaippaḍam eḍukka aṉumati uṇḍā?","lit":"photo · prendre · permission · il y a[question] (-ā)"},{"fr":"Gardez bien votre billet.","tgt":"டிக்கெட்டைப் பத்திரமாக வைத்துக்கொள்ளுங்கள்.","ro":"Ṭikkeṭṭaip pattiramāka vaittukkoḷḷunkaḷ.","lit":"billet[objet] (-ai) · soigneusement · gardez [respect]"},{"fr":"Voici la sortie.","tgt":"இதோ வெளியே போகும் வழி.","ro":"Itō veḷiyē pōkum vaḻi.","lit":"voici · dehors · allant · chemin"}]},{"title":"Rentrer à Chennai","phrases":[{"fr":"Demain, je rentre à Chennai.","tgt":"நான் நாளை சென்னைக்குத் திரும்புகிறேன்.","ro":"Nāṉ nāḷai Cheṉṉaikkut tirumpukirēṉ.","lit":"je · demain · Chennai[à] (-ukku) · retourne"},{"fr":"En bus ou en train ?","tgt":"பஸ்ஸிலா, ரயிலிலா?","ro":"Passilā, rayililā?","lit":"bus[dans][question] (-ilā) · train[dans][question] (-ilā)"},{"fr":"En train, c'est plus confortable.","tgt":"ரயிலில் வசதியாக இருக்கும்.","ro":"Rayilil vachatiyāka irukkum.","lit":"train[dans] (-il) · confortable[-ment] (-āka) · sera"},{"fr":"En bus, ça coûte moins cher.","tgt":"பஸ்ஸில் செலவு குறைவு.","ro":"Passil chelavu kuraivu.","lit":"bus[dans] (-il) · dépense · faible"},{"fr":"Je vais à la gare en rickshaw.","tgt":"நான் ஆட்டோவில் ரயில் நிலையத்துக்குப் போகிறேன்.","ro":"Nāṉ āṭṭōvil rayil nilaiyattukkup pōkirēṉ.","lit":"je · auto[dans] (-il) · train · gare[à] (-ukku) · vais"},{"fr":"Mon ami vient à moto.","tgt":"என் நண்பன் பைக்கில் வருகிறான்.","ro":"Eṉ naṇpaṉ paikkil varukirāṉ.","lit":"mon · ami · moto[dans] (-il) · vient"},{"fr":"Dans le train, je lis un livre.","tgt":"ரயிலில் நான் புத்தகம் படிக்கிறேன்.","ro":"Rayilil nāṉ puttakam paḍikkirēṉ.","lit":"train[dans] (-il) · je · livre · lis"},{"fr":"Le train pour Chennai part à quelle heure ?","tgt":"சென்னை ரயில் எத்தனை மணிக்குக் கிளம்புகிறது?","ro":"Cheṉṉai rayil ettaṉai maṇikkuk kiḷampukiratu?","lit":"Chennai · train · combien · heure[à] (-ukku) · part"},{"fr":"On peut acheter le billet dans le bus ?","tgt":"பஸ்ஸில் டிக்கெட் வாங்க முடியுமா?","ro":"Passil ṭikkeṭ vānka muḍiyumā?","lit":"bus[dans] (-il) · billet · acheter · possible[question] (-ā)"},{"fr":"Oui, c'est le receveur qui donne les billets.","tgt":"ஆமாம், கண்டக்டர் டிக்கெட் கொடுப்பார்.","ro":"Āmām, kaṇḍakṭar ṭikkeṭ koḍuppār.","lit":"oui · receveur · billet · donnera [respect]"}],"tip":{"title":"« -il » + transport : en bus, en train, en rickshaw","example":"Je vais à la gare en rickshaw. — நான் <b>ஆட்டோவில்</b> ரயில் நிலையத்துக்குப் போகிறேன்.","body":"Pour dire comment on voyage, le tamoul utilise la même terminaison que pour dans : « -il ». On dit littéralement dans le bus, dans le train, dans l'auto. « Pas », le bus, qu'on prononce presque « bass », devient « passil », en bus. « Rayil », le train, devient « rayilil », en train, et « āṭṭō » devient « āṭṭōvil », en rickshaw. Remarquez le petit « v » qui se glisse après le « ō », pour que les deux voyelles ne se cognent pas. Exemple : « Nāṉ āṭṭōvil rayil nilaiyattukkup pōkirēṉ », mot à mot, je, auto-dans, gare-vers, vais. Pour demander quel moyen choisir, on ajoute « -ā » : « Passilā, rayililā ? », en bus ou en train. Astuce : imaginez-vous assis dedans, et le « -il » viendra tout seul.","exampleRo":"Nāṉ āṭṭōvil rayil nilaiyattukkup pōkirēṉ.","lit":"je · auto[dans] (-il) · train · gare[à] (-ukku) · vais","say":{"Pas":"பஸ்","passil":"பஸ்ஸில்","Rayil":"ரயில்","rayilil":"ரயிலில்","āṭṭō":"ஆட்டோ","āṭṭōvil":"ஆட்டோவில்","Nāṉ āṭṭōvil rayil nilaiyattukkup pōkirēṉ":"நான் ஆட்டோவில் ரயில் நிலையத்துக்குப் போகிறேன்","Passilā, rayililā ?":"பஸ்ஸிலா, ரயிலிலா?"}}},{"title":"Café filtre et douceurs","phrases":[{"fr":"J'adore le café de cette ville.","tgt":"எனக்கு இந்த ஊர் காபி ரொம்பப் பிடிக்கும்.","ro":"Eṉakku inta ūr kāpi rompap piḍikkum.","lit":"moi[à] (-ukku) · cette · ville · café · très · plaît"},{"fr":"On le verse de très haut.","tgt":"உயரத்திலிருந்து ஊற்றுகிறார்கள்.","ro":"Uyarattiliruntu ūrrukirārkaḷ.","lit":"hauteur[depuis] (-iliruntu) · ils versent"},{"fr":"Comme ça, il y a de la mousse.","tgt":"அப்போது நுரை வருகிறது.","ro":"Appōtu nurai varukiratu.","lit":"alors · mousse · vient"},{"fr":"Mettez peu de sucre, s'il vous plaît.","tgt":"சர்க்கரை கொஞ்சமாகப் போடுங்கள்.","ro":"Charkkarai konchamākap pōḍunkaḷ.","lit":"sucre · peu[-ment] (-āka) · mettez [respect]"},{"fr":"Je voudrais aussi un vada.","tgt":"எனக்கு ஒரு வடையும் வேண்டும்.","ro":"Eṉakku oru vaḍaiyum vēṇḍum.","lit":"moi[à] (-ukku) · un · vada[aussi] (-um) · [il faut]"},{"fr":"Cette douceur est très sucrée.","tgt":"இந்த இனிப்பு ரொம்பத் தித்திப்பு.","ro":"Inta iṉippu rompat tittippu.","lit":"cette · douceur · très · sucrée"},{"fr":"Comment ça s'appelle ?","tgt":"இதன் பெயர் என்ன?","ro":"Itaṉ peyar eṉṉa?","lit":"ceci[de] (-aṉ) · nom · quoi"},{"fr":"C'est du mysore pak.","tgt":"இது மைசூர் பாக்.","ro":"Itu Maichūr pāk.","lit":"ceci · mysore pak"},{"fr":"J'en prends une boîte pour ma famille.","tgt":"என் குடும்பத்துக்கு ஒரு பெட்டி வாங்குகிறேன்.","ro":"Eṉ kuḍumpattukku oru peṭṭi vānkukirēṉ.","lit":"ma · famille[pour] (-ukku) · une · boîte · achète"},{"fr":"Le café ne coûte que vingt roupies.","tgt":"காபி இருபது ரூபாய்தான்.","ro":"Kāpi irupatu rūpāytāṉ.","lit":"café · vingt · roupie[seulement] (-tāṉ)"}]},{"title":"Autour de la pension","phrases":[{"fr":"La plage, c'est loin d'ici ?","tgt":"கடற்கரை இங்கிருந்து தூரமா?","ro":"Kaḍarkarai inkiruntu tūramā?","lit":"plage · ici[depuis] (-iruntu) · loin[question] (-ā)"},{"fr":"Non, non, elle est toute proche.","tgt":"இல்லை, ரொம்பப் பக்கம்.","ro":"Illai, rompap pakkam.","lit":"non · très · près"},{"fr":"Le marché est un peu loin.","tgt":"சந்தை கொஞ்சம் தூரம்.","ro":"Chantai koncham tūram.","lit":"marché · un peu · loin"},{"fr":"La pharmacie est à côté de la pension.","tgt":"மருந்துக் கடை விடுதிக்குப் பக்கத்தில் இருக்கிறது.","ro":"Maruntuk kaḍai viḍutikkup pakkattil irukkiratu.","lit":"médicament · boutique · pension[à] (-ukku) · côté[dans] (-il) · se trouve"},{"fr":"Il y a un petit restaurant près d'ici ?","tgt":"இங்கே பக்கத்தில் ஒரு சின்ன உணவகம் இருக்கிறதா?","ro":"Inkē pakkattil oru chiṉṉa uṇavakam irukkiratā?","lit":"ici · côté[dans] (-il) · un · petit · restaurant · se trouve[question] (-ā)"},{"fr":"Oui, il y en a un juste à côté.","tgt":"ஆமாம், பக்கத்திலேயே.","ro":"Āmām, pakkattilēyē.","lit":"oui · côté[dans] (-il)[même] (-ē)"},{"fr":"C'est trop loin pour y aller à pied.","tgt":"நடந்து போக ரொம்பத் தூரம்.","ro":"Naḍantu pōka rompat tūram.","lit":"en marchant · aller · très · loin"},{"fr":"Il faut combien de minutes ?","tgt":"எத்தனை நிமிடம் ஆகும்?","ro":"Ettaṉai nimiḍam ākum?","lit":"combien · minute · prendra"},{"fr":"Ma chambre est près de la mer.","tgt":"என் அறை கடலுக்குப் பக்கத்தில் இருக்கிறது.","ro":"Eṉ arai kaḍalukkup pakkattil irukkiratu.","lit":"ma · chambre · mer[à] (-ukku) · côté[dans] (-il) · se trouve"},{"fr":"La France, c'est très loin d'ici.","tgt":"பிரான்ஸ் இங்கிருந்து ரொம்பத் தூரம்.","ro":"Pirāṉs inkiruntu rompat tūram.","lit":"France · ici[depuis] (-iruntu) · très · loin"}],"tip":{"title":"« Tūram » et « pakkam » : loin et près","example":"La plage, c'est loin d'ici ? — கடற்கரை இங்கிருந்து <b>தூரமா</b>?","body":"Deux mots très pratiques en voyage : « tūram », loin, et « pakkam », près ou à côté. Ils s'utilisent sans verbe être : « Kaḍarkarai inkiruntu tūramā ? », mot à mot, plage, ici-depuis, loin-question. On répond « rompap pakkam », tout près, ou « koncham tūram », un peu loin. Pour situer précisément, on dit le repère avec « -kku », puis « pakkattil », à côté : « kaḍalukkup pakkattil », à côté de la mer. Et « pakkattilēyē » veut dire juste à côté. Le « ū » de « tūram » est long, comme un « ou » qu'on étire, et le « t » se dit sans souffle. Astuce : « pakkam », c'est le pas qu'on fait pour aller tout près, et « tūram », c'est le grand tour qu'il faut faire quand c'est loin.","exampleRo":"Kaḍarkarai inkiruntu tūramā?","lit":"plage · ici[depuis] (-iruntu) · loin[question] (-ā)","say":{"Tūram":"தூரம்","pakkam":"பக்கம்","tūram":"தூரம்","Kaḍarkarai inkiruntu tūramā ?":"கடற்கரை இங்கிருந்து தூரமா?","rompap pakkam":"ரொம்பப் பக்கம்","koncham tūram":"கொஞ்சம் தூரம்","pakkattil":"பக்கத்தில்","kaḍalukkup pakkattil":"கடலுக்குப் பக்கத்தில்","pakkattilēyē":"பக்கத்திலேயே"}}},{"title":"Un bus en retard","phrases":[{"fr":"Le bus n'est pas encore arrivé.","tgt":"பஸ் இன்னும் வரவில்லை.","ro":"Pas iṉṉum varavillai.","lit":"bus · encore · pas venu"},{"fr":"Il a une demi-heure de retard.","tgt":"அரை மணி நேரம் தாமதம்.","ro":"Arai maṇi nēram tāmatam.","lit":"demi · heure · temps · retard"},{"fr":"Pourquoi un tel retard ?","tgt":"ஏன் இவ்வளவு தாமதம்?","ro":"Ēṉ ivvaḷavu tāmatam?","lit":"pourquoi · autant · retard"},{"fr":"Il y a beaucoup de circulation.","tgt":"போக்குவரத்து நெரிசல் அதிகம்.","ro":"Pōkkuvarattu nerichal atikam.","lit":"circulation · encombrement · beaucoup"},{"fr":"Le prochain bus passe à quelle heure ?","tgt":"அடுத்த பஸ் எத்தனை மணிக்கு?","ro":"Aḍutta pas ettaṉai maṇikku?","lit":"prochain · bus · combien · heure[à] (-ukku)"},{"fr":"Dans vingt minutes à peu près.","tgt":"சுமார் இருபது நிமிடத்தில்.","ro":"Chumār irupatu nimiḍattil.","lit":"environ · vingt · minute[dans] (-il)"},{"fr":"Alors j'attends ici.","tgt":"அப்படியென்றால் நான் இங்கேயே காத்திருக்கிறேன்.","ro":"Appaḍiyeṉrāl nāṉ inkēyē kāttirukkirēṉ.","lit":"alors · je · ici[même] (-ē) · attends"},{"fr":"Je me sens fatigué.","tgt":"எனக்குக் களைப்பாக இருக்கிறது.","ro":"Eṉakkuk kaḷaippāka irukkiratu.","lit":"moi[à] (-ukku) · fatigue[-ment] (-āka) · est"},{"fr":"Le voilà enfin !","tgt":"அதோ, கடைசியில் வந்துவிட்டது!","ro":"Atō, kaḍaichiyil vantuviṭṭatu!","lit":"le voilà · finalement · est arrivé"},{"fr":"Vite, on monte !","tgt":"சீக்கிரம் ஏறுவோம்!","ro":"Chīkkiram ēruvōm!","lit":"vite · montons"}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"J'ai voyagé avec mon ami.","tgt":"நான் என் நண்பனோடு பயணம் செய்தேன்.","ro":"Nāṉ eṉ naṇpaṉōḍu payaṇam cheytēṉ.","lit":"je · mon · ami[avec] (-ōḍu) · voyage · ai fait"},{"fr":"Nous avons vu Pondichéry et Mahabalipuram.","tgt":"நாங்கள் பாண்டிச்சேரியையும் மாமல்லபுரத்தையும் பார்த்தோம்.","ro":"Nānkaḷ Pāṇḍichchēriyaiyum Māmallapurattaiyum pārttōm.","lit":"nous · Pondichéry[objet][et] (-aiyum) · Mahabalipuram[objet][et] (-aiyum) · avons vu"},{"fr":"J'ai parlé tamoul avec les gens.","tgt":"நான் மக்களோடு தமிழ் பேசினேன்.","ro":"Nāṉ makkaḷōḍu Tamiḻ pēchiṉēṉ.","lit":"je · gens[avec] (-ōḍu) · tamoul · ai parlé"},{"fr":"J'ai même parlé avec le chauffeur de rickshaw !","tgt":"ஆட்டோக்காரரோடும் பேசினேன்!","ro":"Āṭṭōkkārarōḍum pēchiṉēṉ!","lit":"chauffeur d'auto[avec][aussi] (-ōḍum) · [j']ai parlé"},{"fr":"Dans ce module, on a appris les mots du voyage.","tgt":"இந்தப் பாடத்தில் பயணச் சொற்களைக் கற்றோம்.","ro":"Intap pāḍattil payaṇach chorkaḷaik karrōm.","lit":"cette · leçon[dans] (-il) · voyage · mots[objet] (-ai) · avons appris"},{"fr":"On sait demander un prix en tamoul.","tgt":"தமிழில் விலை கேட்கத் தெரியும்.","ro":"Tamiḻil vilai kēṭkat teriyum.","lit":"tamoul[dans] (-il) · prix · demander · [on] sait"},{"fr":"On sait aussi demander son chemin.","tgt":"வழி கேட்கவும் தெரியும்.","ro":"Vaḻi kēṭkavum teriyum.","lit":"chemin · demander[aussi] (-um) · [on] sait"},{"fr":"Ces petits mots sont très utiles.","tgt":"இந்தச் சின்ன சொற்கள் ரொம்பப் பயனுள்ளவை.","ro":"Intach chiṉṉa chorkaḷ rompap payaṉuḷḷavai.","lit":"ces · petits · mots · très · utiles"},{"fr":"Le tamoul devient facile, petit à petit !","tgt":"தமிழ் கொஞ்சம் கொஞ்சமாக எளிதாகிறது!","ro":"Tamiḻ koncham konchamāka eḷitākiratu!","lit":"tamoul · peu · peu[-ment] (-āka) · devient facile"},{"fr":"La prochaine fois, je viens avec ma famille.","tgt":"அடுத்த முறை என் குடும்பத்தோடு வருவேன்.","ro":"Aḍutta murai eṉ kuḍumpattōḍu varuvēṉ.","lit":"prochaine · fois · ma · famille[avec] (-ōḍu) · viendrai"}],"tip":{"title":"« -ōḍu » : avec quelqu'un","example":"J'ai voyagé avec mon ami. — நான் என் <b>நண்பனோடு</b> பயணம் செய்தேன்.","body":"Pour dire avec quelqu'un, on colle « -ōḍu » à la fin du nom. « Naṇpaṉ », l'ami, devient « naṇpaṉōḍu », avec l'ami. « Kuḍumpam », la famille, devient « kuḍumpattōḍu », avec la famille. Exemple : « Nāṉ eṉ naṇpaṉōḍu payaṇam cheytēṉ », mot à mot, je, mon ami-avec, voyage, ai fait. Encore une fois, le tamoul met le petit mot derrière, là où le français le met devant. On peut ajouter « -um » pour dire aussi : « āṭṭōkkārarōḍum », avec le chauffeur aussi. Bravo, vous avez terminé ce module de voyage : vous savez maintenant demander un billet, un prix et votre chemin. Astuce : « ōḍu » ressemble à « au doux », car on voyage plus doucement avec quelqu'un.","exampleRo":"Nāṉ eṉ naṇpaṉōḍu payaṇam cheytēṉ.","lit":"je · mon · ami[avec] (-ōḍu) · voyage · ai fait","say":{"Naṇpaṉ":"நண்பன்","naṇpaṉōḍu":"நண்பனோடு","Kuḍumpam":"குடும்பம்","kuḍumpattōḍu":"குடும்பத்தோடு","Nāṉ eṉ naṇpaṉōḍu payaṇam cheytēṉ":"நான் என் நண்பனோடு பயணம் செய்தேன்","āṭṭōkkārarōḍum":"ஆட்டோக்காரரோடும்"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"La rencontre chez Ravi","phrases":[{"fr":"Bonsoir, moi, c'est Lucas.","tgt":"வணக்கம், என் பெயர் லூக்காஸ்.","ro":"Vaṇakkam, eṉ peyar Lūkkās.","lit":"bonjour · mon · nom · Lucas"},{"fr":"Et moi, Meena. Enchantée !","tgt":"நான் மீனா. மகிழ்ச்சி!","ro":"Nāṉ Mīṉā. Magiḻcchi!","lit":"je · Meena · joie"},{"fr":"Tu travailles avec Ravi, c'est ça ?","tgt":"நீ ரவியுடன் வேலை செய்கிறாயா?","ro":"Nī Raviyuḍaṉ vēlai cheygiṛāyā?","lit":"toi · Ravi-[avec] · travail · fais-[question]"},{"fr":"Oui, Ravi et moi, on travaille ensemble.","tgt":"ஆமாம், நானும் ரவியும் ஒன்றாக வேலை செய்கிறோம்.","ro":"Āmām, nāṉum Raviyum oṉṛāga vēlai cheygiṛōm.","lit":"oui · moi-et · Ravi-et · ensemble · travail · faisons"},{"fr":"Tu es la petite sœur de Ravi ?","tgt":"நீ ரவியின் தங்கையா?","ro":"Nī Raviyiṉ tangaiyā?","lit":"toi · Ravi-[de] · petite sœur-[question]"},{"fr":"Oui, c'est mon grand frère.","tgt":"ஆமாம், அவன் என் அண்ணன்.","ro":"Āmām, avaṉ eṉ aṇṇaṉ.","lit":"oui · lui · mon · grand frère"},{"fr":"Et toi, tu viens de quelle ville ?","tgt":"நீ எந்த ஊர்?","ro":"Nī enda ūr?","lit":"toi · quelle · ville"},{"fr":"Ma ville, c'est Lyon, en France.","tgt":"என் ஊர் லியோன், பிரான்ஸில்.","ro":"Eṉ ūr Liyōṉ, Pirāṉsil.","lit":"ma · ville · Lyon · France-[dans]"},{"fr":"Moi, je suis une vraie fille de Madurai.","tgt":"நான் மதுரைக்காரி.","ro":"Nāṉ Maduraikkāri.","lit":"je · Madurai-[femme de]"},{"fr":"Très heureux de te connaître, Meena.","tgt":"ரொம்ப மகிழ்ச்சி, மீனா.","ro":"Romba magiḻcchi, Mīṉā.","lit":"très · joie · Meena"}]},{"title":"Dans la maison de Ravi","phrases":[{"fr":"Voici ma maison, entre donc !","tgt":"இது என் வீடு, உள்ளே வா!","ro":"Idu eṉ vīḍu, uḷḷē vā!","lit":"ceci · ma · maison · dedans · viens"},{"fr":"Ta maison est vraiment jolie.","tgt":"உன் வீடு ரொம்ப அழகு.","ro":"Uṉ vīḍu romba aḻagu.","lit":"ta · maison · très · beauté"},{"fr":"C'est le scooter de Ravi ?","tgt":"இது ரவியுடைய வண்டியா?","ro":"Idu Raviyuḍaiya vaṇḍiyā?","lit":"ceci · Ravi-[de] · scooter-[question]"},{"fr":"Non, c'est le scooter de mon père.","tgt":"இல்லை, இது என் அப்பாவுடைய வண்டி.","ro":"Illai, idu eṉ appāvuḍaiya vaṇḍi.","lit":"non · ceci · mon · père-[de] · scooter"},{"fr":"Et ici, c'est ma chambre.","tgt":"இது என் அறை.","ro":"Idu eṉ aṛai.","lit":"ceci · ma · chambre"},{"fr":"Votre maison est grande, monsieur.","tgt":"உங்கள் வீடு பெரியது, ஐயா.","ro":"Ungaḷ vīḍu periyadu, aiyā.","lit":"votre · maison · grande · monsieur [respect]"},{"fr":"Où est passé mon téléphone ?","tgt":"என் போன் எங்கே?","ro":"Eṉ pōṉ engē?","lit":"mon · téléphone · où"},{"fr":"Ton téléphone est sur la table.","tgt":"உன் போன் மேஜை மேல் இருக்கிறது.","ro":"Uṉ pōṉ mējai mēl irukkiṛadu.","lit":"ton · téléphone · table · sur · se trouve"},{"fr":"Ce petit chat, c'est celui de Meena.","tgt":"இது மீனாவுடைய பூனை.","ro":"Idu Mīṉāvuḍaiya pūṉai.","lit":"ceci · Meena-[de] · chat"},{"fr":"Ma maison est juste à côté d'ici.","tgt":"என் வீடு இங்கே பக்கத்தில்.","ro":"Eṉ vīḍu ingē pakkattil.","lit":"ma · maison · ici · à côté-[dans]"}],"tip":{"title":"Le possessif : « eṉ », « ungaḷ » et « -uḍaiya »","example":"Non, c'est le scooter de mon père. — இல்லை, இது <b>என்</b> <b>அப்பாவுடைய</b> வண்டி.","body":"Pour dire « mon » ou « ma », le tamoul utilise un seul petit mot, « eṉ », placé devant le nom, sans se soucier du masculin ou du féminin : « eṉ vīḍu », ma maison, « eṉ appā », mon père. Entre amis, « ton » se dit « uṉ », et avec une personne qu'on respecte, on dit « ungaḷ », votre : « ungaḷ vīḍu periyadu », votre maison est grande. Pour parler de ce qui appartient à quelqu'un d'autre, on colle « -uḍaiya » à la fin de son nom, comme un « de » placé après le nom au lieu d'avant. Ainsi « Raviyuḍaiya vaṇḍi » se décompose en Ravi, de, scooter : le scooter de Ravi. Le propriétaire vient donc toujours en premier, et l'objet ensuite. Quand le nom finit par une voyelle, on glisse un petit son de liaison : Ravi devient « Raviyuḍaiya », Meena devient « Mīṉāvuḍaiya ». Astuce pour retenir : en tamoul, on annonce d'abord le propriétaire, puis on montre l'objet, comme en français familier quand on dit « Ravi, son scooter ».","exampleRo":"Illai, idu eṉ appāvuḍaiya vaṇḍi.","lit":"non · ceci · mon · père-[de] · scooter","say":{"eṉ":"என்","ungaḷ":"உங்கள்","eṉ vīḍu":"என் வீடு","eṉ appā":"என் அப்பா","uṉ":"உன்","ungaḷ vīḍu periyadu":"உங்கள் வீடு பெரியது","Raviyuḍaiya vaṇḍi":"ரவியுடைய வண்டி","Raviyuḍaiya":"ரவியுடைய","Mīṉāvuḍaiya":"மீனாவுடைய"}}},{"title":"D'où viens-tu ?","phrases":[{"fr":"Tu viens de quel pays, exactement ?","tgt":"நீ எந்த நாட்டிலிருந்து வருகிறாய்?","ro":"Nī enda nāṭṭilirundu varugiṛāy?","lit":"toi · quel · pays-[depuis] · viens"},{"fr":"Je viens de France, du côté de Lyon.","tgt":"நான் பிரான்ஸிலிருந்து வருகிறேன், லியோன் பக்கம்.","ro":"Nāṉ Pirāṉsilirundu varugiṛēṉ, Liyōṉ pakkam.","lit":"je · France-[depuis] · viens · Lyon · côté"},{"fr":"Tu vis à Madurai maintenant ?","tgt":"இப்போது மதுரையில் இருக்கிறாயா?","ro":"Ippōdu Maduraiyil irukkiṛāyā?","lit":"maintenant · Madurai-[dans] · es-[question]"},{"fr":"Oui, j'habite près du marché aux fleurs.","tgt":"ஆமாம், பூச்சந்தை பக்கத்தில் இருக்கிறேன்.","ro":"Āmām, pūcchandai pakkattil irukkiṛēṉ.","lit":"oui · marché aux fleurs · à côté-[dans] · suis"},{"fr":"Ta famille est restée en France ?","tgt":"உன் குடும்பம் பிரான்ஸிலா?","ro":"Uṉ kuḍumbam Pirāṉsilā?","lit":"ta · famille · France-[dans]-[question]"},{"fr":"Oui, mes parents vivent à Lyon.","tgt":"ஆமாம், என் அப்பா அம்மா லியோனில் இருக்கிறார்கள்.","ro":"Āmām, eṉ appā ammā Liyōṉil irukkiṛārgaḷ.","lit":"oui · mon · père · mère · Lyon-[dans] · sont"},{"fr":"Tu parles un peu tamoul ?","tgt":"நீ கொஞ்சம் தமிழ் பேசுகிறாயா?","ro":"Nī konjam tamiḻ pēchugiṛāyā?","lit":"toi · un peu · tamoul · parles-[question]"},{"fr":"Un petit peu, j'apprends encore.","tgt":"கொஞ்சம், நான் இன்னும் கற்றுக்கொள்கிறேன்.","ro":"Konjam, nāṉ iṉṉum kaṛṛukkoḷgiṛēṉ.","lit":"un peu · je · encore · apprends"},{"fr":"Ton tamoul est déjà plutôt bon !","tgt":"உன் தமிழ் நன்றாக இருக்கிறது!","ro":"Uṉ tamiḻ naṉṛāga irukkiṛadu!","lit":"ton · tamoul · bien · est"},{"fr":"Madurai est une ville très ancienne.","tgt":"மதுரை ரொம்ப பழைய ஊர்.","ro":"Madurai romba paḻaiya ūr.","lit":"Madurai · très · vieille · ville"}]},{"title":"Les dosas partagés","phrases":[{"fr":"Tu aimes les dosas, toi ?","tgt":"உனக்கு தோசை பிடிக்குமா?","ro":"Uṉakku tōchai piḍikkumā?","lit":"toi-[à] · dosa · plaît-[question]"},{"fr":"Oui, j'adore les dosas bien croustillants.","tgt":"ஆமாம், எனக்கு மொறுமொறு தோசை ரொம்ப பிடிக்கும்.","ro":"Āmām, eṉakku moṛumoṛu tōchai romba piḍikkum.","lit":"oui · moi-[à] · croustillant · dosa · très · plaît"},{"fr":"Je n'aime pas les plats trop piquants.","tgt":"எனக்கு ரொம்ப காரம் பிடிக்காது.","ro":"Eṉakku romba kāram piḍikkādu.","lit":"moi-[à] · trop · piquant · ne plaît pas"},{"fr":"Tu aimes le chutney de noix de coco ?","tgt":"உனக்கு தேங்காய் சட்னி பிடிக்குமா?","ro":"Uṉakku tēngāy chaṭṉi piḍikkumā?","lit":"toi-[à] · noix de coco · chutney · plaît-[question]"},{"fr":"Meena adore le sambar.","tgt":"மீனாவுக்கு சாம்பார் ரொம்ப பிடிக்கும்.","ro":"Mīṉāvukku chāmbār romba piḍikkum.","lit":"Meena-[à] · sambar · très · plaît"},{"fr":"On partage ce dosa tous les deux ?","tgt":"இந்த தோசையை பகிர்ந்து சாப்பிடலாமா?","ro":"Inda tōchaiyai pagirndu chāppiḍalāmā?","lit":"ce · dosa-[objet] · en partageant · manger-on peut-[question]"},{"fr":"Bien sûr, il est délicieux !","tgt":"கண்டிப்பாக, ரொம்ப ருசியாக இருக்கிறது!","ro":"Kaṇḍippāga, romba ruchiyāga irukkiṛadu!","lit":"bien sûr · très · savoureux · est"},{"fr":"Et le café, tu aimes ?","tgt":"காபி உனக்கு பிடிக்குமா?","ro":"Kāpi uṉakku piḍikkumā?","lit":"café · toi-[à] · plaît-[question]"},{"fr":"Non, moi, j'aime le thé.","tgt":"இல்லை, எனக்கு டீ பிடிக்கும்.","ro":"Illai, eṉakku ṭī piḍikkum.","lit":"non · moi-[à] · thé · plaît"},{"fr":"Ici, tout le monde aime les dosas.","tgt":"இங்கே எல்லோருக்கும் தோசை பிடிக்கும்.","ro":"Ingē ellōrukkum tōchai piḍikkum.","lit":"ici · tous-[à] · dosa · plaît"}],"tip":{"title":"« Piḍikkum » : aimer, ça me plaît","example":"Tu aimes les dosas, toi ? — <b>உனக்கு</b> தோசை <b>பிடிக்குமா</b>?","body":"En tamoul, on ne dit pas « j'aime les dosas » mais plutôt « à moi, les dosas plaisent ». La personne qui aime prend la marque « -kku », qui veut dire « à » : « eṉakku », à moi, « uṉakku », à toi, « Mīṉāvukku », à Meena. Ensuite vient la chose aimée, et enfin le verbe « piḍikkum », ça plaît, toujours en fin de phrase. Décomposons « eṉakku tōchai piḍikkum » : à moi, dosa, plaît, donc j'aime les dosas. Pour poser la question, on ajoute simplement « -ā » au bout du verbe : « uṉakku kāpi piḍikkumā ? », le café te plaît ? Pour dire non, « piḍikkum » devient « piḍikkādu », ça ne plaît pas : « eṉakku kāram piḍikkādu », je n'aime pas le piquant. Et pour dire qu'on adore, on ajoute « romba », très, juste avant. Astuce : pensez à la tournure française « ça me plaît », où c'est la chose qui agit, et vous aurez exactement la logique tamoule.","exampleRo":"Uṉakku tōchai piḍikkumā?","lit":"toi-[à] · dosa · plaît-[question]","say":{"Piḍikkum":"பிடிக்கும்","eṉakku":"எனக்கு","uṉakku":"உனக்கு","Mīṉāvukku":"மீனாவுக்கு","piḍikkum":"பிடிக்கும்","eṉakku tōchai piḍikkum":"எனக்கு தோசை பிடிக்கும்","uṉakku kāpi piḍikkumā ?":"உனக்கு காபி பிடிக்குமா?","piḍikkādu":"பிடிக்காது","eṉakku kāram piḍikkādu":"எனக்கு காரம் பிடிக்காது","romba":"ரொம்ப"}}},{"title":"Le travail de chacun","phrases":[{"fr":"Tu fais quoi, comme travail ?","tgt":"நீ என்ன வேலை செய்கிறாய்?","ro":"Nī eṉṉa vēlai cheygiṛāy?","lit":"toi · quel · travail · fais"},{"fr":"J'enseigne le français dans une école.","tgt":"நான் ஒரு பள்ளியில் பிரெஞ்சு கற்பிக்கிறேன்.","ro":"Nāṉ oru paḷḷiyil pirenju kaṛpikkiṛēṉ.","lit":"je · une · école-[dans] · français · enseigne"},{"fr":"Ravi, lui, travaille dans une banque.","tgt":"ரவி ஒரு வங்கியில் வேலை செய்கிறார்.","ro":"Ravi oru vangiyil vēlai cheygiṛār.","lit":"Ravi · une · banque-[dans] · travail · fait [respect]"},{"fr":"Meena est étudiante en médecine.","tgt":"மீனா மருத்துவ மாணவி.","ro":"Mīṉā maruttuva māṇavi.","lit":"Meena · médecine · étudiante"},{"fr":"Et ton boulot, il te plaît ?","tgt":"உனக்கு உன் வேலை பிடிக்குமா?","ro":"Uṉakku uṉ vēlai piḍikkumā?","lit":"toi-[à] · ton · travail · plaît-[question]"},{"fr":"Oui, même si c'est un peu fatigant.","tgt":"ஆமாம், ஆனால் கொஞ்சம் களைப்பு.","ro":"Āmām, āṉāl konjam kaḷaippu.","lit":"oui · mais · un peu · fatigue"},{"fr":"Mon bureau est près de la gare.","tgt":"என் அலுவலகம் ரயில் நிலையம் பக்கத்தில்.","ro":"Eṉ aluvalagam rayil nilaiyam pakkattil.","lit":"mon · bureau · train · gare · à côté-[dans]"},{"fr":"Le matin, tu commences à quelle heure ?","tgt":"காலையில் எத்தனை மணிக்கு வேலை?","ro":"Kālaiyil ettaṉai maṇikku vēlai?","lit":"matin-[dans] · combien · heure-[à] · travail"},{"fr":"Je commence à neuf heures et je finis à cinq.","tgt":"ஒன்பது மணிக்கு ஆரம்பம், ஐந்து மணிக்கு முடிவு.","ro":"Oṉbadu maṇikku ārambam, aindu maṇikku muḍivu.","lit":"neuf · heure-[à] · début · cinq · heure-[à] · fin"},{"fr":"Le samedi, je suis en repos.","tgt":"சனிக்கிழமை எனக்கு வேலை இல்லை.","ro":"Chaṉikkiḻamai eṉakku vēlai illai.","lit":"samedi · moi-[à] · travail · il n'y a pas"}]},{"title":"La famille qui reçoit","phrases":[{"fr":"Voilà mon père et ma mère.","tgt":"இவர்கள் என் அப்பா, அம்மா.","ro":"Ivargaḷ eṉ appā, ammā.","lit":"ceux-ci · mon · père · mère"},{"fr":"Bonsoir, monsieur, bonsoir, madame.","tgt":"வணக்கம் ஐயா, வணக்கம் அம்மா.","ro":"Vaṇakkam aiyā, vaṇakkam ammā.","lit":"bonjour · monsieur · bonjour · madame (mère)"},{"fr":"Voici mon grand frère, Arun.","tgt":"இவர் என் அண்ணன் அருண்.","ro":"Ivar eṉ aṇṇaṉ Aruṇ.","lit":"celui-ci [respect] · mon · grand frère · Arun"},{"fr":"Et voici ma grande sœur, Kavitha.","tgt":"இவர் என் அக்கா கவிதா.","ro":"Ivar eṉ akkā Kavidā.","lit":"celle-ci [respect] · ma · grande sœur · Kavitha"},{"fr":"Tu as un grand frère ou une grande sœur ?","tgt":"உனக்கு அண்ணன், அக்கா இருக்கிறார்களா?","ro":"Uṉakku aṇṇaṉ, akkā irukkiṛārgaḷā?","lit":"toi-[à] · grand frère · grande sœur · il y a-[question]"},{"fr":"J'ai une grande sœur, elle vit en France.","tgt":"எனக்கு பிரான்ஸில் ஒரு அக்கா இருக்கிறார்.","ro":"Eṉakku Pirāṉsil oru akkā irukkiṛār.","lit":"moi-[à] · France-[dans] · une · grande sœur · il y a"},{"fr":"Ta mère cuisine merveilleusement bien, Ravi.","tgt":"உன் அம்மா ரொம்ப நன்றாக சமைக்கிறார், ரவி.","ro":"Uṉ ammā romba naṉṛāga chamaikkiṛār, Ravi.","lit":"ta · mère · très · bien · cuisine [respect] · Ravi"},{"fr":"Mon grand frère est fou de cricket.","tgt":"என் அண்ணனுக்கு கிரிக்கெட் ரொம்ப பிடிக்கும்.","ro":"Eṉ aṇṇaṉukku kirikkeṭ romba piḍikkum.","lit":"mon · grand frère-[à] · cricket · très · plaît"},{"fr":"Papa, voici mon ami Lucas.","tgt":"அப்பா, இவர் என் நண்பர் லூக்காஸ்.","ro":"Appā, ivar eṉ naṇbar Lūkkās.","lit":"papa · celui-ci [respect] · mon · ami · Lucas"},{"fr":"Ta famille est si affectueuse.","tgt":"உன் குடும்பம் ரொம்ப அன்பானது.","ro":"Uṉ kuḍumbam romba aṉbāṉadu.","lit":"ta · famille · très · affectueuse"}],"tip":{"title":"La famille : « appā », « ammā », « aṇṇaṉ », « akkā »","example":"Voici mon grand frère, Arun. — இவர் என் <b>அண்ணன்</b> அருண்.","body":"Les mots de la famille sont parmi les plus utilisés en tamoul, et ils sonnent presque comme un langage d'enfant : « appā », papa, et « ammā », maman. Pour les frères et sœurs, le tamoul précise toujours qui est l'aîné : « aṇṇaṉ » est le grand frère, « akkā » la grande sœur, tandis que « tambi » et « tangai » désignent le petit frère et la petite sœur. Ces mots servent aussi à appeler directement les gens, sans prénom : on dit « Appā ! » pour interpeller son père, et l'on appelle souvent « ammā » une dame plus âgée, par respect. Décomposons « ivar eṉ aṇṇaṉ Aruṇ » : celui-ci, avec respect, mon, grand frère, Arun, c'est-à-dire voici mon grand frère Arun. Remarquez qu'il n'y a pas de verbe être, la phrase s'en passe très bien. Pour présenter ses deux parents d'un coup, on dit simplement « eṉ appā, ammā ». Astuce pour retenir : doublez la consonne du milieu et allongez la fin, « appā », « ammā », « akkā », comme si vous appeliez quelqu'un à l'autre bout de la maison.","exampleRo":"Ivar eṉ aṇṇaṉ Aruṇ.","lit":"celui-ci [respect] · mon · grand frère · Arun","say":{"appā":"அப்பா","ammā":"அம்மா","aṇṇaṉ":"அண்ணன்","akkā":"அக்கா","tambi":"தம்பி","tangai":"தங்கை","Appā !":"அப்பா!","ivar eṉ aṇṇaṉ Aruṇ":"இவர் என் அண்ணன் அருண்","eṉ appā, ammā":"என் அப்பா, அம்மா"}}},{"title":"Un café sur la terrasse","phrases":[{"fr":"Quel soleil aujourd'hui !","tgt":"இன்று ரொம்ப வெயில்!","ro":"Iṉṛu romba veyil!","lit":"aujourd'hui · très · soleil"},{"fr":"À Madurai, il fait chaud toute l'année.","tgt":"மதுரையில் எப்போதும் வெயில்.","ro":"Maduraiyil eppōdum veyil.","lit":"Madurai-[dans] · toujours · soleil"},{"fr":"On boit un petit café ?","tgt":"ஒரு காபி குடிக்கலாமா?","ro":"Oru kāpi kuḍikkalāmā?","lit":"un · café · boire-on peut-[question]"},{"fr":"D'accord, juste un peu de sucre.","tgt":"சரி, சர்க்கரை கொஞ்சம் போதும்.","ro":"Chari, charkkarai konjam pōdum.","lit":"d'accord · sucre · un peu · suffit"},{"fr":"Le soir, il y a un peu de vent.","tgt":"மாலையில் கொஞ்சம் காற்று வரும்.","ro":"Mālaiyil konjam kāṛṛu varum.","lit":"soir-[dans] · un peu · vent · vient"},{"fr":"La pluie, ça te plaît ?","tgt":"உனக்கு மழை பிடிக்குமா?","ro":"Uṉakku maḻai piḍikkumā?","lit":"toi-[à] · pluie · plaît-[question]"},{"fr":"Oui, ici, la pluie est un vrai bonheur.","tgt":"ஆமாம், இங்கே மழை ஒரு சந்தோஷம்.","ro":"Āmām, ingē maḻai oru chandōsham.","lit":"oui · ici · pluie · un · bonheur"},{"fr":"En France, l'hiver est très froid.","tgt":"பிரான்ஸில் குளிர் காலத்தில் ரொம்ப குளிர்.","ro":"Pirāṉsil kuḷir kālattil romba kuḷir.","lit":"France-[dans] · froid · saison-[dans] · très · froid"},{"fr":"Il neige à Lyon ?","tgt":"லியோனில் பனி பெய்யுமா?","ro":"Liyōṉil paṉi peyyumā?","lit":"Lyon-[dans] · neige · tombe-[question]"},{"fr":"Oui, un peu, au mois de janvier.","tgt":"ஆமாம், ஜனவரியில் கொஞ்சம்.","ro":"Āmām, jaṉavariyil konjam.","lit":"oui · janvier-[dans] · un peu"}]},{"title":"Tutoyer un nouvel ami","phrases":[{"fr":"Comment vas-tu, Arun ?","tgt":"நீ எப்படி இருக்கிறாய், அருண்?","ro":"Nī eppaḍi irukkiṛāy, Aruṇ?","lit":"toi · comment · es · Arun"},{"fr":"Et vous, monsieur, comment allez-vous ?","tgt":"நீங்கள் எப்படி இருக்கிறீர்கள், ஐயா?","ro":"Nīngaḷ eppaḍi irukkiṛīrgaḷ, aiyā?","lit":"vous · comment · êtes · monsieur [respect]"},{"fr":"Tu peux me tutoyer, Lucas.","tgt":"என்னை நீ என்று கூப்பிடலாம், லூக்காஸ்.","ro":"Eṉṉai nī eṉṛu kūppiḍalām, Lūkkās.","lit":"moi-[objet] · toi · [en disant] · appeler-on peut · Lucas"},{"fr":"Tu passes ce soir ?","tgt":"இன்று இரவு நீ வருகிறாயா?","ro":"Iṉṛu iravu nī varugiṛāyā?","lit":"aujourd'hui · nuit · toi · viens-[question]"},{"fr":"Vous venez aussi, madame ?","tgt":"நீங்களும் வருகிறீர்களா, அம்மா?","ro":"Nīngaḷum varugiṛīrgaḷā, ammā?","lit":"vous-aussi · venez-[question] · madame"},{"fr":"Tu as un moment demain ?","tgt":"நாளை உனக்கு நேரம் இருக்கிறதா?","ro":"Nāḷai uṉakku nēram irukkiṛadā?","lit":"demain · toi-[à] · temps · il y a-[question]"},{"fr":"Vous êtes de Madurai, monsieur ?","tgt":"நீங்கள் மதுரைக்காரரா, ஐயா?","ro":"Nīngaḷ Maduraikkārarā, aiyā?","lit":"vous · Madurai-[homme de]-[question] · monsieur"},{"fr":"Dis, tu as faim ?","tgt":"உனக்கு பசிக்கிறதா?","ro":"Uṉakku pachikkiṛadā?","lit":"toi-[à] · a faim-[question]"},{"fr":"Et vous, madame, vous avez faim ?","tgt":"உங்களுக்கு பசிக்கிறதா, அம்மா?","ro":"Ungaḷukku pachikkiṛadā, ammā?","lit":"vous-[à] · a faim-[question] · madame"},{"fr":"Toi et moi, on est amis maintenant.","tgt":"இப்போது நீயும் நானும் நண்பர்கள்.","ro":"Ippōdu nīyum nāṉum naṇbargaḷ.","lit":"maintenant · toi-et · moi-et · amis"}],"tip":{"title":"« Nī » et « nīngaḷ » : tutoyer et vouvoyer","example":"Comment vas-tu, Arun ? — <b>நீ</b> எப்படி <b>இருக்கிறாய்</b>, அருண்?","body":"Comme le français, le tamoul a deux façons de s'adresser à quelqu'un. Avec un ami, un enfant ou un proche du même âge, on dit « nī », c'est le tutoiement. Avec une personne plus âgée, un inconnu ou quelqu'un qu'on respecte, on dit « nīngaḷ », c'est le vouvoiement. La différence s'entend aussi à la fin du verbe : « nī eppaḍi irukkiṛāy ? », comment vas-tu, mais « nīngaḷ eppaḍi irukkiṛīrgaḷ ? », comment allez-vous. Décomposons la première phrase : toi, comment, es, autrement dit comment vas-tu. Les petits mots qui en dérivent suivent la même règle : « uṉakku », à toi, devient « ungaḷukku », à vous. Avec les parents de vos amis, restez toujours sur « nīngaḷ », en ajoutant « aiyā », monsieur, ou « ammā », madame. Astuce : « nīngaḷ » est plus long que « nī », comme si le respect demandait quelques syllabes de plus.","exampleRo":"Nī eppaḍi irukkiṛāy, Aruṇ?","lit":"toi · comment · es · Arun","say":{"Nī":"நீ","nīngaḷ":"நீங்கள்","nī":"நீ","nī eppaḍi irukkiṛāy ?":"நீ எப்படி இருக்கிறாய்?","nīngaḷ eppaḍi irukkiṛīrgaḷ ?":"நீங்கள் எப்படி இருக்கிறீர்கள்?","uṉakku":"உனக்கு","ungaḷukku":"உங்களுக்கு","aiyā":"ஐயா","ammā":"அம்மா"}}},{"title":"Au marché aux fleurs","phrases":[{"fr":"Le marché aux fleurs ouvre à l'aube.","tgt":"பூச்சந்தை அதிகாலையில் திறக்கும்.","ro":"Pūcchandai adigālaiyil tiṛakkum.","lit":"marché aux fleurs · aube-[dans] · ouvre"},{"fr":"Ce jasmin est vraiment magnifique !","tgt":"இந்த மல்லிகைப்பூ ரொம்ப அழகு!","ro":"Inda malligaippū romba aḻagu!","lit":"ce · jasmin-fleur · très · beauté"},{"fr":"Le jasmin de Madurai est très célèbre.","tgt":"மதுரை மல்லி ரொம்ப பிரபலம்.","ro":"Madurai malli romba pirapalam.","lit":"Madurai · jasmin · très · célèbre"},{"fr":"Combien pour une coudée de jasmin ?","tgt":"ஒரு முழம் எவ்வளவு?","ro":"Oru muḻam evvaḷavu?","lit":"une · coudée · combien"},{"fr":"Trente roupies la coudée.","tgt":"ஒரு முழம் முப்பது ரூபாய்.","ro":"Oru muḻam muppadu rūpāy.","lit":"une · coudée · trente · roupie"},{"fr":"C'est un cadeau pour la mère de Ravi.","tgt":"இது ரவியுடைய அம்மாவுக்கு.","ro":"Idu Raviyuḍaiya ammāvukku.","lit":"ceci · Ravi-[de] · mère-[pour]"},{"fr":"Elle adore les fleurs.","tgt":"அவருக்கு பூ ரொம்ப பிடிக்கும்.","ro":"Avarukku pū romba piḍikkum.","lit":"elle [respect]-[à] · fleur · très · plaît"},{"fr":"Et ces roses rouges, c'est combien ?","tgt":"இந்த சிவப்பு ரோஜா எவ்வளவு?","ro":"Inda chivappu rōjā evvaḷavu?","lit":"ce · rouge · rose · combien"},{"fr":"Dix roupies la rose.","tgt":"ஒன்று பத்து ரூபாய்.","ro":"Oṉṛu pattu rūpāy.","lit":"une · dix · roupie"},{"fr":"Quelle foule ce matin !","tgt":"இன்று காலை நிறைய கூட்டம்!","ro":"Iṉṛu kālai niṛaiya kūṭṭam!","lit":"aujourd'hui · matin · beaucoup · foule"}]},{"title":"Madurai ou Chennai ?","phrases":[{"fr":"Chennai est plus grande que Madurai.","tgt":"மதுரையை விட சென்னை பெரியது.","ro":"Maduraiyai viḍa Cheṉṉai periyadu.","lit":"Madurai-[objet] · que · Chennai · grande"},{"fr":"Mais Madurai est plus calme que Chennai.","tgt":"ஆனால் சென்னையை விட மதுரை அமைதியானது.","ro":"Āṉāl Cheṉṉaiyai viḍa Madurai amaidiyāṉadu.","lit":"mais · Chennai-[objet] · que · Madurai · calme"},{"fr":"Le jigarthanda est meilleur que le café.","tgt":"காபியை விட ஜிகர்தண்டா நல்லது.","ro":"Kāpiyai viḍa jigartaṇḍā nalladu.","lit":"café-[objet] · que · jigarthanda · bon"},{"fr":"Ton grand frère est plus grand que toi ?","tgt":"உன்னை விட உன் அண்ணன் உயரமா?","ro":"Uṉṉai viḍa uṉ aṇṇaṉ uyaramā?","lit":"toi-[objet] · que · ton · grand frère · grand-[question]"},{"fr":"Oui, lui, il est plus grand que moi.","tgt":"ஆமாம், அவன் என்னை விட உயரம்.","ro":"Āmām, avaṉ eṉṉai viḍa uyaram.","lit":"oui · lui · moi-[objet] · que · grand"},{"fr":"Ici, les dosas sont meilleurs qu'en France.","tgt":"பிரான்ஸை விட இங்கே தோசை ருசி.","ro":"Pirāṉsai viḍa ingē tōchai ruchi.","lit":"France-[objet] · que · ici · dosa · saveur"},{"fr":"Le train coûte moins cher que le taxi.","tgt":"டாக்ஸியை விட ரயில் மலிவு.","ro":"Ṭāksiyai viḍa rayil malivu.","lit":"taxi-[objet] · que · train · bon marché"},{"fr":"Je préfère le cinéma à la télé.","tgt":"எனக்கு டிவியை விட சினிமா பிடிக்கும்.","ro":"Eṉakku ṭiviyai viḍa chiṉimā piḍikkum.","lit":"moi-[à] · télé-[objet] · que · cinéma · plaît"},{"fr":"Ta petite sœur est plus jeune que toi ?","tgt":"உன் தங்கை உன்னை விட சின்னவளா?","ro":"Uṉ tangai uṉṉai viḍa chiṉṉavaḷā?","lit":"ta · petite sœur · toi-[objet] · que · petite-elle-[question]"},{"fr":"Oui, elle a deux ans de moins.","tgt":"ஆமாம், இரண்டு வயது சின்னவள்.","ro":"Āmām, iraṇḍu vayadu chiṉṉavaḷ.","lit":"oui · deux · ans · petite-elle"}],"tip":{"title":"Comparer avec « -ai viḍa », plus que","example":"Chennai est plus grande que Madurai. — <b>மதுரையை</b> <b>விட</b> சென்னை பெரியது.","body":"Pour comparer deux choses, le tamoul ne dit pas « plus grand que », il dit littéralement « par rapport à Madurai, Chennai est grande ». On prend l'élément de comparaison, on lui colle « -ai », puis on ajoute « viḍa », qui veut dire en le laissant de côté. Décomposons « Maduraiyai viḍa Cheṉṉai periyadu » : Madurai, par rapport à, Chennai, grande, donc Chennai est plus grande que Madurai. L'ordre est inversé par rapport au français : on cite d'abord ce qu'on dépasse, puis ce qui l'emporte. Il n'y a même pas de mot pour « plus », c'est « viḍa » qui fait tout le travail. Avec les pronoms, on dit « eṉṉai viḍa », plus que moi, et « uṉṉai viḍa », plus que toi. On peut aussi l'associer à « piḍikkum » pour dire ce qu'on préfère : « eṉakku ṭiviyai viḍa chiṉimā piḍikkum », je préfère le cinéma à la télé. Astuce : posez d'abord le perdant sur la table, puis annoncez le gagnant.","exampleRo":"Maduraiyai viḍa Cheṉṉai periyadu.","lit":"Madurai-[objet] · que · Chennai · grande","say":{"viḍa":"விட","Maduraiyai viḍa Cheṉṉai periyadu":"மதுரையை விட சென்னை பெரியது","eṉṉai viḍa":"என்னை விட","uṉṉai viḍa":"உன்னை விட","piḍikkum":"பிடிக்கும்","eṉakku ṭiviyai viḍa chiṉimā piḍikkum":"எனக்கு டிவியை விட சினிமா பிடிக்கும்"}}},{"title":"Le cinéma du soir","phrases":[{"fr":"Ce soir, on se fait un cinéma ?","tgt":"இன்று இரவு சினிமாவுக்கு போகலாமா?","ro":"Iṉṛu iravu chiṉimāvukku pōgalāmā?","lit":"aujourd'hui · nuit · cinéma-[à] · aller-on peut-[question]"},{"fr":"Il y a un nouveau film tamoul.","tgt":"ஒரு புதிய தமிழ் படம் இருக்கிறது.","ro":"Oru pudiya tamiḻ paḍam irukkiṛadu.","lit":"un · nouveau · tamoul · film · il y a"},{"fr":"Le film démarre à neuf heures.","tgt":"படம் ஒன்பது மணிக்கு ஆரம்பம்.","ro":"Paḍam oṉbadu maṇikku ārambam.","lit":"film · neuf · heure-[à] · début"},{"fr":"Le billet, c'est combien ?","tgt":"டிக்கெட் எவ்வளவு?","ro":"Ṭikkeṭ evvaḷavu?","lit":"billet · combien"},{"fr":"Cent cinquante roupies par personne.","tgt":"ஒருவருக்கு நூற்றைம்பது ரூபாய்.","ro":"Oruvarukku nūṛṛaimbadu rūpāy.","lit":"une personne-[à] · cent cinquante · roupie"},{"fr":"J'adore les films d'action.","tgt":"எனக்கு ஆக்ஷன் படங்கள் ரொம்ப பிடிக்கும்.","ro":"Eṉakku ākshaṉ paḍangaḷ romba piḍikkum.","lit":"moi-[à] · action · films · très · plaît"},{"fr":"Moi, j'aime surtout les comédies.","tgt":"எனக்கு காமெடி படம் பிடிக்கும்.","ro":"Eṉakku kāmeḍi paḍam piḍikkum.","lit":"moi-[à] · comédie · film · plaît"},{"fr":"On prend du pop-corn ?","tgt":"பாப்கார்ன் வாங்கலாமா?","ro":"Pāpkārṉ vāngalāmā?","lit":"pop-corn · acheter-on peut-[question]"},{"fr":"Dans ce film, le héros chante très bien.","tgt":"இந்த படத்தில் ஹீரோ ரொம்ப நன்றாக பாடுகிறார்.","ro":"Inda paḍattil hīrō romba naṉṛāga pāḍugiṛār.","lit":"ce · film-[dans] · héros · très · bien · chante [respect]"},{"fr":"Les chansons sont superbes.","tgt":"பாடல்கள் ரொம்ப அழகு.","ro":"Pāḍalgaḷ romba aḻagu.","lit":"chansons · très · beauté"}]},{"title":"Pourquoi pas ce soir ?","phrases":[{"fr":"Pourquoi tu restes à la maison ?","tgt":"நீ ஏன் வீட்டில் இருக்கிறாய்?","ro":"Nī ēṉ vīṭṭil irukkiṛāy?","lit":"toi · pourquoi · maison-[dans] · es"},{"fr":"Parce que j'ai du travail demain.","tgt":"ஏனென்றால் நாளை எனக்கு வேலை இருக்கிறது.","ro":"Ēṉeṉṛāl nāḷai eṉakku vēlai irukkiṛadu.","lit":"parce que · demain · moi-[à] · travail · il y a"},{"fr":"Pourquoi Madurai te plaît autant ?","tgt":"உனக்கு ஏன் மதுரை பிடிக்கும்?","ro":"Uṉakku ēṉ Madurai piḍikkum?","lit":"toi-[à] · pourquoi · Madurai · plaît"},{"fr":"Parce que les gens sont très chaleureux.","tgt":"ஏனென்றால் இங்கே மக்கள் ரொம்ப அன்பானவர்கள்.","ro":"Ēṉeṉṛāl ingē makkaḷ romba aṉbāṉavargaḷ.","lit":"parce que · ici · gens · très · affectueux"},{"fr":"Je suis fatigué parce qu'il fait trop chaud.","tgt":"நான் களைப்பாக இருக்கிறேன், ஏனென்றால் ரொம்ப வெயில்.","ro":"Nāṉ kaḷaippāga irukkiṛēṉ, ēṉeṉṛāl romba veyil.","lit":"je · fatigué · suis · parce que · trop · soleil"},{"fr":"Pourquoi Meena n'est pas là ?","tgt":"மீனா ஏன் இங்கே இல்லை?","ro":"Mīṉā ēṉ ingē illai?","lit":"Meena · pourquoi · ici · n'est pas"},{"fr":"Parce qu'elle a un examen demain.","tgt":"ஏனென்றால் நாளை அவளுக்கு பரீட்சை.","ro":"Ēṉeṉṛāl nāḷai avaḷukku parīṭchai.","lit":"parce que · demain · elle-[à] · examen"},{"fr":"J'apprends le tamoul parce que cette langue me plaît.","tgt":"நான் தமிழ் கற்றுக்கொள்கிறேன், ஏனென்றால் எனக்கு தமிழ் பிடிக்கும்.","ro":"Nāṉ tamiḻ kaṛṛukkoḷgiṛēṉ, ēṉeṉṛāl eṉakku tamiḻ piḍikkum.","lit":"je · tamoul · apprends · parce que · moi-[à] · tamoul · plaît"},{"fr":"Mais pourquoi tu rigoles ?","tgt":"நீ ஏன் சிரிக்கிறாய்?","ro":"Nī ēṉ chirikkiṛāy?","lit":"toi · pourquoi · ris"},{"fr":"Parce que ton histoire est trop drôle !","tgt":"ஏனென்றால் உன் கதை ரொம்ப வேடிக்கை!","ro":"Ēṉeṉṛāl uṉ kadai romba vēḍikkai!","lit":"parce que · ton · histoire · très · amusement"}],"tip":{"title":"« Ēṉeṉṛāl » : parce que","example":"Parce que j'ai du travail demain. — <b>ஏனென்றால்</b> நாளை எனக்கு வேலை இருக்கிறது.","body":"Pour demander pourquoi, on utilise « ēṉ », un tout petit mot qui se place juste avant le verbe ou le mot important : « nī ēṉ chirikkiṛāy ? », pourquoi tu ris ? Pour répondre, on commence la phrase par « ēṉeṉṛāl », parce que. Ce mot est d'ailleurs construit sur « ēṉ » lui-même, on pourrait le traduire par « si tu demandes pourquoi ». Décomposons « ēṉeṉṛāl nāḷai eṉakku vēlai irukkiṛadu » : parce que, demain, à moi, travail, il y a, c'est-à-dire parce que j'ai du travail demain. Comme en français, on peut aussi relier deux idées dans la même phrase : « nāṉ kaḷaippāga irukkiṛēṉ, ēṉeṉṛāl romba veyil », je suis fatigué parce qu'il fait trop chaud. Prononcez bien le premier « ē », long, comme dans « fête » mais tenu un peu plus longtemps. Astuce : retenez la paire question et réponse, « ēṉ ? » puis « ēṉeṉṛāl », la réponse reprend toujours l'écho de la question.","exampleRo":"Ēṉeṉṛāl nāḷai eṉakku vēlai irukkiṛadu.","lit":"parce que · demain · moi-[à] · travail · il y a","say":{"Ēṉeṉṛāl":"ஏனென்றால்","ēṉ":"ஏன்","nī ēṉ chirikkiṛāy ?":"நீ ஏன் சிரிக்கிறாய்?","ēṉeṉṛāl":"ஏனென்றால்","ēṉeṉṛāl nāḷai eṉakku vēlai irukkiṛadu":"ஏனென்றால் நாளை எனக்கு வேலை இருக்கிறது","nāṉ kaḷaippāga irukkiṛēṉ, ēṉeṉṛāl romba veyil":"நான் களைப்பாக இருக்கிறேன், ஏனென்றால் ரொம்ப வெயில்","ēṉ ?":"ஏன்?"}}},{"title":"Les loisirs du week-end","phrases":[{"fr":"Qu'est-ce que tu fais de tes week-ends ?","tgt":"வார இறுதியில் நீ என்ன செய்கிறாய்?","ro":"Vāra iṛudiyil nī eṉṉa cheygiṛāy?","lit":"semaine · fin-[dans] · toi · quoi · fais"},{"fr":"Je lis des livres et je dessine.","tgt":"நான் புத்தகம் படிக்கிறேன், படம் வரைகிறேன்.","ro":"Nāṉ puttagam paḍikkiṛēṉ, paḍam varaigiṛēṉ.","lit":"je · livre · lis · image · dessine"},{"fr":"Tu joues d'un instrument de musique ?","tgt":"நீ ஏதாவது இசைக்கருவி வாசிக்கிறாயா?","ro":"Nī ēdāvadu ichaikkaruvi vāchikkiṛāyā?","lit":"toi · quelque · instrument de musique · joues-[question]"},{"fr":"Oui, je joue un peu du violon.","tgt":"ஆமாம், நான் கொஞ்சம் வயலின் வாசிக்கிறேன்.","ro":"Āmām, nāṉ konjam vayaliṉ vāchikkiṛēṉ.","lit":"oui · je · un peu · violon · joue"},{"fr":"Ma petite sœur apprend la danse.","tgt":"என் தங்கை நடனம் கற்றுக்கொள்கிறாள்.","ro":"Eṉ tangai naḍaṉam kaṛṛukkoḷgiṛāḷ.","lit":"ma · petite sœur · danse · apprend"},{"fr":"J'aime marcher en fin de journée.","tgt":"எனக்கு மாலையில் நடக்க பிடிக்கும்.","ro":"Eṉakku mālaiyil naḍakka piḍikkum.","lit":"moi-[à] · soir-[dans] · marcher · plaît"},{"fr":"Faire la cuisine, ça te plaît ?","tgt":"உனக்கு சமைக்க பிடிக்குமா?","ro":"Uṉakku chamaikka piḍikkumā?","lit":"toi-[à] · cuisiner · plaît-[question]"},{"fr":"Je cuisine surtout des plats français.","tgt":"நான் பெரும்பாலும் பிரெஞ்சு சாப்பாடு சமைக்கிறேன்.","ro":"Nāṉ perumbālum pirenju chāppāḍu chamaikkiṛēṉ.","lit":"je · surtout · français · repas · cuisine"},{"fr":"Le week-end, je dors beaucoup.","tgt":"வார இறுதியில் நான் நிறைய தூங்குகிறேன்.","ro":"Vāra iṛudiyil nāṉ niṛaiya tūngugiṛēṉ.","lit":"semaine · fin-[dans] · je · beaucoup · dors"},{"fr":"Moi, je fais du vélo avec des amis.","tgt":"நான் நண்பர்களுடன் சைக்கிள் ஓட்டுகிறேன்.","ro":"Nāṉ naṇbargaḷuḍaṉ chaikkiḷ ōṭṭugiṛēṉ.","lit":"je · amis-[avec] · vélo · conduis"}]},{"title":"Ce que je sais faire","phrases":[{"fr":"Tu sais nager ?","tgt":"உனக்கு நீந்த தெரியுமா?","ro":"Uṉakku nīnda teriyumā?","lit":"toi-[à] · nager · connu-[question]"},{"fr":"Oui, je nage très bien.","tgt":"ஆமாம், எனக்கு நன்றாக நீந்த தெரியும்.","ro":"Āmām, eṉakku naṉṛāga nīnda teriyum.","lit":"oui · moi-[à] · bien · nager · connu"},{"fr":"Tu connais ce petit restaurant ?","tgt":"உனக்கு இந்த உணவகம் தெரியுமா?","ro":"Uṉakku inda uṇavagam teriyumā?","lit":"toi-[à] · ce · restaurant · connu-[question]"},{"fr":"Oui, je connais bien le patron.","tgt":"ஆமாம், எனக்கு அதன் முதலாளியை நன்றாக தெரியும்.","ro":"Āmām, eṉakku adaṉ mudalāḷiyai naṉṛāga teriyum.","lit":"oui · moi-[à] · son · patron-[objet] · bien · connu"},{"fr":"Moi, je ne sais pas conduire un scooter.","tgt":"எனக்கு வண்டி ஓட்ட தெரியாது.","ro":"Eṉakku vaṇḍi ōṭṭa teriyādu.","lit":"moi-[à] · scooter · conduire · pas connu"},{"fr":"Ravi parle un peu français.","tgt":"ரவிக்கு கொஞ்சம் பிரெஞ்சு தெரியும்.","ro":"Ravikku konjam pirenju teriyum.","lit":"Ravi-[à] · un peu · français · connu"},{"fr":"Tu connais Kodaikanal ?","tgt":"உனக்கு கொடைக்கானல் தெரியுமா?","ro":"Uṉakku Koḍaikkāṉal teriyumā?","lit":"toi-[à] · Kodaikanal · connu-[question]"},{"fr":"Non, je ne connais pas encore les montagnes d'ici.","tgt":"இல்லை, இங்கே மலைகள் எனக்கு இன்னும் தெரியாது.","ro":"Illai, ingē malaigaḷ eṉakku iṉṉum teriyādu.","lit":"non · ici · montagnes · moi-[à] · encore · pas connu"},{"fr":"Tu sais faire des dosas ?","tgt":"உனக்கு தோசை சுட தெரியுமா?","ro":"Uṉakku tōchai chuḍa teriyumā?","lit":"toi-[à] · dosa · cuire · connu-[question]"},{"fr":"Pas encore, malheureusement.","tgt":"இன்னும் தெரியாது.","ro":"Iṉṉum teriyādu.","lit":"encore · pas connu"}],"tip":{"title":"« Teriyum » : savoir, connaître","example":"Tu sais nager ? — <b>உனக்கு</b> நீந்த <b>தெரியுமா</b>?","body":"Le verbe « teriyum » fonctionne exactement comme « piḍikkum » : la personne prend la marque « -kku », à moi, à toi, et le verbe se place à la fin. « Eṉakku teriyum » signifie donc mot à mot à moi, c'est connu, autrement dit je sais. Le même mot sert pour savoir faire quelque chose et pour connaître un lieu ou une personne, là où le français hésite entre savoir et connaître. Pour un savoir-faire, on met le verbe d'action juste avant : « uṉakku nīnda teriyumā ? », à toi, nager, c'est connu, question, donc sais-tu nager ? Pour dire qu'on ne sait pas, « teriyum » devient « teriyādu » : « eṉakku vaṇḍi ōṭṭa teriyādu », je ne sais pas conduire de scooter. Et la réponse la plus utile du voyageur reste « teriyādu » tout seul, je ne sais pas. Astuce : c'est la même logique que pour aimer, seul le dernier mot change, « piḍikkum » pour le goût, « teriyum » pour le savoir.","exampleRo":"Uṉakku nīnda teriyumā?","lit":"toi-[à] · nager · connu-[question]","say":{"Teriyum":"தெரியும்","teriyum":"தெரியும்","piḍikkum":"பிடிக்கும்","Eṉakku teriyum":"எனக்கு தெரியும்","uṉakku nīnda teriyumā ?":"உனக்கு நீந்த தெரியுமா?","teriyādu":"தெரியாது","eṉakku vaṇḍi ōṭṭa teriyādu":"எனக்கு வண்டி ஓட்ட தெரியாது"}}},{"title":"Le cricket entre voisins","phrases":[{"fr":"Les voisins jouent au cricket dans la rue.","tgt":"பக்கத்து வீட்டுக்காரர்கள் தெருவில் கிரிக்கெட் விளையாடுகிறார்கள்.","ro":"Pakkattu vīṭṭukkārargaḷ teruvil kirikkeṭ viḷaiyāḍugiṛārgaḷ.","lit":"d'à côté · maison-gens · rue-[dans] · cricket · jouent"},{"fr":"Tu viens jouer avec nous ?","tgt":"எங்களுடன் விளையாட வருகிறாயா?","ro":"Engaḷuḍaṉ viḷaiyāḍa varugiṛāyā?","lit":"nous-[avec] · jouer · viens-[question]"},{"fr":"Je ne connais pas bien les règles.","tgt":"எனக்கு விதிகள் சரியாக தெரியாது.","ro":"Eṉakku vidigaḷ chariyāga teriyādu.","lit":"moi-[à] · règles · correctement · pas connu"},{"fr":"Pas de souci, c'est facile !","tgt":"பரவாயில்லை, இது சுலபம்!","ro":"Paravāyillai, idu chulapam!","lit":"pas grave · ceci · facile"},{"fr":"Tiens, prends la batte.","tgt":"இந்தா, பேட்டை பிடி.","ro":"Indā, pēṭṭai piḍi.","lit":"tiens · batte-[objet] · prends"},{"fr":"Lance la balle doucement !","tgt":"பந்தை மெதுவாக போடு!","ro":"Pandai meduvāga pōḍu!","lit":"balle-[objet] · doucement · lance"},{"fr":"Bravo, quatre points !","tgt":"அருமை, நான்கு ரன்!","ro":"Arumai, nāṉgu raṉ!","lit":"superbe · quatre · points"},{"fr":"Attention à la fenêtre !","tgt":"ஜன்னல் ஜாக்கிரதை!","ro":"Jaṉṉal jākkiradai!","lit":"fenêtre · attention"},{"fr":"Notre équipe est en train de gagner !","tgt":"நம் அணி ஜெயிக்கிறது!","ro":"Nam aṇi jeyikkiṛadu!","lit":"notre · équipe · gagne"},{"fr":"On refait une partie demain soir ?","tgt":"நாளை மாலை மறுபடியும் விளையாடலாமா?","ro":"Nāḷai mālai maṛupaḍiyum viḷaiyāḍalāmā?","lit":"demain · soir · de nouveau · jouer-on peut-[question]"}]},{"title":"Faire des compliments","phrases":[{"fr":"Votre sari est très beau, Kavitha.","tgt":"உங்கள் புடவை ரொம்ப அழகு, கவிதா.","ro":"Ungaḷ puḍavai romba aḻagu, Kavidā.","lit":"votre · sari · très · beauté · Kavitha"},{"fr":"Merci beaucoup, Lucas.","tgt":"ரொம்ப நன்றி, லூக்காஸ்.","ro":"Romba naṉṛi, Lūkkās.","lit":"très · merci · Lucas"},{"fr":"Ce repas est vraiment délicieux.","tgt":"இந்த சாப்பாடு ரொம்ப ருசி.","ro":"Inda chāppāḍu romba ruchi.","lit":"ce · repas · très · saveur"},{"fr":"Tu parles très bien français, Ravi !","tgt":"ரவி, நீ ரொம்ப நன்றாக பிரெஞ்சு பேசுகிறாய்!","ro":"Ravi, nī romba naṉṛāga pirenju pēchugiṛāy!","lit":"Ravi · toi · très · bien · français · parles"},{"fr":"Ce quartier est plein d'animation.","tgt":"இந்த பகுதி ரொம்ப கலகலப்பாக இருக்கிறது.","ro":"Inda pagudi romba kalagalappāga irukkiṛadu.","lit":"ce · quartier · très · animé · est"},{"fr":"Je suis tellement heureux d'être ici.","tgt":"இங்கே இருப்பதில் எனக்கு ரொம்ப சந்தோஷம்.","ro":"Ingē iruppadil eṉakku romba chandōsham.","lit":"ici · être-[dans] · moi-[à] · très · bonheur"},{"fr":"Ta mère est d'une grande gentillesse.","tgt":"உன் அம்மா ரொம்ப அன்பானவர்.","ro":"Uṉ ammā romba aṉbāṉavar.","lit":"ta · mère · très · affectueuse [respect]"},{"fr":"Tu chantes vraiment bien !","tgt":"நீ ரொம்ப நன்றாக பாடுகிறாய்!","ro":"Nī romba naṉṛāga pāḍugiṛāy!","lit":"toi · très · bien · chantes"},{"fr":"Pas tant que ça, mais merci.","tgt":"அவ்வளவு இல்லை, நன்றி.","ro":"Avvaḷavu illai, naṉṛi.","lit":"tant · pas · merci"},{"fr":"Madurai me plaît énormément.","tgt":"எனக்கு மதுரை ரொம்ப ரொம்ப பிடிக்கும்.","ro":"Eṉakku Madurai romba romba piḍikkum.","lit":"moi-[à] · Madurai · très · très · plaît"}],"tip":{"title":"« Romba » : très, beaucoup","example":"Ce repas est vraiment délicieux. — இந்த சாப்பாடு <b>ரொம்ப</b> ருசி.","body":"« Romba » est sans doute le mot que vous entendrez le plus souvent dans les conversations à Madurai. Il veut dire à la fois « très » et « beaucoup », et il se place juste devant le mot qu'il renforce. Décomposons « inda chāppāḍu romba ruchi » : ce, repas, très, saveur, donc ce repas est vraiment délicieux. On l'utilise partout : « romba naṉṛi », merci beaucoup, « romba aḻagu », très beau, « romba piḍikkum », j'aime beaucoup. Pour insister encore plus, on le répète tout simplement : « romba romba piḍikkum », j'adore vraiment. C'est un mot de la langue parlée ; dans un texte soutenu on trouve plutôt « migavum », mais à l'oral, « romba » est parfait et chaleureux. Astuce : prononcez-le avec le sourire, en appuyant sur « rom », c'est le mot idéal pour faire un compliment à vos hôtes.","exampleRo":"Inda chāppāḍu romba ruchi.","lit":"ce · repas · très · saveur","say":{"Romba":"ரொம்ப","inda chāppāḍu romba ruchi":"இந்த சாப்பாடு ரொம்ப ருசி","romba naṉṛi":"ரொம்ப நன்றி","romba aḻagu":"ரொம்ப அழகு","romba piḍikkum":"ரொம்ப பிடிக்கும்","romba romba piḍikkum":"ரொம்ப ரொம்ப பிடிக்கும்","migavum":"மிகவும்","romba":"ரொம்ப"}}},{"title":"Échanger nos numéros","phrases":[{"fr":"Tu as un numéro de téléphone ici ?","tgt":"உனக்கு இங்கே போன் நம்பர் இருக்கிறதா?","ro":"Uṉakku ingē pōṉ nambar irukkiṛadā?","lit":"toi-[à] · ici · téléphone · numéro · il y a-[question]"},{"fr":"Oui, je te l'écris tout de suite.","tgt":"ஆமாம், இப்போதே எழுதி தருகிறேன்.","ro":"Āmām, ippōdē eḻudi tarugiṛēṉ.","lit":"oui · maintenant-[même] · en écrivant · donne"},{"fr":"Je t'envoie un message ce soir.","tgt":"இன்று இரவு உனக்கு குறுஞ்செய்தி அனுப்புகிறேன்.","ro":"Iṉṛu iravu uṉakku kuṛunjeydi aṉuppugiṛēṉ.","lit":"aujourd'hui · nuit · toi-[à] · message · envoie"},{"fr":"Appelle-moi quand tu veux.","tgt":"எப்போது வேண்டுமானாலும் கூப்பிடு.","ro":"Eppōdu vēṇḍumāṉālum kūppiḍu.","lit":"quand · que tu veuilles · appelle"},{"fr":"On se retrouve samedi ?","tgt":"சனிக்கிழமை சந்திக்கலாமா?","ro":"Chaṉikkiḻamai chandikkalāmā?","lit":"samedi · se rencontrer-on peut-[question]"},{"fr":"Désolé, samedi, je suis à Ooty.","tgt":"மன்னிக்கவும், சனிக்கிழமை நான் ஊட்டியில் இருக்கிறேன்.","ro":"Maṉṉikkavum, chaṉikkiḻamai nāṉ Ūṭṭiyil irukkiṛēṉ.","lit":"pardon · samedi · je · Ooty-[dans] · suis"},{"fr":"Alors lundi soir, ça te va ?","tgt":"அப்படியானால் திங்கள் மாலை, சரியா?","ro":"Appaḍiyāṉāl tingaḷ mālai, chariyā?","lit":"dans ce cas · lundi · soir · d'accord-[question]"},{"fr":"D'accord, à lundi soir.","tgt":"சரி, திங்கள் மாலை.","ro":"Chari, tingaḷ mālai.","lit":"d'accord · lundi · soir"},{"fr":"Mon numéro commence par neuf.","tgt":"என் நம்பர் ஒன்பதில் ஆரம்பிக்கிறது.","ro":"Eṉ nambar oṉbadil ārambikkiṛadu.","lit":"mon · numéro · neuf-[dans] · commence"},{"fr":"Je t'appelle demain matin.","tgt":"நாளை காலை உன்னை கூப்பிடுகிறேன்.","ro":"Nāḷai kālai uṉṉai kūppiḍugiṛēṉ.","lit":"demain · matin · toi-[objet] · appelle"}]},{"title":"Les amis de Ravi","phrases":[{"fr":"Voici mes amis de la fac.","tgt":"இவர்கள் என் கல்லூரி நண்பர்கள்.","ro":"Ivargaḷ eṉ kallūri naṇbargaḷ.","lit":"ceux-ci · mes · université · amis"},{"fr":"Les enfants jouent dehors.","tgt":"குழந்தைகள் வெளியே விளையாடுகிறார்கள்.","ro":"Kuḻandaigaḷ veḷiyē viḷaiyāḍugiṛārgaḷ.","lit":"enfants · dehors · jouent"},{"fr":"Ces fleurs sont pour toi.","tgt":"இந்த பூக்கள் உனக்கு.","ro":"Inda pūkkaḷ uṉakku.","lit":"ces · fleurs · toi-[pour]"},{"fr":"Tu as beaucoup de livres !","tgt":"உன்னிடம் நிறைய புத்தகங்கள்!","ro":"Uṉṉiḍam niṛaiya puttagangaḷ!","lit":"toi-[chez] · beaucoup · livres"},{"fr":"Mes voisins sont très sympathiques.","tgt":"என் பக்கத்து வீட்டுக்காரர்கள் ரொம்ப நல்லவர்கள்.","ro":"Eṉ pakkattu vīṭṭukkārargaḷ romba nallavargaḷ.","lit":"mes · d'à côté · maison-gens · très · gentils"},{"fr":"Le soir, les rues de Madurai sont pleines de vie.","tgt":"மதுரை தெருக்கள் மாலையில் கலகலப்பாக இருக்கும்.","ro":"Madurai terukkaḷ mālaiyil kalagalappāga irukkum.","lit":"Madurai · rues · soir-[dans] · animées · sont"},{"fr":"J'aime les films tamouls.","tgt":"எனக்கு தமிழ் படங்கள் பிடிக்கும்.","ro":"Eṉakku tamiḻ paḍangaḷ piḍikkum.","lit":"moi-[à] · tamoul · films · plaît"},{"fr":"Les étudiants arrivent à huit heures.","tgt":"மாணவர்கள் எட்டு மணிக்கு வருகிறார்கள்.","ro":"Māṇavargaḷ eṭṭu maṇikku varugiṛārgaḷ.","lit":"étudiants · huit · heure-[à] · viennent"},{"fr":"Ces bananes, c'est combien ?","tgt":"இந்த வாழைப்பழங்கள் எவ்வளவு?","ro":"Inda vāḻaippaḻangaḷ evvaḷavu?","lit":"ces · bananes · combien"},{"fr":"Maintenant, nous sommes tous amis.","tgt":"இப்போது நாம் எல்லோரும் நண்பர்கள்.","ro":"Ippōdu nām ellōrum naṇbargaḷ.","lit":"maintenant · nous · tous · amis"}],"tip":{"title":"Le pluriel en « -kaḷ »","example":"Voici mes amis de la fac. — இவர்கள் என் கல்லூரி <b>நண்பர்கள்</b>.","body":"Pour mettre un nom au pluriel, le tamoul ajoute simplement « -kaḷ » à la fin du mot. « Naṇbar », un ami, devient « naṇbargaḷ », des amis, et « kuḻandai », un enfant, devient « kuḻandaigaḷ », des enfants. À l'oral, le « k » s'adoucit en « g » après une voyelle ou un « r », d'où ce son « gaḷ » que vous entendez si souvent. Après un mot court comme « pū », fleur, on le double au contraire : « pūkkaḷ », des fleurs. Décomposons « ivargaḷ eṉ kallūri naṇbargaḷ » : ceux-ci, mes, université, amis, c'est-à-dire voici mes amis de la fac. Notez que « ivargaḷ », ceux-ci, porte lui aussi la marque du pluriel, alors que « eṉ » ne change pas. Pour les objets, le tamoul parlé laisse souvent le nom au singulier quand le contexte suffit : « nāṉ puttagam paḍikkiṛēṉ », je lis des livres. Astuce : le « ḷ » final se prononce la langue retournée vers le palais, comme un « l » un peu sourd.","exampleRo":"Ivargaḷ eṉ kallūri naṇbargaḷ.","lit":"ceux-ci · mes · université · amis","say":{"Naṇbar":"நண்பர்","naṇbargaḷ":"நண்பர்கள்","kuḻandai":"குழந்தை","kuḻandaigaḷ":"குழந்தைகள்","pū":"பூ","pūkkaḷ":"பூக்கள்","ivargaḷ eṉ kallūri naṇbargaḷ":"இவர்கள் என் கல்லூரி நண்பர்கள்","ivargaḷ":"இவர்கள்","eṉ":"என்","nāṉ puttagam paḍikkiṛēṉ":"நான் புத்தகம் படிக்கிறேன்"}}},{"title":"Au revoir après la soirée","phrases":[{"fr":"Il se fait tard, je dois rentrer.","tgt":"நேரம் ஆகிறது, நான் வீட்டுக்கு போக வேண்டும்.","ro":"Nēram āgiṛadu, nāṉ vīṭṭukku pōga vēṇḍum.","lit":"temps · devient · je · maison-[à] · aller · il faut"},{"fr":"Merci pour ce merveilleux repas.","tgt":"அருமையான சாப்பாட்டுக்கு நன்றி.","ro":"Arumaiyāṉa chāppāṭṭukku naṉṛi.","lit":"merveilleux · repas-[pour] · merci"},{"fr":"Reviens vite nous voir !","tgt":"மறுபடியும் சீக்கிரம் வா!","ro":"Maṛupaḍiyum chīkkiram vā!","lit":"de nouveau · vite · viens"},{"fr":"Bien sûr, je reviendrai.","tgt":"கண்டிப்பாக வருகிறேன்.","ro":"Kaṇḍippāga varugiṛēṉ.","lit":"bien sûr · viens"},{"fr":"Bon, j'y vais, à bientôt !","tgt":"சரி, போய்விட்டு வருகிறேன்!","ro":"Chari, pōyviṭṭu varugiṛēṉ!","lit":"bon · étant parti · reviens"},{"fr":"Rentre bien, sois prudent.","tgt":"பத்திரமாக போ.","ro":"Pattiramāga pō.","lit":"prudemment · va"},{"fr":"Il y a des rickshaws dans la rue.","tgt":"தெருவில் ஆட்டோ இருக்கிறது.","ro":"Teruvil āṭṭō irukkiṛadu.","lit":"rue-[dans] · rickshaw · se trouve"},{"fr":"Écris-moi un message quand tu es arrivé.","tgt":"வீட்டுக்கு போனதும் குறுஞ்செய்தி அனுப்பு.","ro":"Vīṭṭukku pōṉadum kuṛunjeydi aṉuppu.","lit":"maison-[à] · dès arrivé · message · envoie"},{"fr":"Merci pour tout, Ravi.","tgt":"எல்லாவற்றுக்கும் நன்றி, ரவி.","ro":"Ellāvaṛṛukkum naṉṛi, Ravi.","lit":"tout-[pour] · merci · Ravi"},{"fr":"À la prochaine, mon ami !","tgt":"மீண்டும் சந்திப்போம், நண்பா!","ro":"Mīṇḍum chandippōm, naṇbā!","lit":"de nouveau · nous nous verrons · ami"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Voilà, c'est la fin de ce module.","tgt":"இது இந்த பாடத்தின் முடிவு.","ro":"Idu inda pāḍattiṉ muḍivu.","lit":"ceci · ce · leçon-[de] · fin"},{"fr":"Maintenant, je sais parler un peu tamoul.","tgt":"இப்போது எனக்கு கொஞ்சம் தமிழ் பேச தெரியும்.","ro":"Ippōdu eṉakku konjam tamiḻ pēcha teriyum.","lit":"maintenant · moi-[à] · un peu · tamoul · parler · connu"},{"fr":"Le tamoul, voilà une belle langue !","tgt":"தமிழ்தான் அழகான மொழி!","ro":"Tamiḻtāṉ aḻagāṉa moḻi!","lit":"tamoul-[c'est bien] · belle · langue"},{"fr":"Ce sont les amis qui comptent vraiment.","tgt":"நண்பர்கள்தான் முக்கியம்.","ro":"Naṇbargaḷtāṉ mukkiyam.","lit":"amis-[c'est bien] · important"},{"fr":"Je parle tamoul tous les jours.","tgt":"நான் தினமும் தமிழ் பேசுகிறேன்.","ro":"Nāṉ tiṉamum tamiḻ pēchugiṛēṉ.","lit":"je · chaque jour · tamoul · parle"},{"fr":"Je peux parler de ma famille et de mes loisirs.","tgt":"என் குடும்பம், என் பொழுதுபோக்குகள் பற்றி பேச முடியும்.","ro":"Eṉ kuḍumbam, eṉ poḻudupōkkugaḷ paṛṛi pēcha muḍiyum.","lit":"ma · famille · mes · loisirs · au sujet de · parler · possible"},{"fr":"Madurai, c'est ma deuxième maison.","tgt":"மதுரைதான் என் இரண்டாவது வீடு.","ro":"Maduraitāṉ eṉ iraṇḍāvadu vīḍu.","lit":"Madurai-[c'est bien] · ma · deuxième · maison"},{"fr":"J'appelle Ravi aujourd'hui même.","tgt":"இன்றே ரவியை கூப்பிடுகிறேன்.","ro":"Iṉṛē Raviyai kūppiḍugiṛēṉ.","lit":"aujourd'hui-[même] · Ravi-[objet] · appelle"},{"fr":"La prochaine fois, c'est moi qui invite tout le monde.","tgt":"அடுத்த முறை நான்தான் எல்லோரையும் அழைக்கிறேன்.","ro":"Aḍutta muṛai nāṉtāṉ ellōraiyum aḻaikkiṛēṉ.","lit":"prochaine · fois · moi-[c'est bien] · tous-[objet] · invite"},{"fr":"Félicitations, on se retrouve au prochain module !","tgt":"வாழ்த்துக்கள்! அடுத்த பாடத்தில் சந்திப்போம்.","ro":"Vāḻttukkaḷ! Aḍutta pāḍattil chandippōm.","lit":"félicitations · prochaine · leçon-[dans] · nous nous verrons"}],"tip":{"title":"« -tāṉ » et « -ē » : insister sur un mot","example":"La prochaine fois, c'est moi qui invite tout le monde. — அடுத்த முறை <b>நான்தான்</b> எல்லோரையும் அழைக்கிறேன்.","body":"Pour mettre un mot en valeur, le français utilise « c'est... qui » ; le tamoul colle simplement un petit suffixe au mot important. Le plus courant est « -tāṉ » : « nāṉtāṉ », c'est moi, justement moi. Décomposons « aḍutta muṛai nāṉtāṉ ellōraiyum aḻaikkiṛēṉ » : prochaine, fois, c'est moi, tout le monde, j'invite, donc la prochaine fois, c'est moi qui invite tout le monde. Avec « Maduraitāṉ eṉ iraṇḍāvadu vīḍu », on souligne que c'est bien Madurai, et pas une autre ville, qui est ma deuxième maison. L'autre suffixe, « -ē », allonge simplement la fin du mot et ajoute l'idée de « même » : « iṉṛē », aujourd'hui même, « ippōdē », tout de suite, « nāṉē », moi-même. À l'oral, on appuie légèrement sur le mot qui porte le suffixe. Astuce : « tāṉ » pointe du doigt la personne ou la chose, et « ē » ajoute comme un petit point d'exclamation au bout du mot.","exampleRo":"Aḍutta muṛai nāṉtāṉ ellōraiyum aḻaikkiṛēṉ.","lit":"prochaine · fois · moi-[c'est bien] · tous-[objet] · invite","say":{"nāṉtāṉ":"நான்தான்","aḍutta muṛai nāṉtāṉ ellōraiyum aḻaikkiṛēṉ":"அடுத்த முறை நான்தான் எல்லோரையும் அழைக்கிறேன்","Maduraitāṉ eṉ iraṇḍāvadu vīḍu":"மதுரைதான் என் இரண்டாவது வீடு","iṉṛē":"இன்றே","ippōdē":"இப்போதே","nāṉē":"நானே","tāṉ":"தான்"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une nouvelle vie à Coimbatore","phrases":[{"fr":"Je suis arrivé à Coimbatore la semaine dernière.","tgt":"நான் கடந்த வாரம் கோயம்புத்தூருக்கு வந்தேன்.","ro":"Nāṉ kaḍanda vāram Kōyambuttūrukku vandēṉ."},{"fr":"Je travaille maintenant dans une entreprise textile.","tgt":"நான் இப்போது ஒரு ஜவுளி நிறுவனத்தில் வேலை செய்கிறேன்.","ro":"Nāṉ ippōdu oru javuḷi niṛuvaṉattil vēlai cheykiṛēṉ."},{"fr":"Mon logement se trouve près de la gare.","tgt":"என் வீடு ரயில் நிலையத்துக்கு அருகில் இருக்கிறது.","ro":"Eṉ vīḍu rayil nilaiyattukku arukil irukkiṛadu."},{"fr":"Ici, le climat est plus doux qu'à Chennai.","tgt":"இங்கே சென்னையை விட வானிலை இதமாக இருக்கிறது.","ro":"Ingē Cheṉṉaiyai viḍa vāṉilai idamāka irukkiṛadu."},{"fr":"Les gens d'ici parlent avec beaucoup de politesse.","tgt":"இங்குள்ள மக்கள் மிகவும் மரியாதையாகப் பேசுகிறார்கள்.","ro":"Inguḷḷa makkaḷ mikavum mariyādaiyākap pēchukiṛārkaḷ."},{"fr":"Avez-vous déjà fait le tour de la ville ?","tgt":"நீங்கள் ஏற்கனவே நகரத்தைச் சுற்றிப் பார்த்தீர்களா?","ro":"Nīngaḷ ēṛkaṉavē nakarattaich chuṛṛip pārttīrkaḷā?"},{"fr":"Pas encore, j'ai beaucoup de travail en ce moment.","tgt":"இன்னும் இல்லை, இப்போது எனக்கு வேலை அதிகமாக இருக்கிறது.","ro":"Iṉṉum illai, ippōdu eṉakku vēlai adikamāka irukkiṛadu."},{"fr":"De ma fenêtre, on aperçoit les montagnes.","tgt":"என் ஜன்னலிலிருந்து மலைகள் தெரிகின்றன.","ro":"Eṉ jaṉṉalilirundu malaikaḷ terikiṉṛaṉa."},{"fr":"Ooty n'est qu'à trois heures de route d'ici.","tgt":"ஊட்டி இங்கிருந்து மூன்று மணி நேரப் பயணம்தான்.","ro":"Ūṭṭi ingirundu mūṉṛu maṇi nērap payaṇamtāṉ."},{"fr":"Je crois que cette ville va me plaire.","tgt":"எனக்கு இந்த ஊர் பிடிக்கும் என்று நினைக்கிறேன்.","ro":"Eṉakku inda ūr piḍikkum eṉṛu niṉaikkiṛēṉ."}]},{"title":"Premier jour dans l'entreprise textile","phrases":[{"fr":"Hier, je suis allé au bureau à huit heures.","tgt":"நேற்று நான் எட்டு மணிக்கு அலுவலகத்துக்குப் போனேன்.","ro":"Nēṛṛu nāṉ eṭṭu maṇikku aluvalakattukkup pōṉēṉ."},{"fr":"Je suis venu en bus avec un collègue.","tgt":"நான் ஒரு சக ஊழியருடன் பேருந்தில் வந்தேன்.","ro":"Nāṉ oru chaka ūḻiyaruḍaṉ pērundil vandēṉ."},{"fr":"Le directeur m'a accueilli à l'entrée.","tgt":"இயக்குநர் என்னை வாசலில் வரவேற்றார்.","ro":"Iyakkunar eṉṉai vāchalil varavēṛṛār."},{"fr":"Ensuite, je suis allé à l'atelier de tissage.","tgt":"பிறகு நான் நெசவுப் பிரிவுக்குப் போனேன்.","ro":"Piṛaku nāṉ nechavup pirivukkup pōṉēṉ."},{"fr":"Là-bas, j'ai vu d'énormes machines.","tgt":"அங்கே பெரிய பெரிய இயந்திரங்களைப் பார்த்தேன்.","ro":"Angē periya periya iyandirangaḷaip pārttēṉ."},{"fr":"À midi, nous avons mangé ensemble à la cantine.","tgt":"மதியம் நாங்கள் அலுவலக உணவகத்தில் ஒன்றாகச் சாப்பிட்டோம்.","ro":"Madiyam nāngaḷ aluvalaka uṇavakattil oṉṛākach chāppiṭṭōm."},{"fr":"Êtes-vous allé à la réunion de l'après-midi ?","tgt":"நீங்கள் பிற்பகல் கூட்டத்துக்குப் போனீர்களா?","ro":"Nīngaḷ piṛpakal kūṭṭattukkup pōṉīrkaḷā?"},{"fr":"Oui, j'y suis allé avec mon chef d'équipe.","tgt":"ஆமாம், நான் என் குழுத் தலைவருடன் போனேன்.","ro":"Āmām, nāṉ eṉ kuḻut talaivaruḍaṉ pōṉēṉ."},{"fr":"Le soir, je suis rentré chez moi vers sept heures.","tgt":"மாலை சுமார் ஏழு மணிக்கு நான் வீட்டுக்குத் திரும்பி வந்தேன்.","ro":"Mālai chumār ēḻu maṇikku nāṉ vīṭṭukkut tirumbi vandēṉ."},{"fr":"Ce premier jour s'est très bien passé.","tgt":"முதல் நாள் மிகவும் நன்றாக இருந்தது.","ro":"Mudal nāḷ mikavum naṉṛāka irundadu."}],"tip":{"title":"Le passé : « pōṉēṉ », « vandēṉ », j'allai, je vins","example":"Hier, je suis allé au bureau à huit heures. — நேற்று நான் எட்டு மணிக்கு அலுவலகத்துக்குப் <b>போனேன்</b>.","body":"Pour parler au passé, le tamoul garde sa logique habituelle : le verbe reste à la fin, et c'est sa terminaison qui dit qui agit. On prend le verbe, on ajoute une petite marque de passé, puis la fin « ēṉ » pour je : « pō », aller, devient « pōṉēṉ », je suis allé. Certains verbes changent davantage, comme « vā », venir, qui donne « vandēṉ », je suis venu, un peu comme nos verbes irréguliers. Décomposons « nēṛṛu nāṉ eṭṭu maṇikku aluvalakattukkup pōṉēṉ » : hier, je, à huit heures, au bureau, suis allé. Pour changer de personne, on change seulement la fin : « pōṉōm », nous sommes allés, « vandīrkaḷā ? », êtes-vous venu ?, « chāppiṭṭēṉ », j'ai mangé. Astuce : guettez le « ēṉ » final, c'est la signature du je, au passé comme au présent.","exampleRo":"Nēṛṛu nāṉ eṭṭu maṇikku aluvalakattukkup pōṉēṉ.","lit":"hier · je · huit heures [à] (-ukku) · bureau [vers] (-ukku) · suis allé","say":{"pōṉēṉ":"போனேன்","vandēṉ":"வந்தேன்","pō":"போ","vā":"வா","nēṛṛu nāṉ eṭṭu maṇikku aluvalakattukkup pōṉēṉ":"நேற்று நான் எட்டு மணிக்கு அலுவலகத்துக்குப் போனேன்","pōṉōm":"போனோம்","vandīrkaḷā ?":"வந்தீர்களா?","chāppiṭṭēṉ":"சாப்பிட்டேன்"}}},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"J'aimerais ouvrir un compte d'épargne ici.","tgt":"நான் இங்கே ஒரு சேமிப்புக் கணக்கு தொடங்க விரும்புகிறேன்.","ro":"Nāṉ ingē oru chēmippuk kaṇakku toḍanga virumbukiṛēṉ."},{"fr":"Avez-vous apporté une pièce d'identité ?","tgt":"நீங்கள் அடையாள அட்டை கொண்டு வந்தீர்களா?","ro":"Nīngaḷ aḍaiyāḷa aṭṭai koṇḍu vandīrkaḷā?"},{"fr":"Oui, et j'ai aussi apporté une photo récente.","tgt":"ஆமாம், ஒரு புதிய புகைப்படமும் கொண்டு வந்தேன்.","ro":"Āmām, oru pudiya pukaippaḍamum koṇḍu vandēṉ."},{"fr":"Merci de bien vouloir remplir ce formulaire.","tgt":"தயவுசெய்து இந்தப் படிவத்தை நிரப்புங்கள்.","ro":"Tayavucheytu indap paḍivattai nirappungaḷ."},{"fr":"Mon salaire sera versé sur ce compte.","tgt":"என் சம்பளம் இந்தக் கணக்கில் வரும்.","ro":"Eṉ chambaḷam indak kaṇakkil varum."},{"fr":"Faut-il déposer une somme minimale ?","tgt":"குறைந்தபட்ச வைப்புத் தொகை தேவையா?","ro":"Kuṛaindapaṭcha vaipput tokai tēvaiyā?"},{"fr":"Oui, mille roupies seulement.","tgt":"ஆமாம், ஆயிரம் ரூபாய் மட்டும்.","ro":"Āmām, āyiram rūpāy maṭṭum."},{"fr":"Votre carte arrivera d'ici dix jours.","tgt":"பத்து நாட்களில் உங்கள் அட்டை வந்துவிடும்.","ro":"Pattu nāṭkaḷil ungaḷ aṭṭai vanduviḍum."},{"fr":"Où y a-t-il un distributeur de billets près d'ici ?","tgt":"பக்கத்தில் பணம் எடுக்கும் இயந்திரம் எங்கே இருக்கிறது?","ro":"Pakkattil paṇam eḍukkum iyandiram engē irukkiṛadu?"},{"fr":"Juste à côté de la banque, sur la gauche.","tgt":"வங்கிக்குப் பக்கத்திலேயே, இடது பக்கம்.","ro":"Vangikkup pakkattilēyē, iḍadu pakkam."}]},{"title":"Le marché aux légumes","phrases":[{"fr":"Le samedi matin, j'achète mes légumes au marché.","tgt":"சனிக்கிழமை காலையில் நான் சந்தையில் காய்கறி வாங்குகிறேன்.","ro":"Chaṉikkiḻamai kālaiyil nāṉ chandaiyil kāykaṛi vāngukiṛēṉ."},{"fr":"Les tomates sont très fraîches aujourd'hui.","tgt":"இன்றைக்குத் தக்காளி மிகவும் புதிதாக இருக்கிறது.","ro":"Iṉṛaikkut takkāḷi mikavum pudidāka irukkiṛadu."},{"fr":"À combien est le kilo d'oignons ?","tgt":"ஒரு கிலோ வெங்காயம் என்ன விலை?","ro":"Oru kilō vengāyam eṉṉa vilai?"},{"fr":"Quarante roupies le kilo.","tgt":"கிலோ நாற்பது ரூபாய்.","ro":"Kilō nāṛpadu rūpāy."},{"fr":"C'est un peu cher, vous pouvez faire un petit effort ?","tgt":"கொஞ்சம் விலை அதிகம், குறைத்துத் தர முடியுமா?","ro":"Koncham vilai adikam, kuṛaittut tara muḍiyumā?"},{"fr":"Bon, trente-cinq roupies pour vous.","tgt":"சரி, உங்களுக்கு முப்பத்தைந்து ரூபாய்.","ro":"Chari, ungaḷukku muppattaindu rūpāy."},{"fr":"Donnez-moi aussi un peu de coriandre.","tgt":"கொஞ்சம் கொத்தமல்லியும் கொடுங்கள்.","ro":"Koncham kottamalliyum koḍungaḷ."},{"fr":"J'ai apporté mon propre sac en tissu.","tgt":"நான் என் துணிப் பையைக் கொண்டு வந்தேன்.","ro":"Nāṉ eṉ tuṇip paiyaik koṇḍu vandēṉ."},{"fr":"Ces bananes viennent d'un village voisin.","tgt":"இந்த வாழைப்பழங்கள் பக்கத்துக் கிராமத்திலிருந்து வருகின்றன.","ro":"Inda vāḻaippaḻangaḷ pakkattuk kirāmattilirundu varukiṉṛaṉa."},{"fr":"Merci, à samedi prochain !","tgt":"நன்றி, அடுத்த சனிக்கிழமை பார்க்கலாம்!","ro":"Naṉṛi, aḍutta chaṉikkiḻamai pārkkalām!"}]},{"title":"Les projets du week-end","phrases":[{"fr":"Ce week-end, j'irai à Ooty avec des amis.","tgt":"இந்த வார இறுதியில் நான் நண்பர்களுடன் ஊட்டிக்குப் போவேன்.","ro":"Inda vāra iṛudiyil nāṉ naṇparkaḷuḍaṉ Ūṭṭikkup pōvēṉ."},{"fr":"Nous partirons samedi à six heures.","tgt":"நாங்கள் சனிக்கிழமை ஆறு மணிக்குப் புறப்படுவோம்.","ro":"Nāngaḷ chaṉikkiḻamai āṛu maṇikkup puṛappaḍuvōm."},{"fr":"Viendrez-vous avec nous ?","tgt":"நீங்களும் எங்களுடன் வருவீர்களா?","ro":"Nīngaḷum engaḷuḍaṉ varuvīrkaḷā?"},{"fr":"Oui, je viendrai avec plaisir.","tgt":"ஆமாம், நான் மகிழ்ச்சியாக வருவேன்.","ro":"Āmām, nāṉ makiḻchchiyāka varuvēṉ."},{"fr":"Nous monterons avec le petit train de montagne.","tgt":"நாங்கள் மலை ரயிலில் ஏறிப் போவோம்.","ro":"Nāngaḷ malai rayilil ēṛip pōvōm."},{"fr":"Là-haut, il fera sûrement froid.","tgt":"அங்கே மேலே நிச்சயம் குளிராக இருக்கும்.","ro":"Angē mēlē nichchayam kuḷirāka irukkum."},{"fr":"J'emporterai un pull en laine.","tgt":"நான் ஒரு கம்பளிச் சட்டை எடுத்துக்கொண்டு போவேன்.","ro":"Nāṉ oru kambaḷich chaṭṭai eḍuttukkoṇḍu pōvēṉ."},{"fr":"Nous mangerons dans un petit restaurant.","tgt":"நாங்கள் ஒரு சின்ன உணவகத்தில் சாப்பிடுவோம்.","ro":"Nāngaḷ oru chiṉṉa uṇavakattil chāppiḍuvōm."},{"fr":"Je reviendrai dimanche soir.","tgt":"நான் ஞாயிற்றுக்கிழமை மாலை திரும்பி வருவேன்.","ro":"Nāṉ nyāyiṛṛukkiḻamai mālai tirumbi varuvēṉ."},{"fr":"Lundi, je retournerai au travail plein d'énergie.","tgt":"திங்கள்கிழமை நான் புத்துணர்ச்சியுடன் வேலைக்குத் திரும்புவேன்.","ro":"Tingaḷkiḻamai nāṉ puttuṇarchchiyuḍaṉ vēlaikkut tirumbuvēṉ."}],"tip":{"title":"Le futur : « pōvēṉ », « varuvēṉ »","example":"Ce week-end, j'irai à Ooty avec des amis. — இந்த வார இறுதியில் நான் நண்பர்களுடன் ஊட்டிக்குப் <b>போவேன்</b>.","body":"Le futur se construit comme le passé : le verbe, une petite marque de futur, puis la terminaison de la personne. Cette marque est souvent un simple « v » : « pō », aller, devient « pōvēṉ », j'irai, et « vā », venir, devient « varuvēṉ », je viendrai. Dans « inda vāra iṛudiyil nāṉ naṇparkaḷuḍaṉ ūṭṭikkup pōvēṉ », on entend : ce week-end, je, avec des amis, à Ooty, irai. Pour nous, on dit « pōvōm », nous irons, et pour vous, poliment, « varuvīrkaḷā ? », viendrez-vous ? Bonne nouvelle, ce futur sert aussi pour les habitudes : « kāpi kuḍippēṉ », je bois un café, tous les jours. Astuce : imaginez le « v » comme un petit pas vers demain.","exampleRo":"Inda vāra iṛudiyil nāṉ naṇparkaḷuḍaṉ Ūṭṭikkup pōvēṉ.","lit":"ce · semaine fin [dans] (-il) · je · amis [avec] (-uḍaṉ) · Ooty [à] (-ukku) · irai","say":{"pōvēṉ":"போவேன்","varuvēṉ":"வருவேன்","pō":"போ","vā":"வா","inda vāra iṛudiyil nāṉ naṇparkaḷuḍaṉ ūṭṭikkup pōvēṉ":"இந்த வார இறுதியில் நான் நண்பர்களுடன் ஊட்டிக்குப் போவேன்","pōvōm":"போவோம்","varuvīrkaḷā ?":"வருவீர்களா?","kāpi kuḍippēṉ":"காபி குடிப்பேன்"}}},{"title":"Les démarches de la semaine","phrases":[{"fr":"Demain, je dois aller à la banque.","tgt":"நாளை நான் வங்கிக்குப் போக வேண்டும்.","ro":"Nāḷai nāṉ vangikkup pōka vēṇḍum."},{"fr":"Il faut payer le loyer avant le cinq.","tgt":"ஐந்தாம் தேதிக்கு முன் வாடகை கட்ட வேண்டும்.","ro":"Aindām tēdikku muṉ vāḍakai kaṭṭa vēṇḍum."},{"fr":"Je dois aussi acheter du riz et de l'huile.","tgt":"நான் அரிசி, எண்ணெய் கூட வாங்க வேண்டும்.","ro":"Nāṉ arichi, eṇṇey kūḍa vānga vēṇḍum."},{"fr":"Faut-il réserver pour voir le médecin ?","tgt":"மருத்துவரைப் பார்க்க முன்பதிவு செய்ய வேண்டுமா?","ro":"Maruttuvaraip pārkka muṉpadivu cheyya vēṇḍumā?"},{"fr":"Oui, il faut téléphoner à la clinique le matin.","tgt":"ஆமாம், காலையில் மருத்துவமனையைத் தொலைபேசியில் அழைக்க வேண்டும்.","ro":"Āmām, kālaiyil maruttuvamaṉaiyait tolaipēchiyil aḻaikka vēṇḍum."},{"fr":"Vous devez apporter vos anciennes ordonnances.","tgt":"நீங்கள் பழைய மருந்துச் சீட்டுகளைக் கொண்டு வர வேண்டும்.","ro":"Nīngaḷ paḻaiya marunduch chīṭṭukaḷaik koṇḍu vara vēṇḍum."},{"fr":"Je dois finir ce rapport avant midi.","tgt":"நான் இந்த அறிக்கையை மதியத்துக்குள் முடிக்க வேண்டும்.","ro":"Nāṉ inda aṛikkaiyai madiyattukkuḷ muḍikka vēṇḍum."},{"fr":"Mon chef veut le lire dès aujourd'hui.","tgt":"என் மேலாளர் அதை இன்றைக்கே படிக்க விரும்புகிறார்.","ro":"Eṉ mēlāḷar adai iṉṛaikkē paḍikka virumbukiṛār."},{"fr":"Est-ce que je dois venir samedi aussi ?","tgt":"நான் சனிக்கிழமையும் வர வேண்டுமா?","ro":"Nāṉ chaṉikkiḻamaiyum vara vēṇḍumā?"},{"fr":"Non, ce n'est pas la peine cette fois.","tgt":"இல்லை, இந்த முறை தேவையில்லை.","ro":"Illai, inda muṛai tēvaiyillai."}],"tip":{"title":"L'infinitif + « vēṇḍum » : il faut, je dois","example":"Demain, je dois aller à la banque. — நாளை நான் வங்கிக்குப் <b>போக வேண்டும்</b>.","body":"Pour dire je dois ou il faut, le tamoul utilise un seul mot, « vēṇḍum », placé tout à la fin, juste après le verbe à l'infinitif. Cet infinitif se termine le plus souvent par « a » : « pōka », aller, « vara », venir, « vānga », acheter, « kaṭṭa », payer. Ainsi « nāḷai nāṉ vangikkup pōka vēṇḍum » se décompose en : demain, je, à la banque, aller, il faut. Le mot « vēṇḍum » ne change jamais, quelle que soit la personne : « nīngaḷ vara vēṇḍum », vous devez venir. Pour en faire une question, ajoutez simplement « ā » : « vara vēṇḍumā ? », faut-il venir ? Astuce : vous connaissez déjà « vēṇḍum » pour dire je veux, c'est le même mot, qui signifie au fond c'est nécessaire.","exampleRo":"Nāḷai nāṉ vangikkup pōka vēṇḍum.","lit":"demain · je · banque [à] (-ukku) · aller · il faut","say":{"vēṇḍum":"வேண்டும்","pōka":"போக","vara":"வர","vānga":"வாங்க","kaṭṭa":"கட்ட","nāḷai nāṉ vangikkup pōka vēṇḍum":"நாளை நான் வங்கிக்குப் போக வேண்டும்","nīngaḷ vara vēṇḍum":"நீங்கள் வர வேண்டும்","vara vēṇḍumā ?":"வர வேண்டுமா?"}}},{"title":"La sambar à la maison","phrases":[{"fr":"Ce soir, je vais préparer une sambar.","tgt":"இன்று இரவு நான் சாம்பார் வைக்கப் போகிறேன்.","ro":"Iṉṛu iravu nāṉ chāmbār vaikkap pōkiṛēṉ."},{"fr":"La dame d'à côté m'a appris sa recette.","tgt":"பக்கத்து வீட்டு அம்மா எனக்கு அவருடைய செய்முறையைச் சொல்லிக் கொடுத்தார்.","ro":"Pakkattu vīṭṭu ammā eṉakku avaruḍaiya cheymuṛaiyaich chollik koḍuttār."},{"fr":"D'abord, il faut faire cuire les lentilles.","tgt":"முதலில் பருப்பை வேக வைக்க வேண்டும்.","ro":"Mudalil paruppai vēka vaikka vēṇḍum."},{"fr":"Ensuite, il faut couper les légumes en morceaux.","tgt":"பிறகு காய்கறிகளைத் துண்டுகளாக நறுக்க வேண்டும்.","ro":"Piṛaku kāykaṛikaḷait tuṇḍukaḷāka naṛukka vēṇḍum."},{"fr":"J'ajoute le tamarin et la poudre à sambar.","tgt":"நான் புளியும் சாம்பார் பொடியும் சேர்க்கிறேன்.","ro":"Nāṉ puḷiyum chāmbār poḍiyum chērkkiṛēṉ."},{"fr":"Combien de piment faut-il mettre ?","tgt":"எவ்வளவு மிளகாய் போட வேண்டும்?","ro":"Evvaḷavu miḷakāy pōḍa vēṇḍum?"},{"fr":"Un peu seulement, sinon ce sera trop fort.","tgt":"கொஞ்சம் மட்டும், இல்லையென்றால் காரம் அதிகமாகிவிடும்.","ro":"Koncham maṭṭum, illaiyeṉṛāl kāram adikamākiviḍum."},{"fr":"À la fin, on fait frire la moutarde et les feuilles de curry.","tgt":"கடைசியில் கடுகும் கறிவேப்பிலையும் தாளிக்க வேண்டும்.","ro":"Kaḍaichiyil kaḍukum kaṛivēppilaiyum tāḷikka vēṇḍum."},{"fr":"Ça sent délicieusement bon dans la cuisine !","tgt":"சமையலறையில் நல்ல மணம் வருகிறது!","ro":"Chamaiyalaṛaiyil nalla maṇam varukiṛadu!"},{"fr":"La sambar est prête, venez goûter !","tgt":"சாம்பார் தயார், வந்து ருசி பாருங்கள்!","ro":"Chāmbār tayār, vandu ruchi pārungaḷ!"}]},{"title":"Une visite chez le médecin","phrases":[{"fr":"Docteur, j'ai de la fièvre depuis deux jours.","tgt":"இரண்டு நாட்களாக எனக்குக் காய்ச்சல் இருக்கிறது, டாக்டர்.","ro":"Iraṇḍu nāṭkaḷāka eṉakkuk kāychchal irukkiṛadu, ṭākṭar."},{"fr":"Avez-vous mal à la tête en plus ?","tgt":"உங்களுக்குத் தலைவலியும் இருக்கிறதா?","ro":"Ungaḷukkut talaivaliyum irukkiṛadā?"},{"fr":"Oui, et je tousse beaucoup la nuit.","tgt":"ஆமாம், இரவில் நிறைய இருமல் வருகிறது.","ro":"Āmām, iravil niṛaiya irumal varukiṛadu."},{"fr":"Avez-vous bu assez d'eau ?","tgt":"நீங்கள் போதுமான அளவு தண்ணீர் குடித்தீர்களா?","ro":"Nīngaḷ pōdumāṉa aḷavu taṇṇīr kuḍittīrkaḷā?"},{"fr":"Je vais vous prescrire des médicaments.","tgt":"உங்களுக்கு மருந்து எழுதித் தருகிறேன்.","ro":"Ungaḷukku marundu eḻudit tarukiṛēṉ."},{"fr":"Prenez ces comprimés après les repas.","tgt":"இந்த மாத்திரைகளைச் சாப்பாட்டுக்குப் பிறகு சாப்பிடுங்கள்.","ro":"Inda māttiraikaḷaich chāppāṭṭukkup piṛaku chāppiḍungaḷ."},{"fr":"Deux fois par jour, le matin et le soir.","tgt":"தினமும் இரண்டு முறை, காலையிலும் இரவிலும்.","ro":"Tiṉamum iraṇḍu muṛai, kālaiyilum iravilum."},{"fr":"Reposez-vous bien chez vous pendant trois jours.","tgt":"மூன்று நாட்கள் வீட்டில் நன்றாக ஓய்வெடுங்கள்.","ro":"Mūṉṛu nāṭkaḷ vīṭṭil naṉṛāka ōyveḍungaḷ."},{"fr":"Pourriez-vous me faire un certificat pour mon entreprise ?","tgt":"என் நிறுவனத்துக்கு ஒரு மருத்துவச் சான்றிதழ் தர முடியுமா?","ro":"Eṉ niṛuvaṉattukku oru maruttuvach chāṉṛidaḻ tara muḍiyumā?"},{"fr":"Bien sûr, le voici, et bon rétablissement !","tgt":"நிச்சயமாக, இதோ, சீக்கிரம் குணமடையுங்கள்!","ro":"Nichchayamāka, idō, chīkkiram kuṇamaḍaiyungaḷ!"}]},{"title":"Les voisins du quartier","phrases":[{"fr":"Nos voisins sont d'une grande gentillesse.","tgt":"எங்கள் பக்கத்து வீட்டுக்காரர்கள் மிகவும் அன்பானவர்கள்.","ro":"Engaḷ pakkattu vīṭṭukkārarkaḷ mikavum aṉpāṉavarkaḷ."},{"fr":"Hier soir, ils m'ont invité à dîner.","tgt":"நேற்று இரவு அவர்கள் என்னைச் சாப்பிட அழைத்தார்கள்.","ro":"Nēṛṛu iravu avarkaḷ eṉṉaich chāppiḍa aḻaittārkaḷ."},{"fr":"Leur fils fait des études d'ingénieur ici.","tgt":"அவர்களுடைய மகன் இங்கே பொறியியல் படிக்கிறான்.","ro":"Avarkaḷuḍaiya makaṉ ingē poṛiyiyal paḍikkiṛāṉ."},{"fr":"La grand-mère m'a offert des murukkus faits maison.","tgt":"பாட்டி எனக்கு வீட்டில் செய்த முறுக்கு கொடுத்தார்.","ro":"Pāṭṭi eṉakku vīṭṭil cheyta muṛukku koḍuttār."},{"fr":"Dimanche prochain, j'irai chez eux à mon tour.","tgt":"அடுத்த ஞாயிற்றுக்கிழமை நான் அவர்கள் வீட்டுக்குப் போவேன்.","ro":"Aḍutta nyāyiṛṛukkiḻamai nāṉ avarkaḷ vīṭṭukkup pōvēṉ."},{"fr":"Le matin, le voisin arrose ses plantes.","tgt":"காலையில் பக்கத்து வீட்டுக்காரர் செடிகளுக்குத் தண்ணீர் ஊற்றுவார்.","ro":"Kālaiyil pakkattu vīṭṭukkārar cheḍikaḷukkut taṇṇīr ūṛṛuvār."},{"fr":"Il me salue toujours avec un grand sourire.","tgt":"அவர் எப்போதும் சிரித்துக்கொண்டே வணக்கம் சொல்வார்.","ro":"Avar eppōdum chirittukkoṇḍē vaṇakkam cholvār."},{"fr":"Pourrais-je vous emprunter une échelle ?","tgt":"உங்களிடம் ஒரு ஏணி கடன் வாங்கலாமா?","ro":"Ungaḷiḍam oru ēṇi kaḍaṉ vāngalāmā?"},{"fr":"Bien sûr, prenez-la quand vous voulez.","tgt":"நிச்சயமாக, எப்போது வேண்டுமானாலும் எடுத்துக்கொள்ளுங்கள்.","ro":"Nichchayamāka, eppōdu vēṇḍumāṉālum eḍuttukkoḷḷungaḷ."},{"fr":"Quelle chance d'avoir des voisins pareils !","tgt":"இப்படிப்பட்ட பக்கத்து வீட்டுக்காரர்கள் கிடைத்தது அதிர்ஷ்டம்!","ro":"Ippaḍippaṭṭa pakkattu vīṭṭukkārarkaḷ kiḍaittadu adirshṭam!"}]},{"title":"Une coupure d'eau","phrases":[{"fr":"Ce matin, il n'y a pas d'eau au robinet.","tgt":"இன்று காலை குழாயில் தண்ணீர் இல்லை.","ro":"Iṉṛu kālai kuḻāyil taṇṇīr illai."},{"fr":"La citerne sur le toit est vide.","tgt":"மாடியில் உள்ள தொட்டி காலியாக இருக்கிறது.","ro":"Māḍiyil uḷḷa toṭṭi kāliyāka irukkiṛadu."},{"fr":"J'ai tout de suite appelé le propriétaire.","tgt":"உடனே வீட்டு உரிமையாளரை அழைத்தேன்.","ro":"Uḍaṉē vīṭṭu urimaiyāḷarai aḻaittēṉ."},{"fr":"Il a dit qu'un camion-citerne allait venir.","tgt":"தண்ணீர் லாரி வரும் என்று அவர் சொன்னார்.","ro":"Taṇṇīr lāri varum eṉṛu avar choṉṉār."},{"fr":"Le camion arrivera vers onze heures.","tgt":"லாரி சுமார் பதினொரு மணிக்கு வரும்.","ro":"Lāri chumār padiṉoru maṇikku varum."},{"fr":"En attendant, j'ai rempli deux seaux chez le voisin.","tgt":"அதுவரை பக்கத்து வீட்டில் இரண்டு வாளி தண்ணீர் பிடித்தேன்.","ro":"Aduvarai pakkattu vīṭṭil iraṇḍu vāḷi taṇṇīr piḍittēṉ."},{"fr":"En été, on manque souvent d'eau ici.","tgt":"கோடையில் இங்கே அடிக்கடி தண்ணீர்த் தட்டுப்பாடு வரும்.","ro":"Kōḍaiyil ingē aḍikkaḍi taṇṇīrt taṭṭuppāḍu varum."},{"fr":"Il faut utiliser l'eau avec modération.","tgt":"தண்ணீரைச் சிக்கனமாகப் பயன்படுத்த வேண்டும்.","ro":"Taṇṇīraich chikkaṉamākap payaṉpaḍutta vēṇḍum."},{"fr":"Finalement, l'eau est revenue à midi.","tgt":"கடைசியில் மதியம் தண்ணீர் வந்தது.","ro":"Kaḍaichiyil madiyam taṇṇīr vandadu."},{"fr":"Ouf, quel soulagement !","tgt":"அப்பாடா, என்ன நிம்மதி!","ro":"Appāḍā, eṉṉa nimmadi!"}]},{"title":"Chez le tailleur du quartier","phrases":[{"fr":"Je voudrais faire coudre deux chemises.","tgt":"எனக்கு இரண்டு சட்டைகள் தைக்க வேண்டும்.","ro":"Eṉakku iraṇḍu chaṭṭaikaḷ taikka vēṇḍum."},{"fr":"J'ai acheté ce tissu dans mon entreprise.","tgt":"இந்தத் துணியை எங்கள் நிறுவனத்தில் வாங்கினேன்.","ro":"Indat tuṇiyai engaḷ niṛuvaṉattil vāngiṉēṉ."},{"fr":"Le coton de Coimbatore est très réputé.","tgt":"கோயம்புத்தூர் பருத்தித் துணி மிகவும் பிரபலம்.","ro":"Kōyambuttūr paruttit tuṇi mikavum pirapalam."},{"fr":"Je vais prendre vos mesures.","tgt":"உங்கள் அளவு எடுக்கிறேன்.","ro":"Ungaḷ aḷavu eḍukkiṛēṉ."},{"fr":"Voulez-vous des manches longues ou courtes ?","tgt":"முழுக் கை வேண்டுமா, அரைக் கை வேண்டுமா?","ro":"Muḻuk kai vēṇḍumā, araik kai vēṇḍumā?"},{"fr":"Des manches courtes, il fait trop chaud ici.","tgt":"அரைக் கை போதும், இங்கே வெயில் அதிகம்.","ro":"Araik kai pōdum, ingē veyil adikam."},{"fr":"Quand seront-elles prêtes ?","tgt":"எப்போது தயாராகும்?","ro":"Eppōdu tayārākum?"},{"fr":"Revenez jeudi après cinq heures.","tgt":"வியாழக்கிழமை ஐந்து மணிக்குப் பிறகு வாருங்கள்.","ro":"Viyāḻakkiḻamai aindu maṇikkup piṛaku vārungaḷ."},{"fr":"Combien est-ce que je vous dois ?","tgt":"நான் உங்களுக்கு எவ்வளவு தர வேண்டும்?","ro":"Nāṉ ungaḷukku evvaḷavu tara vēṇḍum?"},{"fr":"Pour les deux, quatre cents roupies.","tgt":"இரண்டுக்கும் சேர்த்து நானூறு ரூபாய்.","ro":"Iraṇḍukkum chērttu nāṉūṛu rūpāy."}]},{"title":"Un jour de grosse pluie","phrases":[{"fr":"Hier, je ne suis pas allé au travail.","tgt":"நேற்று நான் வேலைக்குப் போகவில்லை.","ro":"Nēṛṛu nāṉ vēlaikkup pōkavillai."},{"fr":"Il a plu très fort toute la journée.","tgt":"நாள் முழுவதும் பலத்த மழை பெய்தது.","ro":"Nāḷ muḻuvadum palatta maḻai peytadu."},{"fr":"Les bus ne sont pas passés dans notre rue.","tgt":"எங்கள் தெருவில் பேருந்துகள் வரவில்லை.","ro":"Engaḷ teruvil pērundukaḷ varavillai."},{"fr":"Mon collègue n'est pas venu non plus.","tgt":"என் சக ஊழியரும் வரவில்லை.","ro":"Eṉ chaka ūḻiyarum varavillai."},{"fr":"Le courant n'est pas revenu avant le soir.","tgt":"மாலை வரை மின்சாரம் வரவில்லை.","ro":"Mālai varai miṉchāram varavillai."},{"fr":"Demain non plus, je n'irai pas au bureau.","tgt":"நாளையும் நான் அலுவலகத்துக்குப் போக மாட்டேன்.","ro":"Nāḷaiyum nāṉ aluvalakattukkup pōka māṭṭēṉ."},{"fr":"Je ne conduirai pas mon scooter sous cette pluie.","tgt":"இந்த மழையில் நான் ஸ்கூட்டர் ஓட்ட மாட்டேன்.","ro":"Inda maḻaiyil nāṉ skūṭṭar ōṭṭa māṭṭēṉ."},{"fr":"Le chef ne dira rien, il comprendra.","tgt":"மேலாளர் ஒன்றும் சொல்ல மாட்டார், புரிந்துகொள்வார்.","ro":"Mēlāḷar oṉṛum cholla māṭṭār, purindukoḷvār."},{"fr":"Je n'ai pas oublié de prévenir l'équipe.","tgt":"குழுவிடம் சொல்ல நான் மறக்கவில்லை.","ro":"Kuḻuviḍam cholla nāṉ maṛakkavillai."},{"fr":"Aujourd'hui, je ne sortirai pas, je resterai à la maison.","tgt":"இன்று நான் வெளியே போக மாட்டேன், வீட்டிலேயே இருப்பேன்.","ro":"Iṉṛu nāṉ veḷiyē pōka māṭṭēṉ, vīṭṭilēyē iruppēṉ."}],"tip":{"title":"La négation au passé et au futur : « pōkavillai », « pōka māṭṭēṉ »","example":"Hier, je ne suis pas allé au travail. — நேற்று நான் வேலைக்குப் <b>போகவில்லை</b>.","body":"Nier une action passée est étonnamment simple : on prend l'infinitif du verbe et on lui colle « illai », qui veut dire non. « Pōka » plus « illai » donne « pōkavillai », je ne suis pas allé, et cette forme reste la même pour toutes les personnes : « nēṛṛu nāṉ vēlaikkup pōkavillai », hier, je, au travail, pas allé. Même chose avec « varavillai », pas venu, que ce soit lui, elle ou nous. Pour le futur, on garde l'infinitif, puis on ajoute « māṭṭēṉ », qui change selon la personne : « pōka māṭṭēṉ », je n'irai pas, « cholla māṭṭār », il ne dira pas. Astuce : « illai » regarde en arrière et ne bouge jamais, tandis que « māṭṭ » regarde vers demain et porte la fin de la personne.","exampleRo":"Nēṛṛu nāṉ vēlaikkup pōkavillai.","lit":"hier · je · travail [à] (-ukku) · ne suis pas allé","say":{"pōkavillai":"போகவில்லை","pōka māṭṭēṉ":"போக மாட்டேன்","illai":"இல்லை","Pōka":"போக","nēṛṛu nāṉ vēlaikkup pōkavillai":"நேற்று நான் வேலைக்குப் போகவில்லை","varavillai":"வரவில்லை","māṭṭēṉ":"மாட்டேன்","cholla māṭṭār":"சொல்ல மாட்டார்"}}},{"title":"Le bus de la zone industrielle","phrases":[{"fr":"Quel bus va à la zone industrielle ?","tgt":"தொழிற்பேட்டைக்கு எந்தப் பேருந்து போகும்?","ro":"Toḻiṛpēṭṭaikku endap pērundu pōkum?"},{"fr":"Le numéro vingt, il passe toutes les quinze minutes.","tgt":"இருபதாம் எண் பேருந்து, பதினைந்து நிமிடத்துக்கு ஒரு முறை வரும்.","ro":"Irupadām eṇ pērundu, padiṉaindu nimiḍattukku oru muṛai varum."},{"fr":"Le matin, le bus est toujours bondé.","tgt":"காலையில் பேருந்தில் எப்போதும் கூட்டமாக இருக்கும்.","ro":"Kālaiyil pērundil eppōdum kūṭṭamāka irukkum."},{"fr":"Je préfère prendre celui de sept heures.","tgt":"நான் ஏழு மணிப் பேருந்தில் போவதையே விரும்புகிறேன்.","ro":"Nāṉ ēḻu maṇip pērundil pōvadaiyē virumbukiṛēṉ."},{"fr":"Un ticket pour Peelamedu, s'il vous plaît.","tgt":"பீளமேட்டுக்கு ஒரு டிக்கெட் கொடுங்கள்.","ro":"Pīḷamēṭṭukku oru ṭikkeṭ koḍungaḷ."},{"fr":"Ça fait quinze roupies.","tgt":"பதினைந்து ரூபாய்.","ro":"Padiṉaindu rūpāy."},{"fr":"Prévenez-moi quand on arrive à mon arrêt.","tgt":"என் நிறுத்தம் வந்ததும் சொல்லுங்கள்.","ro":"Eṉ niṛuttam vandadum chollungaḷ."},{"fr":"Le trajet prend environ quarante minutes.","tgt":"பயணம் சுமார் நாற்பது நிமிடம் ஆகும்.","ro":"Payaṇam chumār nāṛpadu nimiḍam ākum."},{"fr":"Pendant le trajet, j'écoute des chansons.","tgt":"பயணத்தின் போது நான் பாட்டு கேட்பேன்.","ro":"Payaṇattiṉ pōdu nāṉ pāṭṭu kēṭpēṉ."},{"fr":"Voilà mon arrêt, je descends ici.","tgt":"இதோ என் நிறுத்தம், நான் இங்கே இறங்குகிறேன்.","ro":"Idō eṉ niṛuttam, nāṉ ingē iṛangukiṛēṉ."}]},{"title":"À la pharmacie","phrases":[{"fr":"Auriez-vous un remède contre la toux ?","tgt":"இருமலுக்கு ஏதாவது மருந்து இருக்கிறதா?","ro":"Irumalukku ēdāvadu marundu irukkiṛadā?"},{"fr":"Ce sirop contre la toux marche très bien.","tgt":"இந்த இருமல் மருந்து நன்றாக வேலை செய்யும்.","ro":"Inda irumal marundu naṉṛāka vēlai cheyyum."},{"fr":"Il faut le prendre combien de fois par jour ?","tgt":"ஒரு நாளைக்கு எத்தனை முறை குடிக்க வேண்டும்?","ro":"Oru nāḷaikku ettaṉai muṛai kuḍikka vēṇḍum?"},{"fr":"Une cuillère, trois fois par jour.","tgt":"ஒரு நாளைக்கு மூன்று முறை, ஒவ்வொரு முறையும் ஒரு கரண்டி.","ro":"Oru nāḷaikku mūṉṛu muṛai, ovvoru muṛaiyum oru karaṇḍi."},{"fr":"Il me faut aussi un baume pour le mal de dos.","tgt":"முதுகு வலிக்கு ஒரு தைலமும் வேண்டும்.","ro":"Muduku valikku oru tailamum vēṇḍum."},{"fr":"Avez-vous une ordonnance pour ces comprimés ?","tgt":"இந்த மாத்திரைகளுக்கு மருந்துச் சீட்டு இருக்கிறதா?","ro":"Inda māttiraikaḷukku marunduch chīṭṭu irukkiṛadā?"},{"fr":"Oui, le médecin me l'a faite hier.","tgt":"ஆமாம், நேற்று மருத்துவர் எழுதிக் கொடுத்தார்.","ro":"Āmām, nēṛṛu maruttuvar eḻudik koḍuttār."},{"fr":"Ça fait deux cent cinquante roupies en tout.","tgt":"மொத்தம் இருநூற்று ஐம்பது ரூபாய்.","ro":"Mottam irunūṛṛu aimbadu rūpāy."},{"fr":"Je peux payer avec mon téléphone ?","tgt":"போன் மூலம் பணம் கட்டலாமா?","ro":"Pōṉ mūlam paṇam kaṭṭalāmā?"},{"fr":"Oui, scannez simplement ce code.","tgt":"ஆமாம், இந்தக் குறியீட்டை ஸ்கேன் செய்யுங்கள்.","ro":"Āmām, indak kuṛiyīṭṭai skēṉ cheyyungaḷ."}]},{"title":"Chez le coiffeur","phrases":[{"fr":"Je voudrais les cheveux courts, s'il vous plaît.","tgt":"தயவுசெய்து முடியைக் குட்டையாக வெட்டுங்கள்.","ro":"Tayavucheytu muḍiyaik kuṭṭaiyāka veṭṭungaḷ."},{"fr":"Combien de temps faut-il attendre ?","tgt":"எவ்வளவு நேரம் காத்திருக்க வேண்டும்?","ro":"Evvaḷavu nēram kāttirukka vēṇḍum?"},{"fr":"Deux clients avant vous, une dizaine de minutes.","tgt":"உங்களுக்கு முன் இரண்டு பேர், சுமார் பத்து நிமிடம்.","ro":"Ungaḷukku muṉ iraṇḍu pēr, chumār pattu nimiḍam."},{"fr":"Vous êtes nouveau dans le quartier ?","tgt":"நீங்கள் இந்தப் பகுதிக்குப் புதியவரா?","ro":"Nīngaḷ indap pakudikkup pudiyavarā?"},{"fr":"Oui, je suis arrivé de France il y a un mois.","tgt":"ஆமாம், ஒரு மாதத்துக்கு முன் பிரான்ஸிலிருந்து வந்தேன்.","ro":"Āmām, oru mādattukku muṉ Pirāṉsilirundu vandēṉ."},{"fr":"Votre tamoul est déjà très bon !","tgt":"உங்கள் தமிழ் ஏற்கனவே நன்றாக இருக்கிறது!","ro":"Ungaḷ Tamiḻ ēṛkaṉavē naṉṛāka irukkiṛadu!"},{"fr":"Je l'apprends petit à petit, chaque jour.","tgt":"தினமும் கொஞ்சம் கொஞ்சமாகக் கற்றுக்கொள்கிறேன்.","ro":"Tiṉamum koncham konchamākak kaṛṛukkoḷkiṛēṉ."},{"fr":"Un peu plus court sur les côtés, s'il vous plaît.","tgt":"பக்கவாட்டில் இன்னும் கொஞ்சம் குட்டையாக வெட்டுங்கள்.","ro":"Pakkavāṭṭil iṉṉum koncham kuṭṭaiyāka veṭṭungaḷ."},{"fr":"Ça vous plaît comme ça ?","tgt":"இப்படிப் பிடித்திருக்கிறதா?","ro":"Ippaḍip piḍittirukkiṛadā?"},{"fr":"C'est parfait, merci beaucoup.","tgt":"அருமையாக இருக்கிறது, ரொம்ப நன்றி.","ro":"Arumaiyāka irukkiṛadu, romba naṉṛi."}]},{"title":"Le scooter en panne","phrases":[{"fr":"Ce matin, mon scooter n'a pas voulu démarrer.","tgt":"இன்று காலை என் ஸ்கூட்டர் ஸ்டார்ட் ஆகவில்லை.","ro":"Iṉṛu kālai eṉ skūṭṭar sṭārṭ ākavillai."},{"fr":"Il y a un mécanicien au coin de la rue.","tgt":"தெருமுனையில் ஒரு மெக்கானிக் இருக்கிறார்.","ro":"Terumuṉaiyil oru mekkāṉik irukkiṛār."},{"fr":"Je pense que c'est la batterie.","tgt":"பேட்டரிதான் பிரச்சினை என்று நினைக்கிறேன்.","ro":"Pēṭṭaridāṉ pirachchiṉai eṉṛu niṉaikkiṛēṉ."},{"fr":"Laissez-le ici jusqu'à ce soir.","tgt":"இன்று மாலை வரை இங்கேயே விட்டுவிடுங்கள்.","ro":"Iṉṛu mālai varai ingēyē viṭṭuviḍungaḷ."},{"fr":"Je vais aussi contrôler les freins.","tgt":"பிரேக்கையும் சோதித்துப் பார்க்கிறேன்.","ro":"Pirēkkaiyum chōdittup pārkkiṛēṉ."},{"fr":"Combien cela va-t-il coûter ?","tgt":"எவ்வளவு செலவாகும்?","ro":"Evvaḷavu chelavākum?"},{"fr":"Environ huit cents roupies.","tgt":"சுமார் எண்ணூறு ரூபாய் ஆகும்.","ro":"Chumār eṇṇūṛu rūpāy ākum."},{"fr":"D'accord, je repasserai à six heures.","tgt":"சரி, நான் ஆறு மணிக்குத் திரும்பி வருவேன்.","ro":"Chari, nāṉ āṛu maṇikkut tirumbi varuvēṉ."},{"fr":"Votre scooter est comme neuf maintenant.","tgt":"இப்போது உங்கள் ஸ்கூட்டர் புதிது போல இருக்கிறது.","ro":"Ippōdu ungaḷ skūṭṭar pudidu pōla irukkiṛadu."},{"fr":"Merci, vous m'avez rendu un grand service.","tgt":"நன்றி, நீங்கள் எனக்குப் பெரிய உதவி செய்தீர்கள்.","ro":"Naṉṛi, nīngaḷ eṉakkup periya udavi cheytīrkaḷ."}]},{"title":"Des clients français à l'usine","phrases":[{"fr":"Demain, des clients français viennent à l'usine.","tgt":"நாளை பிரெஞ்சு வாடிக்கையாளர்கள் எங்கள் நிறுவனத்துக்கு வருகிறார்கள்.","ro":"Nāḷai Pirenchu vāḍikkaiyāḷarkaḷ engaḷ niṛuvaṉattukku varukiṛārkaḷ."},{"fr":"Je serai leur interprète toute la journée.","tgt":"நாள் முழுவதும் நான் அவர்களுக்கு மொழிபெயர்ப்பாளராக இருப்பேன்.","ro":"Nāḷ muḻuvadum nāṉ avarkaḷukku moḻipeyarppāḷarāka iruppēṉ."},{"fr":"Nous leur montrerons les nouveaux tissus.","tgt":"நாங்கள் அவர்களுக்குப் புதிய துணிகளைக் காட்டுவோம்.","ro":"Nāngaḷ avarkaḷukkup pudiya tuṇikaḷaik kāṭṭuvōm."},{"fr":"Ils aiment beaucoup le coton biologique.","tgt":"அவர்களுக்கு இயற்கைப் பருத்தி மிகவும் பிடிக்கும்.","ro":"Avarkaḷukku iyaṛkaip parutti mikavum piḍikkum."},{"fr":"Le directeur a préparé une présentation.","tgt":"இயக்குநர் ஒரு விளக்கக்காட்சி தயார் செய்திருக்கிறார்.","ro":"Iyakkunar oru viḷakkakkāṭchi tayār cheytirukkiṛār."},{"fr":"À midi, nous servirons un repas sur feuille de bananier.","tgt":"மதியம் வாழை இலையில் சாப்பாடு பரிமாறுவோம்.","ro":"Madiyam vāḻai ilaiyil chāppāḍu parimāṛuvōm."},{"fr":"Ils voudront sûrement goûter notre café.","tgt":"அவர்கள் நிச்சயம் நம் காபியை ருசி பார்க்க விரும்புவார்கள்.","ro":"Avarkaḷ nichchayam nam kāpiyai ruchi pārkka virumbuvārkaḷ."},{"fr":"La commande pourrait être très importante.","tgt":"இந்த ஆர்டர் மிகப் பெரியதாக இருக்கலாம்.","ro":"Inda ārṭar mikap periyadāka irukkalām."},{"fr":"Tout le monde est un peu nerveux.","tgt":"எல்லோரும் கொஞ்சம் பதற்றமாக இருக்கிறார்கள்.","ro":"Ellōrum koncham padaṛṛamāka irukkiṛārkaḷ."},{"fr":"J'espère que tout se passera bien.","tgt":"எல்லாம் நன்றாக நடக்கும் என்று நம்புகிறேன்.","ro":"Ellām naṉṛāka naḍakkum eṉṛu nambukiṛēṉ."}]},{"title":"Un dimanche au calme","phrases":[{"fr":"Le dimanche, je me lève tard.","tgt":"ஞாயிற்றுக்கிழமை நான் தாமதமாக எழுந்திருப்பேன்.","ro":"Nyāyiṛṛukkiḻamai nāṉ tāmadamāka eḻundiruppēṉ."},{"fr":"Je bois mon café assis sur le balcon.","tgt":"பால்கனியில் உட்கார்ந்து காபி குடிப்பேன்.","ro":"Pālkaṉiyil uṭkārndu kāpi kuḍippēṉ."},{"fr":"Le matin, le quartier est très silencieux.","tgt":"காலையில் எங்கள் பகுதி மிகவும் அமைதியாக இருக்கும்.","ro":"Kālaiyil engaḷ pakudi mikavum amaidiyāka irukkum."},{"fr":"Ensuite, je lis le journal tranquillement.","tgt":"பிறகு நிதானமாகச் செய்தித்தாள் படிப்பேன்.","ro":"Piṛaku nidāṉamākach cheytittāḷ paḍippēṉ."},{"fr":"Après le déjeuner, je fais une bonne sieste.","tgt":"மதிய உணவுக்குப் பிறகு நன்றாக ஒரு தூக்கம் போடுவேன்.","ro":"Madiya uṇavukkup piṛaku naṉṛāka oru tūkkam pōḍuvēṉ."},{"fr":"Vers cinq heures, je vais marcher au bord du lac.","tgt":"மாலை ஐந்து மணிக்கு ஏரிக்கரைக்கு நடக்கப் போவேன்.","ro":"Mālai aindu maṇikku ērikkaraikku naḍakkap pōvēṉ."},{"fr":"Le soir, une brise agréable se lève.","tgt":"மாலையில் இதமான காற்று வீசும்.","ro":"Mālaiyil idamāṉa kāṛṛu vīchum."},{"fr":"Parfois, je téléphone à ma famille en France.","tgt":"சில சமயம் பிரான்ஸில் உள்ள என் குடும்பத்தோடு போனில் பேசுவேன்.","ro":"Chila chamayam Pirāṉsil uḷḷa eṉ kuḍumbattōḍu pōṉil pēchuvēṉ."},{"fr":"Ce calme me fait vraiment du bien.","tgt":"இந்த அமைதி மனதுக்கு இதமாக இருக்கிறது.","ro":"Inda amaidi maṉadukku idamāka irukkiṛadu."},{"fr":"Je suis prêt pour une nouvelle semaine.","tgt":"புதிய வாரத்துக்கு நான் தயார்.","ro":"Pudiya vārattukku nāṉ tayār."}]},{"title":"Les règles de l'atelier","phrases":[{"fr":"Ne touchez pas aux machines en marche.","tgt":"ஓடும் இயந்திரங்களைத் தொடாதீர்கள்.","ro":"Ōḍum iyandirangaḷait toḍādīrkaḷ."},{"fr":"Ne fumez pas à l'intérieur de l'usine.","tgt":"நிறுவனத்துக்குள் புகைபிடிக்காதீர்கள்.","ro":"Niṛuvaṉattukkuḷ pukaipiḍikkādīrkaḷ."},{"fr":"N'oubliez pas votre badge à l'entrée.","tgt":"வாசலில் உங்கள் அடையாள அட்டையை மறக்காதீர்கள்.","ro":"Vāchalil ungaḷ aḍaiyāḷa aṭṭaiyai maṛakkādīrkaḷ."},{"fr":"Ne courez pas dans les couloirs.","tgt":"நடைபாதைகளில் ஓடாதீர்கள்.","ro":"Naḍaipādaikaḷil ōḍādīrkaḷ."},{"fr":"Dans l'atelier, portez toujours votre masque.","tgt":"பட்டறையில் எப்போதும் முகக்கவசம் அணியுங்கள்.","ro":"Paṭṭaṛaiyil eppōdum mukakkavacham aṇiyungaḷ."},{"fr":"Ne posez pas de tissu par terre.","tgt":"தரையில் துணியைப் போடாதீர்கள்.","ro":"Taraiyil tuṇiyaip pōḍādīrkaḷ."},{"fr":"En cas de problème, ne paniquez pas.","tgt":"பிரச்சினை வந்தால் பதற்றப்படாதீர்கள்.","ro":"Pirachchiṉai vandāl padaṛṛappaḍādīrkaḷ."},{"fr":"Appelez immédiatement le responsable.","tgt":"உடனே பொறுப்பாளரை அழையுங்கள்.","ro":"Uḍaṉē poṛuppāḷarai aḻaiyungaḷ."},{"fr":"Ne partez pas avant la fin de votre service.","tgt":"உங்கள் பணிநேரம் முடிவதற்கு முன் போகாதீர்கள்.","ro":"Ungaḷ paṇinēram muḍivadaṛku muṉ pōkādīrkaḷ."},{"fr":"Ces règles protègent tout le monde.","tgt":"இந்த விதிகள் எல்லோரையும் பாதுகாக்கின்றன.","ro":"Inda vidikaḷ ellōraiyum pādukākkiṉṛaṉa."}],"tip":{"title":"« -ādīrkaḷ » : l'interdiction polie, ne faites pas","example":"Ne touchez pas aux machines en marche. — ஓடும் இயந்திரங்களைத் <b>தொடாதீர்கள்</b>.","body":"Pour interdire poliment, le tamoul utilise une seule terminaison, « ādīrkaḷ », qu'on accroche au verbe. « toḍu », toucher, devient « toḍādīrkaḷ », ne touchez pas, et « pō », aller, devient « pōkādīrkaḷ », ne partez pas. Dans « ōḍum iyandirangaḷait toḍādīrkaḷ », on entend : qui tournent, les machines, ne touchez pas. On la retrouve dans des formules très courantes : « maṛakkādīrkaḷ », n'oubliez pas, et la phrase si gentille « kavalaippaḍādīrkaḷ », ne vous inquiétez pas. C'est l'inverse exact de l'impératif poli en « ungaḷ », comme « vārungaḷ », venez. Astuce : le « ā » long du milieu sonne comme un non, et le « kaḷ » final ajoute le respect.","exampleRo":"Ōḍum iyandirangaḷait toḍādīrkaḷ.","lit":"qui tournent · machines [objet] (-ai) · ne touchez pas [respect]","say":{"toḍu":"தொடு","toḍādīrkaḷ":"தொடாதீர்கள்","pō":"போ","pōkādīrkaḷ":"போகாதீர்கள்","ōḍum iyandirangaḷait toḍādīrkaḷ":"ஓடும் இயந்திரங்களைத் தொடாதீர்கள்","maṛakkādīrkaḷ":"மறக்காதீர்கள்","kavalaippaḍādīrkaḷ":"கவலைப்படாதீர்கள்","ungaḷ":"உங்கள்","vārungaḷ":"வாருங்கள்"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a montré la vie quotidienne à Coimbatore.","tgt":"இந்தப் பகுதி கோயம்புத்தூர் வாழ்க்கையை நமக்குக் காட்டியது.","ro":"Indap pakudi Kōyambuttūr vāḻkkaiyai namakkuk kāṭṭiyadu."},{"fr":"Nous pouvons maintenant raconter ce que nous avons fait hier.","tgt":"நேற்று என்ன செய்தோம் என்று இப்போது சொல்ல முடியும்.","ro":"Nēṛṛu eṉṉa cheytōm eṉṛu ippōdu cholla muḍiyum."},{"fr":"Nous pouvons aussi parler de nos projets pour demain.","tgt":"நாளைய திட்டங்களைப் பற்றியும் பேச முடியும்.","ro":"Nāḷaiya tiṭṭangaḷaip paṛṛiyum pēcha muḍiyum."},{"fr":"Le tamoul me paraît plus facile qu'au début.","tgt":"ஆரம்பத்தை விட இப்போது தமிழ் எளிதாகத் தெரிகிறது.","ro":"Ārambattai viḍa ippōdu Tamiḻ eḷidākat terikiṛadu."},{"fr":"Je dois encore pratiquer tous les jours.","tgt":"நான் இன்னும் தினமும் பயிற்சி செய்ய வேண்டும்.","ro":"Nāṉ iṉṉum tiṉamum payiṛchi cheyya vēṇḍum."},{"fr":"Je n'abandonnerai pas maintenant !","tgt":"இப்போது நான் விட்டுவிட மாட்டேன்!","ro":"Ippōdu nāṉ viṭṭuviḍa māṭṭēṉ!"},{"fr":"Mes voisins remarquent déjà mes progrès.","tgt":"என் முன்னேற்றத்தைப் பக்கத்து வீட்டுக்காரர்கள் ஏற்கனவே கவனிக்கிறார்கள்.","ro":"Eṉ muṉṉēṛṛattaip pakkattu vīṭṭukkārarkaḷ ēṛkaṉavē kavaṉikkiṛārkaḷ."},{"fr":"Le prochain module sera consacré au voyage.","tgt":"அடுத்த பகுதி பயணங்களைப் பற்றியது.","ro":"Aḍutta pakudi payaṇangaḷaip paṛṛiyadu."},{"fr":"Bravo pour tous ces efforts réguliers !","tgt":"இந்த உழைப்புக்கு வாழ்த்துகள்!","ro":"Inda uḻaippukku vāḻttukaḷ!"},{"fr":"Rendez-vous bientôt dans le module suivant.","tgt":"விரைவில் அடுத்த பகுதியில் சந்திப்போம்.","ro":"Viraivil aḍutta pakudiyil chandippōm."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"En route vers les montagnes","phrases":[{"fr":"Nous partons pour Ooty demain matin.","tgt":"நாங்கள் நாளை காலை ஊட்டிக்குக் கிளம்புகிறோம்.","ro":"Nāngaḷ nāḷai kālai Ūṭṭikkuk kiḷambukiṛōm."},{"fr":"Le bus part de Coimbatore à six heures.","tgt":"பேருந்து கோயம்புத்தூரிலிருந்து ஆறு மணிக்குக் கிளம்பும்.","ro":"Pērundu Kōyambuttūrilirundu āṛu maṇikkuk kiḷambum."},{"fr":"J'ai réservé deux places hier soir.","tgt":"நான் நேற்று இரவு இரண்டு இருக்கைகளை முன்பதிவு செய்தேன்.","ro":"Nāṉ nēṛṛu iravu iraṇḍu irukkaikaḷai muṉpadivu cheydēṉ."},{"fr":"Il fera froid là-haut, prenez un pull.","tgt":"மேலே குளிராக இருக்கும், ஒரு ஸ்வெட்டர் எடுத்துக்கொள்ளுங்கள்.","ro":"Mēlē kuḷirāka irukkum, oru sveṭṭar eḍuttukkoḷḷungaḷ."},{"fr":"La route monte à travers la forêt.","tgt":"சாலை காட்டின் வழியாக மேலே ஏறுகிறது.","ro":"Chālai kāṭṭiṉ vaḻiyāka mēlē ēṛukiṛadu."},{"fr":"Nous changerons de bus à Mettupalayam.","tgt":"மேட்டுப்பாளையத்தில் நாங்கள் பேருந்து மாறுவோம்.","ro":"Mēṭṭuppāḷaiyattil nāngaḷ pērundu māṛuvōm."},{"fr":"Ma valise est sur le toit du bus.","tgt":"என் பெட்டி பேருந்தின் கூரை மேல் இருக்கிறது.","ro":"Eṉ peṭṭi pērundiṉ kūrai mēl irukkiṛadu."},{"fr":"Le chauffeur s'est arrêté pour boire un thé.","tgt":"ஓட்டுநர் டீ குடிக்க வண்டியை நிறுத்தினார்.","ro":"Ōṭṭunar ṭī kuḍikka vaṇḍiyai niṛuttiṉār."},{"fr":"Le voyage durera environ quatre heures.","tgt":"பயணம் சுமார் நான்கு மணி நேரம் ஆகும்.","ro":"Payaṇam chumār nāṉku maṇi nēram ākum."},{"fr":"J'ai déjà hâte de voir les montagnes.","tgt":"மலைகளைப் பார்க்க எனக்கு ஏற்கனவே ஆவலாக இருக்கிறது.","ro":"Malaikaḷaip pārkka eṉakku ēṛkaṉavē āvalāka irukkiṛadu."}]},{"title":"Le petit train de montagne","phrases":[{"fr":"Le petit train de montagne part de Mettupalayam.","tgt":"மலை ரயில் மேட்டுப்பாளையத்திலிருந்து கிளம்புகிறது.","ro":"Malai rayil Mēṭṭuppāḷaiyattilirundu kiḷambukiṛadu."},{"fr":"Ce train avance très lentement dans les montées.","tgt":"இந்த ரயில் ஏற்றங்களில் மிகவும் மெதுவாகச் செல்கிறது.","ro":"Inda rayil ēṛṛangaḷil mikavum meduvākach chelkiṛadu."},{"fr":"Nous avons pris des places côté fenêtre.","tgt":"நாங்கள் ஜன்னல் ஓரத்தில் இடம் பிடித்தோம்.","ro":"Nāngaḷ jaṉṉal ōrattil iḍam piḍittōm."},{"fr":"Le train passe par de nombreux tunnels.","tgt":"ரயில் பல சுரங்கப்பாதைகள் வழியாகச் செல்கிறது.","ro":"Rayil pala churangappādaikaḷ vaḻiyākach chelkiṛadu."},{"fr":"Regardez cette cascade sur la droite !","tgt":"வலது பக்கம் அந்த அருவியைப் பாருங்கள்!","ro":"Valadu pakkam anda aruviyaip pārungaḷ!"},{"fr":"Les enfants font coucou par la fenêtre.","tgt":"குழந்தைகள் ஜன்னல் வழியாகக் கை அசைக்கிறார்கள்.","ro":"Kuḻandaikaḷ jaṉṉal vaḻiyākak kai achaikkiṛārkaḷ."},{"fr":"Le train s'est arrêté dans une toute petite gare.","tgt":"ரயில் ஒரு சின்ன நிலையத்தில் நின்றது.","ro":"Rayil oru chiṉṉa nilaiyattil niṉṛadu."},{"fr":"Sur le quai, on a acheté des beignets chauds.","tgt":"நடைமேடையில் சூடான வடை வாங்கினோம்.","ro":"Naḍaimēḍaiyil chūḍāṉa vaḍai vāngiṉōm."},{"fr":"L'air devient plus frais à chaque virage.","tgt":"ஒவ்வொரு வளைவிலும் காற்று இன்னும் குளிர்ச்சியாகிறது.","ro":"Ovvoru vaḷaivilum kāṛṛu iṉṉum kuḷirchchiyākiṛadu."},{"fr":"Nous n'oublierons jamais ce trajet en train.","tgt":"இந்த ரயில் பயணத்தை நாங்கள் ஒருபோதும் மறக்க மாட்டோம்.","ro":"Inda rayil payaṇattai nāngaḷ orupōdum maṛakka māṭṭōm."}]},{"title":"Arrivée à Ooty","phrases":[{"fr":"Nous sommes arrivés à Ooty à midi.","tgt":"நாங்கள் மதியம் ஊட்டிக்கு வந்து சேர்ந்தோம்.","ro":"Nāngaḷ madiyam Ūṭṭikku vandu chērndōm."},{"fr":"Je vais d'abord aller voir l'hôtel.","tgt":"நான் முதலில் ஹோட்டலுக்குப் போய்ப் பார்க்கிறேன்.","ro":"Nāṉ mudalil hōṭṭalukkup pōyp pārkkiṛēṉ."},{"fr":"Allez acheter de l'eau et revenez vite.","tgt":"போய்த் தண்ணீர் வாங்கிக்கொண்டு சீக்கிரம் வாருங்கள்.","ro":"Pōyt taṇṇīr vāngikkoṇḍu chīkkiram vārungaḷ."},{"fr":"Il est venu nous chercher à la gare.","tgt":"அவர் ரயில் நிலையத்துக்கு வந்து எங்களை அழைத்துச் சென்றார்.","ro":"Avar rayil nilaiyattukku vandu engaḷai aḻaittuch cheṉṛār."},{"fr":"Nous avons posé nos sacs et nous sommes ressortis.","tgt":"பைகளை வைத்துவிட்டு மறுபடியும் வெளியே போனோம்.","ro":"Paikaḷai vaittuviṭṭu maṛupaḍiyum veḷiyē pōṉōm."},{"fr":"Je suis allé au marché acheter des fruits.","tgt":"நான் சந்தைக்குப் போய்ப் பழங்கள் வாங்கினேன்.","ro":"Nāṉ chandaikkup pōyp paḻangaḷ vāngiṉēṉ."},{"fr":"Venez donc manger avec nous ce soir.","tgt":"இன்று இரவு எங்களோடு வந்து சாப்பிடுங்கள்.","ro":"Iṉṛu iravu engaḷōḍu vandu chāppiḍungaḷ."},{"fr":"Elle est revenue dans la chambre et s'est reposée.","tgt":"அவள் அறைக்கு வந்து ஓய்வெடுத்தாள்.","ro":"Avaḷ aṛaikku vandu ōyveḍuttāḷ."},{"fr":"Allons marcher au bord du lac d'Ooty.","tgt":"ஊட்டி ஏரிக்குப் போய் நடக்கலாம்.","ro":"Ūṭṭi ērikkup pōy naḍakkalām."},{"fr":"Je suis venu ici surtout pour me reposer.","tgt":"நான் ஓய்வெடுக்கத்தான் இங்கே வந்தேன்.","ro":"Nāṉ ōyveḍukkattāṉ ingē vandēṉ."}],"tip":{"title":"« Pōy », « vandu » : enchaîner les actions avec le participe","example":"Je suis allé au marché acheter des fruits. — நான் சந்தைக்குப் <b>போய்ப்</b> பழங்கள் வாங்கினேன்.","body":"En tamoul, on ne relie presque jamais deux actions avec « et ». On met la première action à une forme figée, le participe, et seul le dernier verbe porte le temps et la personne. « Pōy » veut dire « étant allé », et « vandu » veut dire « étant venu ». Ainsi « Nāṉ chandaikkup pōyp paḻangaḷ vāngiṉēṉ » se décompose en : je, au marché, étant allé, des fruits, j'ai acheté. De la même façon, « vandu chāppiḍungaḷ » veut dire « venez manger », et « pōyp pārungaḷ » veut dire « allez voir ». Pour retenir, imaginez une chaîne où seul le dernier maillon est conjugué, comme si vous disiez en français : étant allé au marché, j'ai acheté des fruits.","exampleRo":"Nāṉ chandaikkup pōyp paḻangaḷ vāngiṉēṉ.","lit":"je · marché [à] · étant allé · fruits · ai acheté","say":{"Pōy":"போய்","vandu":"வந்து","Nāṉ chandaikkup pōyp paḻangaḷ vāngiṉēṉ":"நான் சந்தைக்குப் போய்ப் பழங்கள் வாங்கினேன்","vandu chāppiḍungaḷ":"வந்து சாப்பிடுங்கள்","pōyp pārungaḷ":"போய்ப் பாருங்கள்"}}},{"title":"Un hôtel dans la brume","phrases":[{"fr":"L'hôtel est caché dans le brouillard.","tgt":"ஹோட்டல் பனிமூட்டத்தில் மறைந்திருக்கிறது.","ro":"Hōṭṭal paṉimūṭṭattil maṛaindirukkiṛadu."},{"fr":"Avez-vous une chambre avec un chauffage ?","tgt":"ஹீட்டர் உள்ள அறை இருக்கிறதா?","ro":"Hīṭṭar uḷḷa aṛai irukkiṛadā?"},{"fr":"La chambre coûte deux mille roupies la nuit.","tgt":"அறைக்கு ஒரு இரவுக்கு இரண்டாயிரம் ரூபாய்.","ro":"Aṛaikku oru iravukku iraṇḍāyiram rūpāy."},{"fr":"Le petit-déjeuner est-il compris dans le prix ?","tgt":"காலை உணவும் இதில் அடங்குமா?","ro":"Kālai uṇavum idil aḍangumā?"},{"fr":"Ce matin, il n'y a pas d'eau chaude.","tgt":"இன்று காலை சுடுதண்ணீர் வரவில்லை.","ro":"Iṉṛu kālai chuḍutaṇṇīr varavillai."},{"fr":"Pourriez-vous m'apporter une couverture de plus ?","tgt":"எனக்கு இன்னொரு போர்வை கொண்டு வர முடியுமா?","ro":"Eṉakku iṉṉoru pōrvai koṇḍu vara muḍiyumā?"},{"fr":"La nuit, il fait vraiment très froid ici.","tgt":"இரவில் ரொம்பக் குளிராக இருக்கிறது.","ro":"Iravil rombak kuḷirāka irukkiṛadu."},{"fr":"Par la fenêtre, on ne voit que de la brume.","tgt":"ஜன்னல் வழியே பனிமூட்டம் மட்டும்தான் தெரிகிறது.","ro":"Jaṉṉal vaḻiyē paṉimūṭṭam maṭṭumtāṉ terikiṛadu."},{"fr":"Le gérant nous a servi un thé brûlant.","tgt":"மேலாளர் எங்களுக்குச் சூடான டீ கொடுத்தார்.","ro":"Mēlāḷar engaḷukkuch chūḍāṉa ṭī koḍuttār."},{"fr":"Nous resterons ici trois nuits.","tgt":"நாங்கள் இங்கே மூன்று இரவுகள் தங்குவோம்.","ro":"Nāngaḷ ingē mūṉṛu iravukaḷ tanguvōm."}]},{"title":"Les plantations de thé","phrases":[{"fr":"Nous allons visiter une plantation de thé.","tgt":"நாங்கள் ஒரு தேயிலைத் தோட்டத்தைப் பார்க்கப் போகிறோம்.","ro":"Nāngaḷ oru tēyilait tōṭṭattaip pārkkap pōkiṛōm."},{"fr":"Le guide est sur le point de commencer.","tgt":"வழிகாட்டி ஆரம்பிக்கப் போகிறார்.","ro":"Vaḻikāṭṭi ārambikkap pōkiṛār."},{"fr":"Ces femmes vont cueillir les feuilles de thé.","tgt":"இந்தப் பெண்கள் தேயிலை பறிக்கப் போகிறார்கள்.","ro":"Indap peṇkaḷ tēyilai paṛikkap pōkiṛārkaḷ."},{"fr":"Ils ne cueillent que les deux feuilles du sommet.","tgt":"மேலே உள்ள இரண்டு இலைகளை மட்டும்தான் பறிப்பார்கள்.","ro":"Mēlē uḷḷa iraṇḍu ilaikaḷai maṭṭumtāṉ paṛippārkaḷ."},{"fr":"Il va pleuvoir, dépêchons-nous.","tgt":"மழை பெய்யப் போகிறது, சீக்கிரம் போகலாம்.","ro":"Maḻai peyyap pōkiṛadu, chīkkiram pōkalām."},{"fr":"Je vais goûter ce thé tout frais.","tgt":"நான் இந்தப் புதிய டீயைச் சுவைத்துப் பார்க்கப் போகிறேன்.","ro":"Nāṉ indap pudiya ṭīyaich chuvaittup pārkkap pōkiṛēṉ."},{"fr":"On voit des rangées vertes sur toutes les collines.","tgt":"மலைகள் எங்கும் பச்சை வரிசைகள் தெரிகின்றன.","ro":"Malaikaḷ engum pachchai varichaikaḷ terikiṉṛaṉa."},{"fr":"Ils vont bientôt fermer l'usine.","tgt":"தொழிற்சாலையை மூடப் போகிறார்கள்.","ro":"Toḻiṛchālaiyai mūḍap pōkiṛārkaḷ."},{"fr":"Je vais acheter deux paquets pour ma famille.","tgt":"என் குடும்பத்துக்கு இரண்டு பாக்கெட் வாங்கப் போகிறேன்.","ro":"Eṉ kuḍumbattukku iraṇḍu pākkeṭ vāngap pōkiṛēṉ."},{"fr":"Ce thé sent vraiment très bon.","tgt":"இந்த டீ ரொம்ப மணக்கிறது.","ro":"Inda ṭī romba maṇakkiṛadu."}],"tip":{"title":"« Pōkap pōkiṛēṉ » : être sur le point de","example":"Il va pleuvoir, dépêchons-nous. — மழை <b>பெய்யப்</b> <b>போகிறது</b>, சீக்கிரம் போகலாம்.","body":"Pour dire qu'une chose va arriver tout de suite, le tamoul fait exactement comme le français : il utilise le verbe « aller ». On prend le verbe à l'infinitif, qui finit par « a », puis on ajoute « pōkiṛēṉ », je vais, « pōkiṛadu », ça va, ou « pōkiṛōm », nous allons. Ainsi « Maḻai peyyap pōkiṛadu » se décompose en : la pluie, tomber, elle va. Remarquez le « p » doublé à la jonction : on dit « peyyap pōkiṛadu », en appuyant bien sur ce double « p ». Autres exemples : « pārkkap pōkiṛōm », nous allons voir, et « vāngap pōkiṛēṉ », je vais acheter. Astuce : pensez « aller » en tamoul comme en français, mais placé après le verbe.","exampleRo":"Maḻai peyyap pōkiṛadu, chīkkiram pōkalām.","lit":"pluie · tomber · va · vite · allons-y","say":{"Pōkap pōkiṛēṉ":"போகப் போகிறேன்","pōkiṛēṉ":"போகிறேன்","pōkiṛadu":"போகிறது","pōkiṛōm":"போகிறோம்","Maḻai peyyap pōkiṛadu":"மழை பெய்யப் போகிறது","peyyap pōkiṛadu":"பெய்யப் போகிறது","pārkkap pōkiṛōm":"பார்க்கப் போகிறோம்","vāngap pōkiṛēṉ":"வாங்கப் போகிறேன்"}}},{"title":"Le jardin botanique d'Ooty","phrases":[{"fr":"Le jardin botanique ouvre à huit heures.","tgt":"தாவரவியல் பூங்கா எட்டு மணிக்குத் திறக்கும்.","ro":"Tāvaraviyal pūngā eṭṭu maṇikkut tiṛakkum."},{"fr":"L'entrée coûte cinquante roupies par personne.","tgt":"நுழைவுக் கட்டணம் ஒருவருக்கு ஐம்பது ரூபாய்.","ro":"Nuḻaivuk kaṭṭaṇam oruvarukku aimbadu rūpāy."},{"fr":"Les pelouses sont immenses et très bien entretenues.","tgt":"புல்வெளிகள் மிகப் பெரியவை, நன்றாகப் பராமரிக்கப்படுகின்றன.","ro":"Pulveḷikaḷ mikap periyavai, naṉṛākap parāmarikkappaḍukiṉṛaṉa."},{"fr":"Cet arbre a plus de cent ans.","tgt":"இந்த மரத்துக்கு நூறு வயதுக்கு மேல் ஆகிறது.","ro":"Inda marattukku nūṛu vayadukku mēl ākiṛadu."},{"fr":"J'ai pris beaucoup de photos des fleurs.","tgt":"நான் பூக்களை நிறையப் படம் எடுத்தேன்.","ro":"Nāṉ pūkkaḷai niṛaiyap paḍam eḍuttēṉ."},{"fr":"Une grande exposition de fleurs a lieu en mai.","tgt":"மே மாதத்தில் பெரிய மலர்க் கண்காட்சி நடக்கும்.","ro":"Mē mādattil periya malark kaṇkāṭchi naḍakkum."},{"fr":"Asseyons-nous sur ce banc à l'ombre.","tgt":"நிழலில் உள்ள இந்த இருக்கையில் உட்காரலாம்.","ro":"Niḻalil uḷḷa inda irukkaiyil uṭkāralām."},{"fr":"Le soleil apparaît enfin entre les nuages.","tgt":"மேகங்களுக்கு நடுவே கடைசியில் சூரியன் தெரிகிறது.","ro":"Mēkangaḷukku naḍuvē kaḍaichiyil chūriyaṉ terikiṛadu."},{"fr":"Les enfants courent dans l'herbe.","tgt":"குழந்தைகள் புல்லில் ஓடுகிறார்கள்.","ro":"Kuḻandaikaḷ pullil ōḍukiṛārkaḷ."},{"fr":"Nous avons passé toute la matinée ici.","tgt":"காலை முழுவதும் இங்கேயே இருந்தோம்.","ro":"Kālai muḻuvadum ingēyē irundōm."}]},{"title":"La boulangerie locale","phrases":[{"fr":"Tout le monde connaît cette boulangerie.","tgt":"இந்த பேக்கரியை எல்லோருக்கும் தெரியும்.","ro":"Inda pēkkariyai ellōrukkum teriyum."},{"fr":"Les gâteaux sortent tout juste du four.","tgt":"கேக்குகள் இப்போதுதான் அடுப்பிலிருந்து வந்தன.","ro":"Kēkkukaḷ ippōdutāṉ aḍuppilirundu vandaṉa."},{"fr":"Je voudrais une part de cake aux fruits.","tgt":"எனக்கு ஒரு துண்டு பழக் கேக் வேண்டும்.","ro":"Eṉakku oru tuṇḍu paḻak kēk vēṇḍum."},{"fr":"Ce pain au beurre est délicieux.","tgt":"இந்த வெண்ணெய் ரொட்டி மிகவும் சுவையாக இருக்கிறது.","ro":"Inda veṇṇey roṭṭi mikavum chuvaiyāka irukkiṛadu."},{"fr":"Combien coûte ce gâteau à la noix de coco ?","tgt":"இந்தத் தேங்காய் கேக் எவ்வளவு?","ro":"Indat tēngāy kēk evvaḷavu?"},{"fr":"Est-ce qu'il en reste encore ?","tgt":"இன்னும் மீதி இருக்கிறதா?","ro":"Iṉṉum mīdi irukkiṛadā?"},{"fr":"Le boulanger travaille depuis cinq heures du matin.","tgt":"ரொட்டிக்காரர் காலை ஐந்து மணியிலிருந்து வேலை செய்கிறார்.","ro":"Roṭṭikkārar kālai aindu maṇiyilirundu vēlai cheykiṛār."},{"fr":"J'en prends une boîte pour la route.","tgt":"பயணத்துக்கு ஒரு பெட்டி வாங்கிக்கொள்கிறேன்.","ro":"Payaṇattukku oru peṭṭi vāngikkoḷkiṛēṉ."},{"fr":"Mettez-les dans un sac en papier, s'il vous plaît.","tgt":"தயவுசெய்து இவற்றைக் காகிதப் பையில் போடுங்கள்.","ro":"Tayavucheydu ivaṛṛaik kākidap paiyil pōḍungaḷ."},{"fr":"L'odeur du pain se répand dans toute la rue.","tgt":"ரொட்டி வாசனை தெரு முழுவதும் பரவுகிறது.","ro":"Roṭṭi vāchaṉai teru muḻuvadum paravukiṛadu."}]},{"title":"Une voiture pour Kodaikanal","phrases":[{"fr":"Nous voulons louer une voiture avec chauffeur.","tgt":"நாங்கள் ஓட்டுநருடன் ஒரு கார் வாடகைக்கு எடுக்க விரும்புகிறோம்.","ro":"Nāngaḷ ōṭṭunaruḍaṉ oru kār vāḍakaikku eḍukka virumbukiṛōm."},{"fr":"Si on part tôt, on arrivera avant la nuit.","tgt":"சீக்கிரம் கிளம்பினால் இருட்டுவதற்கு முன் போய்ச் சேருவோம்.","ro":"Chīkkiram kiḷambiṉāl iruṭṭuvadaṛku muṉ pōych chēruvōm."},{"fr":"Si vous payez d'avance, c'est moins cher.","tgt":"முன்பணம் கொடுத்தால் விலை குறைவு.","ro":"Muṉpaṇam koḍuttāl vilai kuṛaivu."},{"fr":"Si la route est mauvaise, roulez doucement.","tgt":"சாலை மோசமாக இருந்தால் மெதுவாக ஓட்டுங்கள்.","ro":"Chālai mōchamāka irundāl meduvāka ōṭṭungaḷ."},{"fr":"Si vous avez faim, on s'arrêtera en route.","tgt":"உங்களுக்குப் பசித்தால் வழியில் நிறுத்துவோம்.","ro":"Ungaḷukkup pachittāl vaḻiyil niṛuttuvōm."},{"fr":"Combien coûte le trajet jusqu'à Kodaikanal ?","tgt":"கொடைக்கானல் வரை எவ்வளவு ஆகும்?","ro":"Koḍaikkāṉal varai evvaḷavu ākum?"},{"fr":"Si vous voulez, nous pouvons partir tout de suite.","tgt":"நீங்கள் விரும்பினால் இப்போதே கிளம்பலாம்.","ro":"Nīngaḷ virumbiṉāl ippōdē kiḷambalām."},{"fr":"Si j'ai la nausée, je vous le dirai.","tgt":"எனக்கு வாந்தி வருவது போல் இருந்தால் உங்களிடம் சொல்கிறேன்.","ro":"Eṉakku vāndi varuvadu pōl irundāl ungaḷiḍam cholkiṛēṉ."},{"fr":"La route a beaucoup de virages en épingle.","tgt":"சாலையில் நிறையக் கொண்டை ஊசி வளைவுகள் உள்ளன.","ro":"Chālaiyil niṛaiyak koṇḍai ūchi vaḷaivukaḷ uḷḷaṉa."},{"fr":"S'il y a du brouillard, nous attendrons un moment.","tgt":"பனிமூட்டம் இருந்தால் சிறிது நேரம் காத்திருப்போம்.","ro":"Paṉimūṭṭam irundāl chiṛidu nēram kāttiruppōm."}],"tip":{"title":"« -āl » : si..., alors","example":"Si on part tôt, on arrivera avant la nuit. — சீக்கிரம் <b>கிளம்பினால்</b> இருட்டுவதற்கு முன் போய்ச் சேருவோம்.","body":"En tamoul, il n'y a pas de petit mot « si » au début de la phrase : la condition se colle à la fin du verbe, sous la forme « -āl ». On part de la forme du passé, puis on ajoute « -āl » : « kiḷambiṉēṉ », je suis parti, devient « kiḷambiṉāl », si on part. Notre exemple se décompose ainsi : tôt, si on part, avant la nuit, on arrivera. La condition vient toujours en premier, puis la conséquence, comme en français. Voici d'autres formes très utiles : « irundāl », s'il y a, « koḍuttāl », si vous donnez, « virumbiṉāl », si vous voulez. Astuce : entendez « -āl » comme un « alors » qui annonce la suite.","exampleRo":"Chīkkiram kiḷambiṉāl iruṭṭuvadaṛku muṉ pōych chēruvōm.","lit":"tôt · si (on) part · faire nuit [pour] · avant · étant allé · arriverons","say":{"kiḷambiṉēṉ":"கிளம்பினேன்","kiḷambiṉāl":"கிளம்பினால்","irundāl":"இருந்தால்","koḍuttāl":"கொடுத்தால்","virumbiṉāl":"விரும்பினால்"}}},{"title":"La panne de voiture","phrases":[{"fr":"La voiture s'est arrêtée en pleine montée.","tgt":"ஏற்றத்தின் நடுவில் கார் நின்றுவிட்டது.","ro":"Ēṛṛattiṉ naḍuvil kār niṉṛuviṭṭadu."},{"fr":"Le moteur fait un bruit bizarre.","tgt":"இன்ஜினில் ஏதோ விசித்திரமான சத்தம் வருகிறது.","ro":"Iṉjiṉil ēdō vichittiramāṉa chattam varukiṛadu."},{"fr":"Le chauffeur a ouvert le capot.","tgt":"ஓட்டுநர் காரின் முன்பக்க மூடியைத் திறந்தார்.","ro":"Ōṭṭunar kāriṉ muṉpakka mūḍiyait tiṛandār."},{"fr":"Je crois que le moteur a trop chauffé.","tgt":"இன்ஜின் அதிகமாகச் சூடாகிவிட்டது என்று நினைக்கிறேன்.","ro":"Iṉjiṉ adikamākach chūḍākiviṭṭadu eṉṛu niṉaikkiṛēṉ."},{"fr":"Ici, il n'y a pas de réseau.","tgt":"இங்கே சிக்னல் இல்லை.","ro":"Ingē chikṉal illai."},{"fr":"Nous allons attendre au bord de la route.","tgt":"சாலை ஓரத்தில் காத்திருப்போம்.","ro":"Chālai ōrattil kāttiruppōm."},{"fr":"Un camion s'est arrêté pour nous aider.","tgt":"எங்களுக்கு உதவ ஒரு லாரி நின்றது.","ro":"Engaḷukku udava oru lāri niṉṛadu."},{"fr":"Le camionneur nous a donné de l'eau pour le moteur.","tgt":"அந்த ஓட்டுநர் இன்ஜினுக்குத் தண்ணீர் கொடுத்தார்.","ro":"Anda ōṭṭunar iṉjiṉukkut taṇṇīr koḍuttār."},{"fr":"Au bout d'une demi-heure, la voiture a redémarré.","tgt":"அரை மணி நேரம் கழித்து கார் மறுபடியும் ஓடத் தொடங்கியது.","ro":"Arai maṇi nēram kaḻittu kār maṛupaḍiyum ōḍat toḍangiyadu."},{"fr":"Heureusement, personne n'a été blessé.","tgt":"நல்லவேளை, யாருக்கும் அடிபடவில்லை.","ro":"Nallavēḷai, yārukkum aḍipaḍavillai."}]},{"title":"Chez le garagiste","phrases":[{"fr":"Où est le garagiste le plus proche ?","tgt":"பக்கத்தில் உள்ள மெக்கானிக் கடை எங்கே?","ro":"Pakkattil uḷḷa mekkāṉik kaḍai engē?"},{"fr":"Pouvez-vous jeter un œil à notre voiture ?","tgt":"எங்கள் காரைப் பார்க்க முடியுமா?","ro":"Engaḷ kāraip pārkka muḍiyumā?"},{"fr":"Le pneu arrière est à plat.","tgt":"பின் டயரில் காற்று இறங்கிவிட்டது.","ro":"Piṉ ṭayaril kāṛṛu iṛangiviṭṭadu."},{"fr":"Combien de temps faut-il pour la réparer ?","tgt":"சரிசெய்ய எவ்வளவு நேரம் ஆகும்?","ro":"Charicheyya evvaḷavu nēram ākum?"},{"fr":"Elle sera prête dans une heure.","tgt":"ஒரு மணி நேரத்தில் தயாராகிவிடும்.","ro":"Oru maṇi nērattil tayārākiviḍum."},{"fr":"Il faut changer une pièce du frein.","tgt":"பிரேக்கில் ஒரு பாகத்தை மாற்ற வேண்டும்.","ro":"Pirēkkil oru pākattai māṛṛa vēṇḍum."},{"fr":"Combien est-ce que je dois payer ?","tgt":"நான் எவ்வளவு பணம் கொடுக்க வேண்டும்?","ro":"Nāṉ evvaḷavu paṇam koḍukka vēṇḍum?"},{"fr":"Ça fera huit cents roupies en tout.","tgt":"மொத்தம் எண்ணூறு ரூபாய் ஆகும்.","ro":"Mottam eṇṇūṛu rūpāy ākum."},{"fr":"En attendant, nous allons boire un café.","tgt":"அதுவரை நாங்கள் ஒரு காபி குடிப்போம்.","ro":"Aduvarai nāngaḷ oru kāpi kuḍippōm."},{"fr":"Merci beaucoup, vous nous avez sauvés aujourd'hui.","tgt":"ரொம்ப நன்றி, இன்று எங்களைக் காப்பாற்றினீர்கள்.","ro":"Romba naṉṛi, iṉṛu engaḷaik kāppāṛṛiṉīrkaḷ."}]},{"title":"Le lac de Kodaikanal","phrases":[{"fr":"Kodaikanal est plus calme qu'Ooty.","tgt":"ஊட்டியை விட கொடைக்கானல் அமைதியாக இருக்கிறது.","ro":"Ūṭṭiyai viḍa Koḍaikkāṉal amaidiyāka irukkiṛadu."},{"fr":"Le lac a la forme d'une étoile.","tgt":"இந்த ஏரி நட்சத்திர வடிவத்தில் இருக்கிறது.","ro":"Inda ēri naṭchattira vaḍivattil irukkiṛadu."},{"fr":"On peut faire le tour du lac à pied.","tgt":"ஏரியைச் சுற்றி நடக்கலாம்.","ro":"Ēriyaich chuṛṛi naḍakkalām."},{"fr":"Louons une barque pour une heure.","tgt":"ஒரு மணி நேரத்துக்கு ஒரு படகை வாடகைக்கு எடுக்கலாம்.","ro":"Oru maṇi nērattukku oru paḍakai vāḍakaikku eḍukkalām."},{"fr":"Je rame et vous prenez les photos.","tgt":"நான் துடுப்பு போடுகிறேன், நீங்கள் படம் எடுங்கள்.","ro":"Nāṉ tuḍuppu pōḍukiṛēṉ, nīngaḷ paḍam eḍungaḷ."},{"fr":"L'eau est très calme ce matin.","tgt":"இன்று காலை தண்ணீர் மிகவும் அமைதியாக இருக்கிறது.","ro":"Iṉṛu kālai taṇṇīr mikavum amaidiyāka irukkiṛadu."},{"fr":"On peut aussi louer des vélos près du lac.","tgt":"ஏரி அருகே சைக்கிளும் வாடகைக்குக் கிடைக்கும்.","ro":"Ēri arukē chaikkiḷum vāḍakaikkuk kiḍaikkum."},{"fr":"Des chevaux attendent les touristes au bord de l'eau.","tgt":"கரையில் குதிரைகள் சுற்றுலாப் பயணிகளுக்காகக் காத்திருக்கின்றன.","ro":"Karaiyil kudiraikaḷ chuṛṛulāp payaṇikaḷukkākak kāttirukkiṉṛaṉa."},{"fr":"Le soir, la brume descend sur le lac.","tgt":"மாலையில் ஏரியின் மேல் பனிமூட்டம் இறங்குகிறது.","ro":"Mālaiyil ēriyiṉ mēl paṉimūṭṭam iṛangukiṛadu."},{"fr":"C'est l'endroit le plus paisible de tout le voyage.","tgt":"இந்தப் பயணத்திலேயே இதுதான் மிக அமைதியான இடம்.","ro":"Indap payaṇattilēyē idutāṉ mika amaidiyāṉa iḍam."}]},{"title":"Une randonnée difficile","phrases":[{"fr":"Ce sentier monte jusqu'au sommet.","tgt":"இந்தப் பாதை உச்சி வரை ஏறுகிறது.","ro":"Indap pādai uchchi varai ēṛukiṛadu."},{"fr":"Je ne peux plus marcher, je suis épuisé.","tgt":"என்னால் இனிமேல் நடக்க முடியாது, ரொம்பக் களைப்பாக இருக்கிறது.","ro":"Eṉṉāl iṉimēl naḍakka muḍiyādu, rombak kaḷaippāka irukkiṛadu."},{"fr":"On ne peut pas passer par ici, c'est fermé.","tgt":"இந்த வழியாகப் போக முடியாது, மூடியிருக்கிறது.","ro":"Inda vaḻiyākap pōka muḍiyādu, mūḍiyirukkiṛadu."},{"fr":"Avec ce brouillard, on ne peut rien voir.","tgt":"இந்தப் பனிமூட்டத்தில் எதையும் பார்க்க முடியாது.","ro":"Indap paṉimūṭṭattil edaiyum pārkka muḍiyādu."},{"fr":"Elle ne peut pas porter ce gros sac.","tgt":"அவளால் இந்தப் பெரிய பையைத் தூக்க முடியாது.","ro":"Avaḷāl indap periya paiyait tūkka muḍiyādu."},{"fr":"Aujourd'hui, je ne peux pas monter plus haut.","tgt":"இன்று என்னால் இதற்கு மேல் ஏற முடியாது.","ro":"Iṉṛu eṉṉāl idaṛku mēl ēṛa muḍiyādu."},{"fr":"Reposons-nous sous cet arbre.","tgt":"இந்த மரத்தடியில் ஓய்வெடுக்கலாம்.","ro":"Inda marattaḍiyil ōyveḍukkalām."},{"fr":"Buvez de l'eau régulièrement.","tgt":"அடிக்கடி தண்ணீர் குடியுங்கள்.","ro":"Aḍikkaḍi taṇṇīr kuḍiyungaḷ."},{"fr":"Sans guide, on ne peut pas entrer dans la forêt.","tgt":"வழிகாட்டி இல்லாமல் காட்டுக்குள் போக முடியாது.","ro":"Vaḻikāṭṭi illāmal kāṭṭukkuḷ pōka muḍiyādu."},{"fr":"Du sommet, la vue est magnifique.","tgt":"உச்சியிலிருந்து பார்க்கும் காட்சி அற்புதமாக இருக்கிறது.","ro":"Uchchiyilirundu pārkkum kāṭchi aṛputamāka irukkiṛadu."}],"tip":{"title":"« Muḍiyādu » : ne pas pouvoir","example":"Je ne peux plus marcher, je suis épuisé. — <b>என்னால்</b> இனிமேல் நடக்க <b>முடியாது</b>, ரொம்பக் களைப்பாக இருக்கிறது.","body":"Pour dire « je ne peux pas », le tamoul ne conjugue pas le verbe pouvoir : il dit plutôt « par moi, marcher, ce n'est pas possible ». La personne prend la terminaison « -āl », par : « eṉṉāl », par moi, « avaḷāl », par elle. Ensuite vient le verbe à l'infinitif en « a », puis le mot invariable « muḍiyādu », impossible. Notre exemple se décompose ainsi : par moi, désormais, marcher, impossible. Pour une règle générale, on peut même enlever la personne : « pōka muḍiyādu », on ne peut pas y aller. Et pour demander poliment, on remplace par « muḍiyumā », est-ce possible, comme dans « vara muḍiyumā », pouvez-vous venir. Astuce : « muḍiyādu » ne change jamais, c'est votre panneau « impossible ».","exampleRo":"Eṉṉāl iṉimēl naḍakka muḍiyādu, rombak kaḷaippāka irukkiṛadu.","lit":"par moi · désormais · marcher · impossible · très · fatigué · c'est","say":{"Muḍiyādu":"முடியாது","eṉṉāl":"என்னால்","avaḷāl":"அவளால்","muḍiyādu":"முடியாது","pōka muḍiyādu":"போக முடியாது","muḍiyumā":"முடியுமா","vara muḍiyumā":"வர முடியுமா"}}},{"title":"Pluie et brouillard","phrases":[{"fr":"Il pleut sans arrêt depuis ce matin.","tgt":"காலையிலிருந்து விடாமல் மழை பெய்கிறது.","ro":"Kālaiyilirundu viḍāmal maḻai peykiṛadu."},{"fr":"Le ciel est tout gris.","tgt":"வானம் முழுவதும் சாம்பல் நிறமாக இருக்கிறது.","ro":"Vāṉam muḻuvadum chāmbal niṛamāka irukkiṛadu."},{"fr":"J'ai oublié mon parapluie à l'hôtel.","tgt":"என் குடையை ஹோட்டலில் மறந்துவிட்டேன்.","ro":"Eṉ kuḍaiyai hōṭṭalil maṛanduviṭṭēṉ."},{"fr":"J'ai les chaussures complètement mouillées.","tgt":"என் காலணிகள் முழுவதும் நனைந்துவிட்டன.","ro":"Eṉ kālaṇikaḷ muḻuvadum naṉainduviṭṭaṉa."},{"fr":"Restons au restaurant jusqu'à la fin de la pluie.","tgt":"மழை நிற்கும் வரை உணவகத்திலேயே இருப்போம்.","ro":"Maḻai niṛkum varai uṇavakattilēyē iruppōm."},{"fr":"On ne voit même plus la route.","tgt":"சாலை கூடத் தெரியவில்லை.","ro":"Chālai kūḍat teriyavillai."},{"fr":"Les voitures roulent avec les phares allumés.","tgt":"கார்கள் விளக்குகளைப் போட்டுக்கொண்டு செல்கின்றன.","ro":"Kārkaḷ viḷakkukaḷaip pōṭṭukkoṇḍu chelkiṉṛaṉa."},{"fr":"En montagne, le temps change vite.","tgt":"மலைகளில் வானிலை சீக்கிரம் மாறும்.","ro":"Malaikaḷil vāṉilai chīkkiram māṛum."},{"fr":"Une tasse de thé chaud nous ferait du bien.","tgt":"ஒரு கப் சூடான டீ குடித்தால் நன்றாக இருக்கும்.","ro":"Oru kap chūḍāṉa ṭī kuḍittāl naṉṛāka irukkum."},{"fr":"D'après la météo, il fera beau demain.","tgt":"வானிலை அறிக்கைப்படி நாளை வெயில் அடிக்கும்.","ro":"Vāṉilai aṛikkaippaḍi nāḷai veyil aḍikkum."}]},{"title":"Le marché de Kodaikanal","phrases":[{"fr":"Le marché est près de la gare routière.","tgt":"சந்தை பேருந்து நிலையத்துக்கு அருகில் இருக்கிறது.","ro":"Chandai pērundu nilaiyattukku arukil irukkiṛadu."},{"fr":"Ici, on vend du chocolat fait maison.","tgt":"இங்கே வீட்டில் செய்த சாக்லேட் விற்கிறார்கள்.","ro":"Ingē vīṭṭil cheyda chākleṭ viṛkiṛārkaḷ."},{"fr":"Ces prunes viennent des vergers voisins.","tgt":"இந்தப் பிளம் பழங்கள் பக்கத்துத் தோட்டங்களிலிருந்து வருகின்றன.","ro":"Indap piḷam paḻangaḷ pakkattut tōṭṭangaḷilirundu varukiṉṛaṉa."},{"fr":"Combien coûte un kilo de poires ?","tgt":"ஒரு கிலோ பேரிக்காய் எவ்வளவு?","ro":"Oru kilō pērikkāy evvaḷavu?"},{"fr":"C'est trop cher, faites-moi un meilleur prix.","tgt":"இது ரொம்ப அதிக விலை, விலையைக் குறைத்துக் கொடுங்கள்.","ro":"Idu romba adika vilai, vilaiyaik kuṛaittuk koḍungaḷ."},{"fr":"D'accord, je vous le laisse à cent roupies.","tgt":"சரி, நூறு ரூபாய்க்குத் தருகிறேன்.","ro":"Chari, nūṛu rūpāykkut tarukiṛēṉ."},{"fr":"Ces champignons sont-ils bien frais ?","tgt":"இந்தக் காளான்கள் புதியவையா?","ro":"Indak kāḷāṉkaḷ pudiyavaiyā?"},{"fr":"Je cherche de l'huile d'eucalyptus.","tgt":"நான் யூகலிப்டஸ் எண்ணெய் தேடுகிறேன்.","ro":"Nāṉ yūkalipṭas eṇṇey tēḍukiṛēṉ."},{"fr":"Le marchand m'a fait goûter un petit morceau.","tgt":"கடைக்காரர் சுவைத்துப் பார்க்க ஒரு சின்னத் துண்டு கொடுத்தார்.","ro":"Kaḍaikkārar chuvaittup pārkka oru chiṉṉat tuṇḍu koḍuttār."},{"fr":"Mon sac est déjà plein de souvenirs.","tgt":"என் பை ஏற்கனவே நினைவுப் பொருட்களால் நிறைந்திருக்கிறது.","ro":"Eṉ pai ēṛkaṉavē niṉaivup poruṭkaḷāl niṛaindirukkiṛadu."}]},{"title":"Un petit souci de santé","phrases":[{"fr":"Depuis hier soir, je ne me sens pas bien.","tgt":"நேற்று இரவிலிருந்து எனக்கு உடம்பு சரியில்லை.","ro":"Nēṛṛu iravilirundu eṉakku uḍambu chariyillai."},{"fr":"J'ai mal à la tête et une légère fièvre.","tgt":"எனக்குத் தலைவலியும் லேசான காய்ச்சலும் இருக்கிறது.","ro":"Eṉakkut talaivaliyum lēchāṉa kāychchalum irukkiṛadu."},{"fr":"Où y a-t-il une pharmacie près d'ici ?","tgt":"பக்கத்தில் மருந்துக்கடை எங்கே இருக்கிறது?","ro":"Pakkattil marundukkaḍai engē irukkiṛadu?"},{"fr":"C'est peut-être à cause de l'altitude.","tgt":"உயரத்தின் காரணமாக இருக்கலாம்.","ro":"Uyarattiṉ kāraṇamāka irukkalām."},{"fr":"Prenez ce comprimé après le repas.","tgt":"சாப்பிட்ட பிறகு இந்த மாத்திரையைச் சாப்பிடுங்கள்.","ro":"Chāppiṭṭa piṛaku inda māttiraiyaich chāppiḍungaḷ."},{"fr":"Deux fois par jour pendant trois jours.","tgt":"மூன்று நாட்களுக்கு ஒரு நாளைக்கு இரண்டு முறை.","ro":"Mūṉṛu nāṭkaḷukku oru nāḷaikku iraṇḍu muṛai."},{"fr":"Reposez-vous et buvez énormément d'eau.","tgt":"நன்றாக ஓய்வெடுங்கள், நிறையத் தண்ணீர் குடியுங்கள்.","ro":"Naṉṛāka ōyveḍungaḷ, niṛaiyat taṇṇīr kuḍiyungaḷ."},{"fr":"Est-ce qu'il faut voir un médecin ?","tgt":"டாக்டரைப் பார்க்க வேண்டுமா?","ro":"Ṭākṭaraip pārkka vēṇḍumā?"},{"fr":"Si ça ne va pas mieux demain, revenez me voir.","tgt":"நாளை சரியாகாவிட்டால் மறுபடியும் வாருங்கள்.","ro":"Nāḷai chariyākāviṭṭāl maṛupaḍiyum vārungaḷ."},{"fr":"Ça va déjà mieux maintenant.","tgt":"எனக்கு இப்போது பரவாயில்லை.","ro":"Eṉakku ippōdu paravāyillai."}]},{"title":"Rencontre avec d'autres voyageurs","phrases":[{"fr":"Nous avons rencontré un couple de Pondichéry.","tgt":"நாங்கள் பாண்டிச்சேரியைச் சேர்ந்த ஒரு தம்பதியைச் சந்தித்தோம்.","ro":"Nāngaḷ Pāṇḍichchēriyaich chērnda oru tambadiyaich chandittōm."},{"fr":"Même s'il pleut, ils vont faire la randonnée.","tgt":"மழை பெய்தாலும் அவர்கள் மலையேற்றத்துக்குப் போவார்கள்.","ro":"Maḻai peydālum avarkaḷ malaiyēṛṛattukkup pōvārkaḷ."},{"fr":"Bien qu'ils soient âgés, ils marchent beaucoup.","tgt":"வயதானவர்களாக இருந்தாலும் அவர்கள் நிறைய நடக்கிறார்கள்.","ro":"Vayadāṉavarkaḷāka irundālum avarkaḷ niṛaiya naḍakkiṛārkaḷ."},{"fr":"Même si je parle peu tamoul, ils me comprennent.","tgt":"நான் தமிழ் குறைவாகப் பேசினாலும் அவர்களுக்குப் புரிகிறது.","ro":"Nāṉ tamiḻ kuṛaivākap pēchiṉālum avarkaḷukkup purikiṛadu."},{"fr":"Ils nous ont invités à dîner ce soir.","tgt":"இன்று இரவு சாப்பிட எங்களை அழைத்தார்கள்.","ro":"Iṉṛu iravu chāppiḍa engaḷai aḻaittārkaḷ."},{"fr":"Même si on est fatigués, on viendra avec plaisir.","tgt":"களைப்பாக இருந்தாலும் சந்தோஷமாக வருவோம்.","ro":"Kaḷaippāka irundālum chandōshamāka varuvōm."},{"fr":"Ils sont en vacances depuis une semaine.","tgt":"அவர்கள் ஒரு வாரமாக விடுமுறையில் இருக்கிறார்கள்.","ro":"Avarkaḷ oru vāramāka viḍumuṛaiyil irukkiṛārkaḷ."},{"fr":"Même si c'est loin, venez nous voir à Pondichéry.","tgt":"தூரமாக இருந்தாலும் பாண்டிச்சேரிக்கு வந்து எங்களைப் பாருங்கள்.","ro":"Tūramāka irundālum Pāṇḍichchērikku vandu engaḷaip pārungaḷ."},{"fr":"Nous avons échangé nos numéros de téléphone.","tgt":"நாங்கள் தொலைபேசி எண்களைப் பரிமாறிக்கொண்டோம்.","ro":"Nāngaḷ tolaipēchi eṇkaḷaip parimāṛikkoṇḍōm."},{"fr":"Grâce à eux, ce voyage est devenu encore plus beau.","tgt":"அவர்களால் இந்தப் பயணம் இன்னும் அழகாக ஆனது.","ro":"Avarkaḷāl indap payaṇam iṉṉum aḻakāka āṉadu."}],"tip":{"title":"« -ālum » : même si, bien que","example":"Même s'il pleut, ils vont faire la randonnée. — மழை <b>பெய்தாலும்</b> அவர்கள் மலையேற்றத்துக்குப் போவார்கள்.","body":"Vous connaissez déjà « -āl », si. Il suffit d'y ajouter « -um », qui veut dire aussi, pour obtenir « -ālum », même si. « Peydāl », s'il pleut, devient donc « peydālum », même s'il pleut. Notre exemple se décompose ainsi : la pluie, même si elle tombe, eux, à la randonnée, ils iront. Le même mot sert pour « bien que » : « irundālum » veut dire « même si c'est » ou « bien que ce soit », comme dans « tūramāka irundālum », même si c'est loin, ou « kaḷaippāka irundālum », même si on est fatigués. Astuce : « si » plus « aussi » donne « même si », exactement comme en français.","exampleRo":"Maḻai peydālum avarkaḷ malaiyēṛṛattukkup pōvārkaḷ.","lit":"pluie · même si (elle) tombe · ils · randonnée [à] · iront","say":{"Peydāl":"பெய்தால்","peydālum":"பெய்தாலும்","irundālum":"இருந்தாலும்","tūramāka irundālum":"தூரமாக இருந்தாலும்","kaḷaippāka irundālum":"களைப்பாக இருந்தாலும்"}}},{"title":"Une cascade dans la forêt","phrases":[{"fr":"Il faut vingt minutes à pied pour aller à la cascade.","tgt":"அருவிக்கு நடந்து போக இருபது நிமிடம் ஆகும்.","ro":"Aruvikku naḍandu pōka irupadu nimiḍam ākum."},{"fr":"Le chemin descend au milieu des pins.","tgt":"பாதை பைன் மரங்களின் நடுவே கீழே இறங்குகிறது.","ro":"Pādai paiṉ marangaḷiṉ naḍuvē kīḻē iṛangukiṛadu."},{"fr":"On entend l'eau avant de la voir.","tgt":"பார்ப்பதற்கு முன்பே தண்ணீரின் சத்தம் கேட்கிறது.","ro":"Pārppadaṛku muṉpē taṇṇīriṉ chattam kēṭkiṛadu."},{"fr":"Après la pluie, il y a beaucoup plus d'eau.","tgt":"மழைக்குப் பிறகு அருவியில் தண்ணீர் அதிகமாக விழுகிறது.","ro":"Maḻaikkup piṛaku aruviyil taṇṇīr adikamāka viḻukiṛadu."},{"fr":"Attention, les rochers sont glissants.","tgt":"கவனம், பாறைகள் வழுக்கும்.","ro":"Kavaṉam, pāṛaikaḷ vaḻukkum."},{"fr":"Ne vous baignez pas ici, c'est dangereux.","tgt":"இங்கே குளிக்காதீர்கள், ஆபத்து.","ro":"Ingē kuḷikkādīrkaḷ, āpattu."},{"fr":"Des singes nous observent depuis les arbres.","tgt":"மரங்களிலிருந்து குரங்குகள் எங்களைப் பார்க்கின்றன.","ro":"Marangaḷilirundu kurangukaḷ engaḷaip pārkkiṉṛaṉa."},{"fr":"Surtout, ne leur donnez rien à manger.","tgt":"அவற்றுக்கு எதுவும் சாப்பிடக் கொடுக்காதீர்கள்.","ro":"Avaṛṛukku eduvum chāppiḍak koḍukkādīrkaḷ."},{"fr":"L'eau est glacée, même en été.","tgt":"கோடையிலும் தண்ணீர் ஐஸ் போலக் குளிர்கிறது.","ro":"Kōḍaiyilum taṇṇīr ais pōlak kuḷirkiṛadu."},{"fr":"Ça valait vraiment la peine de venir ici.","tgt":"இங்கே வந்தது உண்மையிலேயே மதிப்புள்ளது.","ro":"Ingē vandadu uṇmaiyilēyē madippuḷḷadu."}]},{"title":"Préparer le retour","phrases":[{"fr":"Demain, nous redescendons vers la plaine.","tgt":"நாளை நாங்கள் சமவெளிக்குத் திரும்பி இறங்குகிறோம்.","ro":"Nāḷai nāngaḷ chamaveḷikkut tirumbi iṛangukiṛōm."},{"fr":"Avez-vous réservé le bus pour Madurai ?","tgt":"மதுரைக்குப் பேருந்து முன்பதிவு செய்தீர்களா?","ro":"Maduraikkup pērundu muṉpadivu cheydīrkaḷā?"},{"fr":"Oui, il part à sept heures du matin.","tgt":"ஆமாம், காலை ஏழு மணிக்குக் கிளம்பும்.","ro":"Āmām, kālai ēḻu maṇikkuk kiḷambum."},{"fr":"Il faut rendre la clé avant de partir.","tgt":"கிளம்புவதற்கு முன் சாவியைத் திருப்பிக் கொடுக்க வேண்டும்.","ro":"Kiḷambuvadaṛku muṉ chāviyait tiruppik koḍukka vēṇḍum."},{"fr":"J'ai mis les gâteaux en haut du sac.","tgt":"கேக்குகளைப் பையின் மேலே வைத்தேன்.","ro":"Kēkkukaḷaip paiyiṉ mēlē vaittēṉ."},{"fr":"N'oubliez pas le chargeur dans la chambre.","tgt":"அறையில் இருக்கும் சார்ஜரை மறக்காதீர்கள்.","ro":"Aṛaiyil irukkum chārjarai maṛakkādīrkaḷ."},{"fr":"Nous avons réglé la note de l'hôtel.","tgt":"ஹோட்டல் கட்டணத்தைச் செலுத்திவிட்டோம்.","ro":"Hōṭṭal kaṭṭaṇattaich cheluttiviṭṭōm."},{"fr":"Le gérant est venu nous dire au revoir à la porte.","tgt":"மேலாளர் வாசலுக்கு வந்து எங்களை வழியனுப்பினார்.","ro":"Mēlāḷar vāchalukku vandu engaḷai vaḻiyaṉuppiṉār."},{"fr":"Je suis un peu triste de partir.","tgt":"கிளம்புவதில் எனக்குச் சற்று வருத்தம்தான்.","ro":"Kiḷambuvadil eṉakkuch chaṛṛu varuttamtāṉ."},{"fr":"On reviendra un jour, c'est sûr.","tgt":"நாங்கள் ஒருநாள் கண்டிப்பாகத் திரும்பி வருவோம்.","ro":"Nāngaḷ orunāḷ kaṇḍippākat tirumbi varuvōm."}]},{"title":"Les derniers achats","phrases":[{"fr":"Il nous reste une heure avant le bus.","tgt":"பேருந்துக்கு இன்னும் ஒரு மணி நேரம் இருக்கிறது.","ro":"Pērundukku iṉṉum oru maṇi nēram irukkiṛadu."},{"fr":"Je voudrais du thé des Nilgiris pour offrir.","tgt":"பரிசாகக் கொடுக்க எனக்கு நீலகிரி டீ வேண்டும்.","ro":"Parichākak koḍukka eṉakku Nīlakiri ṭī vēṇḍum."},{"fr":"Combien coûte ce paquet de cinq cents grammes ?","tgt":"இந்த ஐநூறு கிராம் பாக்கெட் என்ன விலை?","ro":"Inda ainūṛu kirām pākkeṭ eṉṉa vilai?"},{"fr":"Prenez aussi ce chocolat à la cardamome.","tgt":"இந்த ஏலக்காய் சாக்லேட்டையும் வாங்குங்கள்.","ro":"Inda ēlakkāy chākleṭṭaiyum vāngungaḷ."},{"fr":"Pouvez-vous me faire un paquet cadeau ?","tgt":"இதைப் பரிசுக்காகச் சுற்றித் தர முடியுமா?","ro":"Idaip parichukkākach chuṛṛit tara muḍiyumā?"},{"fr":"Ma mère adore les châles en laine.","tgt":"என் அம்மாவுக்குக் கம்பளி சால்வைகள் ரொம்பப் பிடிக்கும்.","ro":"Eṉ ammāvukkuk kambaḷi chālvaikaḷ rombap piḍikkum."},{"fr":"Celui-ci a été fait à la main par une femme du village.","tgt":"இதைக் கிராமத்துப் பெண் ஒருவர் கையால் செய்தார்.","ro":"Idaik kirāmattup peṇ oruvar kaiyāl cheydār."},{"fr":"Est-ce que je peux payer avec le téléphone ?","tgt":"போனில் பணம் செலுத்தலாமா?","ro":"Pōṉil paṇam cheluttalāmā?"},{"fr":"Maintenant, mon sac est vraiment lourd.","tgt":"இப்போது என் பை ரொம்பக் கனமாக இருக்கிறது.","ro":"Ippōdu eṉ pai rombak kaṉamāka irukkiṛadu."},{"fr":"Voilà, nous sommes prêts à partir.","tgt":"சரி, நாங்கள் கிளம்பத் தயார்.","ro":"Chari, nāngaḷ kiḷambat tayār."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Notre voyage dans les montagnes s'achève ici.","tgt":"மலைகளில் எங்கள் பயணம் இங்கே முடிகிறது.","ro":"Malaikaḷil engaḷ payaṇam ingē muḍikiṛadu."},{"fr":"Nous avons appris à parler du voyage en tamoul.","tgt":"பயணத்தைப் பற்றித் தமிழில் பேசக் கற்றுக்கொண்டோம்.","ro":"Payaṇattaip paṛṛit tamiḻil pēchak kaṛṛukkoṇḍōm."},{"fr":"Nous savons maintenant exprimer une condition.","tgt":"இப்போது நிபந்தனை வாக்கியங்கள் சொல்லத் தெரியும்.","ro":"Ippōdu nipandaṉai vākkiyangaḷ chollat teriyum."},{"fr":"Enchaîner deux actions est devenu plus facile.","tgt":"இரண்டு செயல்களை இணைத்துச் சொல்வது இப்போது எளிதாக இருக்கிறது.","ro":"Iraṇḍu cheyalkaḷai iṇaittuch cholvadu ippōdu eḷidāka irukkiṛadu."},{"fr":"Nous ne pourrons jamais oublier ces paysages.","tgt":"இந்த இயற்கைக் காட்சிகளை எங்களால் மறக்க முடியாது.","ro":"Inda iyaṛkaik kāṭchikaḷai engaḷāl maṛakka muḍiyādu."},{"fr":"Même les imprévus nous ont appris quelque chose.","tgt":"எதிர்பாராத சிக்கல்கள் கூட எங்களுக்கு ஏதோ கற்றுக்கொடுத்தன.","ro":"Edirpārāda chikkalkaḷ kūḍa engaḷukku ēdō kaṛṛukkoḍuttaṉa."},{"fr":"Parler aux gens devient de plus en plus naturel.","tgt":"மக்களிடம் பேசுவது மேலும் மேலும் இயல்பாகிறது.","ro":"Makkaḷiḍam pēchuvadu mēlum mēlum iyalpākiṛadu."},{"fr":"Le prochain module portera sur la vie sociale.","tgt":"அடுத்த பாடம் சமூக வாழ்க்கையைப் பற்றியது.","ro":"Aḍutta pāḍam chamūka vāḻkkaiyaip paṛṛiyadu."},{"fr":"Bravo pour tout le chemin parcouru en montagne.","tgt":"மலைகளில் இதுவரை வந்த தூரத்துக்கு வாழ்த்துகள்.","ro":"Malaikaḷil iduvarai vanda tūrattukku vāḻttukaḷ."},{"fr":"Rendez-vous très vite pour la suite.","tgt":"விரைவில் அடுத்த பாடத்தில் சந்திப்போம்.","ro":"Viraivil aḍutta pāḍattil chandippōm."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles à Trichy","phrases":[{"fr":"Ravi ! Ça fait combien de temps !","tgt":"ரவி! எவ்வளவு நாளாச்சு!","ro":"Ravi! Evvaḷavu nāḷāchchu!"},{"fr":"Je suis tellement content de te revoir.","tgt":"உன்னை மறுபடியும் பார்த்ததில் ரொம்ப சந்தோஷம்.","ro":"Uṉṉai marupaṭiyum pārttadil romba chandōsham."},{"fr":"Tu n'as pas changé d'un poil.","tgt":"நீ அப்படியே இருக்கிறாய்.","ro":"Nī appaṭiyē irukkirāy."},{"fr":"Tu habites toujours à Trichy ?","tgt":"நீ இன்னும் திருச்சியில்தான் இருக்கிறாயா?","ro":"Nī iṉṉum Tiruchchiyiltāṉ irukkirāyā?"},{"fr":"Non, maintenant je vis à Chennai pour le travail.","tgt":"இல்லை, இப்போது வேலைக்காகச் சென்னையில் இருக்கிறேன்.","ro":"Illai, ippōdu vēlaikkākach Cheṉṉaiyil irukkirēṉ."},{"fr":"Je suis venu quelques jours pour voir ma famille.","tgt":"குடும்பத்தைப் பார்க்கச் சில நாட்களுக்கு வந்திருக்கிறேன்.","ro":"Kuṭumbattaip pārkkach chila nāṭkaḷukku vandirukkirēṉ."},{"fr":"Viens, allons boire un café.","tgt":"வா, ஒரு காபி குடிக்கப் போவோம்.","ro":"Vā, oru kāpi kuṭikkap pōvōm."},{"fr":"Bonne idée, je connais un bon endroit près d'ici.","tgt":"நல்ல யோசனை, இங்கே பக்கத்தில் எனக்கு ஒரு நல்ல இடம் தெரியும்.","ro":"Nalla yōchaṉai, ingē pakkattil eṉakku oru nalla iṭam teriyum."},{"fr":"Raconte-moi tout, comment vas-tu ?","tgt":"எல்லாம் சொல்லு, எப்படி இருக்கிறாய்?","ro":"Ellām chollu, eppaṭi irukkirāy?"},{"fr":"Je vais bien, mais la vie file à toute allure.","tgt":"நான் நன்றாக இருக்கிறேன், ஆனால் வாழ்க்கை வேகமாக ஓடுகிறது.","ro":"Nāṉ naṉrāka irukkirēṉ, āṉāl vāḻkkai vēkamāka ōṭukiradu."}]},{"title":"Entre amis : on se tutoie","phrases":[{"fr":"Viens, assieds-toi ici.","tgt":"வா, இங்கே உட்கார்.","ro":"Vā, ingē uṭkār."},{"fr":"Va appeler Kumar, il est dehors.","tgt":"போய்க் குமாரைக் கூப்பிடு, அவன் வெளியே இருக்கிறான்.","ro":"Pōyk Kumāraik kūppiṭu, avaṉ veḷiyē irukkirāṉ."},{"fr":"Dis-moi la vérité, tu es fatigué ?","tgt":"உண்மையைச் சொல்லு, நீ களைப்பாக இருக்கிறாயா?","ro":"Uṇmaiyaich chollu, nī kaḷaippāka irukkirāyā?"},{"fr":"Vas-y, je te rejoins dans dix minutes.","tgt":"நீ போ, நான் பத்து நிமிடத்தில் வருகிறேன்.","ro":"Nī pō, nāṉ pattu nimiṭattil varukirēṉ."},{"fr":"Attends-moi devant la gare.","tgt":"ரயில் நிலையத்துக்கு முன்னால் எனக்காகக் காத்திரு.","ro":"Rayil nilaiyattukku muṉṉāl eṉakkākak kāttiru."},{"fr":"Viens vite, le film commence !","tgt":"சீக்கிரம் வா, படம் ஆரம்பிக்கிறது!","ro":"Chīkkiram vā, paṭam ārambikkiradu!"},{"fr":"Ne t'inquiète pas, je m'en occupe.","tgt":"கவலைப்படாதே, நான் பார்த்துக்கொள்கிறேன்.","ro":"Kavalaippaṭādē, nāṉ pārttukkoḷkirēṉ."},{"fr":"Ne rigole pas, écoute ce que je dis !","tgt":"சிரிக்காதே, நான் சொல்வதைக் கேள்!","ro":"Chirikkādē, nāṉ cholvadaik kēḷ!"},{"fr":"Ressers-toi, ne sois pas timide.","tgt":"இன்னும் சாப்பிடு, வெட்கப்படாதே.","ro":"Iṉṉum chāppiṭu, veṭkappaṭādē."},{"fr":"Allez, va dormir, il est tard.","tgt":"சரி, போய்த் தூங்கு, நேரமாகிவிட்டது.","ro":"Chari, pōyt tūngu, nēramākiviṭṭadu."}],"tip":{"title":"Le registre familier : « vā », « pō », parler entre amis","example":"Viens, assieds-toi ici. — <b>வா</b>, இங்கே <b>உட்கார்</b>.","body":"Entre amis, on se tutoie avec « nī », et l'impératif devient tout simple : on prend le verbe nu, sans rien ajouter. « Vā » veut dire viens, « pō » va, « chollu » dis, « uṭkār » assieds-toi. Dans « Vā, ingē uṭkār », on a mot à mot viens, ici, assieds-toi, exactement comme en français familier. Pour dire à un ami de ne pas faire quelque chose, on ajoute « -ādē » : « chirikkādē », ne rigole pas, « kavalaippaṭādē », ne t'inquiète pas. Ces formes courtes sont réservées aux amis, aux plus jeunes et à la famille proche : avec un inconnu ou une personne âgée, elles sonneraient brusques. Retenez-le ainsi : plus le mot est court, plus on est proche.","exampleRo":"Vā, ingē uṭkār.","lit":"viens · ici · assieds-toi","say":{"vā":"வா","pō":"போ","nī":"நீ","Vā":"வா","chollu":"சொல்லு","uṭkār":"உட்கார்","Vā, ingē uṭkār":"வா, இங்கே உட்கார்","chirikkādē":"சிரிக்காதே","kavalaippaṭādē":"கவலைப்படாதே"}}},{"title":"Les nouvelles de la famille","phrases":[{"fr":"Comment vont tes parents ?","tgt":"உன் அப்பா அம்மா எப்படி இருக்கிறார்கள்?","ro":"Uṉ appā ammā eppaṭi irukkirārkaḷ?"},{"fr":"Ils vont bien, mon père est à la retraite depuis l'an dernier.","tgt":"நன்றாக இருக்கிறார்கள், அப்பா போன வருடத்திலிருந்து ஓய்வில் இருக்கிறார்.","ro":"Naṉrāka irukkirārkaḷ, appā pōṉa varuṭattilirundu ōyvil irukkirār."},{"fr":"Ma petite sœur s'est mariée le mois dernier.","tgt":"என் தங்கைக்குப் போன மாதம் கல்யாணம் ஆனது.","ro":"Eṉ tangaikkup pōṉa mādam kalyāṇam āṉadu."},{"fr":"Et ton grand frère, il travaille où maintenant ?","tgt":"உன் அண்ணன் இப்போது எங்கே வேலை செய்கிறான்?","ro":"Uṉ aṇṇaṉ ippōdu engē vēlai cheykirāṉ?"},{"fr":"Il travaille dans une banque à Madurai.","tgt":"அவன் மதுரையில் ஒரு வங்கியில் வேலை செய்கிறான்.","ro":"Avaṉ Maduraiyil oru vangiyil vēlai cheykirāṉ."},{"fr":"Il a eu un petit garçon il y a deux mois.","tgt":"அவனுக்கு இரண்டு மாதத்துக்கு முன்பு ஒரு ஆண் குழந்தை பிறந்தது.","ro":"Avaṉukku iraṇḍu mādattukku muṉpu oru āṇ kuḻandai pirandadu."},{"fr":"Félicitations, te voilà oncle !","tgt":"வாழ்த்துக்கள், அப்போ நீ சித்தப்பா ஆகிவிட்டாய்!","ro":"Vāḻttukkaḷ, appō nī chittappā ākiviṭṭāy!"},{"fr":"Ta grand-mère vit toujours avec vous ?","tgt":"உன் பாட்டி இன்னும் உங்களோடு இருக்கிறாரா?","ro":"Uṉ pāṭṭi iṉṉum ungaḷōṭu irukkirārā?"},{"fr":"Oui, elle a quatre-vingts ans, mais elle va très bien.","tgt":"ஆமாம், அவருக்கு எண்பது வயது, ஆனால் நன்றாக இருக்கிறார்.","ro":"Āmām, avarukku eṇpadu vayadu, āṉāl naṉrāka irukkirār."},{"fr":"Passe le bonjour à toute ta famille.","tgt":"உன் குடும்பத்தில் எல்லோருக்கும் என் வணக்கத்தைச் சொல்.","ro":"Uṉ kuṭumbattil ellōrukkum eṉ vaṇakkattaich chol."}]},{"title":"Une invitation au mariage","phrases":[{"fr":"Kumar se marie le mois prochain !","tgt":"குமாருக்கு அடுத்த மாதம் கல்யாணம்!","ro":"Kumārukku aṭutta mādam kalyāṇam!"},{"fr":"Sérieux ? Et avec qui ?","tgt":"நிஜமாகவா? யாரோடு?","ro":"Nijamākavā? Yārōṭu?"},{"fr":"Avec Meena, qui était à la fac avec nous.","tgt":"மீனாவோடு, நம்மோடு கல்லூரியில் படித்தவள்.","ro":"Mīṉāvōṭu, nammōṭu kallūriyil paṭittavaḷ."},{"fr":"Il m'a apporté le faire-part hier soir.","tgt":"நேற்று இரவு அவன் எனக்கு அழைப்பிதழ் கொண்டு வந்தான்.","ro":"Nētru iravu avaṉ eṉakku aḻaippidaḻ koṇḍu vandāṉ."},{"fr":"Le mariage aura lieu dans une grande salle de Trichy.","tgt":"கல்யாணம் திருச்சியில் ஒரு பெரிய மண்டபத்தில் நடக்கும்.","ro":"Kalyāṇam Tiruchchiyil oru periya maṇḍapattil naṭakkum."},{"fr":"Tu viendras avec moi ?","tgt":"நீ என்னோடு வருவாயா?","ro":"Nī eṉṉōṭu varuvāyā?"},{"fr":"Bien sûr, je ne le raterais pour rien au monde.","tgt":"கண்டிப்பாக, எதற்காகவும் அதைத் தவறவிட மாட்டேன்.","ro":"Kaṇḍippāka, edarkākavum adait tavaraviṭa māṭṭēṉ."},{"fr":"Il faut lui acheter un cadeau.","tgt":"அவனுக்கு ஒரு பரிசு வாங்க வேண்டும்.","ro":"Avaṉukku oru parichu vānga vēṇḍum."},{"fr":"On n'a qu'à l'acheter tous ensemble, entre amis.","tgt":"நண்பர்கள் எல்லோரும் சேர்ந்து வாங்கலாம்.","ro":"Naṇparkaḷ ellōrum chērndu vāngalām."},{"fr":"Je demande aux autres ce soir.","tgt":"இன்று இரவு மற்றவர்களிடம் கேட்கிறேன்.","ro":"Iṉru iravu matravarkaḷiṭam kēṭkirēṉ."}]},{"title":"Préparer la fête de mariage","phrases":[{"fr":"On peut aller acheter des vêtements ensemble samedi.","tgt":"சனிக்கிழமை சேர்ந்து துணி வாங்கப் போகலாம்.","ro":"Chaṉikkiḻamai chērndu tuṇi vāngap pōkalām."},{"fr":"Pour le mariage, tu peux porter un veshti blanc.","tgt":"கல்யாணத்துக்கு நீ வெள்ளை வேட்டி கட்டலாம்.","ro":"Kalyāṇattukku nī veḷḷai vēṭṭi kaṭṭalām."},{"fr":"On y va en bus ou en rickshaw ?","tgt":"பேருந்தில் போகலாமா, ஆட்டோவில் போகலாமா?","ro":"Pērundil pōkalāmā, āṭṭōvil pōkalāmā?"},{"fr":"Il va peut-être pleuvoir ce jour-là.","tgt":"அன்று மழை பெய்யலாம்.","ro":"Aṉru maḻai peyyalām."},{"fr":"On peut y aller tôt pour donner un coup de main.","tgt":"உதவி செய்யச் சீக்கிரமாகப் போகலாம்.","ro":"Udavi cheyyach chīkkiramākap pōkalām."},{"fr":"Est-ce que je peux amener mon cousin ?","tgt":"என் மாமா பையனை அழைத்து வரலாமா?","ro":"Eṉ māmā paiyaṉai aḻaittu varalāmā?"},{"fr":"Bien sûr, tu peux l'amener sans problème.","tgt":"தாராளமாக அழைத்து வரலாம்.","ro":"Tārāḷamāka aḻaittu varalām."},{"fr":"Kumar est peut-être très stressé en ce moment.","tgt":"குமார் இப்போது ரொம்ப பதற்றமாக இருக்கலாம்.","ro":"Kumār ippōdu romba padatramāka irukkalām."},{"fr":"On pourrait l'appeler ce soir pour l'encourager.","tgt":"இன்று இரவு அவனுக்குப் போன் செய்து தைரியம் சொல்லலாம்.","ro":"Iṉru iravu avaṉukkup pōṉ cheydu tairiyam chollalām."},{"fr":"Bonne idée, on peut l'appeler après le dîner.","tgt":"நல்ல யோசனை, ராத்திரி சாப்பாட்டுக்குப் பிறகு கூப்பிடலாம்.","ro":"Nalla yōchaṉai, rāttiri chāppāṭṭukkup piraku kūppiṭalām."}],"tip":{"title":"« -alām » : on peut, peut-être","example":"On peut aller acheter des vêtements ensemble samedi. — சனிக்கிழமை சேர்ந்து துணி வாங்கப் <b>போகலாம்</b>.","body":"La terminaison « -alām » est un vrai couteau suisse : collée au verbe, elle veut dire on peut, ou bien peut-être. « Pō », aller, devient « pōkalām », on peut y aller ; « vā », venir, devient « varalām », on peut venir. Elle ne change jamais selon la personne : je, tu, nous ou eux, c'est toujours « -alām », ce qui la rend très facile à placer. Dans « Aṉru maḻai peyyalām », mot à mot ce jour-là, pluie, peut tomber, elle exprime une simple possibilité : il va peut-être pleuvoir. Ajoutez « -ā » à la fin et vous obtenez une proposition amicale : « pōkalāmā ? », on y va ? Astuce : chaque fois que vous entendez « -alāmā », pensez « et si on... ? ».","exampleRo":"Chaṉikkiḻamai chērndu tuṇi vāngap pōkalām.","lit":"samedi · ensemble · vêtements · pour acheter · on peut aller","say":{"Pō":"போ","pōkalām":"போகலாம்","vā":"வா","varalām":"வரலாம்","Aṉru maḻai peyyalām":"அன்று மழை பெய்யலாம்","pōkalāmā ?":"போகலாமா?"}}},{"title":"Le jour du mariage","phrases":[{"fr":"Quelle belle salle, il y a des fleurs partout !","tgt":"என்ன அழகான மண்டபம், எல்லா இடத்திலும் பூக்கள்!","ro":"Eṉṉa aḻakāṉa maṇḍapam, ellā iṭattilum pūkkaḷ!"},{"fr":"La musique est déjà très forte.","tgt":"இசை ஏற்கனவே ரொம்ப சத்தமாக இருக்கிறது.","ro":"Ichai ērkaṉavē romba chattamāka irukkiradu."},{"fr":"Les mariés sont magnifiques.","tgt":"மணமக்கள் ரொம்ப அழகாக இருக்கிறார்கள்.","ro":"Maṇamakkaḷ romba aḻakāka irukkirārkaḷ."},{"fr":"Meena porte un sari de soie rouge.","tgt":"மீனா சிவப்புப் பட்டுப் புடவை கட்டியிருக்கிறாள்.","ro":"Mīṉā chivappup paṭṭup puṭavai kaṭṭiyirukkirāḷ."},{"fr":"Viens, allons féliciter les mariés.","tgt":"வா, மணமக்களை வாழ்த்தப் போவோம்.","ro":"Vā, maṇamakkaḷai vāḻttap pōvōm."},{"fr":"Où est-ce qu'on pose le cadeau ?","tgt":"பரிசை எங்கே வைப்பது?","ro":"Parichai engē vaippadu?"},{"fr":"Après les photos, on ira manger.","tgt":"புகைப்படம் எடுத்த பிறகு சாப்பிடப் போவோம்.","ro":"Pukaippaṭam eṭutta piraku chāppiṭap pōvōm."},{"fr":"On sert le repas sur des feuilles de bananier.","tgt":"வாழை இலையில் சாப்பாடு போடுகிறார்கள்.","ro":"Vāḻai ilaiyil chāppāṭu pōṭukirārkaḷ."},{"fr":"Je n'ai jamais mangé un payasam aussi bon.","tgt":"இவ்வளவு சுவையான பாயசம் நான் சாப்பிட்டதே இல்லை.","ro":"Ivvaḷavu chuvaiyāṉa pāyacham nāṉ chāppiṭṭadē illai."},{"fr":"C'était vraiment un mariage réussi.","tgt":"ரொம்ப அருமையான கல்யாணமாக இருந்தது.","ro":"Romba arumaiyāṉa kalyāṇamāka irundadu."}]},{"title":"Un match à la télévision","phrases":[{"fr":"Il y a un match de cricket ce soir à la télé.","tgt":"இன்று இரவு டிவியில் கிரிக்கெட் மேட்ச் இருக்கிறது.","ro":"Iṉru iravu ṭiviyil kirikkeṭ mēṭch irukkiradu."},{"fr":"Tu viens le regarder chez moi ?","tgt":"என் வீட்டில் பார்க்க வருகிறாயா?","ro":"Eṉ vīṭṭil pārkka varukirāyā?"},{"fr":"Notre équipe joue contre une équipe très forte.","tgt":"நம் அணி ஒரு பலமான அணியோடு விளையாடுகிறது.","ro":"Nam aṇi oru palamāṉa aṇiyōṭu viḷaiyāṭukiradu."},{"fr":"Le match commence à sept heures et demie.","tgt":"மேட்ச் ஏழரை மணிக்கு ஆரம்பிக்கும்.","ro":"Mēṭch ēḻarai maṇikku ārambikkum."},{"fr":"J'apporte des samoussas et des boissons fraîches.","tgt":"நான் சமோசாவும் குளிர்பானமும் வாங்கி வருகிறேன்.","ro":"Nāṉ chamōchāvum kuḷirpāṉamum vāngi varukirēṉ."},{"fr":"Ravi adore le cricket plus que tout.","tgt":"ரவிக்குக் கிரிக்கெட் என்றால் உயிர்.","ro":"Ravikkuk kirikkeṭ eṉrāl uyir."},{"fr":"Il connaît par cœur les scores de tous les matchs.","tgt":"எல்லா மேட்ச்களின் ஸ்கோரும் அவனுக்கு மனப்பாடம்.","ro":"Ellā mēṭchkaḷiṉ skōrum avaṉukku maṉappāṭam."},{"fr":"Moi, je ne comprends pas toutes les règles.","tgt":"எனக்கு எல்லா விதிகளும் புரியாது.","ro":"Eṉakku ellā vidikaḷum puriyādu."},{"fr":"Pas de souci, je t'expliquerai pendant le match.","tgt":"பரவாயில்லை, மேட்ச் நடக்கும்போது நான் உனக்கு விளக்குகிறேன்.","ro":"Paravāyillai, mēṭch naṭakkumbōdu nāṉ uṉakku viḷakkukirēṉ."},{"fr":"Viens avant sept heures, sinon tu rateras le début.","tgt":"ஏழு மணிக்கு முன்னால் வா, இல்லையென்றால் ஆரம்பத்தைத் தவறவிடுவாய்.","ro":"Ēḻu maṇikku muṉṉāl vā, illaiyeṉrāl ārambattait tavaraviṭuvāy."}]},{"title":"Commenter le match","phrases":[{"fr":"Quel coup magnifique !","tgt":"என்ன அருமையான அடி!","ro":"Eṉṉa arumaiyāṉa aṭi!"},{"fr":"Et c'est un six !","tgt":"இது சிக்ஸர்!","ro":"Idu chiksar!"},{"fr":"Le batteur joue vraiment bien aujourd'hui.","tgt":"இன்று பேட்ஸ்மேன் ரொம்ப நன்றாக ஆடுகிறார்.","ro":"Iṉru pēṭsmēṉ romba naṉrāka āṭukirār."},{"fr":"Oh non, il est éliminé !","tgt":"ஐயோ, அவர் அவுட் ஆகிவிட்டார்!","ro":"Aiyō, avar avuṭ ākiviṭṭār!"},{"fr":"L'arbitre s'est trompé, il n'était pas out.","tgt":"அம்பயர் தவறு செய்துவிட்டார், அது அவுட் இல்லை.","ro":"Ambayar tavaru cheyduviṭṭār, adu avuṭ illai."},{"fr":"Il reste encore dix overs.","tgt":"இன்னும் பத்து ஓவர் இருக்கிறது.","ro":"Iṉṉum pattu ōvar irukkiradu."},{"fr":"Il nous faut cinquante runs pour gagner.","tgt":"ஜெயிக்க ஐம்பது ரன் வேண்டும்.","ro":"Jeyikka aimbadu raṉ vēṇḍum."},{"fr":"Je crois qu'on va gagner.","tgt":"நாம் ஜெயிப்போம் என்று நினைக்கிறேன்.","ro":"Nām jeyippōm eṉru niṉaikkirēṉ."},{"fr":"Quel suspense, je n'en peux plus !","tgt":"என்ன பரபரப்பு, என்னால் தாங்க முடியவில்லை!","ro":"Eṉṉa paraparappu, eṉṉāl tānga muṭiyavillai!"},{"fr":"On a gagné ! Viens, on fête ça !","tgt":"ஜெயித்துவிட்டோம்! வா, கொண்டாடுவோம்!","ro":"Jeyittuviṭṭōm! Vā, koṇḍāṭuvōm!"}]},{"title":"La musique de film","phrases":[{"fr":"Tu as écouté la nouvelle chanson de ce film ?","tgt":"அந்தப் படத்தின் புதிய பாட்டைக் கேட்டாயா?","ro":"Andap paṭattiṉ pudiya pāṭṭaik kēṭṭāyā?"},{"fr":"Oui, je l'écoute en boucle depuis une semaine.","tgt":"ஆமாம், ஒரு வாரமாக அதையே திரும்பத் திரும்பக் கேட்கிறேன்.","ro":"Āmām, oru vāramāka adaiyē tirumbat tirumbak kēṭkirēṉ."},{"fr":"La mélodie est vraiment entraînante.","tgt":"மெட்டு ரொம்ப துள்ளலாக இருக்கிறது.","ro":"Meṭṭu romba tuḷḷalāka irukkiradu."},{"fr":"Les paroles aussi sont superbes.","tgt":"பாட்டு வரிகளும் ரொம்ப அழகு.","ro":"Pāṭṭu varikaḷum romba aḻaku."},{"fr":"Le chanteur a une voix extraordinaire.","tgt":"பாடகருக்கு அற்புதமான குரல்.","ro":"Pāṭakarukku arpudamāṉa kural."},{"fr":"Ma mère chante toujours les vieilles chansons de film.","tgt":"என் அம்மா எப்போதும் பழைய சினிமாப் பாட்டுகள் பாடுவார்.","ro":"Eṉ ammā eppōdum paḻaiya chiṉimāp pāṭṭukaḷ pāṭuvār."},{"fr":"Moi aussi, je préfère les chansons des années quatre-vingt.","tgt":"எனக்கும் எண்பதுகளின் பாட்டுகள்தான் பிடிக்கும்.","ro":"Eṉakkum eṇpadukaḷiṉ pāṭṭukaḷtāṉ piṭikkum."},{"fr":"On les entend partout, dans les bus comme aux mariages.","tgt":"பேருந்திலும் கல்யாணத்திலும் எல்லா இடத்திலும் அவற்றைக் கேட்கலாம்.","ro":"Pērundilum kalyāṇattilum ellā iṭattilum avatraik kēṭkalām."},{"fr":"Tu sais jouer d'un instrument ?","tgt":"உனக்கு ஏதாவது வாத்தியம் வாசிக்கத் தெரியுமா?","ro":"Uṉakku ēdāvadu vāttiyam vāchikkat teriyumā?"},{"fr":"Je joue de la flûte, mais plus depuis longtemps.","tgt":"புல்லாங்குழல் வாசிப்பேன், ஆனால் ரொம்ப நாளாக வாசிக்கவில்லை.","ro":"Pullānguḻal vāchippēṉ, āṉāl romba nāḷāka vāchikkavillai."}]},{"title":"Une soirée au cinéma","phrases":[{"fr":"On va voir un film ce week-end ?","tgt":"இந்த வார இறுதியில் படம் பார்க்கப் போவோமா?","ro":"Inda vāra irudiyil paṭam pārkkap pōvōmā?"},{"fr":"Il y a un nouveau film tamoul au cinéma près de la gare.","tgt":"ரயில் நிலையம் அருகே உள்ள தியேட்டரில் புதிய தமிழ்ப் படம் ஓடுகிறது.","ro":"Rayil nilaiyam arukē uḷḷa tiyēṭṭaril pudiya tamiḻp paṭam ōṭukiradu."},{"fr":"C'est une comédie ou un film d'action ?","tgt":"அது நகைச்சுவைப் படமா, சண்டைப் படமா?","ro":"Adu nakaichchuvaip paṭamā, chaṇḍaip paṭamā?"},{"fr":"Tout le monde dit que le film est très bon.","tgt":"படம் ரொம்ப நன்றாக இருக்கிறது என்று எல்லோரும் சொல்கிறார்கள்.","ro":"Paṭam romba naṉrāka irukkiradu eṉru ellōrum cholkirārkaḷ."},{"fr":"Je réserve les billets sur mon téléphone.","tgt":"என் போனில் டிக்கெட் புக் செய்கிறேன்.","ro":"Eṉ pōṉil ṭikkeṭ puk cheykirēṉ."},{"fr":"La séance de six heures, ça te va ?","tgt":"ஆறு மணிக் காட்சி உனக்குச் சரியா?","ro":"Āru maṇik kāṭchi uṉakkuch chariyā?"},{"fr":"Parfait, on se retrouve devant l'entrée.","tgt":"சரி, நுழைவாயிலுக்கு முன்னால் சந்திப்போம்.","ro":"Chari, nuḻaivāyilukku muṉṉāl chandippōm."},{"fr":"Le film était trop long, mais les chansons étaient géniales.","tgt":"படம் ரொம்ப நீளமாக இருந்தது, ஆனால் பாட்டுகள் அருமை.","ro":"Paṭam romba nīḷamāka irundadu, āṉāl pāṭṭukaḷ arumai."},{"fr":"Le héros dansait vraiment bien.","tgt":"ஹீரோ ரொம்ப நன்றாக ஆடினார்.","ro":"Hīrō romba naṉrāka āṭiṉār."},{"fr":"La prochaine fois, c'est toi qui choisis le film.","tgt":"அடுத்த தடவை நீதான் படத்தைத் தேர்ந்தெடுக்க வேண்டும்.","ro":"Aṭutta taṭavai nīdāṉ paṭattait tērndeṭukka vēṇḍum."}]},{"title":"Souvenirs de fac","phrases":[{"fr":"Tu te souviens de notre première année à la fac ?","tgt":"கல்லூரியில் நம் முதல் வருடம் உனக்கு நினைவிருக்கிறதா?","ro":"Kallūriyil nam mudal varuṭam uṉakku niṉaivirukkiradā?"},{"fr":"On s'asseyait toujours au dernier rang.","tgt":"நாம் எப்போதும் கடைசி வரிசையில் உட்காருவோம்.","ro":"Nām eppōdum kaṭaichi varichaiyil uṭkāruvōm."},{"fr":"Le prof de chimie nous faisait peur.","tgt":"வேதியியல் ஆசிரியரைப் பார்த்தாலே நமக்குப் பயமாக இருக்கும்.","ro":"Vēdiyiyal āchiriyaraip pārttālē namakkup payamāka irukkum."},{"fr":"Toi, tu révisais toute la nuit avant les examens.","tgt":"பரீட்சைக்கு முன்னால் நீ ராத்திரி முழுவதும் படிப்பாய்.","ro":"Parīṭchaikku muṉṉāl nī rāttiri muḻuvadum paṭippāy."},{"fr":"Et moi, je dormais pendant les cours !","tgt":"நானோ வகுப்பில் தூங்குவேன்!","ro":"Nāṉō vakuppil tūnguvēṉ!"},{"fr":"Tous les jours, on déjeunait à la cantine.","tgt":"தினமும் கேன்டீனில் சாப்பிடுவோம்.","ro":"Tiṉamum kēṉṭīṉil chāppiṭuvōm."},{"fr":"Là-bas, le thé ne coûtait que cinq roupies.","tgt":"அங்கே டீ ஐந்து ரூபாய்தான்.","ro":"Angē ṭī aindu rūpāydāṉ."},{"fr":"C'était la plus belle période de notre vie.","tgt":"அதுதான் நம் வாழ்க்கையின் மிக அழகான காலம்.","ro":"Adudāṉ nam vāḻkkaiyiṉ mika aḻakāṉa kālam."},{"fr":"Il m'arrive de repenser à nos professeurs.","tgt":"சில நேரம் நம் ஆசிரியர்களின் நினைவு வருகிறது.","ro":"Chila nēram nam āchiriyarkaḷiṉ niṉaivu varukiradu."},{"fr":"On devrait retourner voir la fac un jour.","tgt":"ஒரு நாள் கல்லூரிக்குத் திரும்பப் போய்ப் பார்க்க வேண்டும்.","ro":"Oru nāḷ kallūrikkut tirumbap pōyp pārkka vēṇḍum."}]},{"title":"Que deviennent les anciens ?","phrases":[{"fr":"Il paraît qu'Anand vit à Pondichéry maintenant.","tgt":"ஆனந்த் இப்போது பாண்டிச்சேரியில் இருக்கிறானாம்.","ro":"Āṉand ippōdu Pāṇḍichchēriyil irukkirāṉām."},{"fr":"Il paraît qu'il a ouvert un restaurant.","tgt":"அவன் ஒரு உணவகம் திறந்திருக்கிறானாம்.","ro":"Avaṉ oru uṇavakam tirandirukkirāṉām."},{"fr":"On dit que ses dosas sont les meilleures de la ville.","tgt":"ஊரிலேயே அவன் கடை தோசைதான் சிறந்ததாம்.","ro":"Ūrilēyē avaṉ kaṭai tōchaidāṉ chirandadām."},{"fr":"Il paraît que Kala est devenue médecin.","tgt":"கலா டாக்டர் ஆகிவிட்டாளாம்.","ro":"Kalā ṭākṭar ākiviṭṭāḷām."},{"fr":"Qui t'a raconté tout ça ?","tgt":"இதை உனக்கு யார் சொன்னது?","ro":"Idai uṉakku yār choṉṉadu?"},{"fr":"J'ai croisé sa grande sœur au marché, c'est elle qui me l'a dit.","tgt":"அவள் அக்காவைச் சந்தையில் பார்த்தேன், அவர்தான் சொன்னார்.","ro":"Avaḷ akkāvaich chandaiyil pārttēṉ, avartāṉ choṉṉār."},{"fr":"Il paraît que notre vieux professeur prend sa retraite cette année.","tgt":"நம் பழைய ஆசிரியர் இந்த வருடம் ஓய்வு பெறுகிறாராம்.","ro":"Nam paḻaiya āchiriyar inda varuṭam ōyvu perukirārām."},{"fr":"On dit qu'il y aura une fête des anciens élèves en décembre.","tgt":"டிசம்பரில் பழைய மாணவர்கள் சந்திப்பு நடக்குமாம்.","ro":"Ṭichambaril paḻaiya māṇavarkaḷ chandippu naṭakkumām."},{"fr":"Kumar viendra avec sa femme, à ce qu'il dit.","tgt":"குமார் தன் மனைவியோடு வருவானாம்.","ro":"Kumār taṉ maṉaiviyōṭu varuvāṉām."},{"fr":"Si c'est vrai, ce sera une soirée formidable !","tgt":"அது உண்மையானால், அருமையான மாலையாக இருக்கும்!","ro":"Adu uṇmaiyāṉāl, arumaiyāṉa mālaiyāka irukkum!"}],"tip":{"title":"« -ām » : il paraît que, on dit que","example":"Il paraît qu'Anand vit à Pondichéry maintenant. — ஆனந்த் இப்போது பாண்டிச்சேரியில் <b>இருக்கிறானாம்</b>.","body":"Pour rapporter une nouvelle qu'on a entendue sans l'avoir vérifiée, le tamoul n'a pas besoin de « il paraît que » : il suffit d'ajouter « -ām » tout à la fin du verbe. « Irukkirāṉ », il est, devient « irukkirāṉām », il paraît qu'il est. Dans « Āṉand ippōdu Pāṇḍichchēriyil irukkirāṉām », on a mot à mot Anand, maintenant, à Pondichéry, il vit, paraît-il. Ça marche avec tous les temps : « varuvāṉām », il viendra, paraît-il, ou « naṭakkumām », ça aura lieu, à ce qu'on dit. C'est le petit suffixe préféré des conversations entre amis, celui des nouvelles et des potins. Pour le retenir, imaginez un clin d'œil à la fin de la phrase : « -ām ».","exampleRo":"Āṉand ippōdu Pāṇḍichchēriyil irukkirāṉām.","lit":"Anand · maintenant · [dans] Pondichéry · il vit [il paraît]","say":{"Irukkirāṉ":"இருக்கிறான்","irukkirāṉām":"இருக்கிறானாம்","Āṉand ippōdu Pāṇḍichchēriyil irukkirāṉām":"ஆனந்த் இப்போது பாண்டிச்சேரியில் இருக்கிறானாம்","varuvāṉām":"வருவானாம்","naṭakkumām":"நடக்குமாம்"}}},{"title":"Le grand repas de fête","phrases":[{"fr":"Pour la fête, toute la famille se retrouve chez mes grands-parents.","tgt":"பண்டிகைக்குக் குடும்பம் முழுவதும் தாத்தா வீட்டில் கூடும்.","ro":"Paṇḍikaikkuk kuṭumbam muḻuvadum tāttā vīṭṭil kūṭum."},{"fr":"Ma tante cuisine depuis ce matin.","tgt":"என் அத்தை காலையிலிருந்து சமைக்கிறார்.","ro":"Eṉ attai kālaiyilirundu chamaikkirār."},{"fr":"Il y a au moins quinze plats sur la feuille de bananier.","tgt":"வாழை இலையில் குறைந்தது பதினைந்து வகை இருக்கும்.","ro":"Vāḻai ilaiyil kuraindadu padiṉaindu vakai irukkum."},{"fr":"Mon plat préféré, c'est le sambar de ma grand-mère.","tgt":"எனக்கு மிகவும் பிடித்தது பாட்டியின் சாம்பார்.","ro":"Eṉakku mikavum piṭittadu pāṭṭiyiṉ chāmbār."},{"fr":"En attendant, les enfants jouent dans la cour.","tgt":"அதுவரை குழந்தைகள் முற்றத்தில் விளையாடுகிறார்கள்.","ro":"Aduvarai kuḻandaikaḷ mutrattil viḷaiyāṭukirārkaḷ."},{"fr":"Assieds-toi par terre avec nous, fais comme chez toi.","tgt":"எங்களோடு கீழே உட்கார், இது உன் வீடு மாதிரி.","ro":"Engaḷōṭu kīḻē uṭkār, idu uṉ vīṭu mādiri."},{"fr":"Chez nous, on mange avec la main droite.","tgt":"நாங்கள் வலது கையால் சாப்பிடுவோம்.","ro":"Nāngaḷ valadu kaiyāl chāppiṭuvōm."},{"fr":"Je te ressers du riz ?","tgt":"இன்னும் சாதம் போடட்டுமா?","ro":"Iṉṉum chādam pōṭaṭṭumā?"},{"fr":"Non merci, je n'en peux plus, c'était délicieux.","tgt":"வேண்டாம், வயிறு நிறைந்துவிட்டது, ரொம்ப ருசியாக இருந்தது.","ro":"Vēṇḍām, vayiru nirainduviṭṭadu, romba ruchiyāka irundadu."},{"fr":"Après le repas, tout le monde fait une petite sieste.","tgt":"சாப்பாட்டுக்குப் பிறகு எல்லோரும் ஒரு குட்டித் தூக்கம் போடுவார்கள்.","ro":"Chāppāṭṭukkup piraku ellōrum oru kuṭṭit tūkkam pōṭuvārkaḷ."}]},{"title":"Un coup de fil","phrases":[{"fr":"Allô, qu'est-ce que tu es en train de faire ?","tgt":"ஹலோ, என்ன செய்துகொண்டிருக்கிறாய்?","ro":"Halō, eṉṉa cheydukoṇḍirukkirāy?"},{"fr":"Je suis en train d'aider ma mère à la cuisine.","tgt":"அம்மாவுக்குச் சமையலில் உதவி செய்துகொண்டிருக்கிறேன்.","ro":"Ammāvukkuch chamaiyalil udavi cheydukoṇḍirukkirēṉ."},{"fr":"Ma sœur est en train de se préparer pour sortir.","tgt":"என் தங்கை வெளியே போகத் தயாராகிக்கொண்டிருக்கிறாள்.","ro":"Eṉ tangai veḷiyē pōkat tayārākikkoṇḍirukkirāḷ."},{"fr":"En ce moment, il pleut fort à Trichy.","tgt":"இப்போது திருச்சியில் பலமாக மழை பெய்துகொண்டிருக்கிறது.","ro":"Ippōdu Tiruchchiyil palamāka maḻai peydukoṇḍirukkiradu."},{"fr":"Les enfants sont en train de dormir, parle doucement.","tgt":"குழந்தைகள் தூங்கிக்கொண்டிருக்கிறார்கள், மெதுவாகப் பேசு.","ro":"Kuḻandaikaḷ tūngikkoṇḍirukkirārkaḷ, meduvākap pēchu."},{"fr":"Je suis en route, j'arrive dans un quart d'heure.","tgt":"நான் வந்துகொண்டிருக்கிறேன், கால் மணி நேரத்தில் அங்கே இருப்பேன்.","ro":"Nāṉ vandukoṇḍirukkirēṉ, kāl maṇi nērattil angē iruppēṉ."},{"fr":"Et Ravi, qu'est-ce qu'il est en train de faire ?","tgt":"ரவி என்ன செய்துகொண்டிருக்கிறான்?","ro":"Ravi eṉṉa cheydukoṇḍirukkirāṉ?"},{"fr":"Il est en train de réparer sa moto.","tgt":"அவன் தன் பைக்கைச் சரி செய்துகொண்டிருக்கிறான்.","ro":"Avaṉ taṉ paikkaich chari cheydukoṇḍirukkirāṉ."},{"fr":"Je t'entends mal, la musique est trop forte.","tgt":"நீ பேசுவது சரியாகக் கேட்கவில்லை, பாட்டு ரொம்ப சத்தமாக இருக்கிறது.","ro":"Nī pēchuvadu chariyākak kēṭkavillai, pāṭṭu romba chattamāka irukkiradu."},{"fr":"Je te rappelle dans cinq minutes.","tgt":"ஐந்து நிமிடத்தில் திரும்பக் கூப்பிடுகிறேன்.","ro":"Aindu nimiṭattil tirumbak kūppiṭukirēṉ."}],"tip":{"title":"« -koṇḍu irukkirēṉ » : être en train de","example":"Je suis en train d'aider ma mère à la cuisine. — அம்மாவுக்குச் சமையலில் உதவி <b>செய்துகொண்டிருக்கிறேன்</b>.","body":"Pour dire qu'une action est en cours, juste maintenant, le tamoul empile deux verbes, un peu comme notre « être en train de ». On prend le verbe dans sa forme en « -u », comme « cheydu », en faisant, on ajoute « koṇḍu », littéralement en tenant, puis « irukkirēṉ », je suis. À l'oral, tout se soude en un seul long mot : « cheydukoṇḍirukkirēṉ », je suis en train de faire. Seule la fin change selon la personne : « tūngikkoṇḍirukkirārkaḷ », ils sont en train de dormir, « peydukoṇḍirukkiradu », il est en train de pleuvoir. Le présent simple « cheykirēṉ » suffit souvent, mais cette forme insiste sur l'instant présent, idéale au téléphone. Astuce : répétez « koṇḍirukk » comme un refrain, puis collez la terminaison de la personne.","exampleRo":"Ammāvukkuch chamaiyalil udavi cheydukoṇḍirukkirēṉ.","lit":"à maman · [dans] cuisine · aide · faisant je suis","say":{"cheydu":"செய்து","koṇḍu":"கொண்டு","irukkirēṉ":"இருக்கிறேன்","cheydukoṇḍirukkirēṉ":"செய்துகொண்டிருக்கிறேன்","tūngikkoṇḍirukkirārkaḷ":"தூங்கிக்கொண்டிருக்கிறார்கள்","peydukoṇḍirukkiradu":"பெய்துகொண்டிருக்கிறது","cheykirēṉ":"செய்கிறேன்"}}},{"title":"Au bord de la Kaveri","phrases":[{"fr":"Si on allait se promener au bord de la Kaveri ?","tgt":"காவேரிக் கரையில் நடக்கப் போகலாமா?","ro":"Kāvērik karaiyil naṭakkap pōkalāmā?"},{"fr":"Le soir, il fait plus frais près de l'eau.","tgt":"சாயங்காலம் தண்ணீர் பக்கத்தில் குளிர்ச்சியாக இருக்கும்.","ro":"Chāyangālam taṇṇīr pakkattil kuḷirchchiyāka irukkum."},{"fr":"Les jours de congé, beaucoup de familles viennent ici.","tgt":"விடுமுறை நாட்களில் நிறைய குடும்பங்கள் இங்கே வரும்.","ro":"Viṭumurai nāṭkaḷil niraiya kuṭumbangaḷ ingē varum."},{"fr":"Regarde, le soleil se couche sur le fleuve.","tgt":"பார், ஆற்றின் மேல் சூரியன் மறைகிறது.","ro":"Pār, ātriṉ mēl chūriyaṉ maraikiradu."},{"fr":"On s'achète des cacahuètes grillées ?","tgt":"வறுத்த வேர்க்கடலை வாங்கலாமா?","ro":"Varutta vērkkaṭalai vāngalāmā?"},{"fr":"Quand on était petits, on venait ici avec nos pères.","tgt":"சின்ன வயதில் அப்பாக்களோடு இங்கே வருவோம்.","ro":"Chiṉṉa vayadil appākkaḷōṭu ingē varuvōm."},{"fr":"Grâce à la mousson, le fleuve est plein cette année.","tgt":"பருவமழையால் இந்த வருடம் ஆறு நிறைந்து ஓடுகிறது.","ro":"Paruvamaḻaiyāl inda varuṭam āru niraindu ōṭukiradu."},{"fr":"On se croirait à la campagne, en pleine ville.","tgt":"நகரத்தின் நடுவில் கிராமத்தில் இருப்பது போல இருக்கிறது.","ro":"Nakarattiṉ naṭuvil kirāmattil iruppadu pōla irukkiradu."},{"fr":"Tu marches trop vite, attends !","tgt":"நீ ரொம்ப வேகமாக நடக்கிறாய், நில்லு!","ro":"Nī romba vēkamāka naṭakkirāy, nillu!"},{"fr":"Rentrons, il commence à faire nuit.","tgt":"இருட்ட ஆரம்பிக்கிறது, வீட்டுக்குப் போவோம்.","ro":"Iruṭṭa ārambikkiradu, vīṭṭukkup pōvōm."}]},{"title":"Travail et projets","phrases":[{"fr":"Alors, ton nouveau travail te plaît ?","tgt":"அப்புறம், உனக்குப் புதிய வேலை பிடித்திருக்கிறதா?","ro":"Appuram, uṉakkup pudiya vēlai piṭittirukkiradā?"},{"fr":"Oui, mais je travaille souvent tard le soir.","tgt":"ஆமாம், ஆனால் அடிக்கடி இரவு வெகு நேரம் வரை வேலை செய்கிறேன்.","ro":"Āmām, āṉāl aṭikkaṭi iravu veku nēram varai vēlai cheykirēṉ."},{"fr":"Mon chef est sévère, mais juste.","tgt":"என் மேலாளர் கண்டிப்பானவர், ஆனால் நியாயமானவர்.","ro":"Eṉ mēlāḷar kaṇḍippāṉavar, āṉāl niyāyamāṉavar."},{"fr":"Tu comptes rester longtemps à Chennai ?","tgt":"சென்னையில் ரொம்ப நாள் இருக்கப் போகிறாயா?","ro":"Cheṉṉaiyil romba nāḷ irukkap pōkirāyā?"},{"fr":"J'aimerais revenir vivre à Trichy un jour.","tgt":"ஒரு நாள் திருச்சிக்குத் திரும்பி வந்து வாழ எனக்கு ஆசை.","ro":"Oru nāḷ Tiruchchikkut tirumbi vandu vāḻa eṉakku āchai."},{"fr":"Ici, la vie est plus calme et moins chère.","tgt":"இங்கே வாழ்க்கை அமைதியாக இருக்கிறது, செலவும் குறைவு.","ro":"Ingē vāḻkkai amaidiyāka irukkiradu, chelavum kuraivu."},{"fr":"Je voudrais monter ma propre affaire.","tgt":"சொந்தமாக ஒரு தொழில் தொடங்க விரும்புகிறேன்.","ro":"Chondamāka oru toḻil toṭanga virumbukirēṉ."},{"fr":"C'est une bonne idée, je t'aiderai si tu veux.","tgt":"நல்ல எண்ணம், வேண்டுமென்றால் நான் உதவுகிறேன்.","ro":"Nalla eṇṇam, vēṇḍumeṉrāl nāṉ udavukirēṉ."},{"fr":"Il faudra d'abord mettre de l'argent de côté.","tgt":"முதலில் பணம் சேமிக்க வேண்டும்.","ro":"Mudalil paṇam chēmikka vēṇḍum."},{"fr":"Petit à petit, tu réussiras.","tgt":"மெல்ல மெல்ல நீ ஜெயிப்பாய்.","ro":"Mella mella nī jeyippāy."}]},{"title":"Un ami a un souci","phrases":[{"fr":"Tu as l'air soucieux aujourd'hui.","tgt":"இன்று நீ கவலையாக இருப்பது போல் தெரிகிறது.","ro":"Iṉru nī kavalaiyāka iruppadu pōl terikiradu."},{"fr":"Qu'est-ce qui ne va pas ?","tgt":"என்ன பிரச்சினை?","ro":"Eṉṉa pirachchiṉai?"},{"fr":"Mes parents veulent que je me marie bientôt.","tgt":"நான் சீக்கிரம் கல்யாணம் செய்ய வேண்டும் என்று அப்பா அம்மா நினைக்கிறார்கள்.","ro":"Nāṉ chīkkiram kalyāṇam cheyya vēṇḍum eṉru appā ammā niṉaikkirārkaḷ."},{"fr":"Mais moi, je ne me sens pas encore prêt.","tgt":"ஆனால் நான் இன்னும் தயாராக இல்லை.","ro":"Āṉāl nāṉ iṉṉum tayārāka illai."},{"fr":"Parle-leur franchement, ils comprendront.","tgt":"அவர்களிடம் வெளிப்படையாகப் பேசு, புரிந்துகொள்வார்கள்.","ro":"Avarkaḷiṭam veḷippaṭaiyākap pēchu, purindukoḷvārkaḷ."},{"fr":"Tes parents veulent juste ton bonheur.","tgt":"உன் பெற்றோர் உன் சந்தோஷத்தைத்தான் விரும்புகிறார்கள்.","ro":"Uṉ petrōr uṉ chandōshattaittāṉ virumbukirārkaḷ."},{"fr":"Tu as raison, je leur parlerai ce soir.","tgt":"நீ சொல்வது சரி, இன்று இரவு அவர்களிடம் பேசுகிறேன்.","ro":"Nī cholvadu chari, iṉru iravu avarkaḷiṭam pēchukirēṉ."},{"fr":"Si tu as besoin, appelle-moi à n'importe quelle heure.","tgt":"தேவைப்பட்டால் எந்த நேரத்திலும் எனக்குப் போன் செய்.","ro":"Tēvaippaṭṭāl enda nērattilum eṉakkup pōṉ chey."},{"fr":"Merci, tu es un vrai ami.","tgt":"நன்றி, நீ உண்மையான நண்பன்.","ro":"Naṉri, nī uṇmaiyāṉa naṇpaṉ."},{"fr":"C'est à ça que servent les amis.","tgt":"நண்பர்கள் இருப்பதே அதற்குத்தான்.","ro":"Naṇparkaḷ iruppadē adarkuttāṉ."}]},{"title":"Chez les parents d'un ami","phrases":[{"fr":"Entrez, asseyez-vous, je vous en prie.","tgt":"வாங்க, உட்காருங்க.","ro":"Vānga, uṭkārunga."},{"fr":"Bonjour madame, comment allez-vous ?","tgt":"வணக்கம் அம்மா, எப்படி இருக்கீங்க?","ro":"Vaṇakkam ammā, eppaṭi irukkīnga?"},{"fr":"Votre fils parle souvent de vous.","tgt":"உங்கள் மகன் உங்களைப் பற்றி அடிக்கடி பேசுவான்.","ro":"Ungaḷ makaṉ ungaḷaip patri aṭikkaṭi pēchuvāṉ."},{"fr":"Mon père est sorti, il rentre bientôt.","tgt":"அப்பா வெளியே போயிருக்கிறார், சீக்கிரம் வந்துவிடுவார்.","ro":"Appā veḷiyē pōyirukkirār, chīkkiram vanduviṭuvār."},{"fr":"Il est professeur de maths au lycée.","tgt":"அவர் உயர்நிலைப் பள்ளியில் கணக்கு ஆசிரியர்.","ro":"Avar uyarnilaip paḷḷiyil kaṇakku āchiriyar."},{"fr":"Prenez donc un café.","tgt":"காபி குடிங்க.","ro":"Kāpi kuṭinga."},{"fr":"Merci, mais ne vous donnez pas tant de peine.","tgt":"நன்றி, ஆனால் சிரமப்படாதீங்க.","ro":"Naṉri, āṉāl chiramappaṭādīnga."},{"fr":"Restez dîner avec nous ce soir.","tgt":"இன்று இரவு எங்களோடு சாப்பிட்டுவிட்டுப் போங்க.","ro":"Iṉru iravu engaḷōṭu chāppiṭṭuviṭṭup pōnga."},{"fr":"Vous habitez ce quartier depuis longtemps ?","tgt":"நீங்க இந்தப் பகுதியில் ரொம்ப நாளாக இருக்கீங்களா?","ro":"Nīnga indap pakudiyil romba nāḷāka irukkīngaḷā?"},{"fr":"Revenez nous voir quand vous voulez.","tgt":"எப்போது வேண்டுமானாலும் மறுபடியும் வாங்க.","ro":"Eppōdu vēṇḍumāṉālum marupaṭiyum vānga."}],"tip":{"title":"Le respect : « avar », « -īnga » et la forme polie","example":"Entrez, asseyez-vous, je vous en prie. — <b>வாங்க</b>, <b>உட்காருங்க</b>.","body":"En tamoul, le respect s'entend à la fin des mots. Face à un aîné, on ne dit plus « vā », viens, mais « vānga », venez : on ajoute « -nga » ou « -unga » à l'impératif, comme « uṭkārunga », asseyez-vous, ou « kuṭinga », buvez. Même logique pour vous êtes : « irukkīnga », dans « eppaṭi irukkīnga ? », comment allez-vous ? Quand on parle d'une personne respectée, « avaṉ », il, devient « avar », et le verbe se termine en « -ār » : « avar varuvār », il viendra. C'est l'équivalent de notre vouvoiement, mais il s'applique aussi quand on parle d'un père, d'un professeur ou d'une grand-mère. Astuce : entendez ce « nga » final comme une petite révérence ajoutée au verbe.","exampleRo":"Vānga, uṭkārunga.","lit":"venez [respect] · asseyez-vous [respect]","say":{"avar":"அவர்","vā":"வா","vānga":"வாங்க","uṭkārunga":"உட்காருங்க","kuṭinga":"குடிங்க","irukkīnga":"இருக்கீங்க","eppaṭi irukkīnga ?":"எப்படி இருக்கீங்க?","avaṉ":"அவன்","avar varuvār":"அவர் வருவார்"}}},{"title":"Au revoir, Trichy","phrases":[{"fr":"Je repars à Chennai demain matin.","tgt":"நாளை காலை சென்னைக்குத் திரும்பிப் போகிறேன்.","ro":"Nāḷai kālai Cheṉṉaikkut tirumbip pōkirēṉ."},{"fr":"Déjà ? Les vacances sont passées si vite !","tgt":"அதற்குள்ளா? விடுமுறை இவ்வளவு சீக்கிரம் முடிந்துவிட்டதே!","ro":"Adarkuḷḷā? Viṭumurai ivvaḷavu chīkkiram muṭinduviṭṭadē!"},{"fr":"Je te dépose à la gare.","tgt":"நான் உன்னை ரயில் நிலையத்தில் விடுகிறேன்.","ro":"Nāṉ uṉṉai rayil nilaiyattil viṭukirēṉ."},{"fr":"Ton train part à quelle heure ?","tgt":"உன் ரயில் எத்தனை மணிக்குக் கிளம்பும்?","ro":"Uṉ rayil ettaṉai maṇikkuk kiḷambum?"},{"fr":"À six heures, donc il faudra partir tôt.","tgt":"ஆறு மணிக்கு, அதனால் சீக்கிரம் கிளம்ப வேண்டும்.","ro":"Āru maṇikku, adaṉāl chīkkiram kiḷamba vēṇḍum."},{"fr":"N'oublie pas d'envoyer les photos du mariage.","tgt":"கல்யாணப் புகைப்படங்களை அனுப்ப மறக்காதே.","ro":"Kalyāṇap pukaippaṭangaḷai aṉuppa marakkādē."},{"fr":"On s'appelle chaque semaine, d'accord ?","tgt":"வாரா வாரம் போனில் பேசுவோம், சரியா?","ro":"Vārā vāram pōṉil pēchuvōm, chariyā?"},{"fr":"C'est dur de te quitter, mon ami.","tgt":"உன்னைப் பிரிவது கஷ்டமாக இருக்கிறது, நண்பா.","ro":"Uṉṉaip pirivadu kashṭamāka irukkiradu, naṇpā."},{"fr":"Reviens vite à Trichy.","tgt":"சீக்கிரம் திருச்சிக்குத் திரும்பி வா.","ro":"Chīkkiram Tiruchchikkut tirumbi vā."},{"fr":"Bon retour, et fais attention à toi.","tgt":"நல்லபடியாகப் போய் வா, உடம்பைப் பார்த்துக்கொள்.","ro":"Nallapaṭiyākap pōy vā, uṭambaip pārttukkoḷ."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, on a discuté avec des amis de Trichy.","tgt":"இந்தப் பகுதியில் திருச்சி நண்பர்களோடு பேசினோம்.","ro":"Indap pakudiyil Tiruchchi naṇparkaḷōṭu pēchiṉōm."},{"fr":"On sait maintenant parler simplement entre amis.","tgt":"இப்போது நண்பர்களோடு இயல்பாகப் பேசத் தெரியும்.","ro":"Ippōdu naṇparkaḷōṭu iyalpākap pēchat teriyum."},{"fr":"On sait aussi parler poliment aux aînés.","tgt":"பெரியவர்களிடம் மரியாதையாகப் பேசவும் தெரியும்.","ro":"Periyavarkaḷiṭam mariyādaiyākap pēchavum teriyum."},{"fr":"On peut parler d'un mariage, d'un match ou d'un repas de fête.","tgt":"கல்யாணம், மேட்ச், பண்டிகைச் சாப்பாடு பற்றிப் பேசலாம்.","ro":"Kalyāṇam, mēṭch, paṇḍikaich chāppāṭu patrip pēchalām."},{"fr":"On sait dire ce qu'on est en train de faire.","tgt":"என்ன செய்துகொண்டிருக்கிறோம் என்று சொல்லத் தெரியும்.","ro":"Eṉṉa cheydukoṇḍirukkirōm eṉru chollat teriyum."},{"fr":"On sait aussi rapporter les nouvelles qu'on a entendues.","tgt":"கேட்ட செய்திகளைத் திரும்பச் சொல்லவும் தெரியும்.","ro":"Kēṭṭa cheydikaḷait tirumbach chollavum teriyum."},{"fr":"Le tamoul parlé devient de plus en plus naturel.","tgt":"பேச்சுத் தமிழ் நமக்கு இயல்பாகிக்கொண்டிருக்கிறது.","ro":"Pēchchut tamiḻ namakku iyalpākikkoṇḍirukkiradu."},{"fr":"Voilà le deuxième niveau bouclé.","tgt":"இரண்டாம் நிலை இப்போது முடிந்துவிட்டது.","ro":"Iraṇḍām nilai ippōdu muṭinduviṭṭadu."},{"fr":"Bravo pour toute cette belle persévérance !","tgt":"இந்த உழைப்புக்கு வாழ்த்துக்கள்!","ro":"Inda uḻaippukku vāḻttukkaḷ!"},{"fr":"Rendez-vous au troisième niveau !","tgt":"மூன்றாம் நிலையில் சந்திப்போம்!","ro":"Mūṉrām nilaiyil chandippōm!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Inde du Sud, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une réunion importante au bureau","phrases":[{"fr":"La réunion a été reportée à jeudi.","tgt":"கூட்டம் வியாழக்கிழமைக்கு ஒத்திவைக்கப்பட்டது.","ro":"Kūṭṭam viyāḻakkiḻamaikku ottivaikkappaṭṭadu."},{"fr":"Le nouveau projet sera présenté par la directrice.","tgt":"புதிய திட்டம் இயக்குநரால் அறிமுகப்படுத்தப்படும்.","ro":"Pudiya tiṭṭam iyakkunarāl aṛimugappaḍuttappaḍum."},{"fr":"Tous les employés ont été invités à cette réunion.","tgt":"எல்லா ஊழியர்களும் இந்த கூட்டத்திற்கு அழைக்கப்பட்டார்கள்.","ro":"Ellā ūḻiyargaḷum inda kūṭṭattiṛku aḻaikkappaṭṭārgaḷ."},{"fr":"Le compte rendu sera envoyé à tout le monde ce soir.","tgt":"கூட்ட அறிக்கை இன்று மாலை எல்லோருக்கும் அனுப்பப்படும்.","ro":"Kūṭṭa aṛikkai iṉṛu mālai ellōrukkum aṉuppappaḍum."},{"fr":"Cette décision a été prise hier par la direction.","tgt":"இந்த முடிவு நேற்று நிர்வாகத்தால் எடுக்கப்பட்டது.","ro":"Inda muḍivu nēṛṛu nirvāgattāl eḍukkappaṭṭadu."},{"fr":"Le budget n'a pas encore été approuvé.","tgt":"பட்ஜெட் இன்னும் அங்கீகரிக்கப்படவில்லை.","ro":"Paṭjeṭ iṉṉum angīgarikkappaḍavillai."},{"fr":"Les horaires de travail seront modifiés le mois prochain.","tgt":"வேலை நேரம் அடுத்த மாதம் மாற்றப்படும்.","ro":"Vēlai nēram aḍutta mādam māṛṛappaḍum."},{"fr":"Est-ce que ce dossier a déjà été vérifié ?","tgt":"இந்த கோப்பு ஏற்கனவே சரிபார்க்கப்பட்டதா?","ro":"Inda kōppu ēṛkaṉavē charipārkkappaṭṭadā?"},{"fr":"La salle de réunion est réservée pour deux heures.","tgt":"கூட்ட அறை இரண்டு மணி நேரத்திற்கு முன்பதிவு செய்யப்பட்டுள்ளது.","ro":"Kūṭṭa aṛai iraṇḍu maṇi nērattiṛku muṉbadivu cheyyappaṭṭuḷḷadu."},{"fr":"Les nouvelles règles seront expliquées à tous demain.","tgt":"புதிய விதிகள் நாளை எல்லோருக்கும் விளக்கப்படும்.","ro":"Pudiya vidigaḷ nāḷai ellōrukkum viḷakkappaḍum."}],"tip":{"title":"Le passif avec « paḍu »","example":"Cette décision a été prise hier par la direction. — இந்த முடிவு நேற்று நிர்வாகத்தால் <b>எடுக்கப்பட்டது</b>.","body":"En tamoul, le passif se forme avec le verbe « paḍu », qui veut dire à l'origine subir. On prend l'infinitif du verbe principal, par exemple « eḍukka », prendre, et on y colle « paḍu » conjugué : « eḍukkappaṭṭadu », cela a été pris. Celui qui fait l'action reçoit la terminaison « -āl », comme « nirvāgattāl », par la direction, exactement là où le français dit par. Au futur, on entend « -appaḍum » : « aṉuppappaḍum », ce sera envoyé, ou « viḷakkappaḍum », ce sera expliqué. Astuce : ce passif sonne officiel, on l'entend surtout dans les annonces et les réunions, alors qu'entre collègues on préfère souvent une phrase active.","exampleRo":"Inda muḍivu nēṛṛu nirvāgattāl eḍukkappaṭṭadu.","lit":"cette · décision · hier · direction [par] (-āl) · prendre [passif, passé] (-appaṭṭadu)","say":{"paḍu":"படு","eḍukka":"எடுக்க","eḍukkappaṭṭadu":"எடுக்கப்பட்டது","nirvāgattāl":"நிர்வாகத்தால்","aṉuppappaḍum":"அனுப்பப்படும்","viḷakkappaḍum":"விளக்கப்படும்"}}},{"title":"Le trajet vers la zone informatique","phrases":[{"fr":"Mon bureau se trouve dans la zone informatique, au sud de Chennai.","tgt":"என் அலுவலகம் சென்னையின் தெற்கே உள்ள ஐடி பகுதியில் இருக்கிறது.","ro":"Eṉ aluvalagam cheṉṉaiyiṉ teṛkē uḷḷa aiḍi pagudiyil irukkiṛadu."},{"fr":"Le matin, je pars de T. Nagar vers sept heures.","tgt":"காலையில் சுமார் ஏழு மணிக்கு தி நகரிலிருந்து கிளம்புகிறேன்.","ro":"Kālaiyil chumār ēḻu maṇikku ti nagarilirundu kiḷambugiṛēṉ."},{"fr":"Le trajet dure parfois plus d'une heure et demie.","tgt":"பயணம் சில நேரம் ஒன்றரை மணி நேரத்துக்கும் மேல் ஆகிறது.","ro":"Payaṇam chila nēram oṉṛarai maṇi nērattukkum mēl āgiṛadu."},{"fr":"Je prends le métro jusqu'à Guindy, puis un bus de l'entreprise.","tgt":"நான் கிண்டி வரை மெட்ரோவில் போய், பிறகு நிறுவன பேருந்தில் ஏறுகிறேன்.","ro":"Nāṉ kiṇḍi varai meṭrōvil pōy, piṛagu niṛuvaṉa pērundil ēṛugiṛēṉ."},{"fr":"Les autres jours, je partage un taxi avec deux collègues.","tgt":"மற்ற நாட்களில் இரண்டு சக ஊழியர்களுடன் ஒரு டாக்ஸியை பகிர்ந்துகொள்கிறேன்.","ro":"Maṛṛa nāṭkaḷil iraṇḍu chaga ūḻiyargaḷuḍaṉ oru ṭāksiyai pagirndukoḷgiṛēṉ."},{"fr":"En ce moment, il y a beaucoup de chantiers sur la route.","tgt":"இப்போது சாலையில் நிறைய கட்டுமான வேலைகள் நடக்கின்றன.","ro":"Ippōdu chālaiyil niṛaiya kaṭṭumāṉa vēlaigaḷ naḍakkiṉṛaṉa."},{"fr":"Quand il pleut, il vaut mieux partir plus tôt.","tgt":"மழை பெய்யும்போது சீக்கிரம் கிளம்புவது நல்லது.","ro":"Maḻai peyyumbōdu chīkkiram kiḷambuvadu nalladu."},{"fr":"Pendant le trajet, je lis mes courriels sur mon téléphone.","tgt":"பயணத்தின்போது என் போனில் மின்னஞ்சல்களை படிக்கிறேன்.","ro":"Payaṇattiṉbōdu eṉ pōṉil miṉṉanchalgaḷai paḍikkiṛēṉ."},{"fr":"J'arrive généralement au bureau vers neuf heures.","tgt":"பொதுவாக சுமார் ஒன்பது மணிக்கு அலுவலகத்தை அடைகிறேன்.","ro":"Poduvāga chumār oṉbadu maṇikku aluvalagattai aḍaigiṛēṉ."},{"fr":"Un jour, j'aimerais habiter plus près de mon travail.","tgt":"என்றாவது ஒரு நாள் அலுவலகத்துக்கு அருகில் வசிக்க ஆசைப்படுகிறேன்.","ro":"Eṉṛāvadu oru nāḷ aluvalagattukku arugil vachikka āchaippaḍugiṛēṉ."}]},{"title":"Faire réparer le climatiseur","phrases":[{"fr":"Le climatiseur de mon bureau ne fonctionne plus.","tgt":"என் அலுவலக அறையில் உள்ள குளிர்சாதனம் வேலை செய்யவில்லை.","ro":"Eṉ aluvalaga aṛaiyil uḷḷa kuḷirchādaṉam vēlai cheyyavillai."},{"fr":"Je vais le faire réparer dès aujourd'hui.","tgt":"இன்றே அதை சரிசெய்ய வைக்கிறேன்.","ro":"Iṉṛē adai charicheyya vaikkiṛēṉ."},{"fr":"Le responsable m'a fait attendre une demi-heure.","tgt":"மேலாளர் என்னை அரை மணி நேரம் காத்திருக்க வைத்தார்.","ro":"Mēlāḷar eṉṉai arai maṇi nēram kāttirukka vaittār."},{"fr":"J'ai fait venir un réparateur de T. Nagar.","tgt":"தி நகரிலிருந்து ஒரு பழுதுபார்ப்பவரை வரவழைத்தேன்.","ro":"Ti nagarilirundu oru paḻudupārppavarai varavaḻaittēṉ."},{"fr":"Il m'a fait signer un formulaire avant de commencer.","tgt":"தொடங்கும் முன் அவர் என்னை ஒரு படிவத்தில் கையெழுத்திட வைத்தார்.","ro":"Toḍangum muṉ avar eṉṉai oru paḍivattil kaiyeḻuttiḍa vaittār."},{"fr":"La directrice nous a informés du changement par courriel.","tgt":"இயக்குநர் மாற்றத்தை மின்னஞ்சல் மூலம் எங்களுக்கு தெரிவித்தார்.","ro":"Iyakkunar māṛṛattai miṉṉanchal mūlam engaḷukku terivittār."},{"fr":"Elle fait travailler toute l'équipe le samedi aussi.","tgt":"அவர் சனிக்கிழமையும் முழு குழுவையும் வேலை செய்ய வைக்கிறார்.","ro":"Avar chaṉikkiḻamaiyum muḻu kuḻuvaiyum vēlai cheyya vaikkiṛār."},{"fr":"J'ai fait traduire le contrat par un ami.","tgt":"என் நண்பர் ஒருவரை ஒப்பந்தத்தை மொழிபெயர்க்க வைத்தேன்.","ro":"Eṉ naṇbar oruvarai oppandattai moḻipeyarkka vaittēṉ."},{"fr":"Le formateur nous fait répéter chaque phrase à voix haute.","tgt":"பயிற்சியாளர் ஒவ்வொரு வாக்கியத்தையும் எங்களை சத்தமாக திரும்ப சொல்ல வைக்கிறார்.","ro":"Payiṛchiyāḷar ovvoru vākkiyattaiyum engaḷai chattamāga tirumba cholla vaikkiṛār."},{"fr":"Le réparateur a remis l'appareil en marche en dix minutes.","tgt":"பழுதுபார்ப்பவர் பத்து நிமிடங்களில் இயந்திரத்தை மீண்டும் இயங்க வைத்தார்.","ro":"Paḻudupārppavar pattu nimiḍangaḷil iyandirattai mīṇḍum iyanga vaittār."}],"tip":{"title":"Le causatif : « -vi », « -vai », faire faire","example":"Le responsable m'a fait attendre une demi-heure. — மேலாளர் என்னை அரை மணி நேரம் <b>காத்திருக்க</b> <b>வைத்தார்</b>.","body":"Pour dire faire faire quelque chose, le tamoul parlé utilise surtout le verbe « vai », mettre, placé juste après l'infinitif. « Kāttirukka », attendre, suivi de « vaittār », il a mis, donne « kāttirukka vaittār », il m'a fait attendre ; la personne qu'on fait agir prend « -ai », comme « eṉṉai », moi. Sur le même modèle, on dit « charicheyya vaikkiṛēṉ », je fais réparer, ou « vēlai cheyya vaikkiṛār », elle fait travailler. Certains verbes ont aussi une forme causative toute faite en « -vi », comme « terivi », faire savoir, que l'on entend dans « terivittār », elle a informé. Astuce : pensez à l'image de mettre quelqu'un à attendre ou à signer, c'est exactement ce que dit le tamoul.","exampleRo":"Mēlāḷar eṉṉai arai maṇi nēram kāttirukka vaittār.","lit":"responsable · moi [objet] (-ai) · demi · heure · temps · attendre · mettre [passé, respect] (faire attendre)","say":{"vai":"வை","Kāttirukka":"காத்திருக்க","vaittār":"வைத்தார்","kāttirukka vaittār":"காத்திருக்க வைத்தார்","eṉṉai":"என்னை","charicheyya vaikkiṛēṉ":"சரிசெய்ய வைக்கிறேன்","vēlai cheyya vaikkiṛār":"வேலை செய்ய வைக்கிறார்","terivi":"தெரிவி","terivittār":"தெரிவித்தார்"}}},{"title":"Chercher un appartement à T. Nagar","phrases":[{"fr":"Je cherche un appartement de deux chambres à T. Nagar.","tgt":"தி நகரில் இரண்டு படுக்கையறை கொண்ட வீடு தேடுகிறேன்.","ro":"Ti nagaril iraṇḍu paḍukkaiyaṛai koṇḍa vīḍu tēḍugiṛēṉ."},{"fr":"Le quartier est bruyant, mais très pratique.","tgt":"இந்த பகுதி சத்தமாக இருக்கிறது, ஆனால் மிகவும் வசதியானது.","ro":"Inda pagudi chattamāga irukkiṛadu, āṉāl migavum vachadiyāṉadu."},{"fr":"Le loyer demandé est de vingt-cinq mille roupies par mois.","tgt":"கேட்கும் வாடகை மாதம் இருபத்தைந்தாயிரம் ரூபாய்.","ro":"Kēṭkum vāḍagai mādam irubattaindāyiram rūpāy."},{"fr":"Le propriétaire exige dix mois de loyer comme caution.","tgt":"வீட்டு உரிமையாளர் பத்து மாத வாடகையை முன்பணமாக கேட்கிறார்.","ro":"Vīṭṭu urimaiyāḷar pattu māda vāḍagaiyai muṉbaṇamāga kēṭkiṛār."},{"fr":"Est-ce que l'eau arrive toute la journée ?","tgt":"நாள் முழுவதும் தண்ணீர் வருமா?","ro":"Nāḷ muḻuvadum taṇṇīr varumā?"},{"fr":"Y a-t-il un générateur en cas de coupure de courant ?","tgt":"மின்வெட்டு ஏற்பட்டால் ஜெனரேட்டர் இருக்கிறதா?","ro":"Miṉveṭṭu ēṛpaṭṭāl jeṉarēṭṭar irukkiṛadā?"},{"fr":"Le gardien m'a fait visiter l'appartement hier soir.","tgt":"காவலாளி நேற்று மாலை எனக்கு வீட்டை காட்டினார்.","ro":"Kāvalāḷi nēṛṛu mālai eṉakku vīṭṭai kāṭṭiṉār."},{"fr":"La cuisine est petite, mais le balcon est agréable.","tgt":"சமையலறை சிறியது, ஆனால் பால்கனி அழகாக இருக்கிறது.","ro":"Chamaiyalaṛai chiṛiyadu, āṉāl pālgaṉi aḻagāga irukkiṛadu."},{"fr":"Je préfère un logement proche de la station de métro.","tgt":"மெட்ரோ நிலையத்துக்கு அருகில் உள்ள வீடே எனக்கு பிடிக்கும்.","ro":"Meṭrō nilaiyattukku arugil uḷḷa vīḍē eṉakku piḍikkum."},{"fr":"Je donnerai ma réponse au propriétaire avant vendredi.","tgt":"வெள்ளிக்கிழமைக்குள் உரிமையாளரிடம் என் பதிலை சொல்வேன்.","ro":"Veḷḷikkiḻamaikkuḷ urimaiyāḷariḍam eṉ padilai cholvēṉ."}]},{"title":"Signer le bail","phrases":[{"fr":"Le bail est prévu pour onze mois.","tgt":"வாடகை ஒப்பந்தம் பதினொரு மாதங்களுக்கானது.","ro":"Vāḍagai oppandam padiṉoru mādangaḷukkāṉadu."},{"fr":"Vous aurez les clés seulement si vous payez la caution.","tgt":"முன்பணம் கட்டினால் மட்டுமே சாவி கிடைக்கும்.","ro":"Muṉbaṇam kaṭṭiṉāl maṭṭumē chāvi kiḍaikkum."},{"fr":"Le contrat n'est valable que si les deux parties le signent.","tgt":"இரண்டு தரப்பினரும் கையெழுத்திட்டால் மட்டுமே ஒப்பந்தம் செல்லும்.","ro":"Iraṇḍu tarappiṉarum kaiyeḻuttiṭṭāl maṭṭumē oppandam chellum."},{"fr":"Je ne peux repeindre les murs que si le propriétaire est d'accord.","tgt":"உரிமையாளர் ஒப்புக்கொண்டால் மட்டுமே சுவர்களுக்கு மீண்டும் வர்ணம் பூச முடியும்.","ro":"Urimaiyāḷar oppukkoṇḍāl maṭṭumē chuvargaḷukku mīṇḍum varṇam pūcha muḍiyum."},{"fr":"Lisez bien chaque clause avant de signer.","tgt":"கையெழுத்திடும் முன் ஒவ்வொரு விதியையும் கவனமாக படியுங்கள்.","ro":"Kaiyeḻuttiḍum muṉ ovvoru vidiyaiyum kavaṉamāga paḍiyungaḷ."},{"fr":"La caution sera rendue seulement si l'appartement est en bon état.","tgt":"வீடு நல்ல நிலையில் இருந்தால் மட்டுமே முன்பணம் திருப்பி தரப்படும்.","ro":"Vīḍu nalla nilaiyil irundāl maṭṭumē muṉbaṇam tiruppi tarappaḍum."},{"fr":"L'agent immobilier prend un mois de loyer comme commission.","tgt":"தரகர் ஒரு மாத வாடகையை கமிஷனாக எடுத்துக்கொள்கிறார்.","ro":"Taragar oru māda vāḍagaiyai kamishaṉāga eḍuttukkoḷgiṛār."},{"fr":"On ne peut baisser le loyer que si on s'engage pour deux ans.","tgt":"இரண்டு வருடத்துக்கு ஒப்பந்தம் போட்டால் மட்டுமே வாடகையை குறைக்க முடியும்.","ro":"Iraṇḍu varuḍattukku oppandam pōṭṭāl maṭṭumē vāḍagaiyai kuṛaikka muḍiyum."},{"fr":"J'ai demandé une copie signée du contrat.","tgt":"கையெழுத்திட்ட ஒப்பந்தத்தின் ஒரு நகலை கேட்டேன்.","ro":"Kaiyeḻuttiṭṭa oppandattiṉ oru nagalai kēṭṭēṉ."},{"fr":"Je n'emménagerai que si l'eau et l'électricité fonctionnent.","tgt":"தண்ணீரும் மின்சாரமும் சரியாக இருந்தால் மட்டுமே குடியேறுவேன்.","ro":"Taṇṇīrum miṉchāramum chariyāga irundāl maṭṭumē kuḍiyēṛuvēṉ."}],"tip":{"title":"« -āl maṭṭumē » : seulement si","example":"Vous aurez les clés seulement si vous payez la caution. — முன்பணம் <b>கட்டினால்</b> <b>மட்டுமே</b> சாவி கிடைக்கும்.","body":"Le tamoul exprime la condition par une simple terminaison collée au verbe : « -āl », qui veut dire si. Ainsi « kaṭṭu », payer, devient « kaṭṭiṉāl », si vous payez. Ajoutez juste après « maṭṭumē », seulement, et la condition devient stricte : « kaṭṭiṉāl maṭṭumē », seulement si vous payez. Décomposons la phrase entière : « muṉbaṇam kaṭṭiṉāl maṭṭumē chāvi kiḍaikkum », caution, si vous payez, seulement, clé, sera obtenue. Sur le même modèle, on dit « irundāl maṭṭumē », seulement s'il y a, ou « oppukkoṇḍāl maṭṭumē », seulement s'il est d'accord. Astuce : la condition vient toujours avant le résultat, comme quand on dit en français si tu payes, et seulement là, tu as la clé.","exampleRo":"Muṉbaṇam kaṭṭiṉāl maṭṭumē chāvi kiḍaikkum.","lit":"caution · payer [si] (-āl) · seulement · clé · être obtenu [futur]","say":{"kaṭṭu":"கட்டு","kaṭṭiṉāl":"கட்டினால்","maṭṭumē":"மட்டுமே","kaṭṭiṉāl maṭṭumē":"கட்டினால் மட்டுமே","muṉbaṇam kaṭṭiṉāl maṭṭumē chāvi kiḍaikkum":"முன்பணம் கட்டினால் மட்டுமே சாவி கிடைக்கும்","irundāl maṭṭumē":"இருந்தால் மட்டுமே","oppukkoṇḍāl maṭṭumē":"ஒப்புக்கொண்டால் மட்டுமே"}}},{"title":"Un désaccord avec un collègue","phrases":[{"fr":"Hier, j'ai eu un désaccord avec un collègue.","tgt":"நேற்று ஒரு சக ஊழியருடன் எனக்கு கருத்து வேறுபாடு ஏற்பட்டது.","ro":"Nēṛṛu oru chaga ūḻiyaruḍaṉ eṉakku karuttu vēṛupāḍu ēṛpaṭṭadu."},{"fr":"Il pensait que j'avais oublié son rapport.","tgt":"நான் அவருடைய அறிக்கையை மறந்துவிட்டேன் என்று அவர் நினைத்தார்.","ro":"Nāṉ avaruḍaiya aṛikkaiyai maṛanduviṭṭēṉ eṉṛu avar niṉaittār."},{"fr":"En réalité, le courriel était arrivé dans le mauvais dossier.","tgt":"உண்மையில் அந்த மின்னஞ்சல் தவறான கோப்புறைக்குள் போயிருந்தது.","ro":"Uṇmaiyil anda miṉṉanchal tavaṛāṉa kōppuṛaikkuḷ pōyirundadu."},{"fr":"Nous sommes allés à la cantine pour en parler calmement.","tgt":"அமைதியாக பேசுவதற்காக நாங்கள் கேண்டீனுக்கு போனோம்.","ro":"Amaidiyāga pēchuvadaṛkāga nāngaḷ kēṇḍīṉukku pōṉōm."},{"fr":"Chacun a pu expliquer son point de vue.","tgt":"ஒவ்வொருவராலும் தன் கருத்தை விளக்க முடிந்தது.","ro":"Ovvoruvarālum taṉ karuttai viḷakka muḍindadu."},{"fr":"Je lui ai présenté mes excuses pour le malentendu.","tgt":"தவறான புரிதலுக்காக அவரிடம் மன்னிப்பு கேட்டேன்.","ro":"Tavaṛāṉa puridalukkāga avariḍam maṉṉippu kēṭṭēṉ."},{"fr":"Il a reconnu qu'il s'était un peu énervé.","tgt":"தான் கொஞ்சம் கோபப்பட்டதாக அவர் ஒப்புக்கொண்டார்.","ro":"Tāṉ koncham kōpappaṭṭadāga avar oppukkoṇḍār."},{"fr":"Nous avons décidé de mieux répartir les tâches.","tgt":"வேலைகளை இன்னும் சிறப்பாக பகிர்ந்துகொள்ள முடிவு செய்தோம்.","ro":"Vēlaigaḷai iṉṉum chiṛappāga pagirndukoḷḷa muḍivu cheydōm."},{"fr":"Depuis, notre collaboration est bien plus agréable.","tgt":"அதன் பிறகு எங்கள் ஒத்துழைப்பு மிகவும் இனிமையாக இருக்கிறது.","ro":"Adaṉ piṛagu engaḷ ottuḻaippu migavum iṉimaiyāga irukkiṛadu."},{"fr":"Parler franchement évite bien des problèmes.","tgt":"வெளிப்படையாக பேசினால் பல பிரச்சினைகளை தவிர்க்கலாம்.","ro":"Veḷippaḍaiyāga pēchiṉāl pala pirachchiṉaigaḷai tavirkkalām."}]},{"title":"Une démarche administrative","phrases":[{"fr":"Je dois renouveler mon permis de séjour ce mois-ci.","tgt":"இந்த மாதம் என் குடியிருப்பு அனுமதியை புதுப்பிக்க வேண்டும்.","ro":"Inda mādam eṉ kuḍiyiruppu aṉumadiyai puduppikka vēṇḍum."},{"fr":"Le bureau ouvre à dix heures, mais la file est déjà longue.","tgt":"அலுவலகம் பத்து மணிக்கு திறக்கிறது, ஆனால் வரிசை ஏற்கனவே நீளமாக இருக்கிறது.","ro":"Aluvalagam pattu maṇikku tiṛakkiṛadu, āṉāl varichai ēṛkaṉavē nīḷamāga irukkiṛadu."},{"fr":"Il faut apporter deux photos et une copie du passeport.","tgt":"இரண்டு புகைப்படங்களும் கடவுச்சீட்டின் ஒரு நகலும் கொண்டுவர வேண்டும்.","ro":"Iraṇḍu pugaippaḍangaḷum kaḍavuchchīṭṭiṉ oru nagalum koṇḍuvara vēṇḍum."},{"fr":"L'employé au guichet m'a demandé un justificatif de domicile.","tgt":"கவுண்டரில் இருந்தவர் முகவரி சான்று கேட்டார்.","ro":"Kavuṇḍaril irundavar mugavari chāṉṛu kēṭṭār."},{"fr":"Mon bail suffira-t-il comme preuve ?","tgt":"என் வாடகை ஒப்பந்தம் சான்றாக போதுமா?","ro":"Eṉ vāḍagai oppandam chāṉṛāga pōdumā?"},{"fr":"On m'a donné un numéro et je dois attendre mon tour.","tgt":"எனக்கு ஒரு எண் கொடுத்தார்கள், என் முறை வரும் வரை காத்திருக்க வேண்டும்.","ro":"Eṉakku oru eṇ koḍuttārgaḷ, eṉ muṛai varum varai kāttirukka vēṇḍum."},{"fr":"La demande sera examinée sous quinze jours.","tgt":"விண்ணப்பம் பதினைந்து நாட்களுக்குள் பரிசீலிக்கப்படும்.","ro":"Viṇṇappam padiṉaindu nāṭkaḷukkuḷ parichīlikkappaḍum."},{"fr":"Pouvez-vous m'envoyer la réponse par courriel ?","tgt":"பதிலை எனக்கு மின்னஞ்சலில் அனுப்ப முடியுமா?","ro":"Padilai eṉakku miṉṉanchalil aṉuppa muḍiyumā?"},{"fr":"La fonctionnaire a été très patiente avec moi.","tgt":"அந்த அலுவலர் என்னிடம் மிகவும் பொறுமையாக இருந்தார்.","ro":"Anda aluvalar eṉṉiḍam migavum poṛumaiyāga irundār."},{"fr":"Finalement, tout s'est réglé en une seule matinée.","tgt":"கடைசியில் ஒரே காலையில் எல்லாம் முடிந்துவிட்டது.","ro":"Kaḍaichiyil orē kālaiyil ellām muḍinduviṭṭadu."}]},{"title":"Embouteillages un jour de mousson","phrases":[{"fr":"Ce matin, même la grande avenue était inondée.","tgt":"இன்று காலை பெரிய சாலை கூட வெள்ளத்தில் மூழ்கியிருந்தது.","ro":"Iṉṛu kālai periya chālai kūḍa veḷḷattil mūḻgiyirundadu."},{"fr":"Même les bus ne roulaient plus.","tgt":"பேருந்துகள் கூட ஓடவில்லை.","ro":"Pērundugaḷ kūḍa ōḍavillai."},{"fr":"Je n'ai même pas pu sortir de ma rue.","tgt":"என் தெருவிலிருந்து கூட வெளியே வர முடியவில்லை.","ro":"Eṉ teruvilirundu kūḍa veḷiyē vara muḍiyavillai."},{"fr":"Même avec un parapluie, je suis arrivé trempé.","tgt":"குடை இருந்தும் கூட நான் நனைந்துபோய் வந்தேன்.","ro":"Kuḍai irundum kūḍa nāṉ naṉaindupōy vandēṉ."},{"fr":"Même le chauffeur de taxi a refusé de venir jusqu'ici.","tgt":"டாக்ஸி ஓட்டுநர் கூட இங்கே வர மறுத்துவிட்டார்.","ro":"Ṭāksi ōṭṭunar kūḍa ingē vara maṛuttuviṭṭār."},{"fr":"Le bureau a autorisé tout le monde à travailler depuis chez soi.","tgt":"அலுவலகம் எல்லோரையும் வீட்டிலிருந்தே வேலை செய்ய அனுமதித்தது.","ro":"Aluvalagam ellōraiyum vīṭṭilirundē vēlai cheyya aṉumadittadu."},{"fr":"Même le patron est resté à la maison aujourd'hui.","tgt":"இன்று முதலாளி கூட வீட்டிலேயே இருந்தார்.","ro":"Iṉṛu mudalāḷi kūḍa vīṭṭilēyē irundār."},{"fr":"Il n'y a même pas d'électricité depuis ce matin.","tgt":"காலையிலிருந்து மின்சாரம் கூட இல்லை.","ro":"Kālaiyilirundu miṉchāram kūḍa illai."},{"fr":"Les enfants, eux, adorent sauter dans les flaques.","tgt":"குழந்தைகளுக்கோ தேங்கிய தண்ணீரில் குதிப்பது மிகவும் பிடிக்கும்.","ro":"Kuḻandaigaḷukkō tēngiya taṇṇīril kudippadu migavum piḍikkum."},{"fr":"Heureusement, on annonce que la pluie va diminuer d'ici demain.","tgt":"நல்லவேளையாக நாளைக்குள் மழை குறையும் என்று சொல்கிறார்கள்.","ro":"Nallavēḷaiyāga nāḷaikkuḷ maḻai kuṛaiyum eṉṛu cholgiṛārgaḷ."}],"tip":{"title":"« Kūḍa » : même","example":"Même les bus ne roulaient plus. — பேருந்துகள் <b>கூட</b> ஓடவில்லை.","body":"« Kūḍa » se place juste après le mot qu'il met en relief, alors que le français met même avant. On dit donc « pērundugaḷ kūḍa », les bus même, pour même les bus. Dans une phrase négative, il prend le sens de même pas : « miṉchāram kūḍa illai », il n'y a même pas d'électricité. Dans « oru choṭṭu kūḍa », pas même une goutte, on retrouve exactement la même logique. Attention, « kūḍa » veut aussi dire avec, comme dans « eṉ kūḍa », avec moi : c'est le contexte qui tranche. Astuce : dites le mot important, marquez une petite pause, puis « kūḍa », et l'insistance passe toute seule.","exampleRo":"Pērundugaḷ kūḍa ōḍavillai.","lit":"bus [pluriel] (-gaḷ) · même · rouler [passé, négation]","say":{"Kūḍa":"கூட","pērundugaḷ kūḍa":"பேருந்துகள் கூட","miṉchāram kūḍa illai":"மின்சாரம் கூட இல்லை","oru choṭṭu kūḍa":"ஒரு சொட்டு கூட","kūḍa":"கூட","eṉ kūḍa":"என் கூட"}}},{"title":"Un collègue blessé à l'hôpital","phrases":[{"fr":"Mon collègue s'est tordu la cheville en descendant du bus.","tgt":"என் சக ஊழியருக்கு பேருந்திலிருந்து இறங்கும்போது கணுக்காலில் சுளுக்கு ஏற்பட்டது.","ro":"Eṉ chaga ūḻiyarukku pērundilirundu iṛangumbōdu kaṇukkālil chuḷukku ēṛpaṭṭadu."},{"fr":"Je l'ai accompagné à l'hôpital le plus proche.","tgt":"அருகில் உள்ள மருத்துவமனைக்கு அவரை அழைத்து சென்றேன்.","ro":"Arugil uḷḷa maruttuvamaṉaikku avarai aḻaittu cheṉṛēṉ."},{"fr":"À l'accueil, on nous a demandé de remplir un formulaire.","tgt":"வரவேற்பில் ஒரு படிவத்தை நிரப்ப சொன்னார்கள்.","ro":"Varavēṛpil oru paḍivattai nirappa choṉṉārgaḷ."},{"fr":"Le médecin l'a examiné au bout d'une heure.","tgt":"ஒரு மணி நேரம் கழித்து மருத்துவர் அவரை பரிசோதித்தார்.","ro":"Oru maṇi nēram kaḻittu maruttuvar avarai parichōdittār."},{"fr":"On a fait une radio pour vérifier qu'il n'y a pas de fracture.","tgt":"எலும்பு முறிவு இல்லை என்று உறுதிசெய்ய எக்ஸ்ரே எடுக்கப்பட்டது.","ro":"Elumbu muṛivu illai eṉṛu uṛudicheyya eksrē eḍukkappaṭṭadu."},{"fr":"Par chance, ce n'est qu'une petite entorse.","tgt":"நல்லவேளையாக இது ஒரு சிறிய சுளுக்கு மட்டுமே.","ro":"Nallavēḷaiyāga idu oru chiṛiya chuḷukku maṭṭumē."},{"fr":"Il doit se reposer une semaine sans marcher.","tgt":"அவர் ஒரு வாரம் நடக்காமல் ஓய்வு எடுக்க வேண்டும்.","ro":"Avar oru vāram naḍakkāmal ōyvu eḍukka vēṇḍum."},{"fr":"La pharmacie de l'hôpital est ouverte jour et nuit.","tgt":"மருத்துவமனையின் மருந்தகம் இரவும் பகலும் திறந்திருக்கும்.","ro":"Maruttuvamaṉaiyiṉ marundagam iravum pagalum tiṛandirukkum."},{"fr":"L'assurance de l'entreprise couvre tous les frais.","tgt":"நிறுவனத்தின் காப்பீடு எல்லா செலவுகளையும் ஈடுசெய்கிறது.","ro":"Niṛuvaṉattiṉ kāppīḍu ellā chelavugaḷaiyum īḍucheygiṛadu."},{"fr":"Je l'ai ramené chez lui en taxi.","tgt":"டாக்ஸியில் அவரை வீட்டில் கொண்டுபோய் விட்டேன்.","ro":"Ṭāksiyil avarai vīṭṭil koṇḍupōy viṭṭēṉ."}]},{"title":"Un nouveau contrat de travail","phrases":[{"fr":"On m'a proposé un nouveau poste dans l'équipe de Chennai.","tgt":"சென்னை குழுவில் எனக்கு ஒரு புதிய பதவி வழங்கப்பட்டது.","ro":"Cheṉṉai kuḻuvil eṉakku oru pudiya padavi vaḻangappaṭṭadu."},{"fr":"Le salaire est un peu plus élevé qu'avant.","tgt":"சம்பளம் முன்பை விட கொஞ்சம் அதிகம்.","ro":"Chambaḷam muṉbai viḍa koncham adigam."},{"fr":"Le contrat prévoit trois mois de période d'essai.","tgt":"ஒப்பந்தத்தில் மூன்று மாத சோதனை காலம் உள்ளது.","ro":"Oppandattil mūṉṛu māda chōdaṉai kālam uḷḷadu."},{"fr":"J'aurai droit à vingt jours de congés payés par an.","tgt":"ஆண்டுக்கு இருபது நாட்கள் சம்பளத்துடன் விடுப்பு கிடைக்கும்.","ro":"Āṇḍukku irubadu nāṭkaḷ chambaḷattuḍaṉ viḍuppu kiḍaikkum."},{"fr":"Les horaires sont souples, sauf les jours de réunion.","tgt":"கூட்ட நாட்கள் தவிர வேலை நேரம் நெகிழ்வானது.","ro":"Kūṭṭa nāṭkaḷ tavira vēlai nēram negiḻvāṉadu."},{"fr":"Je dois prévenir deux mois à l'avance si je pars.","tgt":"நான் வேலையை விட்டால் இரண்டு மாதம் முன்பே அறிவிக்க வேண்டும்.","ro":"Nāṉ vēlaiyai viṭṭāl iraṇḍu mādam muṉbē aṛivikka vēṇḍum."},{"fr":"J'ai relu chaque page avec l'aide d'une amie avocate.","tgt":"ஒரு வழக்கறிஞர் தோழியின் உதவியுடன் ஒவ்வொரு பக்கத்தையும் மீண்டும் படித்தேன்.","ro":"Oru vaḻakkaṛinyar tōḻiyiṉ udaviyuḍaṉ ovvoru pakkattaiyum mīṇḍum paḍittēṉ."},{"fr":"Une clause sur les heures supplémentaires n'était pas claire.","tgt":"கூடுதல் நேர வேலை பற்றிய ஒரு விதி தெளிவாக இல்லை.","ro":"Kūḍudal nēra vēlai paṛṛiya oru vidi teḷivāga illai."},{"fr":"Les ressources humaines l'ont corrigée tout de suite.","tgt":"மனிதவள துறை உடனே அதை திருத்தியது.","ro":"Maṉidavaḷa tuṛai uḍaṉē adai tiruttiyadu."},{"fr":"Je commencerai officiellement le premier du mois.","tgt":"மாதத்தின் முதல் தேதி அதிகாரபூர்வமாக வேலையை தொடங்குவேன்.","ro":"Mādattiṉ mudal tēdi adigārapūrvamāga vēlaiyai toḍanguvēṉ."}]},{"title":"Un samedi de courses à T. Nagar","phrases":[{"fr":"Le samedi, les rues de T. Nagar sont noires de monde.","tgt":"சனிக்கிழமைகளில் தி நகர் தெருக்களில் கூட்டம் அலைமோதுகிறது.","ro":"Chaṉikkiḻamaigaḷil ti nagar terukkaḷil kūṭṭam alaimōdugiṛadu."},{"fr":"Ma femme cherche un sari en soie pour un mariage.","tgt":"என் மனைவி ஒரு திருமணத்துக்காக பட்டுப்புடவை தேடுகிறார்.","ro":"Eṉ maṉaivi oru tirumaṇattukkāga paṭṭuppuḍavai tēḍugiṛār."},{"fr":"Les boutiques restent ouvertes jusqu'à dix heures du soir.","tgt":"கடைகள் இரவு பத்து மணி வரை திறந்திருக்கும்.","ro":"Kaḍaigaḷ iravu pattu maṇi varai tiṛandirukkum."},{"fr":"Le vendeur nous a montré une dizaine de modèles.","tgt":"விற்பனையாளர் எங்களுக்கு சுமார் பத்து வகைகளை காட்டினார்.","ro":"Viṛpaṉaiyāḷar engaḷukku chumār pattu vagaigaḷai kāṭṭiṉār."},{"fr":"Ce bleu foncé lui va vraiment bien.","tgt":"இந்த அடர் நீல நிறம் அவருக்கு மிகவும் பொருத்தமாக இருக்கிறது.","ro":"Inda aḍar nīla niṛam avarukku migavum poruttamāga irukkiṛadu."},{"fr":"Ici les prix sont fixes, on ne peut pas marchander.","tgt":"இங்கே விலைகள் நிர்ணயிக்கப்பட்டவை, பேரம் பேச முடியாது.","ro":"Ingē vilaigaḷ nirṇayikkappaṭṭavai, pēram pēcha muḍiyādu."},{"fr":"Dans la rue, on peut négocier avec les petits marchands.","tgt":"தெருவில் சிறு வியாபாரிகளிடம் பேரம் பேசலாம்.","ro":"Teruvil chiṛu viyāpārigaḷiḍam pēram pēchalām."},{"fr":"Nous avons fait une pause pour boire un jus de canne à sucre.","tgt":"கரும்புச்சாறு குடிக்க சிறிது நேரம் நின்றோம்.","ro":"Karumbuchchāṛu kuḍikka chiṛidu nēram niṉṛōm."},{"fr":"Au total, nous avons dépensé huit mille roupies.","tgt":"மொத்தம் எட்டாயிரம் ரூபாய் செலவழித்தோம்.","ro":"Mottam eṭṭāyiram rūpāy chelavaḻittōm."},{"fr":"Rentrer en auto-rickshaw a été une petite aventure.","tgt":"ஆட்டோவில் வீடு திரும்புவது ஒரு சிறிய சாகசமாக இருந்தது.","ro":"Āṭṭōvil vīḍu tirumbuvadu oru chiṛiya chāgachamāga irundadu."}]},{"title":"Présenter un projet à la direction","phrases":[{"fr":"Bonjour à tous, merci d'être présents ce matin.","tgt":"அனைவருக்கும் வணக்கம், இன்று காலை வருகை தந்ததற்கு நன்றி.","ro":"Aṉaivarukkum vaṇakkam, iṉṛu kālai varugai tandadaṛku naṉṛi."},{"fr":"Permettez-moi de vous présenter notre nouveau projet.","tgt":"எங்கள் புதிய திட்டத்தை உங்களுக்கு அறிமுகப்படுத்த அனுமதியுங்கள்.","ro":"Engaḷ pudiya tiṭṭattai ungaḷukku aṛimugappaḍutta aṉumadiyungaḷ."},{"fr":"Je tiens d'abord à remercier l'équipe pour son travail.","tgt":"முதலில் குழுவின் உழைப்புக்கு நன்றி தெரிவித்துக்கொள்கிறேன்.","ro":"Mudalil kuḻuviṉ uḻaippukku naṉṛi terivittukkoḷgiṛēṉ."},{"fr":"Veuillez noter que ces chiffres sont provisoires.","tgt":"இந்த எண்ணிக்கைகள் தற்காலிகமானவை என்பதை கவனத்தில் கொள்ளுங்கள்.","ro":"Inda eṇṇikkaigaḷ taṛkāligamāṉavai eṉbadai kavaṉattil koḷḷungaḷ."},{"fr":"Je souhaiterais proposer un calendrier plus court.","tgt":"ஒரு குறுகிய கால அட்டவணையை முன்மொழிய விரும்புகிறேன்.","ro":"Oru kuṛugiya kāla aṭṭavaṇaiyai muṉmoḻiya virumbugiṛēṉ."},{"fr":"N'hésitez pas à m'interrompre si vous avez une question.","tgt":"கேள்வி இருந்தால் தயங்காமல் இடையில் கேளுங்கள்.","ro":"Kēḷvi irundāl tayangāmal iḍaiyil kēḷungaḷ."},{"fr":"Votre avis nous serait très précieux.","tgt":"உங்கள் கருத்து எங்களுக்கு மிகவும் மதிப்புமிக்கது.","ro":"Ungaḷ karuttu engaḷukku migavum madippumikkadu."},{"fr":"Nous vous enverrons le document complet dès demain.","tgt":"முழு ஆவணத்தை நாளையே உங்களுக்கு அனுப்புகிறோம்.","ro":"Muḻu āvaṇattai nāḷaiyē ungaḷukku aṉuppugiṛōm."},{"fr":"Je vous remercie sincèrement de votre attention.","tgt":"உங்கள் கவனத்துக்கு மனமார்ந்த நன்றி.","ro":"Ungaḷ kavaṉattukku maṉamārnda naṉṛi."},{"fr":"Si vous le permettez, passons maintenant aux questions.","tgt":"நீங்கள் அனுமதித்தால், இப்போது கேள்விகளுக்கு வருவோம்.","ro":"Nīngaḷ aṉumadittāl, ippōdu kēḷvigaḷukku varuvōm."}],"tip":{"title":"Le registre soutenu du bureau : les formules formelles","example":"Je tiens d'abord à remercier l'équipe pour son travail. — முதலில் குழுவின் உழைப்புக்கு நன்றி <b>தெரிவித்துக்கொள்கிறேன்</b>.","body":"Dans une réunion, le tamoul passe volontiers à un registre plus soutenu. On salue l'assemblée avec « aṉaivarukkum vaṇakkam », bonjour à tous, et on demande avec l'impératif poli en « -ungaḷ », comme « koḷḷungaḷ », veuillez prendre, ou « kēḷungaḷ », demandez. Pour remercier avec élégance, on dit « naṉṛi terivittukkoḷgiṛēṉ », littéralement j'exprime mes remerciements, au lieu d'un simple « naṉṛi ». La terminaison « -kkoḷgiṛēṉ » ajoute une nuance de modestie, un peu comme je me permets de. Pour conclure, « maṉamārnda naṉṛi », merci du fond du cœur, fait toujours bon effet. Astuce : apprenez ces quelques formules par cœur, elles suffisent pour ouvrir et fermer n'importe quelle présentation.","exampleRo":"Mudalil kuḻuviṉ uḻaippukku naṉṛi terivittukkoḷgiṛēṉ.","lit":"d'abord · équipe [de] (-iṉ) · travail [à] (-ukku) · merci · exprimer [soutenu] (-ttukkoḷgiṛēṉ)","say":{"aṉaivarukkum vaṇakkam":"அனைவருக்கும் வணக்கம்","koḷḷungaḷ":"கொள்ளுங்கள்","kēḷungaḷ":"கேளுங்கள்","naṉṛi terivittukkoḷgiṛēṉ":"நன்றி தெரிவித்துக்கொள்கிறேன்","naṉṛi":"நன்றி","maṉamārnda naṉṛi":"மனமார்ந்த நன்றி"}}},{"title":"Le télétravail pendant la mousson","phrases":[{"fr":"Pendant la mousson, je travaille souvent de chez moi.","tgt":"பருவமழை காலத்தில் நான் அடிக்கடி வீட்டிலிருந்து வேலை செய்கிறேன்.","ro":"Paruvamaḻai kālattil nāṉ aḍikkaḍi vīṭṭilirundu vēlai cheygiṛēṉ."},{"fr":"J'ai installé un petit bureau près de la fenêtre.","tgt":"ஜன்னலுக்கு அருகில் ஒரு சிறிய மேசை அமைத்திருக்கிறேன்.","ro":"Jaṉṉalukku arugil oru chiṛiya mēchai amaittirukkiṛēṉ."},{"fr":"La connexion internet est coupée dès qu'il y a un orage.","tgt":"இடியுடன் மழை பெய்தவுடன் இணைய இணைப்பு துண்டிக்கப்படுகிறது.","ro":"Iḍiyuḍaṉ maḻai peydavuḍaṉ iṇaiya iṇaippu tuṇḍikkappaḍugiṛadu."},{"fr":"Je garde toujours une batterie de secours chargée.","tgt":"எப்போதும் ஒரு கூடுதல் பேட்டரியை சார்ஜ் செய்து வைத்திருக்கிறேன்.","ro":"Eppōdum oru kūḍudal pēṭṭariyai chārj cheydu vaittirukkiṛēṉ."},{"fr":"Les visioconférences commencent à dix heures précises.","tgt":"காணொளி கூட்டங்கள் சரியாக பத்து மணிக்கு தொடங்குகின்றன.","ro":"Kāṇoḷi kūṭṭangaḷ chariyāga pattu maṇikku toḍangugiṉṛaṉa."},{"fr":"Mes collègues entendent parfois la pluie derrière moi.","tgt":"என் பின்னால் பெய்யும் மழையின் சத்தம் சில நேரம் சக ஊழியர்களுக்கு கேட்கிறது.","ro":"Eṉ piṉṉāl peyyum maḻaiyiṉ chattam chila nēram chaga ūḻiyargaḷukku kēṭkiṛadu."},{"fr":"À midi, je me prépare un riz au sambar.","tgt":"மதியம் நானே சாம்பார் சாதம் சமைத்துக்கொள்கிறேன்.","ro":"Madiyam nāṉē chāmbār chādam chamaittukkoḷgiṛēṉ."},{"fr":"Ne pas perdre de temps dans les bouchons, c'est un vrai luxe.","tgt":"போக்குவரத்து நெரிசலில் நேரத்தை வீணாக்காமல் இருப்பது ஒரு பெரிய வசதி.","ro":"Pōkkuvarattu nerichalil nērattai vīṇākkāmal iruppadu oru periya vachadi."},{"fr":"Mais l'ambiance du bureau me manque un peu.","tgt":"ஆனால் அலுவலக சூழலை கொஞ்சம் இழந்தது போல் உணர்கிறேன்.","ro":"Āṉāl aluvalaga chūḻalai koncham iḻandadu pōl uṇargiṛēṉ."},{"fr":"Dès que les routes sèchent, je retourne au bureau.","tgt":"சாலைகள் காய்ந்தவுடன் மீண்டும் அலுவலகம் போவேன்.","ro":"Chālaigaḷ kāyndavuḍaṉ mīṇḍum aluvalagam pōvēṉ."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Pour recevoir mon salaire, je dois ouvrir un compte ici.","tgt":"சம்பளம் பெற இங்கே ஒரு வங்கி கணக்கு திறக்க வேண்டும்.","ro":"Chambaḷam peṛa ingē oru vangi kaṇakku tiṛakka vēṇḍum."},{"fr":"L'agence est juste à côté de la gare de Mambalam.","tgt":"வங்கி கிளை மாம்பலம் ரயில் நிலையத்துக்கு பக்கத்திலேயே உள்ளது.","ro":"Vangi kiḷai māmbalam rayil nilaiyattukku pakkattilēyē uḷḷadu."},{"fr":"Le conseiller m'a expliqué les différents types de comptes.","tgt":"அதிகாரி பல வகையான கணக்குகளை எனக்கு விளக்கினார்.","ro":"Adigāri pala vagaiyāṉa kaṇakkugaḷai eṉakku viḷakkiṉār."},{"fr":"J'ai dû fournir mon passeport et mon contrat de travail.","tgt":"என் கடவுச்சீட்டையும் வேலை ஒப்பந்தத்தையும் கொடுக்க வேண்டியிருந்தது.","ro":"Eṉ kaḍavuchchīṭṭaiyum vēlai oppandattaiyum koḍukka vēṇḍiyirundadu."},{"fr":"On m'a fait signer au moins dix pages.","tgt":"குறைந்தது பத்து பக்கங்களில் என்னை கையெழுத்திட வைத்தார்கள்.","ro":"Kuṛaindadu pattu pakkangaḷil eṉṉai kaiyeḻuttiḍa vaittārgaḷ."},{"fr":"La carte bancaire arrivera par la poste dans une semaine.","tgt":"வங்கி அட்டை ஒரு வாரத்தில் தபாலில் வரும்.","ro":"Vangi aṭṭai oru vārattil tapālil varum."},{"fr":"Je peux aussi payer avec mon téléphone dans les magasins.","tgt":"கடைகளில் என் போனிலிருந்தும் பணம் செலுத்தலாம்.","ro":"Kaḍaigaḷil eṉ pōṉilirundum paṇam cheluttalām."},{"fr":"Les frais mensuels sont très faibles.","tgt":"மாதாந்திர கட்டணம் மிகவும் குறைவு.","ro":"Mādāndira kaṭṭaṇam migavum kuṛaivu."},{"fr":"Il faut garder un solde minimum de cinq mille roupies.","tgt":"குறைந்தபட்சம் ஐயாயிரம் ரூபாய் இருப்பு வைத்திருக்க வேண்டும்.","ro":"Kuṛaindapaṭcham aiyāyiram rūpāy iruppu vaittirukka vēṇḍum."},{"fr":"Tout était prêt en moins d'une heure.","tgt":"ஒரு மணி நேரத்துக்குள் எல்லாம் தயாராகிவிட்டது.","ro":"Oru maṇi nērattukkuḷ ellām tayārāgiviṭṭadu."}]},{"title":"Le déjeuner à la cantine","phrases":[{"fr":"À la cantine, on sert les repas sur feuille de bananier.","tgt":"கேண்டீனில் வாழை இலையில் சாப்பாடு பரிமாறுகிறார்கள்.","ro":"Kēṇḍīṉil vāḻai ilaiyil chāppāḍu parimāṛugiṛārgaḷ."},{"fr":"On commence par le riz avec le sambar.","tgt":"முதலில் சாம்பாருடன் சாதம் சாப்பிடுவோம்.","ro":"Mudalil chāmbāruḍaṉ chādam chāppiḍuvōm."},{"fr":"Ensuite vient le rasam, puis le yaourt.","tgt":"அதன் பிறகு ரசம், பிறகு தயிர்.","ro":"Adaṉ piṛagu racham, piṛagu tayir."},{"fr":"Le serveur repasse sans arrêt pour resservir.","tgt":"பரிமாறுபவர் மீண்டும் மீண்டும் வந்து பரிமாறுகிறார்.","ro":"Parimāṛupavar mīṇḍum mīṇḍum vandu parimāṛugiṛār."},{"fr":"Ici, on mange avec la main droite.","tgt":"இங்கே வலது கையால் சாப்பிடுவார்கள்.","ro":"Ingē valadu kaiyāl chāppiḍuvārgaḷ."},{"fr":"À la fin, on replie la feuille vers soi pour dire que c'était bon.","tgt":"முடிவில் சாப்பாடு நன்றாக இருந்தது என்று காட்ட இலையை நம் பக்கம் மடிப்போம்.","ro":"Muḍivil chāppāḍu naṉṛāga irundadu eṉṛu kāṭṭa ilaiyai nam pakkam maḍippōm."},{"fr":"Le repas complet coûte cent vingt roupies.","tgt":"முழு சாப்பாடு நூற்றிருபது ரூபாய்.","ro":"Muḻu chāppāḍu nūṛṛirubadu rūpāy."},{"fr":"Mes collègues me conseillent de goûter le poriyal au chou.","tgt":"கோஸ் பொரியலை சுவைத்து பார்க்கும்படி சக ஊழியர்கள் சொல்கிறார்கள்.","ro":"Kōs poriyalai chuvaittu pārkkumbaḍi chaga ūḻiyargaḷ cholgiṛārgaḷ."},{"fr":"Après le repas, un café filtre réveille tout le monde.","tgt":"சாப்பாட்டுக்கு பிறகு ஒரு ஃபில்டர் காபி எல்லோரையும் சுறுசுறுப்பாக்குகிறது.","ro":"Chāppāṭṭukku piṛagu oru filṭar kāpi ellōraiyum chuṛuchuṛuppākkugiṛadu."},{"fr":"Ma pause préférée de la journée, c'est ce déjeuner.","tgt":"நாளில் எனக்கு மிகவும் பிடித்த நேரம் இந்த மதிய சாப்பாட்டு நேரம்தான்.","ro":"Nāḷil eṉakku migavum piḍitta nēram inda madiya chāppāṭṭu nēramdāṉ."}]},{"title":"Le gardien et les voisins","phrases":[{"fr":"Le gardien de notre immeuble s'appelle Selvam.","tgt":"எங்கள் குடியிருப்பின் காவலாளி பெயர் செல்வம்.","ro":"Engaḷ kuḍiyiruppiṉ kāvalāḷi peyar chelvam."},{"fr":"Il connaît tous les habitants et toutes leurs habitudes.","tgt":"அவருக்கு எல்லா குடியிருப்பாளர்களையும் அவர்களின் பழக்கங்களையும் தெரியும்.","ro":"Avarukku ellā kuḍiyiruppāḷargaḷaiyum avargaḷiṉ paḻakkangaḷaiyum teriyum."},{"fr":"C'est lui qui reçoit nos colis quand nous sommes absents.","tgt":"நாங்கள் இல்லாதபோது எங்கள் பார்சல்களை அவர்தான் வாங்கி வைக்கிறார்.","ro":"Nāngaḷ illādapōdu engaḷ pārchalgaḷai avardāṉ vāngi vaikkiṛār."},{"fr":"Chaque matin, il met la pompe en marche pour remplir le réservoir du toit.","tgt":"ஒவ்வொரு காலையும் மோட்டார் போட்டு மாடி தொட்டியில் தண்ணீர் ஏற்றுகிறார்.","ro":"Ovvoru kālaiyum mōṭṭār pōṭṭu māḍi toṭṭiyil taṇṇīr ēṛṛugiṛār."},{"fr":"Notre voisine du dessus nous apporte souvent des sucreries.","tgt":"மேல் வீட்டு பெண்மணி அடிக்கடி எங்களுக்கு இனிப்புகள் கொண்டுவருகிறார்.","ro":"Mēl vīṭṭu peṇmaṇi aḍikkaḍi engaḷukku iṉippugaḷ koṇḍuvarugiṛār."},{"fr":"En retour, nous lui offrons parfois des biscuits français.","tgt":"பதிலுக்கு நாங்களும் சில நேரம் பிரெஞ்சு பிஸ்கட்டுகள் கொடுக்கிறோம்.","ro":"Padilukku nāngaḷum chila nēram pirenchu piskaṭṭugaḷ koḍukkiṛōm."},{"fr":"Le dimanche, les enfants jouent au cricket dans la cour.","tgt":"ஞாயிற்றுக்கிழமைகளில் குழந்தைகள் முற்றத்தில் கிரிக்கெட் விளையாடுகிறார்கள்.","ro":"Nyāyiṛṛukkiḻamaigaḷil kuḻandaigaḷ muṛṛattil kirikkeṭ viḷaiyāḍugiṛārgaḷ."},{"fr":"Les voisins se réunissent une fois par mois pour l'entretien.","tgt":"பராமரிப்பு பற்றி பேச அண்டை வீட்டார் மாதம் ஒரு முறை கூடுகிறார்கள்.","ro":"Parāmarippu paṛṛi pēcha aṇḍai vīṭṭār mādam oru muṛai kūḍugiṛārgaḷ."},{"fr":"Cette fois, nous avons décidé de faire repeindre l'escalier.","tgt":"இந்த முறை படிக்கட்டுகளுக்கு மீண்டும் வர்ணம் பூச ஏற்பாடு செய்ய முடிவெடுத்தோம்.","ro":"Inda muṛai paḍikkaṭṭugaḷukku mīṇḍum varṇam pūcha ēṛpāḍu cheyya muḍiveḍuttōm."},{"fr":"Ici, on ne se sent jamais seul.","tgt":"இங்கே ஒருபோதும் தனிமையாக உணர்வதில்லை.","ro":"Ingē orupōdum taṉimaiyāga uṇarvadillai."}]},{"title":"Le manque d'eau et le camion-citerne","phrases":[{"fr":"En été, l'eau manque souvent dans notre quartier.","tgt":"கோடையில் எங்கள் பகுதியில் அடிக்கடி தண்ணீர் பற்றாக்குறை ஏற்படுகிறது.","ro":"Kōḍaiyil engaḷ pagudiyil aḍikkaḍi taṇṇīr paṛṛākkuṛai ēṛpaḍugiṛadu."},{"fr":"Nous faisons alors venir un camion-citerne.","tgt":"அப்போது நாங்கள் ஒரு தண்ணீர் லாரியை வரவழைக்கிறோம்.","ro":"Appōdu nāngaḷ oru taṇṇīr lāriyai varavaḻaikkiṛōm."},{"fr":"Un camion de douze mille litres coûte environ deux mille roupies.","tgt":"பன்னிரண்டாயிரம் லிட்டர் லாரிக்கு சுமார் இரண்டாயிரம் ரூபாய் ஆகும்.","ro":"Paṉṉiraṇḍāyiram liṭṭar lārikku chumār iraṇḍāyiram rūpāy āgum."},{"fr":"Le chauffeur arrive souvent avec deux heures de retard.","tgt":"ஓட்டுநர் பெரும்பாலும் இரண்டு மணி நேரம் தாமதமாக வருகிறார்.","ro":"Ōṭṭunar perumbālum iraṇḍu maṇi nēram tāmadamāga varugiṛār."},{"fr":"En attendant, on économise chaque seau d'eau.","tgt":"அதுவரை ஒவ்வொரு வாளி தண்ணீரையும் சிக்கனமாக பயன்படுத்துகிறோம்.","ro":"Aduvarai ovvoru vāḷi taṇṇīraiyum chikkaṉamāga payaṉbaḍuttugiṛōm."},{"fr":"Les voisins s'organisent pour partager les frais.","tgt":"செலவை பகிர்ந்துகொள்ள அண்டை வீட்டார் ஏற்பாடு செய்கிறார்கள்.","ro":"Chelavai pagirndukoḷḷa aṇḍai vīṭṭār ēṛpāḍu cheygiṛārgaḷ."},{"fr":"Pendant la mousson, c'est l'inverse : il y a trop d'eau.","tgt":"பருவமழை காலத்தில் நிலைமை தலைகீழ், தண்ணீர் அதிகமாகிவிடுகிறது.","ro":"Paruvamaḻai kālattil nilaimai talaigīḻ, taṇṇīr adigamāgiviḍugiṛadu."},{"fr":"Beaucoup d'immeubles récupèrent maintenant l'eau de pluie.","tgt":"இப்போது பல குடியிருப்புகள் மழைநீரை சேகரிக்கின்றன.","ro":"Ippōdu pala kuḍiyiruppugaḷ maḻainīrai chēgarikkiṉṛaṉa."},{"fr":"Cette eau est filtrée puis stockée sous terre.","tgt":"இந்த நீர் வடிகட்டப்பட்டு நிலத்தடியில் சேமிக்கப்படுகிறது.","ro":"Inda nīr vaḍigaṭṭappaṭṭu nilattaḍiyil chēmikkappaḍugiṛadu."},{"fr":"J'ai appris à ne jamais gaspiller une goutte.","tgt":"ஒரு சொட்டு கூட வீணாக்கக்கூடாது என்று கற்றுக்கொண்டேன்.","ro":"Oru choṭṭu kūḍa vīṇākkakkūḍādu eṉṛu kaṛṛukkoṇḍēṉ."}]},{"title":"Accueillir un collègue français","phrases":[{"fr":"Un collègue de Lyon arrive à Chennai lundi prochain.","tgt":"லியோனிலிருந்து ஒரு சக ஊழியர் அடுத்த திங்கள்கிழமை சென்னைக்கு வருகிறார்.","ro":"Liyōṉilirundu oru chaga ūḻiyar aḍutta tingaḷkiḻamai cheṉṉaikku varugiṛār."},{"fr":"C'est son tout premier voyage en Inde.","tgt":"இது அவருடைய முதல் இந்திய பயணம்.","ro":"Idu avaruḍaiya mudal indiya payaṇam."},{"fr":"J'irai moi-même le chercher à l'aéroport.","tgt":"நானே விமான நிலையத்துக்கு சென்று அவரை அழைத்து வருவேன்.","ro":"Nāṉē vimāṉa nilaiyattukku cheṉṛu avarai aḻaittu varuvēṉ."},{"fr":"Je lui ai conseillé d'apporter des vêtements légers.","tgt":"லேசான ஆடைகளை கொண்டுவரும்படி அவருக்கு அறிவுறுத்தினேன்.","ro":"Lēchāṉa āḍaigaḷai koṇḍuvarumbaḍi avarukku aṛivuṛuttiṉēṉ."},{"fr":"Il logera dans un hôtel près du bureau.","tgt":"அவர் அலுவலகத்துக்கு அருகில் உள்ள ஒரு விடுதியில் தங்குவார்.","ro":"Avar aluvalagattukku arugil uḷḷa oru viḍudiyil tanguvār."},{"fr":"Le premier soir, je l'emmènerai manger des dosas.","tgt":"முதல் நாள் இரவு அவரை தோசை சாப்பிட அழைத்து செல்வேன்.","ro":"Mudal nāḷ iravu avarai tōchai chāppiḍa aḻaittu chelvēṉ."},{"fr":"Je lui apprendrai quelques mots de tamoul bien utiles.","tgt":"பயனுள்ள சில தமிழ் சொற்களை அவருக்கு கற்றுத்தருவேன்.","ro":"Payaṉuḷḷa chila tamiḻ choṛkaḷai avarukku kaṛṛuttaruvēṉ."},{"fr":"Il s'inquiète un peu de la chaleur et de la circulation.","tgt":"வெப்பத்தையும் போக்குவரத்தையும் நினைத்து அவர் கொஞ்சம் கவலைப்படுகிறார்.","ro":"Veppattaiyum pōkkuvarattaiyum niṉaittu avar koncham kavalaippaḍugiṛār."},{"fr":"Je lui ai dit qu'on s'y habitue vite.","tgt":"விரைவில் பழகிவிடும் என்று அவரிடம் சொன்னேன்.","ro":"Viraivil paḻagiviḍum eṉṛu avariḍam choṉṉēṉ."},{"fr":"Le week-end, nous irons voir les sculptures de Mahabalipuram.","tgt":"வார இறுதியில் மாமல்லபுரத்து சிற்பங்களை பார்க்க போவோம்.","ro":"Vāra iṛudiyil māmallapurattu chiṛpangaḷai pārkka pōvōm."}]},{"title":"Un dimanche à la plage de Marina","phrases":[{"fr":"Le dimanche, je me lève sans réveil.","tgt":"ஞாயிற்றுக்கிழமை அலாரம் இல்லாமல் எழுந்திருக்கிறேன்.","ro":"Nyāyiṛṛukkiḻamai alāram illāmal eḻundirukkiṛēṉ."},{"fr":"Je prends un petit-déjeuner tranquille avec des idlis.","tgt":"அமைதியாக இட்லியுடன் காலை உணவு சாப்பிடுகிறேன்.","ro":"Amaidiyāga iṭliyuḍaṉ kālai uṇavu chāppiḍugiṛēṉ."},{"fr":"En fin d'après-midi, nous allons marcher sur la plage de Marina.","tgt":"மாலையில் மெரினா கடற்கரையில் நடக்க போகிறோம்.","ro":"Mālaiyil meriṉā kaḍaṛkaraiyil naḍakka pōgiṛōm."},{"fr":"La brise de mer fait du bien après une semaine chargée.","tgt":"பரபரப்பான வாரத்துக்கு பிறகு கடல் காற்று இதமாக இருக்கிறது.","ro":"Paraparappāṉa vārattukku piṛagu kaḍal kāṛṛu idamāga irukkiṛadu."},{"fr":"Des familles entières se retrouvent sur le sable.","tgt":"குடும்பம் குடும்பமாக மக்கள் மணலில் கூடுகிறார்கள்.","ro":"Kuḍumbam kuḍumbamāga makkaḷ maṇalil kūḍugiṛārgaḷ."},{"fr":"Nous achetons du sundal, des pois chiches épicés vendus sur la plage.","tgt":"கடற்கரையில் விற்கப்படும் காரமான சுண்டல் வாங்குகிறோம்.","ro":"Kaḍaṛkaraiyil viṛkappaḍum kāramāṉa chuṇḍal vāngugiṛōm."},{"fr":"Même le dimanche, la circulation reste dense le soir.","tgt":"ஞாயிற்றுக்கிழமை கூட மாலையில் போக்குவரத்து அதிகமாகவே இருக்கிறது.","ro":"Nyāyiṛṛukkiḻamai kūḍa mālaiyil pōkkuvarattu adigamāgavē irukkiṛadu."},{"fr":"Nous rentrons en métro pour éviter les bouchons.","tgt":"நெரிசலை தவிர்க்க மெட்ரோவில் திரும்புகிறோம்.","ro":"Nerichalai tavirkka meṭrōvil tirumbugiṛōm."},{"fr":"Le soir, je prépare mes affaires pour la semaine.","tgt":"இரவில் அடுத்த வாரத்துக்கான பொருட்களை தயார் செய்கிறேன்.","ro":"Iravil aḍutta vārattukkāṉa poruṭkaḷai tayār cheygiṛēṉ."},{"fr":"Ces petits moments rendent la vie à Chennai très douce.","tgt":"இந்த சிறு தருணங்கள் சென்னை வாழ்க்கையை மிகவும் இனிமையாக்குகின்றன.","ro":"Inda chiṛu taruṇangaḷ cheṉṉai vāḻkkaiyai migavum iṉimaiyākkugiṉṛaṉa."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir la vie professionnelle à Chennai.","tgt":"இந்த பாடப்பிரிவு சென்னையின் வேலை வாழ்க்கையை நமக்கு அறிமுகப்படுத்தியது.","ro":"Inda pāḍappirivu cheṉṉaiyiṉ vēlai vāḻkkaiyai namakku aṛimugappaḍuttiyadu."},{"fr":"Nous savons maintenant parler d'un contrat ou d'un loyer.","tgt":"இப்போது ஒப்பந்தம் அல்லது வாடகை பற்றி நம்மால் பேச முடியும்.","ro":"Ippōdu oppandam alladu vāḍagai paṛṛi nammāl pēcha muḍiyum."},{"fr":"Le passif avec « paḍu » nous semble désormais facile.","tgt":"படு வைத்து அமைக்கும் செயப்பாட்டு வினை இப்போது நமக்கு எளிது.","ro":"Paḍu vaittu amaikkum cheyappāṭṭu viṉai ippōdu namakku eḷidu."},{"fr":"Nous savons dire comment faire faire quelque chose à quelqu'un.","tgt":"ஒருவரை ஏதாவது செய்ய வைப்பது எப்படி என்று நமக்கு தெரியும்.","ro":"Oruvarai ēdāvadu cheyya vaippadu eppaḍi eṉṛu namakku teriyum."},{"fr":"Les formules polies du bureau nous seront très utiles.","tgt":"அலுவலக மரியாதை சொற்கள் நமக்கு மிகவும் பயன்படும்.","ro":"Aluvalaga mariyādai choṛkaḷ namakku migavum payaṉbaḍum."},{"fr":"Même les phrases longues nous font moins peur maintenant.","tgt":"நீண்ட வாக்கியங்கள் கூட இப்போது நம்மை அவ்வளவாக பயமுறுத்துவதில்லை.","ro":"Nīṇḍa vākkiyangaḷ kūḍa ippōdu nammai avvaḷavāga payamuṛuttuvadillai."},{"fr":"Le tamoul devient peu à peu une langue de tous les jours.","tgt":"தமிழ் மெல்ல மெல்ல அன்றாட மொழியாக மாறுகிறது.","ro":"Tamiḻ mella mella aṉṛāḍa moḻiyāga māṛugiṛadu."},{"fr":"Le module suivant nous fera voyager à travers le Tamil Nadu.","tgt":"அடுத்த பாடப்பிரிவு நம்மை தமிழ்நாடு முழுவதும் பயணிக்க வைக்கும்.","ro":"Aḍutta pāḍappirivu nammai tamiḻnāḍu muḻuvadum payaṇikka vaikkum."},{"fr":"Prenons quelques jours pour réécouter les leçons.","tgt":"பாடங்களை மீண்டும் கேட்க சில நாட்கள் எடுத்துக்கொள்வோம்.","ro":"Pāḍangaḷai mīṇḍum kēṭka chila nāṭkaḷ eḍuttukkoḷvōm."},{"fr":"Bravo, et à très bientôt pour la suite.","tgt":"பாராட்டுகள், விரைவில் மீண்டும் சந்திப்போம்.","ro":"Pārāṭṭugaḷ, viraivil mīṇḍum chandippōm."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée dans le delta de la Kaveri","phrases":[{"fr":"Le train de nuit nous a déposés à Thanjavur à l'aube.","tgt":"இரவு ரயில் எங்களை அதிகாலையில் தஞ்சாவூரில் இறக்கிவிட்டது.","ro":"Iravu rayil engaḷai adikālaiyil Tanjāvūril iṛakkiviṭṭadu."},{"fr":"Le delta de la Kaveri est surnommé le grenier à riz du Tamil Nadu.","tgt":"காவேரி டெல்டா தமிழ்நாட்டின் நெற்களஞ்சியம் என்று அழைக்கப்படுகிறது.","ro":"Kāvēri ṭelṭā Tamiḻnāṭṭiṉ neṛkaḷanjiyam eṉṛu aḻaikkappaḍugiṛadu."},{"fr":"Notre chambre donne sur une rue calme, loin du bruit de la gare.","tgt":"எங்கள் அறை ரயில் நிலையத்தின் சத்தத்திலிருந்து தள்ளி, ஒரு அமைதியான தெருவைப் பார்த்தபடி உள்ளது.","ro":"Engaḷ aṛai rayil nilaiyattiṉ chattattilirundu taḷḷi, oru amaidiyāṉa teruvaip pārttabaḍi uḷḷadu."},{"fr":"Ici, le rythme de vie paraît beaucoup plus lent qu'à Chennai.","tgt":"இங்கே வாழ்க்கையின் வேகம் சென்னையை விட மிகவும் மெதுவாகத் தெரிகிறது.","ro":"Ingē vāḻkkaiyiṉ vēgam Cheṉṉaiyai viṭa migavum meduvāgat terigiṛadu."},{"fr":"Dans ces petites rues, les vélos sont plus nombreux que les voitures.","tgt":"இந்தச் சிறிய தெருக்களில் கார்களை விட சைக்கிள்கள் அதிகம்.","ro":"Indach chiṛiya terukkaḷil kārgaḷai viṭa chaikkiḷgaḷ adigam."},{"fr":"Le chauffeur de rickshaw connaissait déjà le nom de notre pension.","tgt":"ஆட்டோ ஓட்டுநருக்கு எங்கள் விடுதியின் பெயர் ஏற்கனவே தெரிந்திருந்தது.","ro":"Āṭṭō ōṭṭunarukku engaḷ viḍudiyiṉ peyar ēṛkaṉavē terindirundadu."},{"fr":"Le matin, l'air sent la terre mouillée et le riz qui cuit.","tgt":"காலையில் காற்றில் ஈர மண்ணின் வாசமும் வேகும் சோற்றின் வாசமும் கலந்திருக்கிறது.","ro":"Kālaiyil kāṛṛil īra maṇṇiṉ vāchamum vēgum chōṛṛiṉ vāchamum kalandirukkiṛadu."},{"fr":"On a bu un café filtre debout dans une petite échoppe.","tgt":"ஒரு சிறிய கடையில் நின்றபடி ஒரு ஃபில்டர் காபி குடித்தோம்.","ro":"Oru chiṛiya kaḍaiyil niṉṛabaḍi oru filṭar kāpi kuḍittōm."},{"fr":"Le patron nous a conseillé d'aller au palais dès l'ouverture.","tgt":"அரண்மனை திறந்தவுடனே போய்ப் பார்க்கும்படி கடை உரிமையாளர் எங்களுக்கு அறிவுரை சொன்னார்.","ro":"Araṇmaṉai tiṛandavuḍaṉē pōyp pārkkumbaḍi kaḍai urimaiyāḷar engaḷukku aṛivurai choṉṉār."},{"fr":"Cette première journée dans le delta nous a tout de suite mis à l'aise.","tgt":"டெல்டாவில் இந்த முதல் நாளே எங்களை உடனே நிம்மதியாக உணர வைத்தது.","ro":"Ṭelṭāvil inda mudal nāḷē engaḷai uḍaṉē nimmadiyāga uṇara vaittadu."}]},{"title":"Le grand palais de Thanjavur","phrases":[{"fr":"Le palais que nous avons visité ce matin est immense.","tgt":"இன்று காலை நாங்கள் பார்த்த அரண்மனை மிகப் பெரியது.","ro":"Iṉṛu kālai nāngaḷ pārtta araṇmaṉai migap periyadu."},{"fr":"Les rois qui vivaient ici aimaient profondément la musique et les arts.","tgt":"இங்கே வாழ்ந்த அரசர்கள் இசையையும் கலைகளையும் மிகவும் நேசித்தார்கள்.","ro":"Ingē vāḻnda arachargaḷ ichaiyaiyum kalaigaḷaiyum migavum nēchittārgaḷ."},{"fr":"La haute tour que vous voyez là-bas servait autrefois à monter la garde.","tgt":"அங்கே நீங்கள் பார்க்கும் உயரமான கோபுரம் முன்பு காவலுக்காகப் பயன்பட்டது.","ro":"Angē nīngaḷ pārkkum uyaramāṉa kōburam muṉbu kāvalukkāgap payaṉbaṭṭadu."},{"fr":"Les peintures exposées dans cette salle ont plus de deux cents ans.","tgt":"இந்த அறையில் வைக்கப்பட்டுள்ள ஓவியங்கள் இருநூறு ஆண்டுகளுக்கும் மேல் பழமையானவை.","ro":"Inda aṛaiyil vaikkappaṭṭuḷḷa ōviyangaḷ irunūṛu āṇḍugaḷukkum mēl paḻamaiyāṉavai."},{"fr":"Le guide qui nous accompagnait connaissait chaque détail de l'histoire.","tgt":"எங்களுடன் வந்த வழிகாட்டிக்கு வரலாற்றின் ஒவ்வொரு விவரமும் தெரிந்திருந்தது.","ro":"Engaḷuḍaṉ vanda vaḻikāṭṭikku varalāṛṛiṉ ovvoru vivaramum terindirundadu."},{"fr":"La salle où se réunissait la cour royale est encore bien conservée.","tgt":"அரசவை கூடிய மண்டபம் இன்னும் நன்றாகப் பாதுகாக்கப்பட்டுள்ளது.","ro":"Arachavai kūḍiya maṇḍabam iṉṉum naṉṛāgap pādukākkappaṭṭuḷḷadu."},{"fr":"Voici enfin la ville dont j'ai tant entendu parler.","tgt":"நான் இவ்வளவு கேள்விப்பட்ட ஊர் இதுதான்.","ro":"Nāṉ ivvaḷavu kēḷvippaṭṭa ūr idutāṉ."},{"fr":"Les fenêtres qui donnent sur la cour laissent entrer une lumière douce.","tgt":"முற்றத்தைப் பார்த்தபடி இருக்கும் ஜன்னல்கள் மென்மையான வெளிச்சத்தை உள்ளே விடுகின்றன.","ro":"Muṛṛattaip pārttabaḍi irukkum jaṉṉalgaḷ meṉmaiyāṉa veḷichchattai uḷḷē viḍugiṉṛaṉa."},{"fr":"Le gardien qui ouvre les portes arrive chaque jour à neuf heures.","tgt":"கதவுகளைத் திறக்கும் காவலாளி தினமும் ஒன்பது மணிக்கு வருகிறார்.","ro":"Kadavugaḷait tiṛakkum kāvalāḷi tiṉamum oṉbadu maṇikku varugiṛār."},{"fr":"Tout ce que nous avons vu aujourd'hui restera dans nos mémoires.","tgt":"இன்று நாங்கள் பார்த்தவை எல்லாம் என்றும் எங்கள் நினைவில் இருக்கும்.","ro":"Iṉṛu nāngaḷ pārttavai ellām eṉṛum engaḷ niṉaivil irukkum."}],"tip":{"title":"Les relatives : le participe avant le nom, « nāṉ pārtta ūr »","example":"Le palais que nous avons visité ce matin est immense. — இன்று காலை நாங்கள் <b>பார்த்த</b> அரண்மனை மிகப் பெரியது.","body":"En tamoul, il n'existe pas de petit mot « que » ou « qui » pour relier une phrase à un nom. On met le verbe sous une forme spéciale, le participe, et on le place juste avant le nom : « nāṉ pārtta ūr », mot à mot « moi vu ville », c'est la ville que j'ai vue. Au passé, ce participe se termine par « -a » : « pārtta », vu, « vanda », venu, « vāḻnda », qui a vécu. Au présent, il se termine par « -um » : « kadavugaḷait tiṛakkum kāvalāḷi », le gardien qui ouvre les portes. Le français dit d'abord le nom puis le décrit ; le tamoul décrit d'abord, et le nom arrive à la fin comme une conclusion. Astuce : à l'oral, faites une petite pause après le nom, jamais entre le participe et lui, car ils forment un seul bloc.","exampleRo":"Iṉṛu kālai nāngaḷ pārtta araṇmaṉai migap periyadu.","lit":"aujourd'hui · matin · nous · vu [qui] · palais · très · grand","say":{"nāṉ pārtta ūr":"நான் பார்த்த ஊர்","pārtta":"பார்த்த","vanda":"வந்த","vāḻnda":"வாழ்ந்த","kadavugaḷait tiṛakkum kāvalāḷi":"கதவுகளைத் திறக்கும் காவலாளி"}}},{"title":"La bibliothèque du palais","phrases":[{"fr":"La bibliothèque du palais conserve des milliers de manuscrits anciens.","tgt":"அரண்மனை நூலகம் ஆயிரக்கணக்கான பழைய கையெழுத்துப் பிரதிகளைப் பாதுகாக்கிறது.","ro":"Araṇmaṉai nūlagam āyirakkaṇakkāṉa paḻaiya kaiyeḻuttup piradigaḷaip pādukākkiṛadu."},{"fr":"Beaucoup de ces textes ont été écrits sur des feuilles de palmier.","tgt":"இவற்றில் பல நூல்கள் பனை ஓலைகளில் எழுதப்பட்டவை.","ro":"Ivaṛṛil pala nūlgaḷ paṉai ōlaigaḷil eḻudappaṭṭavai."},{"fr":"On y trouve des traités de médecine, d'astronomie et de musique.","tgt":"இங்கே மருத்துவம், வானியல், இசை பற்றிய நூல்கள் உள்ளன.","ro":"Ingē maruttuvam, vāṉiyal, ichai paṛṛiya nūlgaḷ uḷḷaṉa."},{"fr":"Il est interdit de toucher les manuscrits sans gants.","tgt":"கையுறை இல்லாமல் கையெழுத்துப் பிரதிகளைத் தொடக் கூடாது.","ro":"Kaiyuṛai illāmal kaiyeḻuttup piradigaḷait toḍak kūḍādu."},{"fr":"Une chercheuse nous a montré comment on restaure les feuilles abîmées.","tgt":"சேதமடைந்த ஓலைகளை எப்படிச் சீரமைக்கிறார்கள் என்று ஒரு ஆய்வாளர் எங்களுக்குக் காட்டினார்.","ro":"Chēdamaḍainda ōlaigaḷai eppaḍich chīramaikkiṛārgaḷ eṉṛu oru āyvāḷar engaḷukkuk kāṭṭiṉār."},{"fr":"Certaines feuilles sont si fragiles qu'on ne les sort presque jamais.","tgt":"சில ஓலைகள் எளிதில் உடையக்கூடியவை, அதனால் அவற்றை வெளியே எடுப்பதே அரிது.","ro":"Chila ōlaigaḷ eḷidil uḍaiyakkūḍiyavai, adaṉāl avaṛṛai veḷiyē eḍuppadē aridu."},{"fr":"Les documents les plus anciens ont tous été numérisés.","tgt":"மிகப் பழைய ஆவணங்கள் எல்லாம் கணினியில் பதிவு செய்யப்பட்டுள்ளன.","ro":"Migap paḻaiya āvaṇangaḷ ellām kaṇiṉiyil padivu cheyyappaṭṭuḷḷaṉa."},{"fr":"Le silence de la salle de lecture a quelque chose d'impressionnant.","tgt":"வாசிப்பு அறையின் அமைதி வியக்க வைக்கிறது.","ro":"Vāchippu aṛaiyiṉ amaidi viyakka vaikkiṛadu."},{"fr":"Je n'aurais jamais imaginé trouver un tel trésor ici.","tgt":"இப்படி ஒரு பொக்கிஷத்தை இங்கே பார்ப்பேன் என்று நான் நினைக்கவே இல்லை.","ro":"Ippaḍi oru pokkishattai ingē pārppēṉ eṉṛu nāṉ niṉaikkavē illai."},{"fr":"Le musée voisin expose quelques pages traduites en tamoul moderne.","tgt":"பக்கத்து அருங்காட்சியகத்தில் இன்றைய தமிழில் மொழிபெயர்க்கப்பட்ட சில பக்கங்கள் வைக்கப்பட்டுள்ளன.","ro":"Pakkattu arungāṭchiyagattil iṉṛaiya Tamiḻil moḻipeyarkkappaṭṭa chila pakkangaḷ vaikkappaṭṭuḷḷaṉa."}]},{"title":"L'atelier des poupées de Thanjavur","phrases":[{"fr":"Nous sommes venus dans cet atelier pour voir les célèbres poupées qui dodelinent de la tête.","tgt":"புகழ்பெற்ற தலையாட்டி பொம்மைகளைப் பார்ப்பதற்காக இந்தப் பட்டறைக்கு வந்தோம்.","ro":"Pugaḻbeṛṛa talaiyāṭṭi pommaigaḷaip pārppadaṛkāga indap paṭṭaṛaikku vandōm."},{"fr":"Ces poupées ne sont pas faites seulement pour les enfants, mais aussi pour les adultes.","tgt":"இந்தப் பொம்மைகள் குழந்தைகளுக்காக மட்டுமல்ல, பெரியவர்களுக்காகவும் செய்யப்படுகின்றன.","ro":"Indap pommaigaḷ kuḻandaigaḷukkāga maṭṭumalla, periyavargaḷukkāgavum cheyyappaḍugiṉṛaṉa."},{"fr":"Pour façonner la base, l'artisan utilise de l'argile de la Kaveri.","tgt":"அடிப்பகுதியைச் செய்வதற்காக, பொம்மை செய்பவர் காவேரி ஆற்றுக் களிமண்ணைப் பயன்படுத்துகிறார்.","ro":"Aḍippagudiyaich cheyvadaṛkāga, pommai cheybavar Kāvēri āṛṛuk kaḷimaṇṇaip payaṉbaḍuttugiṛār."},{"fr":"Le poids est placé en bas pour que la poupée se redresse toujours.","tgt":"பொம்மை எப்போதும் மீண்டும் எழுந்து நிற்பதற்காக எடை அடியில் வைக்கப்படுகிறது.","ro":"Pommai eppōdum mīṇḍum eḻundu niṛpadaṛkāga eḍai aḍiyil vaikkappaḍugiṛadu."},{"fr":"Nous en avons acheté une pour ma nièce, qui vit à Paris.","tgt":"பாரிஸில் இருக்கும் என் அண்ணன் மகளுக்காக ஒன்று வாங்கினோம்.","ro":"Pārisil irukkum eṉ aṇṇaṉ magaḷukkāga oṉṛu vāngiṉōm."},{"fr":"Il faut environ une semaine pour fabriquer et peindre une seule poupée.","tgt":"ஒரு பொம்மையைச் செய்து வண்ணம் தீட்ட சுமார் ஒரு வாரம் ஆகும்.","ro":"Oru pommaiyaich cheydu vaṇṇam tīṭṭa chumār oru vāram āgum."},{"fr":"Les couleurs vives sont choisies pour attirer le regard des passants.","tgt":"வழிப்போக்கர்களின் கவனத்தை ஈர்ப்பதற்காகப் பளிச்சென்ற வண்ணங்கள் தேர்ந்தெடுக்கப்படுகின்றன.","ro":"Vaḻippōkkargaḷiṉ kavaṉattai īrppadaṛkāgap paḷichcheṉṛa vaṇṇangaḷ tērndeḍukkappaḍugiṉṛaṉa."},{"fr":"Pour la transporter en avion, il vaut mieux bien l'emballer.","tgt":"விமானத்தில் எடுத்துச் செல்வதற்காக, பொம்மையை நன்றாகச் சுற்றிக் கட்டுவது நல்லது.","ro":"Vimāṉattil eḍuttuch chelvadaṛkāga, pommaiyai naṉṛāgach chuṛṛik kaṭṭuvadu nalladu."},{"fr":"Pour faire vivre cette tradition, il travaille ici depuis trente ans.","tgt":"இந்தப் பாரம்பரியத்தை உயிரோடு வைத்திருப்பதற்காக அவர் முப்பது ஆண்டுகளாக இங்கே வேலை செய்கிறார்.","ro":"Indap pārambariyattai uyirōḍu vaittiruppadaṛkāga avar muppadu āṇḍugaḷāga ingē vēlai cheygiṛār."},{"fr":"Pour nous remercier de notre visite, il nous a offert une petite poupée.","tgt":"நாங்கள் வந்ததற்கு நன்றி சொல்வதற்காக அவர் எங்களுக்கு ஒரு சிறிய பொம்மையைப் பரிசாகக் கொடுத்தார்.","ro":"Nāngaḷ vandadaṛku naṉṛi cholvadaṛkāga avar engaḷukku oru chiṛiya pommaiyaip parichāgak koḍuttār."}],"tip":{"title":"« -ukkāga » et « -adaṛkāga » : pour, afin de","example":"Nous en avons acheté une pour ma nièce, qui vit à Paris. — பாரிஸில் இருக்கும் என் அண்ணன் <b>மகளுக்காக</b> ஒன்று வாங்கினோம்.","body":"Pour dire « pour quelqu'un » ou « dans le but de », le tamoul colle une terminaison à la fin du mot, au lieu de mettre un petit mot devant comme en français. Après un nom, on ajoute « -ukkāga » : « magaḷukkāga », pour ma fille ou ma nièce, « ungaḷukkāga », pour vous. Décomposons : « magaḷ », fille, puis « -ukku », à, puis « -āga », en tant que, soit littéralement « fille-à-en-tant-que ». Après un verbe, on le transforme d'abord en nom d'action en « -adu », puis on ajoute « -aṛkāga » : « pārppadu », le fait de voir, devient « pārppadaṛkāga », pour voir. Ce bloc se place avant le verbe principal, qui reste à la fin de la phrase. Astuce : entendez « kāga » comme l'étiquette d'un cadeau, elle dit pour qui ou pour quoi on agit.","exampleRo":"Pārisil irukkum eṉ aṇṇaṉ magaḷukkāga oṉṛu vāngiṉōm.","lit":"Paris [dans] · étant [qui] · mon · grand frère · fille [pour] · une · avons acheté","say":{"magaḷukkāga":"மகளுக்காக","ungaḷukkāga":"உங்களுக்காக","magaḷ":"மகள்","pārppadu":"பார்ப்பது","pārppadaṛkāga":"பார்ப்பதற்காக"}}},{"title":"Chez un fabricant d'instruments","phrases":[{"fr":"Thanjavur est aussi réputée pour ses instruments de musique faits main.","tgt":"தஞ்சாவூர் கையால் செய்யப்படும் இசைக் கருவிகளுக்கும் பெயர் பெற்றது.","ro":"Tanjāvūr kaiyāl cheyyappaḍum ichaik karuvigaḷukkum peyar peṛṛadu."},{"fr":"Une vina est sculptée dans un seul bloc de bois de jacquier.","tgt":"ஒரு வீணை ஒரே பலா மரத் துண்டிலிருந்து செதுக்கப்படுகிறது.","ro":"Oru vīṇai orē palā marat tuṇḍilirundu chedukkappaḍugiṛadu."},{"fr":"Le luthier travaille lentement, sans jamais se presser.","tgt":"கருவி செய்பவர் அவசரப்படாமல் மெதுவாக வேலை செய்கிறார்.","ro":"Karuvi cheybavar avacharappaḍāmal meduvāga vēlai cheygiṛār."},{"fr":"Il faut plusieurs mois pour terminer un seul instrument.","tgt":"ஒரு கருவியை முடிக்கப் பல மாதங்கள் ஆகும்.","ro":"Oru karuviyai muḍikkap pala mādangaḷ āgum."},{"fr":"Il a joué quelques notes pour nous faire entendre le son.","tgt":"ஒலியை நாங்கள் கேட்கும்படி அவர் சில ஸ்வரங்களை வாசித்தார்.","ro":"Oliyai nāngaḷ kēṭkumbaḍi avar chila svarangaḷai vāchittār."},{"fr":"Le son est profond et résonne longtemps dans la pièce.","tgt":"அதன் ஒலி ஆழமானது, அறையில் நீண்ட நேரம் எதிரொலிக்கிறது.","ro":"Adaṉ oli āḻamāṉadu, aṛaiyil nīṇḍa nēram edirolikkiṛadu."},{"fr":"Son père et son grand-père exerçaient déjà ce même métier.","tgt":"அவருடைய அப்பாவும் தாத்தாவும் ஏற்கனவே இதே தொழிலைச் செய்தவர்கள்.","ro":"Avaruḍaiya appāvum tāttāvum ēṛkaṉavē idē toḻilaich cheydavargaḷ."},{"fr":"Aujourd'hui, peu de jeunes veulent apprendre cet art difficile.","tgt":"இன்று இந்தக் கடினமான கலையைக் கற்க விரும்பும் இளம் வயதினர் குறைவு.","ro":"Iṉṛu indak kaḍiṉamāṉa kalaiyaik kaṛka virumbum iḷam vayadiṉar kuṛaivu."},{"fr":"Un instrument comme celui-ci coûte des dizaines de milliers de roupies.","tgt":"இது போன்ற ஒரு கருவியின் விலை பல்லாயிரக்கணக்கான ரூபாய்.","ro":"Idu pōṉṛa oru karuviyiṉ vilai pallāyirakkaṇakkāṉa rūbāy."},{"fr":"Je repars avec un profond respect pour ces artisans.","tgt":"இந்தக் கைத்தொழிலாளர்கள் மீது ஆழ்ந்த மரியாதையோடு நான் கிளம்புகிறேன்.","ro":"Indak kaittoḻilāḷargaḷ mīdu āḻnda mariyādaiyōḍu nāṉ kiḷambugiṛēṉ."}]},{"title":"À vélo dans les rizières de la Kaveri","phrases":[{"fr":"Nous avons loué deux vélos pour traverser les rizières.","tgt":"வயல்களைக் கடந்து செல்ல இரண்டு சைக்கிள்களை வாடகைக்கு எடுத்தோம்.","ro":"Vayalgaḷaik kaḍandu chella iraṇḍu chaikkiḷgaḷai vāḍagaikku eḍuttōm."},{"fr":"À perte de vue, les champs sont d'un vert éclatant.","tgt":"கண்ணுக்கு எட்டிய தூரம் வரை வயல்கள் பளிச்சென்ற பச்சையாக இருக்கின்றன.","ro":"Kaṇṇukku eṭṭiya tūram varai vayalgaḷ paḷichcheṉṛa pachchaiyāga irukkiṉṛaṉa."},{"fr":"Des canaux étroits amènent l'eau du fleuve jusqu'aux parcelles.","tgt":"குறுகிய வாய்க்கால்கள் ஆற்று நீரை வயல்கள் வரை கொண்டு செல்கின்றன.","ro":"Kuṛugiya vāykkālgaḷ āṛṛu nīrai vayalgaḷ varai koṇḍu chelgiṉṛaṉa."},{"fr":"Les aigrettes blanches suivent les paysans dans la boue.","tgt":"வெள்ளைக் கொக்குகள் சேற்றில் விவசாயிகளைப் பின்தொடர்கின்றன.","ro":"Veḷḷaik kokkugaḷ chēṛṛil vivachāyigaḷaip piṉdoḍargiṉṛaṉa."},{"fr":"Le chemin de terre devient glissant après la pluie.","tgt":"மழைக்குப் பிறகு மண் பாதை வழுக்கலாகிவிடுகிறது.","ro":"Maḻaikkup piṛagu maṇ pādai vaḻukkalāgiviḍugiṛadu."},{"fr":"Un paysan nous a expliqué qu'on fait ici trois récoltes par an.","tgt":"இங்கே ஆண்டுக்கு மூன்று முறை அறுவடை செய்வதாக ஒரு விவசாயி எங்களுக்கு விளக்கினார்.","ro":"Ingē āṇḍukku mūṉṛu muṛai aṛuvaḍai cheyvadāga oru vivachāyi engaḷukku viḷakkiṉār."},{"fr":"Il nous a invités à nous asseoir à l'ombre d'un cocotier.","tgt":"ஒரு தென்னை மரத்தின் நிழலில் உட்காரும்படி அவர் எங்களை அழைத்தார்.","ro":"Oru teṉṉai marattiṉ niḻalil uṭkārumbaḍi avar engaḷai aḻaittār."},{"fr":"Sa femme nous a apporté de l'eau de coco bien fraîche.","tgt":"அவருடைய மனைவி எங்களுக்குக் குளிர்ந்த இளநீர் கொண்டு வந்தார்.","ro":"Avaruḍaiya maṉaivi engaḷukkuk kuḷirnda iḷanīr koṇḍu vandār."},{"fr":"Le niveau de la rivière dépend surtout de la mousson.","tgt":"ஆற்றின் நீர்மட்டம் பெரும்பாலும் பருவமழையைப் பொறுத்தது.","ro":"Āṛṛiṉ nīrmaṭṭam perumbālum paruvamaḻaiyaip poṛuttadu."},{"fr":"En rentrant, nous étions couverts de poussière mais ravis.","tgt":"திரும்பி வரும்போது நாங்கள் தூசியால் மூடப்பட்டிருந்தோம், ஆனாலும் மகிழ்ச்சியாக இருந்தோம்.","ro":"Tirumbi varumbōdu nāngaḷ tūchiyāl mūḍappaṭṭirundōm, āṉālum magiḻchchiyāga irundōm."}]},{"title":"Une journée de repiquage du riz","phrases":[{"fr":"Avant notre arrivée, les femmes avaient déjà repiqué tout un champ.","tgt":"நாங்கள் வருவதற்குள் பெண்கள் ஒரு வயல் முழுவதும் நாற்று நட்டுவிட்டார்கள்.","ro":"Nāngaḷ varuvadaṛkuḷ peṇgaḷ oru vayal muḻuvadum nāṛṛu naṭṭuviṭṭārgaḷ."},{"fr":"J'ai enlevé mes sandales et je suis descendu dans la boue.","tgt":"நான் செருப்பைக் கழற்றிவிட்டுச் சேற்றில் இறங்கினேன்.","ro":"Nāṉ cheruppaik kaḻaṛṛiviṭṭuch chēṛṛil iṛangiṉēṉ."},{"fr":"Au bout d'une heure, j'étais déjà complètement épuisé.","tgt":"ஒரு மணி நேரத்திலேயே நான் சோர்ந்துவிட்டேன்.","ro":"Oru maṇi nērattilēyē nāṉ chōrnduviṭṭēṉ."},{"fr":"Les femmes, elles, chantaient sans s'arrêter.","tgt":"பெண்களோ நிறுத்தாமல் பாடிக்கொண்டிருந்தார்கள்.","ro":"Peṇgaḷō niṛuttāmal pāḍikkoṇḍirundārgaḷ."},{"fr":"Avant midi, nous avions planté toute la rangée.","tgt":"மதியத்திற்குள் அந்த வரிசை முழுவதையும் நட்டுவிட்டோம்.","ro":"Madiyattiṛkuḷ anda varichai muḻuvadaiyum naṭṭuviṭṭōm."},{"fr":"Le repas a été servi sur des feuilles de bananier, au bord du champ.","tgt":"வயலின் ஓரத்தில் வாழை இலையில் சாப்பாடு பரிமாறப்பட்டது.","ro":"Vayaliṉ ōrattil vāḻai ilaiyil chāppāḍu parimāṛappaṭṭadu."},{"fr":"J'avais tellement faim que j'ai tout mangé en cinq minutes.","tgt":"எனக்கு அவ்வளவு பசி, ஐந்து நிமிடத்தில் எல்லாவற்றையும் சாப்பிட்டுவிட்டேன்.","ro":"Eṉakku avvaḷavu pachi, aindu nimiḍattil ellāvaṛṛaiyum chāppiṭṭuviṭṭēṉ."},{"fr":"Le soleil s'était couché avant même notre retour.","tgt":"நாங்கள் திரும்புவதற்குள் சூரியன் மறைந்துவிட்டது.","ro":"Nāngaḷ tirumbuvadaṛkuḷ chūriyaṉ maṛainduviṭṭadu."},{"fr":"J'ai complètement oublié de photographier les femmes au travail.","tgt":"வேலை செய்யும் பெண்களைப் புகைப்படம் எடுக்க நான் முற்றிலும் மறந்துவிட்டேன்.","ro":"Vēlai cheyyum peṇgaḷaip pugaippaḍam eḍukka nāṉ muṛṛilum maṛanduviṭṭēṉ."},{"fr":"Cette journée m'a fait comprendre la valeur de chaque grain de riz.","tgt":"இந்த நாள் ஒவ்வொரு அரிசி மணியின் மதிப்பையும் எனக்குப் புரிய வைத்துவிட்டது.","ro":"Inda nāḷ ovvoru arichi maṇiyiṉ madippaiyum eṉakkup puriya vaittuviṭṭadu."}],"tip":{"title":"« Viḍu » : l'action complètement terminée","example":"J'avais tellement faim que j'ai tout mangé en cinq minutes. — எனக்கு அவ்வளவு பசி, ஐந்து நிமிடத்தில் எல்லாவற்றையும் <b>சாப்பிட்டுவிட்டேன்</b>.","body":"Le verbe « viḍu » veut dire laisser, lâcher. Placé après un autre verbe, il ajoute l'idée que l'action est complètement terminée, parfois même faite d'un seul coup. On met le premier verbe à sa forme liée en « -u » ou « -i », puis on ajoute « viṭṭēṉ », j'ai laissé : « chāppiṭṭu », ayant mangé, plus « viṭṭēṉ » donne « chāppiṭṭuviṭṭēṉ », j'ai tout mangé, c'est fini. Comparez « maṛandēṉ », j'ai oublié, et « maṛanduviṭṭēṉ », j'ai complètement oublié. Avec nous, on dit « naṭṭuviṭṭōm », nous avons fini de planter. C'est un peu notre « ça y est » ajouté à la fin de la phrase. Astuce : quand vous entendez « viṭṭu », imaginez quelqu'un qui pose son outil, le travail est terminé.","exampleRo":"Eṉakku avvaḷavu pachi, aindu nimiḍattil ellāvaṛṛaiyum chāppiṭṭuviṭṭēṉ.","lit":"à moi · tellement · faim · cinq · minute [dans] · tout [objet] · ai mangé (complètement)","say":{"Viḍu":"விடு","viḍu":"விடு","viṭṭēṉ":"விட்டேன்","chāppiṭṭu":"சாப்பிட்டு","chāppiṭṭuviṭṭēṉ":"சாப்பிட்டுவிட்டேன்","maṛandēṉ":"மறந்தேன்","maṛanduviṭṭēṉ":"மறந்துவிட்டேன்","naṭṭuviṭṭōm":"நட்டுவிட்டோம்","viṭṭu":"விட்டு"}}},{"title":"Kumbakonam et son café filtre","phrases":[{"fr":"Kumbakonam est célèbre dans tout le Tamil Nadu pour son café.","tgt":"கும்பகோணம் அதன் காபிக்காகத் தமிழ்நாடு முழுவதும் புகழ்பெற்றது.","ro":"Kumbakōṇam adaṉ kāpikkāgat Tamiḻnāḍu muḻuvadum pugaḻbeṛṛadu."},{"fr":"Le secret, paraît-il, c'est le lait frais et un peu de chicorée.","tgt":"புதிய பாலும் கொஞ்சம் சிக்கரியும்தான் அதன் ரகசியம் என்று சொல்கிறார்கள்.","ro":"Pudiya pālum konjam chikkariyumtāṉ adaṉ ragachiyam eṉṛu cholgiṛārgaḷ."},{"fr":"On verse le café de haut, d'un gobelet à l'autre, pour le faire mousser.","tgt":"நுரை வருவதற்காகக் காபியை ஒரு டம்ளரிலிருந்து இன்னொன்றுக்கு உயரத்திலிருந்து ஊற்றுகிறார்கள்.","ro":"Nurai varuvadaṛkāgak kāpiyai oru ṭamḷarilirundu iṉṉoṉṛukku uyarattilirundu ūṛṛugiṛārgaḷ."},{"fr":"On le sert dans un petit gobelet en laiton posé dans une coupelle.","tgt":"அதை டபராவில் வைத்த சிறிய பித்தளை டம்ளரில் கொடுக்கிறார்கள்.","ro":"Adai ṭabarāvil vaitta chiṛiya pittaḷai ṭamḷaril koḍukkiṛārgaḷ."},{"fr":"Le patron torréfie lui-même ses grains chaque matin.","tgt":"கடை உரிமையாளர் தினமும் காலையில் காபிக் கொட்டைகளைத் தானே வறுக்கிறார்.","ro":"Kaḍai urimaiyāḷar tiṉamum kālaiyil kāpik koṭṭaigaḷait tāṉē vaṛukkiṛār."},{"fr":"L'odeur du café grillé envahit toute la rue.","tgt":"வறுத்த காபியின் மணம் தெரு முழுவதும் பரவுகிறது.","ro":"Vaṛutta kāpiyiṉ maṇam teru muḻuvadum paravugiṛadu."},{"fr":"Je n'ai jamais bu un café aussi corsé et aussi doux à la fois.","tgt":"இவ்வளவு திடமாகவும் அதே நேரம் இனிப்பாகவும் இருக்கும் காபியை நான் குடித்ததே இல்லை.","ro":"Ivvaḷavu tiḍamāgavum adē nēram iṉippāgavum irukkum kāpiyai nāṉ kuḍittadē illai."},{"fr":"Nous avons acheté une livre de café moulu à rapporter.","tgt":"ஊருக்கு எடுத்துச் செல்ல அரை கிலோ காபித் தூள் வாங்கினோம்.","ro":"Ūrukku eḍuttuch chella arai kilō kāpit tūḷ vāngiṉōm."},{"fr":"Ici, les cafés ouvrent avant même cinq heures du matin.","tgt":"இங்கே காபிக் கடைகள் காலை ஐந்து மணிக்கு முன்பே திறந்துவிடுகின்றன.","ro":"Ingē kāpik kaḍaigaḷ kālai aindu maṇikku muṉbē tiṛanduviḍugiṉṛaṉa."},{"fr":"Un deuxième café ? Avec grand plaisir !","tgt":"இன்னொரு காபியா? மிகவும் சந்தோஷமாக!","ro":"Iṉṉoru kāpiyā? Migavum chandōshamāga!"}]},{"title":"Le marché aux ustensiles de cuivre","phrases":[{"fr":"Kumbakonam est aussi connue pour ses ustensiles en laiton et en cuivre.","tgt":"கும்பகோணம் பித்தளை, செம்புப் பாத்திரங்களுக்கும் பெயர் பெற்றது.","ro":"Kumbakōṇam pittaḷai, chembup pāttirangaḷukkum peyar peṛṛadu."},{"fr":"Les marchands tapotent les pots pour montrer leur qualité.","tgt":"வியாபாரிகள் பாத்திரங்களின் தரத்தைக் காட்டத் தட்டிப் பார்க்கிறார்கள்.","ro":"Viyābārigaḷ pāttirangaḷiṉ tarattaik kāṭṭat taṭṭip pārkkiṛārgaḷ."},{"fr":"Chaque cruche est martelée à la main, une par une.","tgt":"ஒவ்வொரு குடமும் கையால் ஒவ்வொன்றாக அடித்து வடிவமைக்கப்படுகிறது.","ro":"Ovvoru kuḍamum kaiyāl ovvoṉṛāga aḍittu vaḍivamaikkappaḍugiṛadu."},{"fr":"Ma mère m'a demandé de lui rapporter un plateau en cuivre.","tgt":"ஒரு செம்புத் தட்டு வாங்கி வரும்படி என் அம்மா என்னிடம் சொன்னார்.","ro":"Oru chembut taṭṭu vāngi varumbaḍi eṉ ammā eṉṉiḍam choṉṉār."},{"fr":"Le prix se calcule au poids, pas à la pièce.","tgt":"விலை எண்ணிக்கையைப் பொறுத்து அல்ல, எடையைப் பொறுத்துக் கணக்கிடப்படுகிறது.","ro":"Vilai eṇṇikkaiyaip poṛuttu alla, eḍaiyaip poṛuttuk kaṇakkiḍappaḍugiṛadu."},{"fr":"Si j'en prends deux, vous pouvez baisser un peu le prix ?","tgt":"நான் இரண்டு வாங்கினால் விலையைக் கொஞ்சம் குறைக்க முடியுமா?","ro":"Nāṉ iraṇḍu vāngiṉāl vilaiyaik konjam kuṛaikka muḍiyumā?"},{"fr":"Le vendeur a gravé mon prénom sous le plateau, sans supplément.","tgt":"கூடுதல் கட்டணம் இல்லாமல் கடைக்காரர் தட்டின் அடியில் என் பெயரைப் பொறித்தார்.","ro":"Kūḍudal kaṭṭaṇam illāmal kaḍaikkārar taṭṭiṉ aḍiyil eṉ peyaraip poṛittār."},{"fr":"Ces objets lourds seront difficiles à caser dans la valise.","tgt":"இந்தக் கனமான பொருட்களைப் பெட்டியில் வைப்பது கஷ்டமாக இருக்கும்.","ro":"Indak kaṉamāṉa poruṭkaḷaip peṭṭiyil vaippadu kashṭamāga irukkum."},{"fr":"Le marchand peut nous les envoyer directement par la poste.","tgt":"வியாபாரி அவற்றை நேரடியாக எங்கள் வீட்டுக்குத் தபாலில் அனுப்ப முடியும்.","ro":"Viyābāri avaṛṛai nēraḍiyāga engaḷ vīṭṭukkut tabālil aṉuppa muḍiyum."},{"fr":"Chaque objet ici a été fabriqué par une famille du quartier.","tgt":"இங்குள்ள ஒவ்வொரு பொருளும் இந்தப் பகுதியைச் சேர்ந்த ஒரு குடும்பத்தால் செய்யப்பட்டது.","ro":"Inguḷḷa ovvoru poruḷum indap pagudiyaich chērnda oru kuḍumbattāl cheyyappaṭṭadu."}]},{"title":"La route vers Chettinad","phrases":[{"fr":"Nous avons pris un taxi pour rejoindre Karaikudi, au cœur du Chettinad.","tgt":"செட்டிநாட்டின் மையத்தில் உள்ள காரைக்குடிக்குச் செல்ல ஒரு டாக்ஸி எடுத்தோம்.","ro":"Cheṭṭināṭṭiṉ maiyattil uḷḷa Kāraikkuḍikkuch chella oru ṭāksi eḍuttōm."},{"fr":"Le trajet dure environ trois heures, selon la circulation.","tgt":"போக்குவரத்தைப் பொறுத்து பயணம் சுமார் மூன்று மணி நேரம் ஆகும்.","ro":"Pōkkuvarattaip poṛuttu payaṇam chumār mūṉṛu maṇi nēram āgum."},{"fr":"La route longe des étangs couverts de lotus.","tgt":"சாலை தாமரை நிறைந்த குளங்களின் ஓரமாகச் செல்கிறது.","ro":"Chālai tāmarai niṛainda kuḷangaḷiṉ ōramāgach chelgiṛadu."},{"fr":"Le chauffeur s'est arrêté pour nous acheter des goyaves au bord de la route.","tgt":"ஓட்டுநர் வண்டியை நிறுத்தி சாலையோரத்தில் எங்களுக்குக் கொய்யாப்பழம் வாங்கினார்.","ro":"Ōṭṭunar vaṇḍiyai niṛutti chālaiyōrattil engaḷukkuk koyyāppaḻam vāngiṉār."},{"fr":"Plus on s'éloigne du fleuve, plus la terre paraît sèche.","tgt":"ஆற்றிலிருந்து விலக விலக நிலம் வறண்டு காணப்படுகிறது.","ro":"Āṛṛilirundu vilaga vilaga nilam vaṛaṇḍu kāṇappaḍugiṛadu."},{"fr":"Pourriez-vous rouler un peu moins vite, s'il vous plaît ?","tgt":"தயவுசெய்து கொஞ்சம் மெதுவாக ஓட்ட முடியுமா?","ro":"Tayavucheydu konjam meduvāga ōṭṭa muḍiyumā?"},{"fr":"On s'est arrêtés un moment dans un village pour boire un thé.","tgt":"டீ குடிக்க ஒரு கிராமத்தில் கொஞ்ச நேரம் நின்றோம்.","ro":"Ṭī kuḍikka oru kirāmattil konja nēram niṉṛōm."},{"fr":"Des enfants couraient derrière la voiture en nous faisant signe.","tgt":"குழந்தைகள் காருக்குப் பின்னால் ஓடிக்கொண்டே எங்களுக்குக் கை அசைத்தார்கள்.","ro":"Kuḻandaigaḷ kārukkup piṉṉāl ōḍikkoṇḍē engaḷukkuk kai achaittārgaḷ."},{"fr":"Les premières grandes demeures sont apparues à l'entrée de la ville.","tgt":"ஊரின் நுழைவாயிலில் முதல் பெரிய வீடுகள் தென்பட்டன.","ro":"Ūriṉ nuḻaivāyilil mudal periya vīḍugaḷ teṉbaṭṭaṉa."},{"fr":"Notre hôtel est une ancienne maison de marchands rénovée.","tgt":"எங்கள் விடுதி, மாற்றி அமைக்கப்பட்ட ஒரு பழைய வணிகர் வீடு.","ro":"Engaḷ viḍudi, māṛṛi amaikkappaṭṭa oru paḻaiya vaṇigar vīḍu."}]},{"title":"Les grandes demeures de Chettinad","phrases":[{"fr":"Ces demeures ont été bâties par de riches familles de marchands.","tgt":"இந்த மாளிகைகள் பணக்கார வணிகக் குடும்பங்களால் கட்டப்பட்டவை.","ro":"Inda māḷigaigaḷ paṇakkāra vaṇigak kuḍumbangaḷāl kaṭṭappaṭṭavai."},{"fr":"Ces familles faisaient du commerce au-delà des mers.","tgt":"அவர்கள் கடல் கடந்து வாணிபம் செய்தார்கள்.","ro":"Avargaḷ kaḍal kaḍandu vāṇibam cheydārgaḷ."},{"fr":"Les colonnes de la cour sont en bois de teck.","tgt":"முற்றத்தின் தூண்கள் தேக்கு மரத்தால் செய்யப்பட்டவை.","ro":"Muṛṛattiṉ tūṇgaḷ tēkku marattāl cheyyappaṭṭavai."},{"fr":"Le sol en carreaux colorés reste frais même au cœur de l'été.","tgt":"வண்ண ஓடுகள் பதித்த தரை கடும் கோடையிலும் குளிர்ச்சியாக இருக்கிறது.","ro":"Vaṇṇa ōḍugaḷ paditta tarai kaḍum kōḍaiyilum kuḷirchchiyāga irukkiṛadu."},{"fr":"Certaines maisons comptent plus de cinquante pièces.","tgt":"சில வீடுகளில் ஐம்பதுக்கும் மேற்பட்ட அறைகள் உள்ளன.","ro":"Chila vīḍugaḷil aimbadukkum mēṛpaṭṭa aṛaigaḷ uḷḷaṉa."},{"fr":"La plupart des propriétaires vivent aujourd'hui à Chennai.","tgt":"பெரும்பாலான உரிமையாளர்கள் இப்போது சென்னையில் வசிக்கிறார்கள்.","ro":"Perumbālāṉa urimaiyāḷargaḷ ippōdu Cheṉṉaiyil vachikkiṛārgaḷ."},{"fr":"Ils ne reviennent que pour les mariages et les grandes fêtes de famille.","tgt":"திருமணங்களுக்கும் பெரிய குடும்ப விழாக்களுக்கும் மட்டுமே அவர்கள் திரும்பி வருகிறார்கள்.","ro":"Tirumaṇangaḷukkum periya kuḍumba viḻākkaḷukkum maṭṭumē avargaḷ tirumbi varugiṛārgaḷ."},{"fr":"Un vieux gardien nous a fait visiter la maison de son ancien patron.","tgt":"ஒரு வயதான காவலாளி தன் பழைய முதலாளியின் வீட்டைச் சுற்றிக் காட்டினார்.","ro":"Oru vayadāṉa kāvalāḷi taṉ paḻaiya mudalāḷiyiṉ vīṭṭaich chuṛṛik kāṭṭiṉār."},{"fr":"Les miroirs et les lustres sont arrivés de très loin, par bateau.","tgt":"கண்ணாடிகளும் சரவிளக்குகளும் கப்பலில் வெகு தூரத்திலிருந்து வந்தவை.","ro":"Kaṇṇāḍigaḷum charaviḷakkugaḷum kappalil vegu tūrattilirundu vandavai."},{"fr":"Marcher dans ces couloirs déserts donne une impression étrange.","tgt":"இந்த வெறிச்சோடிய தாழ்வாரங்களில் நடப்பது ஒரு விசித்திரமான உணர்வைத் தருகிறது.","ro":"Inda veṛichchōḍiya tāḻvārangaḷil naḍappadu oru vichittiramāṉa uṇarvait tarugiṛadu."}]},{"title":"Une maison fermée depuis longtemps","phrases":[{"fr":"Cette maison doit être fermée depuis des années.","tgt":"இந்த வீடு பல ஆண்டுகளாகப் பூட்டியிருக்கலாம்.","ro":"Inda vīḍu pala āṇḍugaḷāgap pūṭṭiyirukkalām."},{"fr":"Les propriétaires ont dû partir s'installer en ville.","tgt":"உரிமையாளர்கள் நகரத்துக்குக் குடிபெயர்ந்திருக்கலாம்.","ro":"Urimaiyāḷargaḷ nagarattukkuk kuḍipeyarndirukkalām."},{"fr":"Il a dû y avoir une grande fête ici autrefois.","tgt":"முன்பு இங்கே ஒரு பெரிய விழா நடந்திருக்கலாம்.","ro":"Muṉbu ingē oru periya viḻā naḍandirukkalām."},{"fr":"Ces portes sculptées ont sans doute plus de cent ans.","tgt":"இந்தச் செதுக்கப்பட்ட கதவுகள் நூறு ஆண்டுகளுக்கும் மேல் பழமையானவையாக இருக்கலாம்.","ro":"Indach chedukkappaṭṭa kadavugaḷ nūṛu āṇḍugaḷukkum mēl paḻamaiyāṉavaiyāga irukkalām."},{"fr":"Le gardien est peut-être parti déjeuner.","tgt":"காவலாளி சாப்பிடப் போயிருக்கலாம்.","ro":"Kāvalāḷi chāppiḍap pōyirukkalām."},{"fr":"Quelqu'un a dû oublier de fermer cette fenêtre.","tgt":"யாரோ இந்த ஜன்னலை மூட மறந்திருக்கலாம்.","ro":"Yārō inda jaṉṉalai mūḍa maṛandirukkalām."},{"fr":"D'après le voisin, la famille revient une fois par an.","tgt":"பக்கத்து வீட்டுக்காரர் சொன்னபடி, அந்தக் குடும்பம் ஆண்டுக்கு ஒரு முறை வருகிறது.","ro":"Pakkattu vīṭṭukkārar choṉṉabaḍi, andak kuḍumbam āṇḍukku oru muṛai varugiṛadu."},{"fr":"Le sol est propre, ils sont sans doute venus récemment.","tgt":"தரை சுத்தமாக இருக்கிறது, அவர்கள் சமீபத்தில் வந்திருக்கலாம்.","ro":"Tarai chuttamāga irukkiṛadu, avargaḷ chamībattil vandirukkalām."},{"fr":"Cette pièce servait probablement de réserve à riz.","tgt":"இந்த அறை நெல் சேமிக்கும் கிடங்காக இருந்திருக்கலாம்.","ro":"Inda aṛai nel chēmikkum kiḍangāga irundirukkalām."},{"fr":"On ne saura jamais vraiment qui vivait derrière ces murs.","tgt":"இந்தச் சுவர்களுக்குப் பின்னால் யார் வாழ்ந்தார்கள் என்று நமக்கு ஒருபோதும் தெரியாது.","ro":"Indach chuvargaḷukkup piṉṉāl yār vāḻndārgaḷ eṉṛu namakku orupōdum teriyādu."}],"tip":{"title":"« -irukkalām » : ça doit être, la supposition","example":"Le gardien est peut-être parti déjeuner. — காவலாளி சாப்பிடப் <b>போயிருக்கலாம்</b>.","body":"Pour faire une supposition sur ce qui s'est passé, le tamoul assemble trois morceaux : le verbe à sa forme liée en « -u » ou « -i », puis « iru », être, et enfin « -alām », c'est possible. « Pōy », étant allé, plus « irukkalām » donne « pōyirukkalām » : il est peut-être parti, il a dû partir. De la même façon, « vandirukkalām », ils sont sans doute venus, et « maṛandirukkalām », quelqu'un a dû oublier. Bonne nouvelle : cette forme ne change jamais selon la personne, elle reste identique pour je, il ou ils. C'est l'équivalent de notre « il a dû » ou « sans doute ». Astuce : retenez « -alām », c'est possible, et vous pourrez deviner sans jamais rien affirmer.","exampleRo":"Kāvalāḷi chāppiḍap pōyirukkalām.","lit":"gardien · manger [pour] · est peut-être allé","say":{"iru":"இரு","Pōy":"போய்","irukkalām":"இருக்கலாம்","pōyirukkalām":"போயிருக்கலாம்","vandirukkalām":"வந்திருக்கலாம்","maṛandirukkalām":"மறந்திருக்கலாம்"}}},{"title":"Un cours de cuisine chettinad","phrases":[{"fr":"Une cuisinière du village nous a invités dans sa cuisine.","tgt":"ஊரைச் சேர்ந்த ஒரு சமையல்காரப் பெண்மணி எங்களைத் தன் சமையலறைக்கு அழைத்தார்.","ro":"Ūraich chērnda oru chamaiyalkārap peṇmaṇi engaḷait taṉ chamaiyalaṛaikku aḻaittār."},{"fr":"La cuisine chettinad est connue pour ses épices très parfumées.","tgt":"செட்டிநாட்டுச் சமையல் நறுமணமிக்க மசாலாக்களுக்குப் பெயர் போனது.","ro":"Cheṭṭināṭṭuch chamaiyal naṛumaṇamikka machālākkaḷukkup peyar pōṉadu."},{"fr":"Elle fait griller les épices entières avant de les moudre.","tgt":"அவர் முழு மசாலாப் பொருட்களை அரைப்பதற்கு முன் வறுக்கிறார்.","ro":"Avar muḻu machālāp poruṭkaḷai araippadaṛku muṉ vaṛukkiṛār."},{"fr":"Le poivre noir et l'anis étoilé donnent ce goût si particulier.","tgt":"மிளகும் அன்னாசிப் பூவும்தான் அந்தத் தனித்துவமான சுவையைத் தருகின்றன.","ro":"Miḷagum aṉṉāchip pūvumtāṉ andat taṉittuvamāṉa chuvaiyait tarugiṉṛaṉa."},{"fr":"Il faut écraser l'ail et le gingembre au mortier.","tgt":"பூண்டையும் இஞ்சியையும் உரலில் இடிக்க வேண்டும்.","ro":"Pūṇḍaiyum injiyaiyum uralil iḍikka vēṇḍum."},{"fr":"Elle m'a laissé remuer la sauce pendant qu'elle coupait les oignons.","tgt":"அவர் வெங்காயம் நறுக்கும்போது என்னைக் குழம்பைக் கிளற விட்டார்.","ro":"Avar vengāyam naṛukkumbōdu eṉṉaik kuḻambaik kiḷaṛa viṭṭār."},{"fr":"Selon elle, tout l'art tient dans la patience et le feu doux.","tgt":"அவரைப் பொறுத்தவரை, பொறுமையும் சிறு தீயும்தான் ரகசியம்.","ro":"Avaraip poṛuttavarai, poṛumaiyum chiṛu tīyumtāṉ ragachiyam."},{"fr":"J'ai noté chaque étape dans mon petit carnet.","tgt":"எல்லாப் படிகளையும் என் குறிப்பேட்டில் எழுதிக்கொண்டேன்.","ro":"Ellāp paḍigaḷaiyum eṉ kuṛippēṭṭil eḻudikkoṇḍēṉ."},{"fr":"Mes mains vont sentir les épices toute la journée.","tgt":"நாள் முழுவதும் என் கைகளில் மசாலா வாசனை இருக்கும்.","ro":"Nāḷ muḻuvadum eṉ kaigaḷil machālā vāchaṉai irukkum."},{"fr":"Je vais essayer de refaire cette recette une fois rentré en France.","tgt":"பிரான்ஸுக்குத் திரும்பியதும் இந்தச் சமையலை மீண்டும் செய்து பார்க்கப் போகிறேன்.","ro":"Pirāṉsukkut tirumbiyadum indach chamaiyalai mīṇḍum cheydu pārkkap pōgiṛēṉ."}]},{"title":"Un déjeuner très épicé","phrases":[{"fr":"Ici, le déjeuner est servi sur une grande feuille de bananier.","tgt":"இங்கே மதிய உணவு பெரிய வாழை இலையில் பரிமாறப்படுகிறது.","ro":"Ingē madiya uṇavu periya vāḻai ilaiyil parimāṛappaḍugiṛadu."},{"fr":"Il y avait au moins douze plats différents.","tgt":"குறைந்தது பன்னிரண்டு வகை உணவுகள் இருந்தன.","ro":"Kuṛaindadu paṉṉiraṇḍu vagai uṇavugaḷ irundaṉa."},{"fr":"Le poulet chettinad m'a vraiment mis la bouche en feu.","tgt":"செட்டிநாட்டுக் கோழிக் குழம்பு என் வாயை உண்மையிலேயே எரித்துவிட்டது.","ro":"Cheṭṭināṭṭuk kōḻik kuḻambu eṉ vāyai uṇmaiyilēyē erittuviṭṭadu."},{"fr":"J'avais les larmes aux yeux, mais je ne pouvais pas m'arrêter.","tgt":"என் கண்களில் நீர் வழிந்தது, ஆனாலும் நிறுத்த முடியவில்லை.","ro":"Eṉ kaṇgaḷil nīr vaḻindadu, āṉālum niṛutta muḍiyavillai."},{"fr":"Le serveur m'a apporté du yaourt pour calmer le feu.","tgt":"காரத்தைத் தணிக்கப் பரிமாறுபவர் எனக்குத் தயிர் கொண்டு வந்தார்.","ro":"Kārattait taṇikkap parimāṛubavar eṉakkut tayir koṇḍu vandār."},{"fr":"On mange avec la main droite, en mélangeant le riz et la sauce.","tgt":"சாதத்தையும் குழம்பையும் கலந்து வலது கையால் சாப்பிடுகிறோம்.","ro":"Chādattaiyum kuḻambaiyum kalandu valadu kaiyāl chāppiḍugiṛōm."},{"fr":"Les serveurs remplissent la feuille dès qu'elle se vide.","tgt":"இலை காலியானவுடனே பரிமாறுபவர்கள் மீண்டும் நிரப்புகிறார்கள்.","ro":"Ilai kāliyāṉavuḍaṉē parimāṛubavargaḷ mīṇḍum nirappugiṛārgaḷ."},{"fr":"Pour montrer qu'on a fini, on replie la feuille vers soi.","tgt":"சாப்பிட்டு முடித்ததைக் காட்ட இலையை நம் பக்கமாக மடிக்கிறோம்.","ro":"Chāppiṭṭu muḍittadaik kāṭṭa ilaiyai nam pakkamāga maḍikkiṛōm."},{"fr":"Le dessert au lait et à la cardamome a tout adouci.","tgt":"பாலும் ஏலக்காயும் சேர்த்த பாயசம் எல்லாவற்றையும் தணித்தது.","ro":"Pālum ēlakkāyum chērtta pāyacham ellāvaṛṛaiyum taṇittadu."},{"fr":"C'est sans doute le repas le plus mémorable du voyage.","tgt":"இதுதான் இந்தப் பயணத்தின் மிக மறக்க முடியாத சாப்பாடு.","ro":"Idutāṉ indap payaṇattiṉ miga maṛakka muḍiyāda chāppāḍu."}]},{"title":"Le marché aux antiquités de Karaikudi","phrases":[{"fr":"Karaikudi a un marché aux antiquités unique dans la région.","tgt":"காரைக்குடியில் இந்தப் பகுதியிலேயே தனித்துவமான ஒரு பழம்பொருள் சந்தை உள்ளது.","ro":"Kāraikkuḍiyil indap pagudiyilēyē taṉittuvamāṉa oru paḻamboruḷ chandai uḷḷadu."},{"fr":"On y vend des objets récupérés dans les vieilles demeures.","tgt":"பழைய வீடுகளிலிருந்து எடுக்கப்பட்ட பொருட்கள் இங்கே விற்கப்படுகின்றன.","ro":"Paḻaiya vīḍugaḷilirundu eḍukkappaṭṭa poruṭkaḷ ingē viṛkappaḍugiṉṛaṉa."},{"fr":"J'ai déniché une vieille boîte à épices en bois sculpté.","tgt":"செதுக்கிய மரத்தாலான ஒரு பழைய மசாலாப் பெட்டியைக் கண்டுபிடித்தேன்.","ro":"Chedukkiya marattālāṉa oru paḻaiya machālāp peṭṭiyaik kaṇḍubiḍittēṉ."},{"fr":"Le marchand affirme qu'elle a plus d'un siècle.","tgt":"அது நூறு ஆண்டுகளுக்கும் மேல் பழமையானது என்று வியாபாரி உறுதியாகச் சொல்கிறார்.","ro":"Adu nūṛu āṇḍugaḷukkum mēl paḻamaiyāṉadu eṉṛu viyābāri uṛudiyāgach cholgiṛār."},{"fr":"Je ne sais pas s'il dit toute la vérité.","tgt":"அவர் முழு உண்மையைச் சொல்கிறாரா என்று எனக்குத் தெரியவில்லை.","ro":"Avar muḻu uṇmaiyaich cholgiṛārā eṉṛu eṉakkut teriyavillai."},{"fr":"Il en demandait trois mille roupies, on s'est mis d'accord sur deux mille.","tgt":"அவர் மூவாயிரம் ரூபாய் கேட்டார், இரண்டாயிரத்துக்கு ஒப்புக்கொண்டோம்.","ro":"Avar mūvāyiram rūbāy kēṭṭār, iraṇḍāyirattukku oppukkoṇḍōm."},{"fr":"Les vieilles photos de famille m'ont beaucoup ému.","tgt":"பழைய குடும்பப் புகைப்படங்கள் என் மனதை மிகவும் தொட்டன.","ro":"Paḻaiya kuḍumbap pugaippaḍangaḷ eṉ maṉadai migavum toṭṭaṉa."},{"fr":"On y voit des visages graves, en habits de fête.","tgt":"விழா உடையில் கம்பீரமான முகங்களைப் பார்க்க முடிகிறது.","ro":"Viḻā uḍaiyil kambīramāṉa mugangaḷaip pārkka muḍigiṛadu."},{"fr":"Ma femme a eu un coup de cœur pour une paire de vieux bracelets.","tgt":"என் மனைவிக்கு ஒரு ஜோடி பழைய வளையல்கள் மிகவும் பிடித்துவிட்டன.","ro":"Eṉ maṉaivikku oru jōḍi paḻaiya vaḷaiyalgaḷ migavum piḍittuviṭṭaṉa."},{"fr":"Il va falloir trouver de la place pour tout ça dans les bagages.","tgt":"இவை எல்லாவற்றுக்கும் பெட்டியில் இடம் தேட வேண்டும்.","ro":"Ivai ellāvaṛṛukkum peṭṭiyil iḍam tēḍa vēṇḍum."}]},{"title":"Une route sous les eaux","phrases":[{"fr":"Une grosse averse a éclaté sur la route de la côte.","tgt":"கடற்கரைக்குச் செல்லும் வழியில் பெருமழை கொட்டத் தொடங்கியது.","ro":"Kaḍaṛkaraikkuch chellum vaḻiyil perumaḻai koṭṭat toḍangiyadu."},{"fr":"En quelques minutes, la route était sous l'eau.","tgt":"சில நிமிடங்களிலேயே சாலை தண்ணீரில் மூழ்கியது.","ro":"Chila nimiḍangaḷilēyē chālai taṇṇīril mūḻgiyadu."},{"fr":"Par prudence, le chauffeur a refusé de traverser.","tgt":"எச்சரிக்கையாக இருக்க, ஓட்டுநர் கடந்து செல்ல மறுத்தார்.","ro":"Echcharikkaiyāga irukka, ōṭṭunar kaḍandu chella maṛuttār."},{"fr":"Nous avons attendu sous l'auvent d'une petite boutique.","tgt":"ஒரு சிறிய கடையின் கூரையின் கீழ் காத்திருந்தோம்.","ro":"Oru chiṛiya kaḍaiyiṉ kūraiyiṉ kīḻ kāttirundōm."},{"fr":"Le commerçant nous a offert du thé chaud et des beignets.","tgt":"கடைக்காரர் எங்களுக்குச் சூடான டீயும் வடையும் கொடுத்தார்.","ro":"Kaḍaikkārar engaḷukkuch chūḍāṉa ṭīyum vaḍaiyum koḍuttār."},{"fr":"D'après lui, l'eau se retire en général en une heure ou deux.","tgt":"அவர் சொன்னபடி, தண்ணீர் பொதுவாக ஒன்றிரண்டு மணி நேரத்தில் வடிந்துவிடும்.","ro":"Avar choṉṉabaḍi, taṇṇīr poduvāga oṉṛiraṇḍu maṇi nērattil vaḍinduviḍum."},{"fr":"Nous avons dû annuler la visite prévue l'après-midi.","tgt":"மதியம் திட்டமிட்டிருந்த பயணத்தை ரத்து செய்ய வேண்டியதாயிற்று.","ro":"Madiyam tiṭṭamiṭṭirunda payaṇattai rattu cheyya vēṇḍiyadāyiṛṛu."},{"fr":"Finalement, un tracteur a tiré notre voiture jusqu'à l'autre rive.","tgt":"கடைசியில், ஒரு டிராக்டர் எங்கள் காரை மறுபக்கம் வரை இழுத்துச் சென்றது.","ro":"Kaḍaichiyil, oru ṭirākṭar engaḷ kārai maṛupakkam varai iḻuttuch cheṉṛadu."},{"fr":"Tout le village était sorti regarder la scène en riant.","tgt":"அந்தக் காட்சியைப் பார்த்துச் சிரிக்க ஊரே வெளியே வந்திருந்தது.","ro":"Andak kāṭchiyaip pārttuch chirikka ūrē veḷiyē vandirundadu."},{"fr":"Ce genre d'imprévu fait aussi partie du voyage.","tgt":"இப்படிப்பட்ட எதிர்பாராத நிகழ்வுகளும் பயணத்தின் ஒரு பகுதிதான்.","ro":"Ippaḍippaṭṭa edirbārāda nigaḻvugaḷum payaṇattiṉ oru paguditāṉ."}]},{"title":"Les oiseaux de Kodiakkarai","phrases":[{"fr":"Avant les mangroves, nous avons fait un détour par la réserve d'oiseaux de Kodiakkarai.","tgt":"அலையாத்திக் காடுகளுக்கு முன், கோடியக்கரை பறவைகள் சரணாலயத்துக்குச் சென்றோம்.","ro":"Alaiyāttik kāḍugaḷukku muṉ, Kōḍiyakkarai paṛavaigaḷ charaṇālayattukkuch cheṉṛōm."},{"fr":"Des milliers de flamants roses font halte ici chaque hiver.","tgt":"ஒவ்வொரு குளிர்காலத்திலும் ஆயிரக்கணக்கான பூநாரைகள் இங்கே தங்குகின்றன.","ro":"Ovvoru kuḷirkālattilum āyirakkaṇakkāṉa pūnāraigaḷ ingē tangugiṉṛaṉa."},{"fr":"Il faut arriver très tôt pour les observer sans les déranger.","tgt":"அவற்றைத் தொந்தரவு செய்யாமல் பார்க்க மிகவும் சீக்கிரமாக வர வேண்டும்.","ro":"Avaṛṛait tondaravu cheyyāmal pārkka migavum chīkkiramāga vara vēṇḍum."},{"fr":"Le guide nous a prêté une paire de jumelles.","tgt":"வழிகாட்டி எங்களுக்கு ஒரு தொலைநோக்கியைக் கொடுத்தார்.","ro":"Vaḻikāṭṭi engaḷukku oru tolainōkkiyaik koḍuttār."},{"fr":"On reconnaît les flamants à leur long cou et à leurs pattes fines.","tgt":"நீண்ட கழுத்தையும் மெல்லிய கால்களையும் வைத்துப் பூநாரைகளை அடையாளம் காணலாம்.","ro":"Nīṇḍa kaḻuttaiyum melliya kālgaḷaiyum vaittup pūnāraigaḷai aḍaiyāḷam kāṇalām."},{"fr":"Des antilopes broutaient tranquillement près de la plage.","tgt":"கடற்கரை அருகே வெளிமான்கள் அமைதியாக மேய்ந்துகொண்டிருந்தன.","ro":"Kaḍaṛkarai arugē veḷimāṉgaḷ amaidiyāga mēyndugoṇḍirundaṉa."},{"fr":"Ne faites pas de bruit, sinon ils vont s'envoler.","tgt":"சத்தம் போடாதீர்கள், இல்லையென்றால் அவை பறந்துவிடும்.","ro":"Chattam pōḍādīrgaḷ, illaiyeṉṛāl avai paṛanduviḍum."},{"fr":"Du phare, au bout de la pointe, la vue est magnifique.","tgt":"முனையில் உள்ள கலங்கரை விளக்கத்திலிருந்து அருமையான காட்சி தெரிகிறது.","ro":"Muṉaiyil uḷḷa kalangarai viḷakkattilirundu arumaiyāṉa kāṭchi terigiṛadu."},{"fr":"Je n'avais jamais vu autant d'oiseaux à la fois.","tgt":"இத்தனை பறவைகளை ஒரே நேரத்தில் நான் பார்த்ததே இல்லை.","ro":"Ittaṉai paṛavaigaḷai orē nērattil nāṉ pārttadē illai."},{"fr":"Nous repartons vers le nord, en direction de Pichavaram.","tgt":"பிச்சாவரத்தை நோக்கி வடக்கே புறப்படுகிறோம்.","ro":"Pichchāvarattai nōkki vaḍakkē puṛappaḍugiṛōm."}]},{"title":"En barque dans les mangroves de Pichavaram","phrases":[{"fr":"Le batelier nous a emmenés dans un labyrinthe de canaux.","tgt":"படகோட்டி எங்களைக் கால்வாய்களின் ஒரு சிக்கலான வலைக்குள் அழைத்துச் சென்றார்.","ro":"Paḍagōṭṭi engaḷaik kālvāygaḷiṉ oru chikkalāṉa valaikkuḷ aḻaittuch cheṉṛār."},{"fr":"Les canaux deviennent de plus en plus étroits.","tgt":"கால்வாய்கள் மேலும் மேலும் குறுகலாகின்றன.","ro":"Kālvāygaḷ mēlum mēlum kuṛugalāgiṉṛaṉa."},{"fr":"Les racines des arbres plongent de plus en plus près de la barque.","tgt":"மரங்களின் வேர்கள் படகுக்கு மேலும் மேலும் அருகில் தண்ணீரில் இறங்குகின்றன.","ro":"Marangaḷiṉ vērgaḷ paḍagukku mēlum mēlum arugil taṇṇīril iṛangugiṉṛaṉa."},{"fr":"Plus on avance, plus le silence devient profond.","tgt":"முன்னே போகப் போக அமைதி மேலும் மேலும் ஆழமாகிறது.","ro":"Muṉṉē pōgap pōga amaidi mēlum mēlum āḻamāgiṛadu."},{"fr":"Sous les feuillages, la lumière se fait de plus en plus rare.","tgt":"இலைகளுக்குக் கீழே வெளிச்சம் மேலும் மேலும் குறைகிறது.","ro":"Ilaigaḷukkuk kīḻē veḷichcham mēlum mēlum kuṛaigiṛadu."},{"fr":"Ces mangroves protègent les villages des vagues et des tempêtes.","tgt":"இந்த அலையாத்திக் காடுகள் அலைகளிடமிருந்தும் புயல்களிடமிருந்தும் கிராமங்களைக் காக்கின்றன.","ro":"Inda alaiyāttik kāḍugaḷ alaigaḷiḍamirundum puyalgaḷiḍamirundum kirāmangaḷaik kākkiṉṛaṉa."},{"fr":"De plus en plus de visiteurs viennent ici le week-end.","tgt":"வார இறுதியில் மேலும் மேலும் அதிகமான பார்வையாளர்கள் இங்கே வருகிறார்கள்.","ro":"Vāra iṛudiyil mēlum mēlum adigamāṉa pārvaiyāḷargaḷ ingē varugiṛārgaḷ."},{"fr":"Le batelier rame sans bruit pour ne pas effrayer les oiseaux.","tgt":"பறவைகளைப் பயமுறுத்தாமல் இருக்கப் படகோட்டி சத்தமில்லாமல் துடுப்பு போடுகிறார்.","ro":"Paṛavaigaḷaip payamuṛuttāmal irukkap paḍagōṭṭi chattamillāmal tuḍuppu pōḍugiṛār."},{"fr":"Un martin-pêcheur bleu a plongé juste sous nos yeux.","tgt":"ஒரு நீல மீன்கொத்தி எங்கள் கண் முன்னே தண்ணீரில் பாய்ந்தது.","ro":"Oru nīla mīṉkotti engaḷ kaṇ muṉṉē taṇṇīril pāyndadu."},{"fr":"Je m'attache au Tamil Nadu de plus en plus à chaque voyage.","tgt":"ஒவ்வொரு பயணத்திலும் தமிழ்நாட்டை மேலும் மேலும் நேசிக்கிறேன்.","ro":"Ovvoru payaṇattilum Tamiḻnāṭṭai mēlum mēlum nēchikkiṛēṉ."}],"tip":{"title":"« Mēlum mēlum » : de plus en plus","example":"Les canaux deviennent de plus en plus étroits. — கால்வாய்கள் <b>மேலும் மேலும்</b> குறுகலாகின்றன.","body":"Le mot « mēlum » veut dire encore, en plus. En le répétant, « mēlum mēlum », on crée une progression : de plus en plus. Il se place juste avant le mot qui grandit, adjectif ou verbe : « kālvāygaḷ mēlum mēlum kuṛugalāgiṉṛaṉa », mot à mot « canaux encore encore deviennent étroits ». Il marche aussi avec les quantités : « mēlum mēlum adigamāṉa pārvaiyāḷargaḷ », de plus en plus de visiteurs. Pour dire « plus on avance, plus », le tamoul répète le verbe lui-même : « pōgap pōga », en allant, en allant. Astuce : en tamoul, dire un mot deux fois fait souvent grandir l'idée, alors prononcez le second « mēlum » un peu plus fort que le premier.","exampleRo":"Kālvāygaḷ mēlum mēlum kuṛugalāgiṉṛaṉa.","lit":"canaux · encore · encore · deviennent étroits","say":{"Mēlum mēlum":"மேலும் மேலும்","mēlum":"மேலும்","mēlum mēlum":"மேலும் மேலும்","kālvāygaḷ mēlum mēlum kuṛugalāgiṉṛaṉa":"கால்வாய்கள் மேலும் மேலும் குறுகலாகின்றன","mēlum mēlum adigamāṉa pārvaiyāḷargaḷ":"மேலும் மேலும் அதிகமான பார்வையாளர்கள்","pōgap pōga":"போகப் போக"}}},{"title":"Le retour vers Chennai","phrases":[{"fr":"Le train du retour longe la côte pendant des heures.","tgt":"திரும்பும் ரயில் பல மணி நேரம் கடற்கரையை ஒட்டியே செல்கிறது.","ro":"Tirumbum rayil pala maṇi nēram kaḍaṛkaraiyai oṭṭiyē chelgiṛadu."},{"fr":"Je regarde les rizières défiler par la fenêtre.","tgt":"ஜன்னல் வழியே வயல்கள் கடந்து போவதைப் பார்த்துக்கொண்டிருக்கிறேன்.","ro":"Jaṉṉal vaḻiyē vayalgaḷ kaḍandu pōvadaip pārttukkoṇḍirukkiṛēṉ."},{"fr":"Mon sac est deux fois plus lourd qu'au départ.","tgt":"புறப்படும்போது இருந்ததை விட என் பை இரண்டு மடங்கு கனமாக இருக்கிறது.","ro":"Puṛappaḍumbōdu irundadai viṭa eṉ pai iraṇḍu maḍangu kaṉamāga irukkiṛadu."},{"fr":"Je me demande déjà à qui je vais raconter tout ça.","tgt":"இதையெல்லாம் யாரிடம் சொல்லப் போகிறேன் என்று ஏற்கனவே யோசிக்கிறேன்.","ro":"Idaiyellām yāriḍam chollap pōgiṛēṉ eṉṛu ēṛkaṉavē yōchikkiṛēṉ."},{"fr":"Mon voisin de banquette m'a demandé ce que j'avais préféré.","tgt":"பக்கத்தில் உட்கார்ந்திருந்தவர் எனக்கு எது மிகவும் பிடித்தது என்று கேட்டார்.","ro":"Pakkattil uṭkārndirundavar eṉakku edu migavum piḍittadu eṉṛu kēṭṭār."},{"fr":"J'ai longtemps hésité avant de lui répondre.","tgt":"பதில் சொல்வதற்கு முன் நீண்ட நேரம் தயங்கினேன்.","ro":"Padil cholvadaṛku muṉ nīṇḍa nēram tayangiṉēṉ."},{"fr":"Finalement, j'ai répondu : les gens que j'ai rencontrés.","tgt":"கடைசியில், நான் சந்தித்த மனிதர்கள்தான் என்று சொன்னேன்.","ro":"Kaḍaichiyil, nāṉ chanditta maṉidargaḷtāṉ eṉṛu choṉṉēṉ."},{"fr":"Ce voyage m'a appris à parler plus lentement et à mieux écouter.","tgt":"இந்தப் பயணம் எனக்கு மெதுவாகப் பேசவும் நன்றாகக் கேட்கவும் கற்றுக்கொடுத்தது.","ro":"Indap payaṇam eṉakku meduvāgap pēchavum naṉṛāgak kēṭkavum kaṛṛukkoḍuttadu."},{"fr":"J'aimerais revenir un jour au moment des récoltes.","tgt":"ஒரு நாள் அறுவடைக் காலத்தில் மீண்டும் வர விரும்புகிறேன்.","ro":"Oru nāḷ aṛuvaḍaik kālattil mīṇḍum vara virumbugiṛēṉ."},{"fr":"Le train entre enfin en gare d'Egmore, à Chennai.","tgt":"ரயில் கடைசியாக சென்னை எழும்பூர் நிலையத்துக்குள் நுழைகிறது.","ro":"Rayil kaḍaichiyāga Cheṉṉai Eḻumbūr nilaiyattukkuḷ nuḻaigiṛadu."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce module nous a menés du delta jusqu'aux mangroves.","tgt":"இந்தப் பகுதி நம்மை டெல்டாவிலிருந்து அலையாத்திக் காடுகள் வரை அழைத்துச் சென்றது.","ro":"Indap pagudi nammai ṭelṭāvilirundu alaiyāttik kāḍugaḷ varai aḻaittuch cheṉṛadu."},{"fr":"Vous savez maintenant placer le participe avant le nom.","tgt":"பெயருக்கு முன்னால் பெயரெச்சத்தை வைக்க இப்போது உங்களுக்குத் தெரியும்.","ro":"Peyarukku muṉṉāl peyarechchattai vaikka ippōdu ungaḷukkut teriyum."},{"fr":"Vous pouvez aussi expliquer dans quel but vous faites quelque chose.","tgt":"ஏன் ஒன்றைச் செய்கிறீர்கள் என்றும் இப்போது உங்களால் விளக்க முடியும்.","ro":"Ēṉ oṉṛaich cheygiṛīrgaḷ eṉṛum ippōdu ungaḷāl viḷakka muḍiyum."},{"fr":"Faire des suppositions vous paraît désormais facile.","tgt":"ஊகித்துப் பேசுவது இப்போது உங்களுக்கு எளிது.","ro":"Ūgittup pēchuvadu ippōdu ungaḷukku eḷidu."},{"fr":"Le tamoul vous semble de plus en plus naturel.","tgt":"தமிழ் உங்களுக்கு மேலும் மேலும் இயல்பாகத் தோன்றுகிறது.","ro":"Tamiḻ ungaḷukku mēlum mēlum iyalbāgat tōṉṛugiṛadu."},{"fr":"Vous pourriez maintenant voyager seul dans tout le Tamil Nadu.","tgt":"இப்போது நீங்கள் தமிழ்நாடு முழுவதும் தனியாகப் பயணம் செய்யலாம்.","ro":"Ippōdu nīngaḷ Tamiḻnāḍu muḻuvadum taṉiyāgap payaṇam cheyyalām."},{"fr":"Chaque leçon vous a rapprochés des gens d'ici.","tgt":"ஒவ்வொரு பாடமும் உங்களை இங்குள்ள மக்களுக்கு நெருக்கமாக்கியது.","ro":"Ovvoru pāḍamum ungaḷai inguḷḷa makkaḷukku nerukkamākkiyadu."},{"fr":"Bravo pour tout le chemin parcouru depuis Thanjavur.","tgt":"தஞ்சாவூரிலிருந்து நீங்கள் கடந்து வந்த தூரத்துக்கு வாழ்த்துக்கள்.","ro":"Tanjāvūrilirundu nīngaḷ kaḍandu vanda tūrattukku vāḻttukkaḷ."},{"fr":"Prenez le temps de réécouter vos leçons préférées.","tgt":"உங்களுக்குப் பிடித்த பாடங்களை மீண்டும் கேட்க நேரம் ஒதுக்குங்கள்.","ro":"Ungaḷukkup piḍitta pāḍangaḷai mīṇḍum kēṭka nēram odukkungaḷ."},{"fr":"On se retrouve bientôt pour le dernier module.","tgt":"விரைவில் கடைசிப் பகுதியில் சந்திப்போம்.","ro":"Viraivil kaḍaichip pagudiyil chandippōm."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une soirée à Tirunelveli : parler en images","phrases":[{"fr":"Mon ami de Tirunelveli parle toujours avec des images.","tgt":"திருநெல்வேலியைச் சேர்ந்த என் நண்பர் எப்போதும் உவமைகளோடு பேசுகிறார்.","ro":"Tirunelvēliyaich chērnda eṉ naṇbar eppōdum uvamaigaḷōḍu pēchugiṛār."},{"fr":"Ce soir, nous avons parlé à cœur ouvert jusqu'à minuit.","tgt":"இன்று இரவு நாங்கள் நள்ளிரவு வரை மனம் விட்டுப் பேசினோம்.","ro":"Iṉṛu iravu nāngaḷ naḷḷiravu varai maṉam viṭṭup pēchiṉōm."},{"fr":"Il a la colère sur le bout du nez, mais il a très bon cœur.","tgt":"அவருக்கு மூக்கின் மேல் கோபம் வரும், ஆனால் அவர் நல்ல மனம் கொண்டவர்.","ro":"Avarukku mūkkiṉ mēl kōbam varum, āṉāl avar nalla maṉam koṇḍavar."},{"fr":"Pour lui, la cuisine est un art qu'il a vraiment en main.","tgt":"சமையல் அவருக்குக் கை வந்த கலை.","ro":"Chamaiyal avarukkuk kai vanda kalai."},{"fr":"J'ai tellement de travail que j'en ai par-dessus la tête.","tgt":"எனக்குத் தலைக்கு மேல் வேலை இருக்கிறது.","ro":"Eṉakkut talaikku mēl vēlai irukkiṛadu."},{"fr":"Gardez bien ce conseil au creux de l'oreille.","tgt":"இந்த அறிவுரையைக் காதில் போட்டுக்கொள்ளுங்கள்.","ro":"Inda aṛivuraiyaik kādil pōṭṭukkoḷḷungaḷ."},{"fr":"Sa voix douce m'a touché droit au cœur.","tgt":"அவருடைய மென்மையான குரல் என் நெஞ்சைத் தொட்டது.","ro":"Avaruḍaiya meṉmaiyāṉa kural eṉ nenchait toṭṭadu."},{"fr":"Ma grand-mère garde ce vieux livre comme la prunelle de ses yeux.","tgt":"என் பாட்டி இந்தப் பழைய புத்தகத்தைக் கண் போலப் பாதுகாக்கிறார்.","ro":"Eṉ pāṭṭi indap paḻaiya puttagattaik kaṇ pōlap pādugākkiṛār."},{"fr":"Il fait toujours son travail avec un soin extrême.","tgt":"அவர் எப்போதும் தன் வேலையைக் கண்ணும் கருத்துமாகச் செய்கிறார்.","ro":"Avar eppōdum taṉ vēlaiyaik kaṇṇum karuttumāgach cheygiṛār."},{"fr":"Ces expressions imagées donnent tellement de vie à la conversation.","tgt":"இந்த மரபுத் தொடர்கள் உரையாடலை இன்னும் உயிரோட்டமாக்குகின்றன.","ro":"Inda marabut toḍargaḷ uraiyāḍalai iṉṉum uyirōṭṭamākkugiṉṛaṉa."}],"tip":{"title":"Les expressions imagées du tamoul","example":"J'ai tellement de travail que j'en ai par-dessus la tête. — எனக்குத் <b>தலைக்கு மேல்</b> வேலை இருக்கிறது.","body":"Le tamoul adore parler en images, et très souvent avec les parties du corps. Pour dire qu'on est débordé, on dit « talaikku mēl vēlai », mot à mot du travail au-dessus de la tête, presque comme notre « par-dessus la tête ». Quelqu'un qui s'énerve vite a « mūkkiṉ mēl kōbam », la colère sur le nez. Parler franchement se dit « maṉam viṭṭup pēchu », parler en lâchant le cœur, et un talent naturel est une « kai vanda kalai », un art venu dans la main. Faire quelque chose avec grand soin, c'est le faire « kaṇṇum karuttumāga », avec les yeux et l'esprit. Astuce : associez chaque expression à un geste, la main au-dessus de la tête, le doigt sur le nez, et elle restera.","exampleRo":"Eṉakkut talaikku mēl vēlai irukkiṛadu.","lit":"à moi · tête [à] (-ukku) · au-dessus · travail · il y a","say":{"talaikku mēl vēlai":"தலைக்கு மேல் வேலை","mūkkiṉ mēl kōbam":"மூக்கின் மேல் கோபம்","maṉam viṭṭup pēchu":"மனம் விட்டுப் பேசு","kai vanda kalai":"கை வந்த கலை","kaṇṇum karuttumāga":"கண்ணும் கருத்துமாக"}}},{"title":"La littérature tamoule ancienne","phrases":[{"fr":"Le tamoul possède une littérature vieille de plus de deux mille ans.","tgt":"தமிழுக்கு இரண்டாயிரம் ஆண்டுகளுக்கும் மேலான இலக்கியம் இருக்கிறது.","ro":"Tamiḻukku iraṇḍāyiram āṇḍugaḷukkum mēlāṉa ilakkiyam irukkiṛadu."},{"fr":"Les poèmes de l'époque du Sangam parlent d'amour et de nature.","tgt":"சங்க காலக் கவிதைகள் காதலையும் இயற்கையையும் பற்றிப் பேசுகின்றன.","ro":"Changa kālak kavidaigaḷ kādalaiyum iyaṛkaiyaiyum paṛṛip pēchugiṉṛaṉa."},{"fr":"Le Thirukkural est lu dans presque toutes les familles tamoules.","tgt":"திருக்குறள் கிட்டத்தட்ட எல்லாத் தமிழ்க் குடும்பங்களிலும் படிக்கப்படுகிறது.","ro":"Tirukkuṛaḷ kiṭṭattaṭṭa ellāt tamiḻk kuḍumbangaḷilum paḍikkappaḍugiṛadu."},{"fr":"Il a été écrit par le poète Thiruvalluvar il y a très longtemps.","tgt":"அது மிக நீண்ட காலத்துக்கு முன்பு திருவள்ளுவரால் எழுதப்பட்டது.","ro":"Adu miga nīṇḍa kālattukku muṉbu tiruvaḷḷuvarāl eḻudappaṭṭadu."},{"fr":"Chaque distique ne compte que sept mots, mais il en dit long.","tgt":"ஒவ்வொரு குறளிலும் ஏழு சொற்கள் மட்டுமே உள்ளன, ஆனால் அது நிறையச் சொல்கிறது.","ro":"Ovvoru kuṛaḷilum ēḻu choṛkaḷ maṭṭumē uḷḷaṉa, āṉāl adu niṛaiyach cholgiṛadu."},{"fr":"Mon professeur de Tirunelveli en récitait des centaines par cœur.","tgt":"திருநெல்வேலியில் என் ஆசிரியர் அவற்றில் நூற்றுக்கணக்கானவற்றை மனப்பாடமாகச் சொல்வார்.","ro":"Tirunelvēliyil eṉ āchiriyar avaṛṛil nūṛṛukkaṇakkāṉavaṛṛai maṉappāḍamāgach cholvār."},{"fr":"Les livres que j'ai lus cette année m'ont fait aimer cette langue.","tgt":"இந்த ஆண்டு நான் படித்த புத்தகங்கள் இந்த மொழியை எனக்குப் பிடிக்க வைத்தன.","ro":"Inda āṇḍu nāṉ paḍitta puttagangaḷ inda moḻiyai eṉakkup piḍikka vaittaṉa."},{"fr":"La poésie ancienne est difficile, mais un bon commentaire aide beaucoup.","tgt":"பழைய கவிதை கடினமானது, ஆனால் ஒரு நல்ல உரை மிகவும் உதவுகிறது.","ro":"Paḻaiya kavidai kaḍiṉamāṉadu, āṉāl oru nalla urai migavum udavugiṛadu."},{"fr":"Les poèmes de Bharathiyar sont encore chantés aujourd'hui.","tgt":"பாரதியாரின் பாடல்கள் இன்றும் பாடப்படுகின்றன.","ro":"Pāradiyāriṉ pāḍalgaḷ iṉṛum pāḍappaḍugiṉṛaṉa."},{"fr":"Lire en tamoul m'ouvre un monde entièrement nouveau.","tgt":"தமிழில் படிப்பது எனக்கு ஒரு புதிய உலகத்தையே திறக்கிறது.","ro":"Tamiḻil paḍippadu eṉakku oru pudiya ulagattaiyē tiṛakkiṛadu."}]},{"title":"Chez une famille de Tirunelveli","phrases":[{"fr":"Dès que je suis entré, la grand-mère m'a demandé si j'avais mangé.","tgt":"நான் உள்ளே நுழைந்தவுடனே பாட்டி சாப்பிட்டீங்களா என்று கேட்டார்.","ro":"Nāṉ uḷḷē nuḻaindavuḍaṉē pāṭṭi chāppiṭṭīngaḷā eṉṛu kēṭṭār."},{"fr":"Ici, « vous avez mangé ? » veut simplement dire bonjour.","tgt":"இங்கே சாப்பிட்டீங்களா என்றால் வெறுமனே வணக்கம் என்று அர்த்தம்.","ro":"Ingē chāppiṭṭīngaḷā eṉṛāl veṛumaṉē vaṇakkam eṉṛu arttam."},{"fr":"Oui, j'ai mangé. Et vous aussi, vous avez mangé ?","tgt":"ஆமாம், சாப்பிட்டேன். நீங்களும் சாப்பிட்டீங்களா?","ro":"Āmām, chāppiṭṭēṉ. Nīngaḷum chāppiṭṭīngaḷā?"},{"fr":"Parlez doucement, s'il vous plaît, j'apprends encore.","tgt":"தயவுசெய்து மெல்லப் பேசுங்கள், நான் இன்னும் கற்றுக்கொண்டிருக்கிறேன்.","ro":"Tayavucheydu mellap pēchungaḷ, nāṉ iṉṉum kaṛṛukkoṇḍirukkiṛēṉ."},{"fr":"Peu à peu, je comprends mieux le parler de la région.","tgt":"மெல்ல மெல்ல இந்தப் பகுதியின் பேச்சு வழக்கு எனக்குப் புரிகிறது.","ro":"Mella mella indap pagudiyiṉ pēchchu vaḻakku eṉakkup purigiṛadu."},{"fr":"Marchez doucement, le sol est encore mouillé.","tgt":"மெல்ல நடங்கள், தரை இன்னும் ஈரமாக இருக்கிறது.","ro":"Mella naḍangaḷ, tarai iṉṉum īramāga irukkiṛadu."},{"fr":"Il se fait tard ; je m'en vais, et je reviendrai.","tgt":"நேரமாகிவிட்டது, போயிட்டு வரேன்.","ro":"Nēramāgiviṭṭadu, pōyiṭṭu varēṉ."},{"fr":"On ne dit jamais simplement « je pars », c'est un peu impoli.","tgt":"வெறுமனே போகிறேன் என்று சொல்வதில்லை, அது கொஞ்சம் மரியாதைக் குறைவு.","ro":"Veṛumaṉē pōgiṛēṉ eṉṛu cholvadillai, adu koncham mariyādaik kuṛaivu."},{"fr":"« Allez, et revenez », a répondu le grand-père en souriant.","tgt":"போயிட்டு வாங்க என்று தாத்தா புன்னகையோடு பதில் சொன்னார்.","ro":"Pōyiṭṭu vānga eṉṛu tāttā puṉṉagaiyōḍu padil choṉṉār."},{"fr":"Ces petites formules rendent chaque départ plus chaleureux.","tgt":"இந்தச் சின்ன வார்த்தைகள் விடைபெறுதலை இன்னும் அன்பானதாக்குகின்றன.","ro":"Indach chiṉṉa vārttaigaḷ viḍaibeṛudalai iṉṉum aṉbāṉadākkugiṉṛaṉa."}],"tip":{"title":"Les expressions du quotidien : « chāppiṭṭīngaḷā », « mella », « pōyiṭṭu varēṉ »","example":"Il se fait tard ; je m'en vais, et je reviendrai. — நேரமாகிவிட்டது, <b>போயிட்டு வரேன்</b>.","body":"Trois petites formules vous feront tout de suite passer pour un habitué. « Chāppiṭṭīngaḷā », vous avez mangé, sert de bonjour chaleureux : on répond « chāppiṭṭēṉ », j'ai mangé, et on renvoie la question. « Mella » veut dire doucement, lentement : « mellap pēchungaḷ », parlez doucement, et répété, « mella mella », il signifie peu à peu. Enfin, pour partir, on ne dit pas seulement « je m'en vais » mais « pōyiṭṭu varēṉ », mot à mot étant allé, je viens, autrement dit je pars et je reviens. On vous répondra « pōyiṭṭu vānga », allez et revenez. Astuce : en tamoul, on ne part jamais vraiment, on promet toujours de revenir.","exampleRo":"Nēramāgiviṭṭadu, pōyiṭṭu varēṉ.","lit":"il est devenu tard · étant allé · je viens","say":{"chāppiṭṭīngaḷā":"சாப்பிட்டீங்களா","mella":"மெல்ல","pōyiṭṭu varēṉ":"போயிட்டு வரேன்","Chāppiṭṭīngaḷā":"சாப்பிட்டீங்களா","chāppiṭṭēṉ":"சாப்பிட்டேன்","Mella":"மெல்ல","mellap pēchungaḷ":"மெல்லப் பேசுங்கள்","mella mella":"மெல்ல மெல்ல","pōyiṭṭu vānga":"போயிட்டு வாங்க"}}},{"title":"Un concert de musique carnatique","phrases":[{"fr":"Hier soir, nous sommes allés à un concert de musique carnatique.","tgt":"நேற்று இரவு நாங்கள் ஒரு கர்நாடக இசைக் கச்சேரிக்குப் போனோம்.","ro":"Nēṛṛu iravu nāngaḷ oru karnāḍaga ichaik kachchērikkup pōṉōm."},{"fr":"Un violoniste et un joueur de mridangam accompagnaient la chanteuse.","tgt":"வயலின் கலைஞரும் மிருதங்கக் கலைஞரும் பாடகிக்குப் பக்கவாத்தியம் வாசித்தார்கள்.","ro":"Vayaliṉ kalainyarum mirudangak kalainyarum pāḍagikkup pakkavāttiyam vāchittārgaḷ."},{"fr":"Chaque raga éveille une émotion différente.","tgt":"ஒவ்வொரு ராகமும் ஒரு வேறுபட்ட உணர்வை எழுப்புகிறது.","ro":"Ovvoru rāgamum oru vēṛubaṭṭa uṇarvai eḻuppugiṛadu."},{"fr":"Les auditeurs marquent le rythme de la main sur leur cuisse.","tgt":"ரசிகர்கள் தொடையில் கையால் தாளம் போடுகிறார்கள்.","ro":"Rachigargaḷ toḍaiyil kaiyāl tāḷam pōḍugiṛārgaḷ."},{"fr":"Je ne connais pas les règles, mais cette musique m'a ému.","tgt":"எனக்கு இசையின் விதிகள் தெரியாது, ஆனால் அந்த இசை என்னை நெகிழ வைத்தது.","ro":"Eṉakku ichaiyiṉ vidigaḷ teriyādu, āṉāl anda ichai eṉṉai negiḻa vaittadu."},{"fr":"Mon voisin de siège m'a expliqué le nom de chaque raga.","tgt":"பக்கத்தில் உட்கார்ந்திருந்தவர் ஒவ்வொரு ராகத்தின் பெயரையும் எனக்கு விளக்கினார்.","ro":"Pakkattil uṭkārndirundavar ovvoru rāgattiṉ peyaraiyum eṉakku viḷakkiṉār."},{"fr":"Cette musique est transmise de maître à élève depuis des siècles.","tgt":"இந்த இசை பல நூற்றாண்டுகளாக ஆசிரியரிடமிருந்து மாணவருக்குக் கற்பிக்கப்படுகிறது.","ro":"Inda ichai pala nūṛṛāṇḍugaḷāga āchiriyariḍamirundu māṇavarukkuk kaṛpikkappaḍugiṛadu."},{"fr":"L'improvisation du début, l'alapana, était ma partie préférée.","tgt":"தொடக்கத்தில் வந்த ஆலாபனைதான் எனக்கு மிகவும் பிடித்த பகுதி.","ro":"Toḍakkattil vanda ālābaṉaidāṉ eṉakku migavum piḍitta pagudi."},{"fr":"J'aimerais apprendre à jouer de la veena un jour.","tgt":"ஒரு நாள் வீணை வாசிக்கக் கற்றுக்கொள்ள விரும்புகிறேன்.","ro":"Oru nāḷ vīṇai vāchikkak kaṛṛukkoḷḷa virumbugiṛēṉ."},{"fr":"La saison musicale de décembre à Chennai est célèbre dans tout le pays.","tgt":"சென்னையின் டிசம்பர் இசை விழா நாடு முழுவதும் புகழ்பெற்றது.","ro":"Cheṉṉaiyiṉ ṭichambar ichai viḻā nāḍu muḻuvadum pugaḻbeṛṛadu."}]},{"title":"Le soleil couchant à Kanyakumari","phrases":[{"fr":"À Kanyakumari, la mer ressemble à un immense miroir doré.","tgt":"கன்னியாகுமரியில் கடல் ஒரு பெரிய தங்கக் கண்ணாடி போல இருக்கிறது.","ro":"Kaṉṉiyāgumariyil kaḍal oru periya tangak kaṇṇāḍi pōla irukkiṛadu."},{"fr":"Le soleil semblait plonger lentement dans l'eau.","tgt":"சூரியன் மெல்லத் தண்ணீரில் மூழ்குவது போல இருந்தது.","ro":"Chūriyaṉ mellat taṇṇīril mūḻguvadu pōla irundadu."},{"fr":"On dirait que trois mers se rencontrent juste devant nous.","tgt":"மூன்று கடல்களும் எங்கள் கண் முன்னே சந்திப்பது போல இருக்கிறது.","ro":"Mūṉṛu kaḍalgaḷum engaḷ kaṇ muṉṉē chandippadu pōla irukkiṛadu."},{"fr":"Les nuages étaient rouges comme du feu.","tgt":"மேகங்கள் நெருப்பு போலச் சிவந்திருந்தன.","ro":"Mēgangaḷ neruppu pōlach chivandirundaṉa."},{"fr":"On dirait qu'il va pleuvoir ce soir.","tgt":"இன்று மாலை மழை வரும் போல இருக்கிறது.","ro":"Iṉṛu mālai maḻai varum pōla irukkiṛadu."},{"fr":"Comme tout le monde, j'ai pris beaucoup trop de photos.","tgt":"எல்லாரையும் போல நானும் நிறையப் புகைப்படங்கள் எடுத்தேன்.","ro":"Ellāraiyum pōla nāṉum niṛaiyap pugaippaḍangaḷ eḍuttēṉ."},{"fr":"Ce moment au bord de l'eau ressemblait à un rêve.","tgt":"கடற்கரையில் அந்தத் தருணம் ஒரு கனவு போல இருந்தது.","ro":"Kaḍaṛkaraiyil andat taruṇam oru kaṉavu pōla irundadu."},{"fr":"La statue du poète Thiruvalluvar semble sortir de la mer.","tgt":"திருவள்ளுவர் சிலை கடலிலிருந்து எழுந்து நிற்பது போலத் தெரிகிறது.","ro":"Tiruvaḷḷuvar chilai kaḍalilirundu eḻundu niṛpadu pōlat terigiṛadu."},{"fr":"Les pêcheurs parlaient vite, comme s'ils chantaient.","tgt":"மீனவர்கள் பாடுவது போல வேகமாகப் பேசினார்கள்.","ro":"Mīṉavargaḷ pāḍuvadu pōla vēgamāgap pēchiṉārgaḷ."},{"fr":"Je n'avais jamais vu un coucher de soleil pareil.","tgt":"இது போன்ற ஒரு சூரிய அஸ்தமனத்தை நான் பார்த்ததே இல்லை.","ro":"Idu pōṉṛa oru chūriya astamaṉattai nāṉ pārttadē illai."}],"tip":{"title":"« Pōla » : comme, on dirait que","example":"On dirait qu'il va pleuvoir ce soir. — இன்று மாலை மழை வரும் <b>போல</b> இருக்கிறது.","body":"Le petit mot « pōla » veut dire comme, et il se place après ce qu'on compare, à l'inverse du français. On dit « neruppu pōla », mot à mot feu comme, pour comme du feu, et « kaṉavu pōla irundadu », c'était comme un rêve. Avec un verbe, il devient notre on dirait que : « maḻai varum pōla irukkiṛadu », pluie viendra comme c'est, donc on dirait qu'il va pleuvoir. Avant un nom, on utilise plutôt « pōṉṛa », semblable à : « idu pōṉṛa », pareil à ceci. Astuce : pensez à « pōla » comme à un miroir posé juste après le mot que vous voulez comparer.","exampleRo":"Iṉṛu mālai maḻai varum pōla irukkiṛadu.","lit":"aujourd'hui · soir · pluie · viendra · comme · il est","say":{"Pōla":"போல","pōla":"போல","neruppu pōla":"நெருப்பு போல","kaṉavu pōla irundadu":"கனவு போல இருந்தது","maḻai varum pōla irukkiṛadu":"மழை வரும் போல இருக்கிறது","pōṉṛa":"போன்ற","idu pōṉṛa":"இது போன்ற"}}},{"title":"Débat : grande ville ou petite ville","phrases":[{"fr":"Mon oncle pense que la vie est plus simple dans une grande ville.","tgt":"பெரிய நகரத்தில் வாழ்க்கை எளிது என்று என் மாமா நினைக்கிறார்.","ro":"Periya nagarattil vāḻkkai eḷidu eṉṛu eṉ māmā niṉaikkiṛār."},{"fr":"Moi, je préfère le calme d'une ville comme Tirunelveli.","tgt":"எனக்குத் திருநெல்வேலி போன்ற ஊரின் அமைதிதான் பிடிக்கும்.","ro":"Eṉakkut tirunelvēli pōṉṛa ūriṉ amaididāṉ piḍikkum."},{"fr":"À Chennai, on trouve du travail plus facilement.","tgt":"சென்னையில் வேலை எளிதாகக் கிடைக்கிறது.","ro":"Cheṉṉaiyil vēlai eḷidāgak kiḍaikkiṛadu."},{"fr":"Mais dans les embouteillages, on perd des heures chaque jour.","tgt":"ஆனால் போக்குவரத்து நெரிசலில் தினமும் பல மணி நேரம் வீணாகிறது.","ro":"Āṉāl pōkkuvarattu nerichalil tiṉamum pala maṇi nēram vīṇāgiṛadu."},{"fr":"Dans une petite ville, tout le monde connaît tout le monde.","tgt":"சிறிய ஊரில் எல்லாருக்கும் எல்லாரையும் தெரியும்.","ro":"Chiṛiya ūril ellārukkum ellāraiyum teriyum."},{"fr":"C'est rassurant, mais on n'a presque aucune vie privée.","tgt":"அது நிம்மதியாக இருக்கிறது, ஆனால் தனிப்பட்ட வாழ்க்கை என்பதே கிட்டத்தட்ட இல்லை.","ro":"Adu nimmadiyāga irukkiṛadu, āṉāl taṉippaṭṭa vāḻkkai eṉbadē kiṭṭattaṭṭa illai."},{"fr":"Les loyers ont énormément augmenté dans les grandes villes.","tgt":"பெரிய நகரங்களில் வாடகை மிகவும் அதிகமாகிவிட்டது.","ro":"Periya nagarangaḷil vāḍagai migavum adigamāgiviṭṭadu."},{"fr":"Les jeunes qui partent en ville reviennent rarement.","tgt":"நகரத்துக்குப் போகும் இளைஞர்கள் அரிதாகவே திரும்பி வருகிறார்கள்.","ro":"Nagarattukkup pōgum iḷainyargaḷ aridāgavē tirumbi varugiṛārgaḷ."},{"fr":"Chacun a ses raisons, et personne n'a vraiment tort.","tgt":"ஒவ்வொருவருக்கும் அவரவர் காரணங்கள் உண்டு, யார் சொல்வதும் தவறில்லை.","ro":"Ovvoruvarukkum avaravar kāraṇangaḷ uṇḍu, yār cholvadum tavaṛillai."},{"fr":"Finalement, nous avons clos le débat autour d'un café filtre.","tgt":"கடைசியில் ஒரு ஃபில்டர் காபியோடு விவாதத்தை முடித்தோம்.","ro":"Kaḍaichiyil oru filṭar kāpiyōḍu vivādattai muḍittōm."}]},{"title":"La vie moderne et les écrans","phrases":[{"fr":"Aujourd'hui, même les grands-parents ont un téléphone portable.","tgt":"இன்று தாத்தா பாட்டிகளிடம் கூடக் கைபேசி இருக்கிறது.","ro":"Iṉṛu tāttā pāṭṭigaḷiḍam kūḍak kaibēchi irukkiṛadu."},{"fr":"Les enfants restent assis des heures devant les écrans.","tgt":"குழந்தைகள் திரைகளுக்கு முன்னால் மணிக்கணக்கில் உட்கார்ந்திருக்கிறார்கள்.","ro":"Kuḻandaigaḷ tiraigaḷukku muṉṉāl maṇikkaṇakkil uṭkārndirukkiṛārgaḷ."},{"fr":"Avant, les voisins bavardaient le soir devant leur porte.","tgt":"முன்பெல்லாம் மாலையில் அக்கம்பக்கத்தினர் வாசலில் உட்கார்ந்து பேசிக்கொள்வார்கள்.","ro":"Muṉbellām mālaiyil akkambakkattiṉar vāchalil uṭkārndu pēchikkoḷvārgaḷ."},{"fr":"La technologie nous rapproche et nous éloigne à la fois.","tgt":"தொழில்நுட்பம் நம்மை ஒரே நேரத்தில் நெருக்கமாகவும் தூரமாகவும் ஆக்குகிறது.","ro":"Toḻilnuṭpam nammai orē nērattil nerukkamāgavum tūramāgavum ākkugiṛadu."},{"fr":"Ma sœur aînée fait ses courses en ligne pour gagner du temps.","tgt":"நேரத்தை மிச்சப்படுத்த என் அக்கா இணையத்தில் பொருட்கள் வாங்குகிறார்.","ro":"Nērattai michchappaḍutta eṉ akkā iṇaiyattil poruṭkaḷ vāngugiṛār."},{"fr":"Payer avec son téléphone est devenu normal, même au marché.","tgt":"சந்தையில் கூடக் கைபேசி மூலம் பணம் செலுத்துவது சாதாரணமாகிவிட்டது.","ro":"Chandaiyil kūḍak kaibēchi mūlam paṇam cheluttuvadu chādāraṇamāgiviṭṭadu."},{"fr":"Je me demande si nous sommes plus heureux qu'avant.","tgt":"நாம் முன்பை விட மகிழ்ச்சியாக இருக்கிறோமா என்று யோசிக்கிறேன்.","ro":"Nām muṉbai viḍa magiḻchchiyāga irukkiṛōmā eṉṛu yōchikkiṛēṉ."},{"fr":"Mon grand-père dit que la vie était plus lente, mais plus douce.","tgt":"வாழ்க்கை மெதுவாக இருந்தது, ஆனால் இனிமையாக இருந்தது என்று என் தாத்தா சொல்கிறார்.","ro":"Vāḻkkai meduvāga irundadu, āṉāl iṉimaiyāga irundadu eṉṛu eṉ tāttā cholgiṛār."},{"fr":"Le dimanche, je laisse mon téléphone éteint toute la journée.","tgt":"ஞாயிற்றுக்கிழமை முழுவதும் நான் என் கைபேசியை அணைத்து வைக்கிறேன்.","ro":"Nyāyiṛṛukkiḻamai muḻuvadum nāṉ eṉ kaibēchiyai aṇaittu vaikkiṛēṉ."},{"fr":"Trouver le juste équilibre, voilà le vrai défi d'aujourd'hui.","tgt":"சரியான சமநிலையைக் கண்டுபிடிப்பதுதான் இன்றைய உண்மையான சவால்.","ro":"Chariyāṉa chamanilaiyaik kaṇḍubiḍippadudāṉ iṉṛaiya uṇmaiyāṉa chavāl."}]},{"title":"Voyager sans rien prévoir","phrases":[{"fr":"Il y a deux ans, je suis parti à Courtallam sans rien prévoir.","tgt":"இரண்டு ஆண்டுகளுக்கு முன்பு எதையும் திட்டமிடாமல் குற்றாலத்துக்குப் போனேன்.","ro":"Iraṇḍu āṇḍugaḷukku muṉbu edaiyum tiṭṭamiḍāmal kuṛṛālattukkup pōṉēṉ."},{"fr":"Je suis monté dans le bus sans savoir où dormir.","tgt":"எங்கே தங்குவது என்று தெரியாமல் பேருந்தில் ஏறினேன்.","ro":"Engē tanguvadu eṉṛu teriyāmal pērundil ēṛiṉēṉ."},{"fr":"Je me suis baigné sous la cascade sans penser à l'heure.","tgt":"நேரத்தைப் பற்றி யோசிக்காமல் அருவியில் குளித்தேன்.","ro":"Nērattaip paṛṛi yōchikkāmal aruviyil kuḷittēṉ."},{"fr":"Une famille m'a accueilli sans même me demander mon nom.","tgt":"என் பெயரைக் கூடக் கேட்காமல் ஒரு குடும்பம் என்னை வரவேற்றது.","ro":"Eṉ peyaraik kūḍak kēṭkāmal oru kuḍumbam eṉṉai varavēṛṛadu."},{"fr":"Ne repartez pas sans goûter le halwa de Tirunelveli.","tgt":"திருநெல்வேலி அல்வாவைச் சுவைக்காமல் போகாதீர்கள்.","ro":"Tirunelvēli alvāvaich chuvaikkāmal pōgādīrgaḷ."},{"fr":"Nous avons bavardé toute la nuit sans dormir.","tgt":"நாங்கள் தூங்காமல் இரவு முழுவதும் பேசினோம்.","ro":"Nāngaḷ tūngāmal iravu muḻuvadum pēchiṉōm."},{"fr":"Sans connaître la langue, j'aurais tout manqué.","tgt":"மொழி தெரியாமல் இருந்திருந்தால், எல்லாவற்றையும் தவறவிட்டிருப்பேன்.","ro":"Moḻi teriyāmal irundirundāl, ellāvaṛṛaiyum tavaṛaviṭṭiruppēṉ."},{"fr":"Pendant la mousson, prenez un parapluie sans faute.","tgt":"மழைக்காலத்தில் மறக்காமல் குடை எடுத்துச் செல்லுங்கள்.","ro":"Maḻaikkālattil maṛakkāmal kuḍai eḍuttuch chellungaḷ."},{"fr":"Le train est parti sans attendre les retardataires.","tgt":"தாமதமாக வந்தவர்களுக்காகக் காத்திருக்காமல் ரயில் புறப்பட்டது.","ro":"Tāmadamāga vandavargaḷukkāgak kāttirukkāmal rayil puṛappaṭṭadu."},{"fr":"Voyager sans plan m'a appris à faire confiance aux gens.","tgt":"திட்டம் இல்லாமல் பயணம் செய்தது மக்களை நம்ப எனக்குக் கற்றுக்கொடுத்தது.","ro":"Tiṭṭam illāmal payaṇam cheydadu makkaḷai namba eṉakkuk kaṛṛukkoḍuttadu."}],"tip":{"title":"« -āmal » : sans faire","example":"Je me suis baigné sous la cascade sans penser à l'heure. — நேரத்தைப் பற்றி <b>யோசிக்காமல்</b> அருவியில் குளித்தேன்.","body":"Pour dire sans faire quelque chose, le tamoul n'a pas besoin d'un mot séparé : on colle « -āmal » au verbe. « Yōchi », penser, donne « yōchikkāmal », sans penser ; « tūngu », dormir, donne « tūngāmal », sans dormir ; « teriyum », savoir, donne « teriyāmal », sans savoir. Comme toujours, ce morceau se place avant le verbe principal : « tūngāmal pēchiṉōm », sans dormir nous avons parlé. Une formule à connaître absolument : « maṛakkāmal », sans oublier, qui veut dire sans faute. Et avec « illai », il n'y a pas, on obtient « illāmal », sans rien : « tiṭṭam illāmal », sans plan. Astuce : écoutez le « -āmal » final, il sonne comme un petit refus collé au verbe.","exampleRo":"Nērattaip paṛṛi yōchikkāmal aruviyil kuḷittēṉ.","lit":"temps [objet] (-ai) · à propos de · sans penser · cascade [dans] (-il) · je me suis baigné","say":{"Yōchi":"யோசி","yōchikkāmal":"யோசிக்காமல்","tūngu":"தூங்கு","tūngāmal":"தூங்காமல்","teriyum":"தெரியும்","teriyāmal":"தெரியாமல்","tūngāmal pēchiṉōm":"தூங்காமல் பேசினோம்","maṛakkāmal":"மறக்காமல்","illai":"இல்லை","illāmal":"இல்லாமல்","tiṭṭam illāmal":"திட்டம் இல்லாமல்"}}},{"title":"Souvenirs de Madurai et de Thanjavur","phrases":[{"fr":"Je me souviens encore des rues animées de Madurai la nuit.","tgt":"இரவில் மதுரையின் கலகலப்பான தெருக்கள் இன்னும் என் நினைவில் இருக்கின்றன.","ro":"Iravil maduraiyiṉ kalagalappāṉa terukkaḷ iṉṉum eṉ niṉaivil irukkiṉṛaṉa."},{"fr":"On dit que cette ville ne dort jamais.","tgt":"இந்த நகரம் ஒருபோதும் தூங்குவதில்லை என்று சொல்வார்கள்.","ro":"Inda nagaram orubōdum tūnguvadillai eṉṛu cholvārgaḷ."},{"fr":"À Thanjavur, j'ai visité le palais et sa vieille bibliothèque.","tgt":"தஞ்சாவூரில் அரண்மனையையும் அதன் பழைய நூலகத்தையும் பார்வையிட்டேன்.","ro":"Tanchāvūril araṇmaṉaiyaiyum adaṉ paḻaiya nūlagattaiyum pārvaiyiṭṭēṉ."},{"fr":"Les manuscrits sur feuilles de palmier m'ont beaucoup impressionné.","tgt":"பனை ஓலைச் சுவடிகள் என்னை மிகவும் வியக்க வைத்தன.","ro":"Paṉai ōlaich chuvaḍigaḷ eṉṉai migavum viyakka vaittaṉa."},{"fr":"Un artisan m'a montré comment on fabrique une poupée de Thanjavur.","tgt":"தஞ்சாவூர் பொம்மை எப்படிச் செய்யப்படுகிறது என்று ஒரு கைவினைஞர் எனக்குக் காட்டினார்.","ro":"Tanchāvūr pommai eppaḍich cheyyappaḍugiṛadu eṉṛu oru kaiviṉainyar eṉakkuk kāṭṭiṉār."},{"fr":"Cette poupée se balance sans jamais tomber.","tgt":"அந்தப் பொம்மை ஆடினாலும் ஒருபோதும் கீழே விழாது.","ro":"Andap pommai āḍiṉālum orubōdum kīḻē viḻādu."},{"fr":"Le guide qui nous accompagnait connaissait chaque pierre de la ville.","tgt":"எங்களுடன் வந்த வழிகாட்டிக்கு நகரத்தின் ஒவ்வொரு கல்லும் தெரியும்.","ro":"Engaḷuḍaṉ vanda vaḻigāṭṭikku nagarattiṉ ovvoru kallum teriyum."},{"fr":"Chez un ami, nous avons mangé sur une feuille de bananier.","tgt":"ஒரு நண்பரின் வீட்டில் வாழை இலையில் சாப்பிட்டோம்.","ro":"Oru naṇbariṉ vīṭṭil vāḻai ilaiyil chāppiṭṭōm."},{"fr":"Ce voyage m'a fait comprendre la richesse de cette région.","tgt":"அந்தப் பயணம் இந்தப் பகுதியின் செழுமையை எனக்குப் புரிய வைத்தது.","ro":"Andap payaṇam indap pagudiyiṉ cheḻumaiyai eṉakkup puriya vaittadu."},{"fr":"J'aimerais y retourner un jour avec ma famille.","tgt":"ஒரு நாள் என் குடும்பத்தோடு அங்கே மீண்டும் போக ஆசைப்படுகிறேன்.","ro":"Oru nāḷ eṉ kuḍumbattōḍu angē mīṇḍum pōga āchaippaḍugiṛēṉ."}]},{"title":"Dans les montagnes : Ooty et Kodaikanal","phrases":[{"fr":"Le petit train de montagne vers Ooty avance très lentement.","tgt":"ஊட்டிக்குச் செல்லும் மலை ரயில் மிக மெதுவாகச் செல்கிறது.","ro":"Ūṭṭikkuch chellum malai rayil miga meduvāgach chelgiṛadu."},{"fr":"Chaque virage offrait une vue nouvelle sur les plantations de thé.","tgt":"ஒவ்வொரு வளைவிலும் தேயிலைத் தோட்டங்களின் புதிய காட்சி தெரிந்தது.","ro":"Ovvoru vaḷaivilum tēyilait tōṭṭangaḷiṉ pudiya kāṭchi terindadu."},{"fr":"À Kodaikanal, le brouillard couvrait tout le lac le matin.","tgt":"கொடைக்கானலில் காலையில் மூடுபனி ஏரி முழுவதையும் மூடியிருந்தது.","ro":"Koḍaikkāṉalil kālaiyil mūḍubaṉi ēri muḻuvadaiyum mūḍiyirundadu."},{"fr":"Nous avions apporté des pulls, mais nous avions quand même froid.","tgt":"நாங்கள் ஸ்வெட்டர் கொண்டு வந்திருந்தோம், ஆனாலும் குளிராக இருந்தது.","ro":"Nāngaḷ sveṭṭar koṇḍu vandirundōm, āṉālum kuḷirāga irundadu."},{"fr":"Les gens de la montagne parlent avec un accent un peu différent.","tgt":"மலைப் பகுதி மக்கள் கொஞ்சம் வித்தியாசமான உச்சரிப்பில் பேசுகிறார்கள்.","ro":"Malaip pagudi makkaḷ koncham vittiyāchamāṉa uchcharippil pēchugiṛārgaḷ."},{"fr":"Le thé qu'on nous a servi là-haut était le meilleur de ma vie.","tgt":"அங்கே எங்களுக்குக் கொடுக்கப்பட்ட தேநீர்தான் என் வாழ்க்கையிலேயே மிகச் சிறந்தது.","ro":"Angē engaḷukkuk koḍukkappaṭṭa tēnīrdāṉ eṉ vāḻkkaiyilēyē migach chiṛandadu."},{"fr":"Nous avons marché trois heures dans une forêt d'eucalyptus.","tgt":"நாங்கள் தைல மரக் காட்டில் மூன்று மணி நேரம் நடந்தோம்.","ro":"Nāngaḷ taila marak kāṭṭil mūṉṛu maṇi nēram naḍandōm."},{"fr":"Le bruit de la ville me semblait très lointain.","tgt":"நகரத்தின் சத்தம் வெகு தொலைவில் இருப்பது போலத் தோன்றியது.","ro":"Nagarattiṉ chattam vegu tolaivil iruppadu pōlat tōṉṛiyadu."},{"fr":"Ces montagnes donnent envie de tout ralentir.","tgt":"இந்த மலைகள் எல்லாவற்றையும் மெதுவாக்கத் தூண்டுகின்றன.","ro":"Inda malaigaḷ ellāvaṛṛaiyum meduvākkat tūṇḍugiṉṛaṉa."},{"fr":"C'est le souvenir de voyage que je raconte le plus souvent.","tgt":"நான் அடிக்கடி சொல்லும் பயண நினைவு இதுதான்.","ro":"Nāṉ aḍikkaḍi chollum payaṇa niṉaivu idudāṉ."}]},{"title":"Un roman tamoul moderne","phrases":[{"fr":"Un libraire de Tirunelveli m'a conseillé un roman moderne.","tgt":"திருநெல்வேலியில் ஒரு புத்தகக் கடைக்காரர் எனக்கு ஒரு நவீன நாவலைப் பரிந்துரைத்தார்.","ro":"Tirunelvēliyil oru puttagak kaḍaikkārar eṉakku oru navīṉa nāvalaip parinduraittār."},{"fr":"L'histoire se passe dans un village au bord de la Tamirabarani.","tgt":"கதை தாமிரபரணி ஆற்றங்கரையில் உள்ள ஒரு கிராமத்தில் நடக்கிறது.","ro":"Kadai tāmirabaraṇi āṛṛangaraiyil uḷḷa oru kirāmattil naḍakkiṛadu."},{"fr":"L'auteur écrit dans le parler local, ce qui n'est pas facile à suivre.","tgt":"எழுத்தாளர் அந்தப் பகுதியின் பேச்சு வழக்கில் எழுதியிருக்கிறார், அதைப் புரிந்துகொள்வது எளிதல்ல.","ro":"Eḻuttāḷar andap pagudiyiṉ pēchchu vaḻakkil eḻudiyirukkiṛār, adaip purindugoḷvadu eḷidalla."},{"fr":"J'ai dû demander le sens de nombreux mots à mes amis.","tgt":"பல சொற்களின் அர்த்தத்தை நான் நண்பர்களிடம் கேட்க வேண்டியிருந்தது.","ro":"Pala choṛkaḷiṉ arttattai nāṉ naṇbargaḷiḍam kēṭka vēṇḍiyirundadu."},{"fr":"Les personnages sont si vrais qu'on croirait les connaître.","tgt":"கதாபாத்திரங்கள் மிகவும் உண்மையாக இருப்பதால், அவர்களை நமக்கு முன்பே தெரியும் என்று தோன்றுகிறது.","ro":"Kadābāttirangaḷ migavum uṇmaiyāga iruppadāl, avargaḷai namakku muṉbē teriyum eṉṛu tōṉṛugiṛadu."},{"fr":"Ce roman a été traduit dans plusieurs langues indiennes.","tgt":"இந்த நாவல் பல இந்திய மொழிகளில் மொழிபெயர்க்கப்பட்டிருக்கிறது.","ro":"Inda nāval pala indiya moḻigaḷil moḻibeyarkkappaṭṭirukkiṛadu."},{"fr":"J'en lis une page chaque soir, lentement, avec un dictionnaire.","tgt":"நான் ஒவ்வொரு இரவும் அகராதியோடு மெதுவாக ஒரு பக்கம் படிக்கிறேன்.","ro":"Nāṉ ovvoru iravum agarādiyōḍu meduvāga oru pakkam paḍikkiṛēṉ."},{"fr":"Le livre que je viens de finir m'a fait pleurer.","tgt":"நான் இப்போதுதான் படித்து முடித்த புத்தகம் என்னை அழ வைத்தது.","ro":"Nāṉ ippōdudāṉ paḍittu muḍitta puttagam eṉṉai aḻa vaittadu."},{"fr":"Les romans nous font entrer dans la vie des autres.","tgt":"நாவல்கள் மற்றவர்களின் வாழ்க்கைக்குள் நம்மை அழைத்துச் செல்கின்றன.","ro":"Nāvalgaḷ maṛṛavargaḷiṉ vāḻkkaikkuḷ nammai aḻaittuch chelgiṉṛaṉa."},{"fr":"Un jour, j'aimerais lire ce livre sans dictionnaire.","tgt":"ஒரு நாள் இந்தப் புத்தகத்தை அகராதி இல்லாமல் படிக்க விரும்புகிறேன்.","ro":"Oru nāḷ indap puttagattai agarādi illāmal paḍikka virumbugiṛēṉ."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Ma grand-mère répond à tout par un proverbe.","tgt":"என் பாட்டி எல்லாவற்றுக்கும் ஒரு பழமொழியால் பதில் சொல்வார்.","ro":"Eṉ pāṭṭi ellāvaṛṛukkum oru paḻamoḻiyāl padil cholvār."},{"fr":"« Petite goutte, grande crue » : les petits efforts s'additionnent.","tgt":"சிறு துளி பெரு வெள்ளம், சின்ன முயற்சிகள் சேர்ந்து பெரிதாகும்.","ro":"Chiṛu tuḷi peru veḷḷam, chiṉṉa muyaṛchigaḷ chērndu peridāgum."},{"fr":"« Ne mets pas le pied dans l'eau sans en connaître la profondeur. »","tgt":"ஆழம் தெரியாமல் காலை விடாதே.","ro":"Āḻam teriyāmal kālai viḍādē."},{"fr":"Un arbre seul ne fait pas un bosquet, dit-on.","tgt":"தனிமரம் தோப்பாகாது என்று சொல்வார்கள்.","ro":"Taṉimaram tōppāgādu eṉṛu cholvārgaḷ."},{"fr":"Ce proverbe veut dire qu'on a toujours besoin des autres.","tgt":"நமக்கு எப்போதும் மற்றவர்கள் தேவை என்பதுதான் இந்தப் பழமொழியின் பொருள்.","ro":"Namakku eppōdum maṛṛavargaḷ tēvai eṉbadudāṉ indap paḻamoḻiyiṉ poruḷ."},{"fr":"« Vue de cette rive, l'autre rive est toujours plus verte. »","tgt":"இக்கரைக்கு அக்கரை பச்சை.","ro":"Ikkaraikku akkarai pachchai."},{"fr":"« Ce qu'on sait tient dans une poignée de sable, ce qu'on ignore a la taille du monde. »","tgt":"கற்றது கைமண் அளவு, கல்லாதது உலகளவு.","ro":"Kaṛṛadu kaimaṇ aḷavu, kallādadu ulagaḷavu."},{"fr":"« Ceux qui savent patienter finissent par régner sur la terre. »","tgt":"பொறுத்தார் பூமி ஆள்வார்.","ro":"Poṛuttār pūmi āḷvār."},{"fr":"Les proverbes condensent en quelques mots le savoir de générations entières.","tgt":"பழமொழிகள் பல தலைமுறைகளின் அறிவைச் சில சொற்களில் சுருக்கிச் சொல்கின்றன.","ro":"Paḻamoḻigaḷ pala talaimuṛaigaḷiṉ aṛivaich chila choṛkaḷil churukkich cholgiṉṛaṉa."},{"fr":"Glisser un proverbe au bon moment fait toujours sourire.","tgt":"சரியான நேரத்தில் ஒரு பழமொழி சொன்னால் எல்லாரும் புன்னகைப்பார்கள்.","ro":"Chariyāṉa nērattil oru paḻamoḻi choṉṉāl ellārum puṉṉagaippārgaḷ."}],"tip":{"title":"Les proverbes tamouls","example":"Un arbre seul ne fait pas un bosquet, dit-on. — <b>தனிமரம் தோப்பாகாது</b> என்று சொல்வார்கள்.","body":"Les proverbes, « paḻamoḻi », mot à mot vieilles paroles, sont partout dans la conversation tamoule. Ils sont très courts, sans verbe être et souvent sans petits mots, ce qui les rend faciles à retenir. « Taṉimaram tōppāgādu » se décompose ainsi : arbre seul, bosquet ne devient pas ; autrement dit, seul on ne fait rien. « Chiṛu tuḷi peru veḷḷam », petite goutte, grande crue, encourage les petits efforts, et « ikkaraikku akkarai pachchai », pour cette rive l'autre rive est verte, ressemble à notre herbe plus verte ailleurs. Pour en citer un, on ajoute simplement « eṉṛu cholvārgaḷ », comme on dit. Astuce : apprenez-les en rythme, comme un refrain, car ils sont faits pour être dits à voix haute.","exampleRo":"Taṉimaram tōppāgādu eṉṛu cholvārgaḷ.","lit":"arbre seul · ne devient pas bosquet · [que] (eṉṛu) · ils disent","say":{"paḻamoḻi":"பழமொழி","Taṉimaram tōppāgādu":"தனிமரம் தோப்பாகாது","Chiṛu tuḷi peru veḷḷam":"சிறு துளி பெரு வெள்ளம்","ikkaraikku akkarai pachchai":"இக்கரைக்கு அக்கரை பச்சை","eṉṛu cholvārgaḷ":"என்று சொல்வார்கள்"}}},{"title":"Débattre du cinéma tamoul","phrases":[{"fr":"Partout au Tamil Nadu, les gens adorent le cinéma tamoul.","tgt":"தமிழ்நாடு முழுவதும் மக்கள் தமிழ் சினிமாவை உயிராக நேசிக்கிறார்கள்.","ro":"Tamiḻnāḍu muḻuvadum makkaḷ tamiḻ chiṉimāvai uyirāga nēchikkiṛārgaḷ."},{"fr":"Mon ami trouve les films d'aujourd'hui trop longs et trop bruyants.","tgt":"இன்றைய படங்கள் மிகவும் நீளமாகவும் சத்தமாகவும் இருப்பதாக என் நண்பர் நினைக்கிறார்.","ro":"Iṉṛaiya paḍangaḷ migavum nīḷamāgavum chattamāgavum iruppadāga eṉ naṇbar niṉaikkiṛār."},{"fr":"Moi, j'aime surtout les films qui parlent de la vie au village.","tgt":"எனக்குக் கிராம வாழ்க்கையைப் பற்றிப் பேசும் படங்கள்தான் அதிகம் பிடிக்கும்.","ro":"Eṉakkuk kirāma vāḻkkaiyaip paṛṛip pēchum paḍangaḷdāṉ adigam piḍikkum."},{"fr":"Les chansons deviennent célèbres avant même la sortie du film.","tgt":"படம் வெளியாவதற்கு முன்பே பாடல்கள் பிரபலமாகிவிடுகின்றன.","ro":"Paḍam veḷiyāvadaṛku muṉbē pāḍalgaḷ pirabalamāgiviḍugiṉṛaṉa."},{"fr":"En salle, le public siffle et applaudit pendant la projection.","tgt":"திரையரங்கில் படம் ஓடும்போதே ரசிகர்கள் விசில் அடித்துக் கைதட்டுகிறார்கள்.","ro":"Tiraiyarangil paḍam ōḍumbōdē rachigargaḷ vichil aḍittuk kaidaṭṭugiṛārgaḷ."},{"fr":"Pour un étranger, c'est une expérience inoubliable.","tgt":"ஒரு வெளிநாட்டவருக்கு அது மறக்க முடியாத அனுபவம்.","ro":"Oru veḷināṭṭavarukku adu maṛakka muḍiyāda aṉubavam."},{"fr":"Les sous-titres m'aident, mais j'essaie de comprendre sans eux.","tgt":"துணைத்தலைப்புகள் உதவுகின்றன, ஆனால் அவை இல்லாமல் புரிந்துகொள்ள முயற்சிக்கிறேன்.","ro":"Tuṇaittalaippugaḷ udavugiṉṛaṉa, āṉāl avai illāmal purindugoḷḷa muyaṛchikkiṛēṉ."},{"fr":"Certains films abordent des problèmes de société très sérieux.","tgt":"சில படங்கள் மிகவும் தீவிரமான சமூகப் பிரச்சினைகளைப் பேசுகின்றன.","ro":"Chila paḍangaḷ migavum tīviramāṉa chamūgap pirachchiṉaigaḷaip pēchugiṉṛaṉa."},{"fr":"Nous n'étions pas d'accord, mais la discussion était passionnante.","tgt":"எங்களுக்குள் கருத்து வேறுபாடு இருந்தது, ஆனால் விவாதம் சுவாரசியமாக இருந்தது.","ro":"Engaḷukkuḷ karuttu vēṛubāḍu irundadu, āṉāl vivādam chuvārachiyamāga irundadu."},{"fr":"La prochaine fois, c'est moi qui choisirai le film.","tgt":"அடுத்த முறை நான்தான் படத்தைத் தேர்ந்தெடுப்பேன்.","ro":"Aḍutta muṛai nāṉdāṉ paḍattait tērndeḍuppēṉ."}]},{"title":"Les saveurs du Sud qui changent","phrases":[{"fr":"Le halwa de Tirunelveli est connu dans tout le Tamil Nadu.","tgt":"திருநெல்வேலி அல்வா தமிழ்நாடு முழுவதும் பிரபலமானது.","ro":"Tirunelvēli alvā tamiḻnāḍu muḻuvadum pirabalamāṉadu."},{"fr":"On dit que l'eau de la rivière lui donne son goût unique.","tgt":"தாமிரபரணி ஆற்றுத் தண்ணீர்தான் அதற்குத் தனிச் சுவையைத் தருகிறது என்று சொல்கிறார்கள்.","ro":"Tāmirabaraṇi āṛṛut taṇṇīrdāṉ adaṛkut taṉich chuvaiyait tarugiṛadu eṉṛu cholgiṛārgaḷ."},{"fr":"Ma tante cuisine encore exactement comme sa mère.","tgt":"என் அத்தை இன்னும் அவருடைய அம்மா சமைத்தது போலவே சமைக்கிறார்.","ro":"Eṉ attai iṉṉum avaruḍaiya ammā chamaittadu pōlavē chamaikkiṛār."},{"fr":"Pour les idlis, elle moud encore le riz dans un mortier de pierre.","tgt":"இட்லிக்கு அவர் இன்னும் அரிசியைக் கல்லுரலில் அரைக்கிறார்.","ro":"Iṭlikku avar iṉṉum arichiyaik kalluralil araikkiṛār."},{"fr":"Les jeunes achètent la pâte toute prête au magasin.","tgt":"இளைஞர்கள் கடையில் தயாரான மாவை வாங்குகிறார்கள்.","ro":"Iḷainyargaḷ kaḍaiyil tayārāṉa māvai vāngugiṛārgaḷ."},{"fr":"Le goût n'est pas le même, mais on gagne du temps.","tgt":"சுவை ஒன்றாக இல்லை, ஆனால் நேரம் மிச்சமாகிறது.","ro":"Chuvai oṉṛāga illai, āṉāl nēram michchamāgiṛadu."},{"fr":"Dans la cuisine de Kanyakumari, on utilise beaucoup la noix de coco.","tgt":"கன்னியாகுமரி சமையலில் தேங்காய் அதிகமாகப் பயன்படுத்தப்படுகிறது.","ro":"Kaṉṉiyāgumari chamaiyalil tēngāy adigamāgap payaṉbaḍuttappaḍugiṛadu."},{"fr":"On y sent l'influence de la cuisine du Kerala voisin.","tgt":"அதில் பக்கத்தில் உள்ள கேரளச் சமையலின் தாக்கம் தெரிகிறது.","ro":"Adil pakkattil uḷḷa kēraḷach chamaiyaliṉ tākkam terigiṛadu."},{"fr":"Les recettes se transmettent de bouche à oreille, rarement par écrit.","tgt":"சமையல் குறிப்புகள் வாய்மொழியாகவே கடத்தப்படுகின்றன, அரிதாகவே எழுதப்படுகின்றன.","ro":"Chamaiyal kuṛippugaḷ vāymoḻiyāgavē kaḍattappaḍugiṉṛaṉa, aridāgavē eḻudappaḍugiṉṛaṉa."},{"fr":"J'ai demandé à ma tante de m'apprendre sa recette de sambar.","tgt":"அத்தையிடம் அவருடைய சாம்பார் செய்முறையைக் கற்றுத்தரச் சொன்னேன்.","ro":"Attaiyiḍam avaruḍaiya chāmbār cheymuṛaiyaik kaṛṛuttarach choṉṉēṉ."}]},{"title":"La mer et les pêcheurs de Kanyakumari","phrases":[{"fr":"Les pêcheurs partent en mer bien avant le lever du soleil.","tgt":"மீனவர்கள் சூரியன் உதிப்பதற்கு வெகு முன்பே கடலுக்குச் செல்கிறார்கள்.","ro":"Mīṉavargaḷ chūriyaṉ udippadaṛku vegu muṉbē kaḍalukkuch chelgiṛārgaḷ."},{"fr":"Leurs bateaux sont peints de couleurs très vives.","tgt":"அவர்களுடைய படகுகளுக்குப் பளிச்சென்ற வண்ணங்கள் பூசப்பட்டிருக்கின்றன.","ro":"Avargaḷuḍaiya paḍagugaḷukkup paḷichcheṉṛa vaṇṇangaḷ pūchappaṭṭirukkiṉṛaṉa."},{"fr":"Sur la plage, un vieux pêcheur m'a raconté sa vie.","tgt":"ஒரு வயதான மீனவர் கடற்கரையில் தன் வாழ்க்கையைப் பற்றி என்னிடம் சொன்னார்.","ro":"Oru vayadāṉa mīṉavar kaḍaṛkaraiyil taṉ vāḻkkaiyaip paṛṛi eṉṉiḍam choṉṉār."},{"fr":"Selon lui, il y a de moins en moins de poissons.","tgt":"அவருடைய கருத்துப்படி மீன்கள் குறைந்துகொண்டே வருகின்றன.","ro":"Avaruḍaiya karuttuppaḍi mīṉgaḷ kuṛaindugoṇḍē varugiṉṛaṉa."},{"fr":"Ses fils ne veulent pas faire ce métier difficile.","tgt":"அவருடைய மகன்கள் இந்தக் கடினமான தொழிலைச் செய்ய விரும்பவில்லை.","ro":"Avaruḍaiya magaṉgaḷ indak kaḍiṉamāṉa toḻilaich cheyya virumbavillai."},{"fr":"La mer leur a tout donné, mais elle peut aussi tout reprendre.","tgt":"கடல் அவர்களுக்கு எல்லாவற்றையும் கொடுத்தது, ஆனால் எல்லாவற்றையும் எடுத்துக்கொள்ளவும் முடியும்.","ro":"Kaḍal avargaḷukku ellāvaṛṛaiyum koḍuttadu, āṉāl ellāvaṛṛaiyum eḍuttukkoḷḷavum muḍiyum."},{"fr":"Le poisson frais est vendu directement sur le sable.","tgt":"புதிய மீன் நேரடியாக மணலிலேயே விற்கப்படுகிறது.","ro":"Pudiya mīṉ nēraḍiyāga maṇalilēyē viṛkappaḍugiṛadu."},{"fr":"Les femmes négocient les prix avec une grande habileté.","tgt":"பெண்கள் மிகத் திறமையாக விலை பேசுகிறார்கள்.","ro":"Peṇgaḷ migat tiṛamaiyāga vilai pēchugiṛārgaḷ."},{"fr":"Ici, protéger la mer est devenu une question de survie.","tgt":"இங்கே கடலைப் பாதுகாப்பது வாழ்வா சாவா என்ற பிரச்சினையாகிவிட்டது.","ro":"Ingē kaḍalaip pādugāppadu vāḻvā chāvā eṉṛa pirachchiṉaiyāgiviṭṭadu."},{"fr":"Désormais, je regarde le poisson dans mon assiette autrement.","tgt":"இப்போது என் தட்டில் உள்ள மீனை வேறு விதமாகப் பார்க்கிறேன்.","ro":"Ippōdu eṉ taṭṭil uḷḷa mīṉai vēṛu vidamāgap pārkkiṛēṉ."}]},{"title":"Partir ou rester : les jeunes et l'avenir","phrases":[{"fr":"Le fils de nos voisins part travailler à Chennai la semaine prochaine.","tgt":"எங்கள் பக்கத்து வீட்டுக்காரரின் மகன் அடுத்த வாரம் சென்னைக்கு வேலைக்குப் போகிறான்.","ro":"Engaḷ pakkattu vīṭṭukkārariṉ magaṉ aḍutta vāram cheṉṉaikku vēlaikkup pōgiṛāṉ."},{"fr":"Ses parents sont fiers, mais un peu tristes aussi.","tgt":"அவனுடைய பெற்றோர் பெருமைப்படுகிறார்கள், ஆனால் கொஞ்சம் வருத்தமாகவும் இருக்கிறார்கள்.","ro":"Avaṉuḍaiya peṛṛōr perumaippaḍugiṛārgaḷ, āṉāl koncham varuttamāgavum irukkiṛārgaḷ."},{"fr":"Beaucoup de jeunes diplômés ne trouvent pas de travail ici.","tgt":"பல பட்டதாரி இளைஞர்களுக்கு இங்கே வேலை கிடைப்பதில்லை.","ro":"Pala paṭṭadāri iḷainyargaḷukku ingē vēlai kiḍaippadillai."},{"fr":"Certains reviennent pour créer leur propre entreprise.","tgt":"சிலர் சொந்தத் தொழில் தொடங்கத் திரும்பி வருகிறார்கள்.","ro":"Chilar chondat toḻil toḍangat tirumbi varugiṛārgaḷ."},{"fr":"Grâce à internet, on peut maintenant travailler depuis le village.","tgt":"இப்போது இணையம் மூலம் கிராமத்திலிருந்தே வேலை செய்ய முடிகிறது.","ro":"Ippōdu iṇaiyam mūlam kirāmattilirundē vēlai cheyya muḍigiṛadu."},{"fr":"Ma voisine a été envoyée à Coimbatore par son entreprise.","tgt":"என் பக்கத்து வீட்டுப் பெண் அவருடைய நிறுவனத்தால் கோயம்புத்தூருக்கு அனுப்பப்பட்டார்.","ro":"Eṉ pakkattu vīṭṭup peṇ avaruḍaiya niṛuvaṉattāl kōyambuttūrukku aṉuppappaṭṭār."},{"fr":"Elle dit que la grande ville lui a appris l'indépendance.","tgt":"நகரம் தனக்குச் சுதந்திரத்தைக் கற்றுக்கொடுத்தது என்று அவர் சொல்கிறார்.","ro":"Nagaram taṉakkuch chudandirattaik kaṛṛukkoḍuttadu eṉṛu avar cholgiṛār."},{"fr":"Mais pendant les vacances, tout le monde rentre au village natal.","tgt":"ஆனால் ஒவ்வொரு விடுமுறைக்கும் எல்லாரும் சொந்த ஊருக்குத் திரும்புகிறார்கள்.","ro":"Āṉāl ovvoru viḍumuṛaikkum ellārum chonda ūrukkut tirumbugiṛārgaḷ."},{"fr":"Partir est parfois la seule façon de mieux revenir.","tgt":"சில நேரங்களில் வெளியே போவதுதான் மேலும் சிறப்பாகத் திரும்பி வருவதற்கான ஒரே வழி.","ro":"Chila nērangaḷil veḷiyē pōvadudāṉ mēlum chiṛappāgat tirumbi varuvadaṛkāṉa orē vaḻi."},{"fr":"Je comprends aussi bien ceux qui partent que ceux qui restent.","tgt":"போகிறவர்களையும் இங்கேயே இருப்பவர்களையும் நான் புரிந்துகொள்கிறேன்.","ro":"Pōgiṛavargaḷaiyum ingēyē iruppavargaḷaiyum nāṉ purindugoḷgiṛēṉ."}]},{"title":"L'hospitalité du Sud","phrases":[{"fr":"Ici, on ne laisse jamais un invité repartir le ventre vide.","tgt":"இங்கே விருந்தினரை ஒருபோதும் பசியோடு அனுப்புவதில்லை.","ro":"Ingē virundiṉarai orubōdum pachiyōḍu aṉuppuvadillai."},{"fr":"On m'a resservi trois fois avant même que j'aie fini.","tgt":"நான் சாப்பிட்டு முடிப்பதற்குள் மூன்று முறை எனக்குப் பரிமாறினார்கள்.","ro":"Nāṉ chāppiṭṭu muḍippadaṛkuḷ mūṉṛu muṛai eṉakkup parimāṛiṉārgaḷ."},{"fr":"Refuser un plat peut être mal compris.","tgt":"உணவை மறுப்பது தவறாகப் புரிந்துகொள்ளப்படலாம்.","ro":"Uṇavai maṛuppadu tavaṛāgap purindugoḷḷappaḍalām."},{"fr":"Pour dire « assez », on couvre la feuille avec la main.","tgt":"போதும் என்று சொல்ல இலையைக் கையால் மூட வேண்டும்.","ro":"Pōdum eṉṛu cholla ilaiyaik kaiyāl mūḍa vēṇḍum."},{"fr":"Mes hôtes m'ont fait sentir comme un membre de la famille.","tgt":"என்னை வரவேற்றவர்கள் என்னைக் குடும்பத்தில் ஒருவனாக உணர வைத்தார்கள்.","ro":"Eṉṉai varavēṛṛavargaḷ eṉṉaik kuḍumbattil oruvaṉāga uṇara vaittārgaḷ."},{"fr":"À mon départ, ils m'ont donné un sac rempli de bananes.","tgt":"நான் கிளம்பும்போது வாழைப்பழங்கள் நிறைந்த ஒரு பையை எனக்குக் கொடுத்தார்கள்.","ro":"Nāṉ kiḷambumbōdu vāḻaippaḻangaḷ niṛainda oru paiyai eṉakkuk koḍuttārgaḷ."},{"fr":"Le doyen de la famille m'a accompagné jusqu'à l'arrêt de bus.","tgt":"வீட்டுப் பெரியவர் பேருந்து நிறுத்தம் வரை என்னுடன் வந்தார்.","ro":"Vīṭṭup periyavar pērundu niṛuttam varai eṉṉuḍaṉ vandār."},{"fr":"Cette générosité toute simple m'est allée droit au cœur.","tgt":"இந்த எளிய தாராள மனப்பான்மை என் மனதைத் தொட்டது.","ro":"Inda eḷiya tārāḷa maṉappāṉmai eṉ maṉadait toṭṭadu."},{"fr":"Je leur ai promis de revenir avec mes parents.","tgt":"என் பெற்றோருடன் மீண்டும் வருவதாக அவர்களுக்கு வாக்குக் கொடுத்தேன்.","ro":"Eṉ peṛṛōruḍaṉ mīṇḍum varuvadāga avargaḷukku vākkuk koḍuttēṉ."},{"fr":"Ici, accueillir est un plaisir plus qu'un devoir.","tgt":"இங்கே விருந்தோம்பல் ஒரு கடமையை விட ஒரு மகிழ்ச்சி.","ro":"Ingē virundōmbal oru kaḍamaiyai viḍa oru magiḻchchi."}]},{"title":"Les petits bonheurs du matin","phrases":[{"fr":"Chaque matin, je marche au bord de la Tamirabarani.","tgt":"ஒவ்வொரு காலையும் தாமிரபரணி ஆற்றங்கரையில் நடக்கிறேன்.","ro":"Ovvoru kālaiyum tāmirabaraṇi āṛṛangaraiyil naḍakkiṛēṉ."},{"fr":"Les femmes dessinent des kolams devant les maisons.","tgt":"பெண்கள் வீட்டு வாசலில் கோலம் போடுகிறார்கள்.","ro":"Peṇgaḷ vīṭṭu vāchalil kōlam pōḍugiṛārgaḷ."},{"fr":"L'odeur du café filtre sort de toutes les cuisines.","tgt":"எல்லாச் சமையலறைகளிலிருந்தும் ஃபில்டர் காபியின் மணம் வருகிறது.","ro":"Ellāch chamaiyalaṛaigaḷilirundum filṭar kāpiyiṉ maṇam varugiṛadu."},{"fr":"Le marchand de lait passe à vélo en appelant ses clients.","tgt":"பால்காரர் சத்தமாகக் கூப்பிட்டபடி சைக்கிளில் வருகிறார்.","ro":"Pālgārar chattamāgak kūppiṭṭabaḍi chaikkiḷil varugiṛār."},{"fr":"Ces petits moments me rendent plus heureux que les grandes choses.","tgt":"பெரிய விஷயங்களை விட இந்தச் சின்னத் தருணங்கள்தான் என்னை மகிழ்ச்சிப்படுத்துகின்றன.","ro":"Periya vishayangaḷai viḍa indach chiṉṉat taruṇangaḷdāṉ eṉṉai magiḻchchippaḍuttugiṉṛaṉa."},{"fr":"J'ai appris à savourer le silence avant le réveil de la ville.","tgt":"நகரம் விழிப்பதற்கு முன் உள்ள அமைதியை ரசிக்கக் கற்றுக்கொண்டேன்.","ro":"Nagaram viḻippadaṛku muṉ uḷḷa amaidiyai rachikkak kaṛṛukkoṇḍēṉ."},{"fr":"Un vieil homme me salue toujours de la même façon.","tgt":"ஒரு பெரியவர் எப்போதும் ஒரே மாதிரி எனக்கு வணக்கம் சொல்கிறார்.","ro":"Oru periyavar eppōdum orē mādiri eṉakku vaṇakkam cholgiṛār."},{"fr":"Nous ne parlons pas beaucoup, mais nous nous comprenons.","tgt":"நாங்கள் அதிகம் பேசுவதில்லை, ஆனாலும் ஒருவரை ஒருவர் புரிந்துகொள்கிறோம்.","ro":"Nāngaḷ adigam pēchuvadillai, āṉālum oruvarai oruvar purindugoḷgiṛōm."},{"fr":"Le bonheur se cache souvent dans les gestes ordinaires.","tgt":"மகிழ்ச்சி பெரும்பாலும் சாதாரணச் செயல்களில்தான் ஒளிந்திருக்கிறது.","ro":"Magiḻchchi perumbālum chādāraṇach cheyalgaḷildāṉ oḷindirukkiṛadu."},{"fr":"Ces matins-là me manqueront quand je serai rentré en France.","tgt":"பிரான்சுக்குத் திரும்பிய பிறகு இந்தக் காலை நேரங்களை நினைத்து ஏங்குவேன்.","ro":"Pirāṉchukkut tirumbiya piṛagu indak kālai nērangaḷai niṉaittu ēnguvēṉ."}]},{"title":"Regard en arrière sur mon parcours en tamoul","phrases":[{"fr":"Quand j'ai commencé le tamoul, je ne savais même pas dire bonjour.","tgt":"நான் தமிழ் கற்கத் தொடங்கியபோது எனக்கு வணக்கம் சொல்லக்கூடத் தெரியாது.","ro":"Nāṉ tamiḻ kaṛkat toḍangiyabōdu eṉakku vaṇakkam chollakkūḍat teriyādu."},{"fr":"Je pensais ne jamais réussir à prononcer les sons rétroflexes.","tgt":"நாக்கை மடக்கி உச்சரிக்கும் ஒலிகளை என்னால் ஒருபோதும் சொல்ல முடியாது என்று நினைத்தேன்.","ro":"Nākkai maḍakki uchcharikkum oligaḷai eṉṉāl orubōdum cholla muḍiyādu eṉṛu niṉaittēṉ."},{"fr":"Le verbe à la fin de la phrase me déroutait complètement.","tgt":"வாக்கியத்தின் கடைசியில் வரும் வினைச்சொல் என்னை மிகவும் குழப்பியது.","ro":"Vākkiyattiṉ kaḍaichiyil varum viṉaichchol eṉṉai migavum kuḻappiyadu."},{"fr":"Aujourd'hui, je peux discuter de littérature avec mes amis.","tgt":"இன்று என் நண்பர்களுடன் இலக்கியம் பற்றி என்னால் பேச முடிகிறது.","ro":"Iṉṛu eṉ naṇbargaḷuḍaṉ ilakkiyam paṛṛi eṉṉāl pēcha muḍigiṛadu."},{"fr":"Je fais encore des fautes, mais elles ne me font plus peur.","tgt":"நான் இன்னும் தவறுகள் செய்கிறேன், ஆனால் அவை இப்போது என்னைப் பயமுறுத்துவதில்லை.","ro":"Nāṉ iṉṉum tavaṛugaḷ cheygiṛēṉ, āṉāl avai ippōdu eṉṉaip payamuṛuttuvadillai."},{"fr":"Les gens sont toujours ravis quand un étranger parle tamoul.","tgt":"ஒரு வெளிநாட்டவர் தமிழ் பேசும்போது மக்கள் எப்போதும் மகிழ்ந்து போகிறார்கள்.","ro":"Oru veḷināṭṭavar tamiḻ pēchumbōdu makkaḷ eppōdum magiḻndu pōgiṛārgaḷ."},{"fr":"Chaque discussion avec des Tamouls m'a appris une chose nouvelle.","tgt":"தமிழர்களுடனான ஒவ்வொரு உரையாடலும் எனக்கு ஏதாவது ஒரு புதிய விஷயத்தைக் கற்றுக்கொடுத்தது.","ro":"Tamiḻargaḷuḍaṉāṉa ovvoru uraiyāḍalum eṉakku ēdāvadu oru pudiya vishayattaik kaṛṛukkoḍuttadu."},{"fr":"Mes trajets de tous les jours sont devenus de vraies séances de tamoul.","tgt":"என் தினசரிப் பயணங்கள் உண்மையான தமிழ் வகுப்புகளாக மாறிவிட்டன.","ro":"Eṉ tiṉacharip payaṇangaḷ uṇmaiyāṉa tamiḻ vaguppugaḷāga māṛiviṭṭaṉa."},{"fr":"Je suis fier de tout ce chemin depuis ma toute première leçon de tamoul.","tgt":"என் முதல் தமிழ்ப் பாடத்திலிருந்து நான் கடந்து வந்த பாதையை நினைத்துப் பெருமைப்படுகிறேன்.","ro":"Eṉ mudal tamiḻp pāḍattilirundu nāṉ kaḍandu vanda pādaiyai niṉaittup perumaippaḍugiṛēṉ."},{"fr":"Apprendre le tamoul m'a fait voir l'Inde du Sud autrement.","tgt":"தமிழ் கற்றது என்னைத் தென்னிந்தியாவை வேறு கண்ணோட்டத்தில் பார்க்க வைத்தது.","ro":"Tamiḻ kaṛṛadu eṉṉait teṉṉindiyāvai vēṛu kaṇṇōṭṭattil pārkka vaittadu."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a menés de Tirunelveli à Kanyakumari.","tgt":"இந்தக் கடைசிப் பகுதி நம்மைத் திருநெல்வேலியிலிருந்து கன்னியாகுமரி வரை அழைத்துச் சென்றது.","ro":"Indak kaḍaichip pagudi nammait tirunelvēliyilirundu kaṉṉiyāgumari varai aḻaittuch cheṉṛadu."},{"fr":"Nous avons parlé de poésie, de musique et de vie moderne.","tgt":"கவிதை, இசை, நவீன வாழ்க்கை பற்றியெல்லாம் பேசினோம்.","ro":"Kavidai, ichai, navīṉa vāḻkkai paṛṛiyellām pēchiṉōm."},{"fr":"Les expressions imagées et les proverbes nous sont désormais familiers.","tgt":"மரபுத் தொடர்களும் பழமொழிகளும் இப்போது நமக்குப் பழக்கமாகிவிட்டன.","ro":"Marabut toḍargaḷum paḻamoḻigaḷum ippōdu namakkup paḻakkamāgiviṭṭaṉa."},{"fr":"Nous savons maintenant comparer et nuancer sans hésiter.","tgt":"இப்போது நமக்குத் தயங்காமல் ஒப்பிட்டுப் பேசவும் நுணுக்கமாகச் சொல்லவும் தெரியும்.","ro":"Ippōdu namakkut tayangāmal oppiṭṭup pēchavum nuṇukkamāgach chollavum teriyum."},{"fr":"Ce troisième niveau achève notre long voyage en tamoul.","tgt":"இந்த மூன்றாம் நிலையோடு நம் நீண்ட தமிழ்ப் பயணம் நிறைவடைகிறது.","ro":"Inda mūṉṛām nilaiyōḍu nam nīṇḍa tamiḻp payaṇam niṛaivaḍaigiṛadu."},{"fr":"Des premiers mots jusqu'aux proverbes, quel chemin parcouru !","tgt":"முதல் வார்த்தைகளிலிருந்து பழமொழிகள் வரை, எவ்வளவு தூரம் வந்திருக்கிறோம்!","ro":"Mudal vārttaigaḷilirundu paḻamoḻigaḷ varai, evvaḷavu tūram vandirukkiṛōm!"},{"fr":"Le tamoul fait maintenant partie de notre vie de tous les jours.","tgt":"தமிழ் இப்போது நம் அன்றாட வாழ்க்கையின் ஒரு பகுதியாகிவிட்டது.","ro":"Tamiḻ ippōdu nam aṉṛāḍa vāḻkkaiyiṉ oru pagudiyāgiviṭṭadu."},{"fr":"Bravo pour votre persévérance jusqu'à la toute dernière phrase.","tgt":"கடைசி வாக்கியம் வரை நீங்கள் காட்டிய விடாமுயற்சிக்கு வாழ்த்துகள்.","ro":"Kaḍaichi vākkiyam varai nīngaḷ kāṭṭiya viḍāmuyaṛchikku vāḻttugaḷ."},{"fr":"Continuez à parler tamoul à chaque occasion, sans avoir peur.","tgt":"பயப்படாமல் ஒவ்வொரு வாய்ப்பிலும் தொடர்ந்து தமிழ் பேசுங்கள்.","ro":"Payappaḍāmal ovvoru vāyppilum toḍarndu tamiḻ pēchungaḷ."},{"fr":"Comme on dit ici, je pars et je reviens : à bientôt en tamoul !","tgt":"போயிட்டு வரேன், மீண்டும் தமிழில் சந்திப்போம்!","ro":"Pōyiṭṭu varēṉ, mīṇḍum tamiḻil chandippōm!"}]}]}]}];
